test('Wine hub: /wineries is enabled, winery-only, valley-wide, and themed for the hub ONLY', async () => {
  // 1. the route is enabled via the ALL_REGIONS_CATEGORIES allowlist
  assert.ok(app.ALL_REGIONS_CATEGORIES.includes('winery'), '/wineries Okanagan-wide hub must be enabled');
  assert.ok(app.ALL_REGIONS_CATEGORIES.includes('beach'), 'enabling Wine must not disable Beaches');
  assert.ok(app.ALL_REGIONS_CATEGORIES.includes('golf'), 'enabling Wine must not disable Golf');

  // 2. every winery in the valley is present before any region is chosen,
  //    and the hub carries the Beaches-style themed presentation
  const wineries = app.getVenuesByCategory('winery');
  const hub = app.renderCategoryAllRegionsPage('winery', wineries);
  assert.match(hub, /<h1>Wineries in the Okanagan<\/h1>/, 'hub needs the Wineries heading');
  assert.match(hub, /class="golf-page winery-page"/, 'hub uses the Beaches-style themed body class');
  assert.match(hub, /class="category-region-selector"/, 'hub shows the Beaches-style region selector');
  for (const v of wineries) {
    assert.ok(hub.includes(v.name), `hub must list every winery before filtering: ${v.name}`);
  }

  // 3. winery-only: every rendered card is a winery, and no other type leaks in
  const nonWinery = wineries.filter((v) => v.type !== 'winery');
  assert.equal(nonWinery.length, 0, 'getVenuesByCategory("winery") must return winery venues only');
  // Match only real cards (data-venue-category on a card carries a
  // data-venue-name beside it); the themed page's CSS/script also mention
  // data-venue-category="golf" in selectors, which are not cards.
  const cardTypes = [...hub.matchAll(/data-venue-category="([a-z]+)" data-venue-name=/g)].map((m) => m[1]);
  assert.ok(cardTypes.length > 0, 'themed hub cards must carry data-venue-category');
  assert.deepEqual([...new Set(cardTypes)], ['winery'], 'the hub must render winery cards and nothing else');
  for (const other of ['restaurant', 'cafe', 'brewery', 'pub', 'cocktail', 'golf', 'beach', 'outdoor']) {
    assert.ok(!hub.includes(`data-venue-category="${other}" data-venue-name=`), `hub must not contain any ${other} card`);
  }

  // 4. the region selector filters by linking to the existing region pages
  const regions = [...new Set(wineries.map((v) => v.region))];
  for (const r of regions) {
    assert.ok(hub.includes(`href="/${r}/wineries"`), `region selector must link to /${r}/wineries`);
  }

  // 5. hub-only theming: the REGION page must be untouched. (Stage 4.1: the
  // VENUE page uses the themed venue shell -- see the Stage 4.1 tests.)
  const first = wineries[0];
  const regionPage = app.renderCategoryPage(first.region, 'winery', app.getVenuesByRegionCategory(first.region, 'winery'), []);
  assert.doesNotMatch(regionPage, /class="golf-page/, 'winery region pages must NOT be themed');
  assert.doesNotMatch(regionPage, /venue-card-cue/, 'winery region cards must keep their original markup');
  assert.ok(!app.THEMED_CATEGORY_TYPES.has('winery'), 'winery must never join the global THEMED_CATEGORY_TYPES');
});

test('Wine engagement: winery region and venue pages carry Favorite / Add to Trip WITHOUT the themed styling', () => {
  const wineries = app.getVenuesByCategory('winery');
  const first = wineries[0];

  // 1. region page: controls present, presentation untouched
  const regionPage = app.renderCategoryPage(first.region, 'winery', app.getVenuesByRegionCategory(first.region, 'winery'), []);
  assert.match(regionPage, /class="card-action fav-btn"/, 'winery region cards must render Favorite');
  assert.match(regionPage, /class="card-action trip-btn"/, 'winery region cards must render Add to Trip');
  assert.match(regionPage, /data-venue-category="winery" data-venue-name=/, 'cards need the attributes the engagement script binds to');
  assert.doesNotMatch(regionPage, /class="golf-page/, 'winery region pages must stay unthemed');
  assert.doesNotMatch(regionPage, /venue-card-cue/, 'winery region cards keep their original markup');
  assert.doesNotMatch(regionPage, /class="golf-desc"/, 'winery region cards must not gain the themed description block');
  assert.doesNotMatch(regionPage, /id="tripTray"/, 'engagement-only pages must not pull in the trip tray');

  // 2. venue page: controls in the CTA row (Stage 4.1: inside the themed venue shell)
  const venuePage = app.renderVenuePage(first, [], [], []);
  assert.match(venuePage, /class="card-action fav-btn"/, 'winery venue pages must render Favorite');
  assert.match(venuePage, /class="card-action trip-btn"/, 'winery venue pages must render Add to Trip');
  assert.match(venuePage, /<div class="venue-cta-row" data-venue-id=/, 'the CTA row needs its engagement attributes');

  // 3. the controls are wired: the standalone script needs no app.js
  assert.match(regionPage, /var HOLDER = '\[data-venue-category="winery"\]'/, 'region page must bind the engagement script to winery cards');
  assert.match(venuePage, /okanaganFavorites/, 'venue page controls must use the shared favourites key');
  assert.match(venuePage, /okanaganTrip/, 'venue page controls must use the shared trip key');

  // 4. a category with no engagement controls is untouched
  const restaurants = app.getVenuesByRegionCategory(first.region, 'restaurant');
  if (restaurants.length) {
    const other = app.renderCategoryPage(first.region, 'restaurant', restaurants, []);
    assert.doesNotMatch(other, /class="card-action fav-btn"/, 'non-engagement categories must not gain the controls');
  }
  assert.ok(!app.ENGAGEMENT_ONLY_TYPES.has('restaurant'), 'only winery is an engagement-only type for now');
});

// ---- category-change redirect (2026-09-24) ------------------------------
//
// When a venue's `type` is corrected (e.g. a pub that had been filed as a
// restaurant), CATEGORY_SLUGS changes its canonical URL, so the previously
// published/indexed URL would 404. server.js's venue route now falls back to
// findActiveVenueBySlugAcrossTypes() and 301s to the new URL instead.
//
// The subtle part -- and what this test protects -- is the helper's guards,
// not the 301 itself: (region, slug) is NOT unique in production (three golf
// clubs keep a clubhouse-restaurant record under the same region+slug as the
// course), and a retired venue must stay with the existing venue-to-venue
// redirect rather than being caught here.
//
// Deliberately NOT an HTTP test: the shared harness's only listener runs on
// port 3001 inside the long 'HTTP routes' test, which currently fails on a
// pre-existing golf-selector assertion BEFORE reaching its app.server.close()
// -- so that port can still be held when later tests run. A port-bound test
// here would be flaky for reasons unrelated to this feature.
test('Category-change redirect: the cross-type slug lookup resolves a moved venue and refuses to guess', () => {
  const insertRedirect = db.prepare(
    'INSERT INTO venues (name, region, type, slug, redirect_to) VALUES (?, ?, ?, ?, ?)'
  );
  const insertPlain = db.prepare(
    'INSERT INTO venues (name, region, type, slug) VALUES (?, ?, ?, ?)'
  );

  // 1. A venue whose type was corrected: findable by region+slug across types.
  insertPlain.run('CCR Moved Pub', 'kelowna', 'pub', 'ccr-moved-pub');
  const moved = app.findActiveVenueBySlugAcrossTypes('kelowna', 'ccr-moved-pub');
  assert.ok(moved, 'a single active venue must be found by region+slug regardless of type');
  assert.equal(moved.type, 'pub');
  assert.equal(app.CATEGORY_SLUGS[moved.type], 'pubs', 'the redirect target slug comes from CATEGORY_SLUGS');
  // The old URL's category slug differs from the new one -- the route's
  // redirect condition -- so no self-redirect (loop) is possible.
  assert.notEqual(app.CATEGORY_SLUGS[moved.type], 'restaurants');

  // 2. Ambiguity guard: two ACTIVE venues sharing region+slug must return null,
  //    so the route 404s rather than guessing between them. This mirrors real
  //    production data (e.g. penticton/penticton-golf-country-club exists as
  //    both type='golf' and type='restaurant').
  insertPlain.run('CCR Ambiguous Course', 'vernon', 'golf', 'ccr-ambiguous');
  insertPlain.run('CCR Ambiguous Clubhouse', 'vernon', 'restaurant', 'ccr-ambiguous');
  assert.equal(
    app.findActiveVenueBySlugAcrossTypes('vernon', 'ccr-ambiguous'),
    null,
    'an ambiguous (region, slug) must return null -- never guess between two real venues'
  );
  // Each remains individually reachable by its own exact type.
  assert.ok(app.findVenueBySlug('vernon', 'golf', 'ccr-ambiguous'));
  assert.ok(app.findVenueBySlug('vernon', 'restaurant', 'ccr-ambiguous'));

  // 3. Retired venues stay out of this path, so the pre-existing
  //    venue-to-venue redirect keeps owning them.
  const target = app.findVenueBySlug('kelowna', 'pub', 'ccr-moved-pub');
  insertRedirect.run('CCR Retired', 'penticton', 'restaurant', 'ccr-retired', target.id);
  assert.equal(
    app.findActiveVenueBySlugAcrossTypes('penticton', 'ccr-retired'),
    null,
    'a redirected venue must not be resolved here'
  );

  // 4. Unknown slug -> null (plain 404, no redirect).
  assert.equal(app.findActiveVenueBySlugAcrossTypes('kelowna', 'ccr-no-such-slug'), null);
});

// ---- region-change redirect + Distillery type (2026-09-24) ---------------
//
// A corrected `region` moves a venue's canonical URL the same way a corrected
// `type` does, so the venue route also falls back to
// findActiveVenueBySlugAcrossRegions(). Same guards: exactly one active match,
// never a retired venue. Not an HTTP test, for the port-3001 reason above.
test('Region-change redirect: the cross-region slug lookup resolves a moved venue and refuses to guess', () => {
  const insertPlain = db.prepare('INSERT INTO venues (name, region, type, slug) VALUES (?, ?, ?, ?)');
  const insertRedirect = db.prepare('INSERT INTO venues (name, region, type, slug, redirect_to) VALUES (?, ?, ?, ?, ?)');

  insertPlain.run('RCR Moved Winery', 'lake-country', 'winery', 'rcr-moved-winery');
  const moved = app.findActiveVenueBySlugAcrossRegions('winery', 'rcr-moved-winery');
  assert.ok(moved, 'a single active venue must be found by type+slug regardless of region');
  assert.equal(moved.region, 'lake-country');

  // Two active venues share type+slug in different regions: never guess.
  insertPlain.run('RCR Twin', 'kelowna', 'cafe', 'rcr-twin');
  insertPlain.run('RCR Twin', 'vernon', 'cafe', 'rcr-twin');
  assert.equal(app.findActiveVenueBySlugAcrossRegions('cafe', 'rcr-twin'), null);

  // A retired venue stays with the venue-to-venue redirect.
  insertRedirect.run('RCR Retired', 'penticton', 'pub', 'rcr-retired', moved.id);
  assert.equal(app.findActiveVenueBySlugAcrossRegions('pub', 'rcr-retired'), null);

  assert.equal(app.findActiveVenueBySlugAcrossRegions('winery', 'rcr-no-such-slug'), null);
});

