test('S6 #2-#8: the date step renders in the reserved slot; presets and custom ranges drive the server window exactly like the API', async () => {
  const today = app.todayLocal();
  const { text } = await s6get('/whats-on');
  const markup = s6markup(text);
  // Simplified surface (2026-09-24): the category image grid, the step
  // headings and the "Show results" CTA are gone. Categories are a chip row,
  // dates live in the Date popover, and results follow immediately.
  const order = ['data-filter="category"', 'id="whatsOnDateBtn"', 'data-filter="date"', 'id="whatsOnResultsSummary"', 'id="whatsOnResults"'];
  let pos = -1; for (const m of order) { const i = markup.indexOf(m); assert.ok(i > pos, `slot order: ${m}`); pos = i; }
  for (const key of ['today', 'this-weekend', 'this-week', 'this-month']) assert.match(markup, new RegExp(`<a class="outdoor-filter-chip whatson-date-chip" href="/whats-on\\?when=${key}" data-when="${key}" aria-pressed="false">`));
  assert.match(markup, /id="whatsOnCustomToggle" data-when="custom" aria-pressed="false" aria-expanded="false"/);
  assert.match(markup, /<form class="whatson-custom-dates" id="whatsOnCustomDates" method="get" action="\/whats-on" hidden>/);
  assert.match(markup, /<input type="date" name="from" id="whatsOnFrom" value="" required>/);
  assert.match(markup, new RegExp(`Showing the next 90 days: ${app.formatLocalDateShort(today, { weekday: false })} – ${app.formatLocalDateShort(app.addLocalDays(today, 90), { weekday: false })}`));
  assert.match(text, /var DATE = \{"when":"","from":"","to":""\};/);
  for (const when of ['today', 'this-weekend', 'this-week', 'this-month']) {
    const win = app.dateWindowForPreset(when, today);
    const page = s6markup((await s6get(`/whats-on?when=${when}`)).text);
    assert.match(page, new RegExp(`data-when="${when}" aria-pressed="true"`), `${when} chip pressed`);
    assert.match(page, /id="whatsOnDateCount"> · 1</, `${when} shows on the Date popover badge`);
    const expectedNames = app.queryWhatsOnEvents({ from: win.from, to: win.to }).map((e) => e.name);
    const shown = [...page.matchAll(/data-venue-name="([^"]+)"/g)].map((m) => m[1]);
    assert.deepEqual(shown, expectedNames, `${when} renders exactly the API window's events`);
  }
  const custom = (await s6get('/whats-on?when=custom&from=2033-03-01&to=2033-03-31')).text;
  const cm = s6markup(custom);
  assert.match(cm, /id="whatsOnCustomToggle" data-when="custom" aria-pressed="true" aria-expanded="true"/);
  assert.match(cm, /<form class="whatson-custom-dates" id="whatsOnCustomDates" method="get" action="\/whats-on">/, 'form open for a custom window');
  assert.match(cm, /id="whatsOnFrom" value="2033-03-01"/); assert.match(cm, /id="whatsOnTo" value="2033-03-31"/);
  assert.deepEqual([...cm.matchAll(/data-venue-name="([^"]+)"/g)].map((m) => m[1]), ['S6 Far Future Gala']);
  assert.match(custom, /var DATE = \{"when":"custom","from":"2033-03-01","to":"2033-03-31"\};/);
  const bare = s6markup((await s6get('/whats-on?from=2033-03-01&to=2033-03-31')).text);
  assert.deepEqual([...bare.matchAll(/data-venue-name="([^"]+)"/g)].map((m) => m[1]), ['S6 Far Future Gala'], 'bare from/to works like the API');
  for (const q of ['when=custom&from=2033-03-31&to=2033-03-01', 'when=custom&from=2033-02-30&to=2033-03-01', 'when=custom&from=2033-01-01&to=2034-01-03', 'when=custom&from=x&to=y']) {
    const fb = s6markup((await s6get(`/whats-on?${q}`)).text);
    assert.match(fb, /class="whatson-date-note" role="status">Those dates weren’t a valid range/, q);
    assert.match(fb, /Showing the next 90 days:/, `${q} -> default window`);
    assert.match(fb, /aria-live="polite">4 events<\/p>/, `${q} -> default window results`);
  }
  const okMax = s6markup((await s6get('/whats-on?when=custom&from=2033-01-01&to=2034-01-02')).text);
  assert.doesNotMatch(okMax, /class="whatson-date-note"/, 'exactly 366 days is accepted');
});

test('S6 #9-#11/#21: region/category multi-select and no-match state over the rendered window', async () => {
  const both = s6markup((await s6get('/whats-on?regions=kelowna,vernon&categories=live-music,markets-fairs')).text);
  assert.match(both, /data-region="kelowna" aria-pressed="true"/); assert.match(both, /data-region="vernon" aria-pressed="true"/);
  assert.match(both, /data-category="live-music" aria-pressed="true"/); assert.match(both, /data-category="markets-fairs" aria-pressed="true"/);
  assert.match(both, /aria-live="polite">2 of 4 events<\/p>/, 'regions OR, categories OR, AND between');
  assert.match(both, /id="whatsOnResultsSummary" aria-live="polite">2 of \d+ events</, 'the compact count reports the filtered total');
  assert.match(both, /id="whatsOnSelectedClear">Clear all</, 'Clear all now lives with the removable filter chips');
  const regionOnly = s6markup((await s6get('/whats-on?regions=peachland')).text);
  assert.match(regionOnly, /aria-live="polite">1 of 4 events<\/p>/, 'valley-wide festival matches a region with nothing else');
  assert.match(regionOnly, /data-region="peachland" aria-pressed="true">Peachland<span class="outdoor-activity-count">1<\/span>/, 'region chip counts include valley-wide rows');
  const noMatch = s6markup((await s6get('/whats-on?regions=vernon&categories=nightlife')).text);
  assert.match(noMatch, /aria-live="polite">0 of 4 events<\/p>/);
  assert.match(noMatch, /<p class="outdoor-no-results" id="whatsOnNoResults">No events match that combination yet\./, 'no-match state, not the empty-inventory state');
  assert.match(noMatch, /<div class="whatson-empty" id="whatsOnEmptyInventory" hidden>/);
  assert.match(noMatch, /<ul class="card-grid" id="whatsOnResults" hidden>/);
  assert.equal((noMatch.match(/<li class="venue-card whatson-event-card" hidden/g) || []).length, 4, 'all four window cards are rendered hidden, so unselecting a chip can reveal them client-side');
  assert.equal((both.match(/<li class="venue-card whatson-event-card" hidden/g) || []).length, 2, 'pre-filtered render: 2 shown, 2 hidden');
});

test('S6 #12/#13/#19: the client script keeps the date window on chip pushState, reloads on Back/Forward date changes, clears all, and keeps Favorite/Add to Trip wiring', () => {
  const script = app.renderWhatsOnFilterScriptHtml({ hasInventory: true, dateState: { when: 'this-week', from: '', to: '' } });
  for (const needle of [
    "var DATE = {\"when\":\"this-week\",\"from\":\"\",\"to\":\"\"};",
    "if (d.when) q.push('when=' + encodeURIComponent(d.when));",
    "if (d.when === 'custom') { if (d.from) q.push('from=' + encodeURIComponent(d.from)); if (d.to) q.push('to=' + encodeURIComponent(d.to)); }",
    "window.addEventListener('popstate'",
    "if (d.when !== DATE.when || d.from !== DATE.from || d.to !== DATE.to) { window.location.reload(); return; }",
    "readUrlIntoChips(); openGroupsForSelection(); apply('none');",
    "function clearAll(){ chips.forEach(function(c){ c.setAttribute('aria-pressed', 'false'); }); searchTerm = ''; if (searchInput) searchInput.value = ''; apply('push'); }",
    "filter(function(c){ return !c.hasAttribute('data-when') && !c.hasAttribute('data-category-all'); })",
    "querySelectorAll('a[data-when]')",
    "customForm.addEventListener('submit'",
    "cardMatches(d, regions, categories)",
    "(d.valley ? allRegionKeys : [d.region])",
    "emptyInventory.hidden = INVENTORY;",
    "empty.hidden = !(INVENTORY && shown === 0);",
    app.OUTDOOR_FILTER_CLIENT_PREDICATE_SRC,
  ]) assert.ok(script.includes(needle), `script contains ${needle}`);
  const page = app.renderWhatsOnPage(app.parseWhatsOnPageQuery({ when: 'this-week' }));
  assert.match(page, /<script src="\/scripts\/app\.js\?v=[0-9a-f]{12}"><\/script>/, 'app.js (homepage favourites/trip modules) still loads');
  assert.match(page, /data-venue-category="whatson"/, 'cards carry the holder attribute the shared fav/trip module keys off');
  assert.match(page, /var INVENTORY = true;/);
});

test('S6 #24/#25: no token or admin surface in the page; the shell-era markup is unchanged apart from the data now flowing through it', async () => {
  const src = fs.readFileSync(path.join(__dirname, '..', 'server.js'), 'utf8');
  const page = (await s6get('/whats-on?when=today')).text;
  assert.doesNotMatch(page, /test-fixture-admin-token|ENRICHMENT_ADMIN_TOKEN|Authorization|\/api\/events/);
  assert.ok(!/fetch\(['"`]\/api\/events/.test(src.slice(src.indexOf('function renderWhatsOnFilterScriptHtml'), src.indexOf('function renderWhatsOnPage'))), 'the page is server-rendered; no browser-side API fetch');
  // Structural markers of the approved shell are all still present, in order.
  const markup = s6markup(page);
  // Simplified surface (2026-09-24): search -> category chips -> compact
  // Regions/Date controls -> count -> results. The region chips still exist
  // in full, now inside the Regions popover panel.
  const order = ['<body class="golf-page outdoor-page whatson-page">', '<p class="outdoor-intro whatson-intro">', 'id="whatsOnSearch"', 'class="whatson-cat-row"', 'data-filter="category"', 'class="whatson-controls"', 'id="whatsOnRegionsBtn"', 'data-filter="region"', 'id="whatsOnResultsSummary"', 'id="whatsOnSelected"', 'id="whatsOnEmptyInventory"', 'id="whatsOnNoResults"', 'id="whatsOnResults"', '<footer class="home-footer"'];
  let pos = -1; for (const m of order) { const i = markup.indexOf(m); assert.ok(i > pos, `order: ${m}`); pos = i; }
  assert.equal((markup.match(/class="outdoor-filter-chip" data-region="/g) || []).length, 20, 'all 20 region chips still present, inside the Regions popover');
  assert.deepEqual([...markup.matchAll(/data-category="([a-z-]+)" aria-pressed="false"/g)].map((m) => m[1]), app.WHATSON_CATEGORIES.map((c) => c.key), 'twelve category chips in the approved order');
});

test("What's On simplification: results are reachable without scrolling past a filter form", async () => {
  const { text } = await s6get('/whats-on');
  const markup = s6markup(text);

  // 1. The twelve 1376x768 category tiles are gone from above the results --
  //    they were the single biggest mobile cost on this page.
  const above = markup.slice(markup.indexOf('<h1>'), markup.indexOf('id="whatsOnResults"'));
  assert.ok(above.length > 0, 'results list must come after the heading');
  assert.equal((above.match(/outdoor-activity-card/g) || []).length, 0, 'no category image tiles above the results');
  assert.equal((above.match(/<img/g) || []).length, 0, 'no images at all above the results');

  // 2. Replaced by one compact chip row: All + the twelve categories.
  assert.match(markup, /<div class="whatson-cat-row" role="group" aria-label="Choose categories" data-filter="category">/);
  assert.match(markup, /data-category-all="1"/, 'an All reset chip');
  assert.equal((markup.match(/<button type="button" class="outdoor-filter-chip whatson-cat-chip/g) || []).length, app.WHATSON_CATEGORIES.length + 1, 'All + one chip per category');

  // 3. Search exists and is a real input, not a heading-sized block.
  assert.match(markup, /<input type="search" id="whatsOnSearch" class="whatson-search-input" placeholder="Search events\.\.\."/);

  // 4. Regions collapse into a popover that starts closed, and the full
  //    region chip set still lives inside it (nothing was removed).
  assert.match(markup, /<button type="button" class="whatson-pop-btn" id="whatsOnRegionsBtn" aria-expanded="false"/);
  assert.match(markup, /<div class="whatson-pop-panel" id="whatsOnRegionsPanel" hidden>/);
  assert.equal((markup.match(/class="outdoor-filter-chip" data-region="/g) || []).length, 20, 'all 20 regions still selectable');
  assert.match(markup, /data-region-group="/, 'the derived region grouping is preserved');

  // 5. The old step scaffolding is gone.
  for (const gone of ['Choose Region(s)</h2>', 'Choose Category(s)</h2>', 'id="whatsOnShowResults"']) {
    assert.ok(markup.indexOf(gone) === -1, `removed from the page: ${gone}`);
  }

  // 6. No sort control was added (deliberately out of scope).
  assert.ok(markup.indexOf('whatsOnSort') === -1, 'sort was intentionally not added');
});

test("What's On and Outdoors keep separate simplified surfaces (no markup or CSS leak in either direction)", () => {
  // Both pages share OUTDOOR_FILTER_CLIENT_PREDICATE_SRC and the region-group
  // markup, and both now ship a compact surface (What's On d8f5ea6, Outdoors
  // 2026-09-24). Each must use only its own classes and ids.
  const landing = app.renderCategoryAllRegionsPage('outdoor', app.getVenuesByCategory('outdoor'));
  const whatsOn = app.renderWhatsOnPage(app.parseWhatsOnPageQuery({}));
  // Outdoors carries its own controls and none of What's On's.
  assert.match(landing, /class="outdoors-search"/, 'Outdoors has its own search');
  assert.match(landing, /outdoors-act-row/, 'Outdoors has its own activity chip row');
  assert.match(landing, /id="outdoorRegionsBtn"/, 'Outdoors has its own Regions popover');
  for (const leak of ['whatson-cat-row', 'whatson-pop-btn', 'whatsOnSearch', 'whatsOnDateBtn', 'data-category-all'])
    assert.ok(landing.indexOf(leak) === -1, `What's On's ${leak} must not leak onto Outdoors`);
  // What's On carries its own and none of Outdoors' new ones.
  for (const leak of ['outdoors-search', 'outdoors-act-row', 'outdoors-pop-btn', 'outdoorsSearch', 'data-activity-all'])
    assert.ok(whatsOn.indexOf(leak) === -1, `Outdoors' ${leak} must not leak onto What's On (markup or stylesheet)`);
  // The landing's stylesheet is emitted by the landing alone, never by the
  // shared outdoor theme block that /whats-on and the activity pages load.
  assert.ok(!app.renderOutdoorThemeStyles().includes('outdoors-act-row'), 'the simplified rules are not in the shared outdoor stylesheet');
  assert.match(whatsOn, /class="whatson-cat-row"/); assert.match(whatsOn, /id="whatsOnSearch"/); assert.match(whatsOn, /id="whatsOnDateBtn"/);
  // One shared predicate, shipped verbatim on both.
  assert.ok(landing.includes(app.OUTDOOR_FILTER_CLIENT_PREDICATE_SRC) && whatsOn.includes(app.OUTDOOR_FILTER_CLIENT_PREDICATE_SRC), 'one shared predicate implementation');
  // Outdoors has no date filter of any kind.
  for (const d of ['whatsOnDate', 'data-when', 'when=', 'Choose Dates', 'whatson-date'])
    assert.ok(landing.indexOf(d) === -1, `Outdoors must carry no date artefact (${d})`);
});

test('S6 cleanup: remove every Step 6 fixture event', () => {
  const ids = db.prepare("SELECT id FROM events WHERE name LIKE 'S6 %'").all().map((r) => r.id);
  for (const id of ids) {
    db.prepare('DELETE FROM event_enrichment_log WHERE event_id = ?').run(id);
    db.prepare('DELETE FROM event_categories WHERE event_id = ?').run(id);
    db.prepare('DELETE FROM event_occurrences WHERE event_id = ?').run(id);
    db.prepare('DELETE FROM events WHERE id = ?').run(id);
  }
  assert.equal(db.prepare("SELECT COUNT(*) AS n FROM events WHERE name LIKE 'S6 %'").get().n, 0);
  assert.equal(db.prepare('SELECT COUNT(*) AS n FROM event_occurrences').get().n, 5);
});

// ---- Event page rendering + SEO (noindex) --------------------------------
// The editorial copy must apply only to the verified 2026 Vernon season.
function withFieldOfScreamsFixture(overrides, check) {
  const event = s5create({
    name: 'Field of Screams XIII: The Unlucky', region: 'vernon', venue_id: null,
    venue_name_text: "Historic O'Keefe Ranch, 9380 Hwy 97 N, Vernon",
    description: 'Original stored event description.',
    categories: ['holiday-seasonal'],
    occurrences: [{ start_date: '2026-09-25', end_date: '2026-11-01', start_time: '18:30' }],
    ...overrides,
  });
  try { check(event); } finally {
    db.prepare('DELETE FROM event_enrichment_log WHERE event_id = ?').run(event.id);
    db.prepare('DELETE FROM event_categories WHERE event_id = ?').run(event.id);
    db.prepare('DELETE FROM event_occurrences WHERE event_id = ?').run(event.id);
    db.prepare('DELETE FROM events WHERE id = ?').run(event.id);
  }
}

test('Field of Screams: active page has practical SEO copy and official visitor links without data changes', () => {
  withFieldOfScreamsFixture({}, (event) => {
    const before = JSON.stringify(app.getEventById(event.id));
    const html = app.renderEventPage(event, null, { now: new Date('2026-10-10T19:00:00Z') });
    assert.match(html, /<title>Field of Screams Vernon 2026: Dates &amp; Tickets \| Okanagan Roam<\/title>/);
    assert.match(html, /<meta name="description" content="Explore Field of Screams in Vernon, September 25–November 1, 2026\./);
    assert.match(html, /rel="canonical" href="https:\/\/okanaganroam.com\/vernon\/events\/field-of-screams-xiii-the-unlucky"/);
    assert.match(html, /<h1>Field of Screams XIII: The Unlucky<\/h1>/);
    assert.match(html, /href="https:\/\/fosvernon.fearticket.com\/"/);
    assert.match(html, /href="https:\/\/fosokanagan.com\/plan-your-visit\/ticket-availability\/"/);
    assert.match(html, /St\. Anne’s Road/);
    assert.match(html, /not recommended for children under 12/);
    assert.match(html, /href="\/trip"/);
    assert.doesNotMatch(html, /Original stored event description\./);
    const schema = s5jsonLd(html).find((s) => s['@type'] === 'Event');
    assert.match(schema.description, /^Field of Screams returns to Historic O’Keefe Ranch/);
    assert.match(schema.startDate, /^2026-09-25T18:30/);
    assert.match(schema.endDate, /^2026-11-01/);
    assert.equal(JSON.stringify(app.getEventById(event.id)), before);
  });
});

