// ==== Batch 4A (2026-09-27): Food & Drink venue pages use the themed shell ====
//
// Restaurant, cafe, pub, brewery, cocktail lounge and distillery VENUE pages
// move from the old siteHeader() shell to the existing themed shell (site
// header + navigation, Trip tray, <main>, app.css / app.js, body.golf-page,
// hero title). Shell only: SEO head, content, CTAs and links are unchanged;
// no Favorite / Add to Trip, analytics or data-track; listings and winery
// pages are untouched.
const BATCH4A_FD_TYPES = ['restaurant', 'cafe', 'pub', 'brewery', 'cocktail', 'distillery'];
const batch4aVenue = (type) => ({ ...app.findVenueBySlug('kelowna', 'restaurant', 'test-trattoria'), type });

test('Batch 4A: the venue-shell predicate covers exactly the themed types plus the six Food & Drink types (and, since Stage 4.1, winery)', () => {
  assert.deepEqual([...app.THEMED_VENUE_SHELL_TYPES].sort(), [...BATCH4A_FD_TYPES, 'winery'].sort());
  for (const t of [...BATCH4A_FD_TYPES, 'winery', 'golf', 'beach', 'outdoor']) assert.equal(app.usesThemedVenueShell(t), true, t);
  // The listing / card predicate is unchanged.
  assert.deepEqual([...app.THEMED_CATEGORY_TYPES].sort(), ['beach', 'golf', 'indoor', 'outdoor', 'sport', 'tour']); // + indoor, tour (2026-10-11), sport (2026-10-12)
  for (const t of BATCH4A_FD_TYPES) assert.equal(app.usesThemedCategoryLayout(t), false, t);
});

test('Batch 4A: every Food & Drink venue page renders the themed shell with one hero <h1>', () => {
  for (const type of BATCH4A_FD_TYPES) {
    const html = app.renderVenuePage(batch4aVenue(type), [], [], []);
    const label = app.CATEGORY_LABELS[type].singular;
    assert.match(html, /<link rel="stylesheet" href="\/styles\/app\.css">/, type);
    assert.ok(html.indexOf('/styles/app.css') < html.indexOf('<style>'), `${type}: app.css before the inline SEO CSS`);
    assert.match(html, /body\.golf-page \{/, type);
    assert.match(html, /<style>\s*\/\* Hero: same per-type gradient/, `${type}: venue hero polish`);
    assert.match(html, new RegExp(`<body class="golf-page ${type}-page">`), type);
    assert.match(html, /<div id="tripTray">[\s\S]*<button id="tripTrayToggle">/, type);
    assert.ok(html.indexOf('<div id="tripTray">') < html.indexOf('<header id="top">'), `${type}: tray precedes the header`);
    assert.match(html, /<header id="top">/, type);
    assert.doesNotMatch(html, /<header class="top">|Explore the full directory/, `${type}: old shell header gone`);
    assert.equal((html.match(/<main class="wrap-wide golf-main" id="main">/g) || []).length, 1, `${type}: one <main>`);
    assert.ok(html.indexOf('<main ') < html.indexOf('<nav class="breadcrumb"') && html.indexOf('</main>') < html.indexOf('<footer class="home-footer">'), `${type}: content inside <main>, footer after`);
    assert.equal((html.match(/<script src="\/scripts\/app\.js\?v=[0-9a-f]{12}"><\/script>/g) || []).length, 1, type);
    assert.equal((html.match(/<h1[\s>]/g) || []).length, 1, `${type}: exactly one <h1>`);
    assert.match(html, new RegExp(`<div class="venue-hero venue-hero-fallback venue-hero-${type} venue-hero-has-photo">\\s*<img class="venue-hero-img" src="[^"]+"[^>]*>\\s*<span class="venue-hero-type">${label}</span>\\s*<h1>Test Trattoria</h1>\\s*<span class="venue-hero-example">Example photo</span>\\s*</div>`), `${type}: hero carries the title`);
    assert.match(html, /<div class="venue-header">\s*<p class="venue-at-a-glance">/, `${type}: header does not repeat the name`);
    assert.doesNotMatch(html.replace(/<style>[\s\S]*?<\/style>/g, ''), /venue-hero-name/, `${type}: duplicate hero name removed`);
  }
});

test('Batch 4A: Food & Drink venue pages keep their SEO head, content and CTAs; Favorite / Add to Trip since 2026-10-14 (GA4 since Phase A, venue_view/outbound_click since Phase C)', () => {
  for (const type of BATCH4A_FD_TYPES) {
    const venue = batch4aVenue(type);
    const html = app.renderVenuePage(venue, [], [], []);
    const label = app.CATEGORY_LABELS[type];
    const slug = app.CATEGORY_SLUGS[type];
    const canonical = `https://okanaganroam.com/kelowna/${slug}/test-trattoria`;
    const title = `Test Trattoria — ${label.singular} in Kelowna, BC | Okanagan Roam`;
    const head = html.split('</head>')[0];
    assert.equal((head.match(/<title>/g) || []).length, 1);
    assert.ok(head.includes(`<title>${title}</title>`), `${type}: title`);
    assert.ok(head.includes('<meta name="description" content="A fixture restaurant used only by the automated test suite.">'), `${type}: meta description`);
    assert.ok(head.includes(`<link rel="canonical" href="${canonical}">`), `${type}: canonical`);
    assert.ok(head.includes(`<meta property="og:url" content="${canonical}">`), `${type}: og:url`);
    assert.doesNotMatch(head, /name="robots"/, `${type}: indexable, as before`);
    const ld = [...head.matchAll(/<script type="application\/ld\+json">\n([\s\S]*?)\n<\/script>/g)].map((m) => JSON.parse(m[1]));
    assert.equal(ld.length, 2, `${type}: breadcrumb + LocalBusiness JSON-LD`);
    assert.equal(ld[0]['@type'], 'BreadcrumbList');
    assert.deepEqual(ld[0].itemListElement.map((i) => i.item), ['https://okanaganroam.com/', 'https://okanaganroam.com/kelowna', `https://okanaganroam.com/kelowna/${slug}`, canonical]);
    assert.equal(ld[1]['@type'], app.SCHEMA_TYPE_MAP[type] || 'LocalBusiness');
    assert.equal(ld[1].url, canonical);
    assert.match(html, new RegExp(`<nav class="breadcrumb"[^>]*>[\\s\\S]*?<a href="/kelowna/${slug}">${label.plural}</a>[\\s\\S]*?Test Trattoria[\\s\\S]*?</nav>`), `${type}: breadcrumb nav`);
    // Content and CTAs unchanged.
    assert.match(html, /<p class="venue-description">A fixture restaurant used only by the automated test suite\.<\/p>/);
    assert.match(html, new RegExp(`<div class="venue-cta-row" data-venue-id="\\d+" data-venue-region="kelowna" data-venue-category="${type}" data-venue-name="Test Trattoria" data-surface="venue_page">\\s*<a class="cta secondary" href="https://www\\.google\\.com/maps/search/\\?api=1&query=49\\.888,-119\\.496" rel="nofollow noopener" target="_blank" data-track="directions">Get Directions</a>\\s*<a class="cta secondary" href="tel:\\+1 250-555-0100" data-track="phone">Call</a>\\s*<button type="button" class="card-action fav-btn"[^>]*>[\\s\\S]*?Favorite</button>\\s*<button type="button" class="card-action trip-btn"[^>]*>[^<]*Add to trip</button>\\s*</div>`), `${type}: CTA row with Favorite / Add to trip`);
    assert.match(html, new RegExp(`<a class="cta secondary" href="/kelowna/${slug}">Back to ${label.plural} in Kelowna</a>\\s*<a class="cta secondary" href="/kelowna">Explore all of Kelowna</a>`));
    assert.match(html, /<h2>Good to Know<\/h2>/);
    // Favorite / Add to Trip (2026-10-14): one of each, in the CTA row.
    const markup = html.replace(/<style>[\s\S]*?<\/style>/g, '');
    assert.equal((markup.match(/class="card-action fav-btn"/g) || []).length, 1, `${type}: one Favorite`);
    assert.equal((markup.match(/class="card-action trip-btn"/g) || []).length, 1, `${type}: one Add to trip`);
    assert.equal((head.match(/googletagmanager\.com\/gtag\/js\?id=G-J312FGJPSC/g) || []).length, 1, `${type}: one GA4 tag`);
    assert.ok(head.includes("var cfg = { page_type: 'venue' };"), `${type}: page_type venue`);
    // Measurement Phase C: venue_view + outbound_click reporting, plus the Favorite / Add to Trip module.
    assert.equal((html.match(/track\('venue_view', ctx\(\)\)/g) || []).length, 1, `${type}: one venue_view`);
    assert.match(html, /'outbound_click'/, `${type}: outbound_click`);
    assert.match(markup, /okanaganFavorites/, `${type}: Favorite module`);
  }
});

// ---- Stage 4.1 (2026-09-30): winery VENUE pages use the themed venue shell ----
// Same shell as the Golf / Beach / Food & Drink venue pages (site header and
// navigation, Trip tray, <main>, app.css / app.js, body.golf-page, hero <h1>).
// The Favorite / Add to Trip controls stay, with app.js's labels, and the
// engagement script takes its hand-off branch; winery REGION pages are unchanged.
test('Stage 4.1: winery venue pages render the themed shell with one hero <h1> and their Favorite / Add to Trip controls', () => {
  const html = app.renderVenuePage(app.findVenueBySlug('kelowna', 'winery', 'test-winery'), [], [], []);
  assert.match(html, /<body class="golf-page winery-page">/);
  assert.match(html, /<link rel="stylesheet" href="\/styles\/app\.css">/);
  assert.match(html, /id="tripTray"/, 'the site-wide Trip tray is on the page');
  assert.match(html, /<header id="top">/, 'the shared site header and navigation');
  assert.doesNotMatch(html, /<header class="top">|Explore the full directory/, 'the old minimal header is gone');
  assert.match(html, /<main class="wrap-wide golf-main" id="main">/);
  assert.equal((html.match(/<h1[\s>]/g) || []).length, 1, 'exactly one <h1>');
  assert.match(html, /<div class="venue-hero venue-hero-fallback[^"]*">\s*(?:<img class="venue-hero-img"[^>]*>\s*)?<span class="venue-hero-type">Winery<\/span>\s*<h1>Test Winery<\/h1>/, 'the hero carries the <h1>');
  // Favorite / Add to Trip: app.js's labels, and no standalone-page stylesheet.
  assert.match(html, /<button type="button" class="card-action fav-btn" data-fav-name="Test Winery" aria-pressed="false" aria-label="Favorite Test Winery"><svg [^>]*>[\s\S]*?<\/svg> Favorite<\/button>/, 'app.js heart label, as on Golf venue pages');
  assert.match(html, /class="card-action trip-btn" data-trip-name="Test Winery"[^>]*>\u{1F9F3} Add to trip<\/button>/u);
  assert.doesNotMatch(html, /\.venue-card\[data-venue-category="winery"\] \.card-actions/, 'the engagement-only stylesheet is for unthemed pages');
  assert.match(html, /body\.golf-page \.venue-cta-row \.card-action \{/, 'the themed CTA-row button rules apply instead');
  assert.match(html, /<div class="venue-cta-row" data-venue-id="\d+" data-venue-region="kelowna" data-venue-category="winery" data-venue-name="Test Winery" data-surface="venue_page">/);
  // app.js loads first, so the engagement script takes its hand-off branch (as on Golf venue pages).
  const appAt = html.indexOf(`<script src="${app.APP_JS_SRC}"></script>`);
  assert.ok(appAt > 0 && appAt < html.indexOf('var pageCtx'), 'app.js loads before the venue engagement script');
  assert.match(html, /if \(window\.__syncTripButtons \|\| window\.__syncFavButtons\) \{/);
  assert.match(html, /okanaganFavorites/, 'standalone fallback still present');
  // Measurement Phase A/C: one GA4 tag, page_type venue, one venue_view.
  assert.equal((html.match(/googletagmanager\.com\/gtag\/js\?id=G-J312FGJPSC/g) || []).length, 1);
  assert.ok(html.includes("var cfg = { page_type: 'venue' };"));
  assert.equal((html.match(/track\('venue_view', ctx\(\)\)/g) || []).length, 1);
  assert.doesNotMatch(html, /data-track=/, 'the fixture has no website, phone or address');
});

