test('Outdoor activity cards (2026-09-22 explorer): nine data-model activities in the approved order, live ones are filter toggles with a Guide link, below-gate ones are inert "Coming soon" tiles; no invented slugs', () => {
  const cards = app.OUTDOOR_ACTIVITY_CARDS;
  assert.deepEqual(cards.map((c) => c.title), ['Hiking & Trails', 'Cycling & Bike Trails', 'Water Activities', 'Adventure', 'Fishing', 'Winter', 'Nature & Wildlife', 'Viewpoints & Lookouts', 'Camping']);
  assert.equal(cards.length, 9, 'one card per data-model activity');
  for (const c of cards) assert.ok(app.OUTDOOR_ACTIVITY_BY_SLUG[c.slug], `${c.title} maps onto an existing activity slug (${c.slug})`);
  assert.deepEqual([...cards.map((c) => c.slug)].sort(), [...app.OUTDOOR_ACTIVITIES.map((a) => a.slug)].sort(), 'exactly the nine activities, nothing invented');

  const meta = { reason: 'test', batch_id: 'outdoors-showcase-test', reviewed_by: null };
  const ids = []; const added = [];
  const mk = (name, region, slug) => { const info = insert.run({ name, region, type: 'outdoor', cuisine: null, phone: null, price: null, reviews: null, rating: null, description: `${name} fixture.`, address: null, latitude: null, longitude: null, hours: null, slug }); ids.push(Number(info.lastInsertRowid)); return Number(info.lastInsertRowid); };
  const add = (kind, id) => { const r = app.guardedCollectionMembershipUpdate(kind, id, 'add', null, meta); assert.equal(r.ok, true, JSON.stringify(r)); added.push([kind, id]); };
  try {
    // Nothing live yet: every card is a "Coming soon" tile, none is a control.
    const none = app.renderOutdoorActivityShowcaseHtml();
    assert.equal((none.match(/<button type="button" class="outdoor-activity-card/g) || []).length, 0);
    assert.equal((none.match(/Coming soon/g) || []).length, 9);
    assert.doesNotMatch(none, /outdoor-activity-card-link/, 'no guide links while nothing is live');
    // Make hiking live (3 members) -> only Hiking is a toggle (+ guide link to the existing activity page).
    const a = mk('Showcase A', 'kelowna', 'showcase-a'), b = mk('Showcase B', 'vernon', 'showcase-b'), c = mk('Showcase C', 'apex', 'showcase-c');
    add('activity_hiking', a); add('activity_hiking', b); add('activity_hiking', c);
    const html = app.renderOutdoorActivityShowcaseHtml();
    assert.match(html, /<h2 class="category-subsection-heading" id="outdoorActivitiesHeading">Choose Activity\(s\)<\/h2>/);
    assert.match(html, /<div class="outdoor-activity-card-grid" role="group" aria-label="Choose activities" data-filter="activity">/);
    assert.match(html, /<button type="button" class="outdoor-activity-card outdoor-activity-card-hiking outdoor-activity-toggle" data-activity="hiking" aria-pressed="false" aria-label="Hiking &amp; Trails"><span class="outdoor-activity-card-check" aria-hidden="true">&#10003; Selected<\/span>[\s\S]*?Hiking &amp; Trails<\/span>\s*<span class="outdoor-activity-card-count"><span class="outdoor-activity-count">3<\/span> <span class="outdoor-activity-count-noun">destinations<\/span><\/span>/);
    assert.match(html, /<a class="outdoor-activity-card-link" href="\/outdoors\/hiking" aria-label="Hiking &amp; Trails guide">Guide &rarr;<\/a>/);
    assert.equal((html.match(/<button type="button" class="outdoor-activity-card/g) || []).length, 1, 'only the live activity is a toggle');
    assert.equal((html.match(/outdoor-activity-card-link/g) || []).length, 1, 'only the live activity has a guide link');
    assert.match(html, /<div class="outdoor-activity-card outdoor-activity-card-fishing outdoor-activity-card-pending" aria-disabled="true">[\s\S]*?Fishing<\/span>\s*<span class="outdoor-activity-card-soon">Coming soon<\/span>/, 'Fishing exists in the data model but has no members in the fixture, so it is a Coming soon tile');
    assert.match(html, /<div class="outdoor-activity-card outdoor-activity-card-water outdoor-activity-card-pending" aria-disabled="true">/, 'an existing activity below the gate is a Coming soon tile too');
    assert.doesNotMatch(html, /href="\/outdoors\/(fishing|water|camping)"|data-activity="(fishing|water|camping)"/, 'no dead links or controls for below-gate activities');
    assert.doesNotMatch(html, /<details|View All Outdoor Activities|outdoor-activity-card-secondary|boating|climbing/, 'no reveal, no secondary grid, no non-data-model cards');
    // Order: the nine cards in one grid in the approved order.
    assert.deepEqual([...html.matchAll(/outdoor-activity-card outdoor-activity-card-([a-z]+)/g)].map((m) => m[1]), cards.map((c) => c.key));
    // Pressed + contextual count from the server-applied URL state.
    const pressed = app.renderOutdoorActivityShowcaseHtml({ selectedActivities: ['hiking'], counts: { activities: { hiking: 2 } } });
    assert.match(pressed, /data-activity="hiking" aria-pressed="true"/);
    assert.match(pressed, /<span class="outdoor-activity-count">2<\/span> <span class="outdoor-activity-count-noun">destinations<\/span>/);
    assert.match(pressed, /<span class="outdoor-step-status" id="outdoorActivityStatus">1 selected<\/span>/);
    assert.match(html, /<span class="outdoor-step-status" id="outdoorActivityStatus" hidden><\/span>/);
    assert.match(app.renderOutdoorActivityShowcaseHtml({ counts: { activities: { hiking: 1 } } }), /<span class="outdoor-activity-count">1<\/span> <span class="outdoor-activity-count-noun">destination<\/span>/, 'singular noun');
    // Images only when the asset exists; otherwise no <img> (navy fallback), never a broken src.
    for (const cd of app.OUTDOOR_ACTIVITY_CARDS) {
      const p = app.outdoorActivityImagePath(cd.key);
      if (p) assert.match(html, new RegExp(`<img class="outdoor-activity-card-img" src="${p.replace(/\//g, '\\/')}" width="1376" height="768" alt="" loading="lazy">`));
      else assert.doesNotMatch(html, new RegExp(`/images/outdoors/${cd.key}\\.webp`));
    }
    // All nine cards carry approved art (nature / viewpoints / camping added 2026-09-22), 1376x768 WebP under public/images/outdoors.
    for (const k of ['hiking', 'cycling', 'water', 'adventure', 'fishing', 'winter', 'nature', 'viewpoints', 'camping']) assert.equal(app.outdoorActivityImagePath(k), `/images/outdoors/${k}.webp`, `approved image wired for ${k}`);
    assert.equal(app.outdoorActivityImagePath('boating'), null, 'a key with no file gets no <img>');
    // The showcase renderer above is retained (and still resolves the approved
    // art) but since 2026-09-24 it is NOT placed on the landing: the landing
    // uses the compact chip row instead. Placement is asserted here.
    const landing = outdoorMarkupOnly(app.renderCategoryAllRegionsPage('outdoor', app.getVenuesByCategory('outdoor')));
    const iIntro = landing.indexOf('<p class="outdoor-intro outdoors-intro">'), iSearch = landing.indexOf('id="outdoorsSearch"'), iActs = landing.indexOf('outdoors-act-row'), iRegion = landing.indexOf('id="outdoorRegionsBtn"'), iRes = landing.indexOf('id="outdoorResults"');
    assert.ok(iIntro > 0 && iSearch > iIntro && iActs > iSearch && iRegion > iActs && iRes > iRegion, 'intro -> search -> activity chips -> Regions -> results');
    assert.doesNotMatch(landing, /outdoor-activity-showcase|outdoor-activity-card-img|Choose Activity\(s\)|Choose Region\(s\)/, 'no image tiles and no step headings on the landing');
    assert.match(landing, /<button type="button" class="outdoor-filter-chip" data-region="kelowna" aria-pressed="false">Kelowna<span class="outdoor-activity-count">\d+<\/span>/, 'region chip and label untouched');
    // Activity pages and region pages do not carry the activity cards.
    // (markup only -- the shared outdoor <style> block legitimately carries the card class names on every outdoor page)
    assert.doesNotMatch(outdoorMarkupOnly(app.renderOutdoorActivityPage(app.OUTDOOR_ACTIVITY_BY_SLUG.hiking, app.getOutdoorActivityVenues(app.OUTDOOR_ACTIVITY_BY_SLUG.hiking))), /outdoor-activity-showcase|outdoor-activity-toggle/);
    assert.doesNotMatch(outdoorMarkupOnly(app.renderCategoryPage('kelowna', 'outdoor', app.getVenuesByRegionCategory('kelowna', 'outdoor'), [])), /outdoor-activity-showcase|outdoor-activity-toggle/);
  } finally {
    for (const [kind, id] of added) app.guardedCollectionMembershipUpdate(kind, id, 'remove', null, meta);
    for (const id of ids) db.prepare('DELETE FROM venues WHERE id = ?').run(id);
  }
});

// ==== Outdoors explorer (2026-09-22): Choose Region(s) + Choose Activity(s) -> Results ==

test('Outdoors explorer: no filter = every destination; one/many regions (OR); one/many activities (OR); region AND activity; clear = everything; counts, statuses, tags, Clear all, compact cards; homepage/golf/beaches untouched (fixture-only, cleaned up)', () => {
  const meta = { reason: 'test', batch_id: 'outdoors-explorer-test', reviewed_by: null };
  const ids = []; const added = [];
  const mk = (name, region, slug) => { const info = insert.run({ name, region, type: 'outdoor', cuisine: null, phone: null, price: null, reviews: null, rating: null, description: `${name} is a fixture outdoor destination with a description long enough to be clamped by the landing card, used only by the automated test suite.`, address: null, latitude: null, longitude: null, hours: null, slug }); ids.push(Number(info.lastInsertRowid)); return Number(info.lastInsertRowid); };
  const add = (kind, id) => { const r = app.guardedCollectionMembershipUpdate(kind, id, 'add', null, meta); assert.equal(r.ok, true, JSON.stringify(r)); added.push([kind, id]); };
  const homeBefore = fs.readFileSync(path.join(__dirname, '..', 'okanagan.html'), 'utf8');
  const golfBefore = app.renderCategoryAllRegionsPage('golf', app.getVenuesByCategory('golf'));
  const beachBefore = app.renderCategoryAllRegionsPage('beach', app.getVenuesByCategory('beach'));
  try {
    const kelA = mk('Explorer Kelowna Trail', 'kelowna', 'explorer-kelowna-trail');
    const kelB = mk('Explorer Kelowna Campground', 'kelowna', 'explorer-kelowna-campground');
    const penA = mk('Explorer Penticton Bluffs', 'penticton', 'explorer-penticton-bluffs');
    const verA = mk('Explorer Vernon Falls', 'vernon', 'explorer-vernon-falls');
    const osoA = mk('Explorer Osoyoos Desert', 'osoyoos', 'explorer-osoyoos-desert');
    // hiking: kelA, penA, verA, osoA (live); camping: kelB, penA, verA (live); nature: osoA (below gate)
    for (const id of [kelA, penA, verA, osoA]) add('activity_hiking', id);
    for (const id of [kelB, penA, verA]) add('activity_camping', id);
    add('activity_nature', osoA);
    const all = app.getVenuesByCategory('outdoor');
    const map = app.getOutdoorActivitySlugsByVenue(all);
    const byId = (list) => list.map((v) => v.id).sort((x, y) => x - y);
    const visible = (html) => [...outdoorMarkupOnly(html).matchAll(/<li class="venue-card" data-venue-id="(\d+)"(?![^>]* hidden)[^>]*>/g)].map((m) => Number(m[1])).sort((x, y) => x - y);
    const summary = (html) => outdoorMarkupOnly(html).match(/id="outdoorResultsSummary" aria-live="polite">([^<]*)<\/p>/)[1];

    // 1. No filters -> every current outdoor destination, plain count, nothing pressed, statuses hidden, Clear all hidden.
    const plain = app.renderCategoryAllRegionsPage('outdoor', all);
    assert.deepEqual(visible(plain), byId(all));
    assert.equal(summary(plain), `${all.length} outdoor destinations`);
    const pm = outdoorMarkupOnly(plain);
    // Nothing is selected, so the only pressed control is the "All" reset chip.
    assert.deepEqual((pm.match(/aria-pressed="true"/g) || []).length, 1, 'only the All chip is pressed on the unfiltered landing');
    assert.match(pm, /data-activity-all="1" aria-pressed="true"/);
    assert.match(pm, /id="outdoorRegionStatus" hidden>/); assert.match(pm, /id="outdoorActivityStatus" hidden>/);
    assert.doesNotMatch(pm, /id="outdoorClearFilters"|id="outdoorShowResults"/); assert.match(pm, /id="outdoorSelected" hidden><\/div>/);
    // Compact activity chips, live activities only (hiking, camping), no image tiles.
    assert.equal((pm.match(/outdoor-activity-card-img/g) || []).length, 0, 'no image tiles on the landing');
    assert.deepEqual([...pm.matchAll(/data-activity="([a-z]+)" aria-pressed="false"/g)].map((m) => m[1]), ['hiking', 'camping']);
    assert.match(pm, /data-activity="hiking"[^>]*>[\s\S]*?<span class="outdoor-activity-count">4<\/span>/); assert.match(pm, /data-activity="camping"[^>]*>[\s\S]*?<span class="outdoor-activity-count">3<\/span>/);

    // 2. One region.
    const kel = app.renderCategoryAllRegionsPage('outdoor', all, { regions: ['kelowna'], activities: [] });
    const kelExpected = all.filter((v) => v.region === 'kelowna');
    assert.deepEqual(visible(kel), byId(kelExpected));
    assert.equal(summary(kel), `${kelExpected.length} of ${all.length} outdoor destinations`);
    const km = outdoorMarkupOnly(kel);
    assert.match(km, /data-region="kelowna" aria-pressed="true"/); assert.match(km, /id="outdoorRegionStatus">1 selected</); assert.match(km, /id="outdoorActivityStatus" hidden>/);
    assert.match(km, /<div class="outdoor-selected-row"><span class="outdoor-selected-label">Regions<\/span> <button type="button" class="outdoor-selected-tag" data-remove-region="kelowna"/);
    assert.doesNotMatch(km, /outdoor-selected-label">Activities/);
    assert.match(km, /id="outdoorSelectedClear">Clear all</); assert.match(km, /data-activity-all="1" aria-pressed="true"/, 'All stays pressed while only a region is chosen');
    // Activity card counts are contextual to the region selection: hiking in Kelowna = kelA (1), camping in Kelowna = kelB (1).
    assert.match(km, /data-activity="hiking"[^>]*>[^<]*<span class="outdoor-activity-count">1<\/span>/);
    assert.match(km, /data-activity="camping"[^>]*>[^<]*<span class="outdoor-activity-count">1<\/span>/);

    // 3. Multiple regions = OR.
    const kp = app.renderCategoryAllRegionsPage('outdoor', all, { regions: ['kelowna', 'penticton'], activities: [] });
    const kpExpected = all.filter((v) => v.region === 'kelowna' || v.region === 'penticton');
    assert.deepEqual(visible(kp), byId(kpExpected));
    assert.equal(summary(kp), `${kpExpected.length} of ${all.length} outdoor destinations`);
    assert.match(outdoorMarkupOnly(kp), /id="outdoorRegionStatus">2 selected</);
    assert.deepEqual(app.filterOutdoorVenues(all, ['kelowna', 'penticton'], [], map).map((v) => v.id).sort((x, y) => x - y), byId(kpExpected));

    // 4. One activity.
    const camp = app.renderCategoryAllRegionsPage('outdoor', all, { regions: [], activities: ['camping'] });
    assert.deepEqual(visible(camp), [kelB, penA, verA].sort((x, y) => x - y));
    assert.equal(summary(camp), `3 of ${all.length} outdoor destinations`);
    const cm = outdoorMarkupOnly(camp);
    assert.match(cm, /data-activity="camping" aria-pressed="true"/); assert.match(cm, /data-activity="hiking" aria-pressed="false"/);
    assert.match(cm, /data-activity-all="1" aria-pressed="false"/, 'All releases when an activity is chosen');
    assert.match(cm, /id="outdoorActivityStatus">1 selected</); assert.match(cm, /id="outdoorRegionStatus" hidden>/);
    assert.match(cm, /<div class="outdoor-selected-row"><span class="outdoor-selected-label">Activities<\/span> <button type="button" class="outdoor-selected-tag" data-remove-activity="camping" aria-label="Remove Camping">Camping<span/);
    assert.doesNotMatch(cm, /outdoor-selected-label">Regions/);
    // Region pill counts are contextual to the activity selection: Kelowna camping = 1, Osoyoos camping = 0.
    assert.match(cm, /data-region="kelowna" aria-pressed="false">Kelowna<span class="outdoor-activity-count">1<\/span>/);
    assert.match(cm, /data-region="osoyoos" aria-pressed="false">Osoyoos<span class="outdoor-activity-count">0<\/span>/);

    // 5. Multiple activities = OR.
    const hc = app.renderCategoryAllRegionsPage('outdoor', all, { regions: [], activities: ['hiking', 'camping'] });
    assert.deepEqual(visible(hc), [kelA, kelB, penA, verA, osoA].sort((x, y) => x - y));
    assert.equal(summary(hc), `5 of ${all.length} outdoor destinations`);
    assert.match(outdoorMarkupOnly(hc), /id="outdoorActivityStatus">2 selected</);

    // 6. Regions AND activities: (Kelowna OR Penticton) AND (Hiking OR Camping).
    const both = app.renderCategoryAllRegionsPage('outdoor', all, { regions: ['kelowna', 'penticton'], activities: ['hiking', 'camping'] });
    assert.deepEqual(visible(both), [kelA, kelB, penA].sort((x, y) => x - y), 'verA (Vernon) and osoA (Osoyoos) are outside the region group; kelB has camping only, kelA hiking only, penA both -- each listed once');
    assert.equal(summary(both), `3 of ${all.length} outdoor destinations`);
    const bm = outdoorMarkupOnly(both);
    assert.match(bm, /id="outdoorResultsSummary" aria-live="polite">3 of \d+ outdoor destinations</);
    assert.match(bm, /data-activity-all="1" aria-pressed="false"/, 'All releases once an activity is chosen');
    assert.match(bm, /<div class="outdoor-selected" id="outdoorSelected"><div class="outdoor-selected-row"><span class="outdoor-selected-label">Regions<\/span> [\s\S]*?data-remove-region="kelowna"[\s\S]*?data-remove-region="penticton"[\s\S]*?<\/div><div class="outdoor-selected-row"><span class="outdoor-selected-label">Activities<\/span> [\s\S]*?data-remove-activity="hiking"[\s\S]*?data-remove-activity="camping"[\s\S]*?<\/div><button type="button" class="outdoor-selected-clear" id="outdoorSelectedClear">Clear all<\/button><\/div>/);
    // Contextual counts in the combined state: Kelowna = Kelowna venues with hiking OR camping (kelA, kelB) = 2; hiking = hiking venues in Kelowna OR Penticton (kelA, penA) = 2.
    assert.match(bm, /data-region="kelowna" aria-pressed="true">Kelowna<span class="outdoor-activity-count">2<\/span>/);
    assert.match(bm, /data-activity="hiking" aria-pressed="true"[^>]*>[\s\S]*?<span class="outdoor-activity-count">2<\/span>/);
    // Same result from the shipped client predicate.
    const clientMatches = new Function(`${app.OUTDOOR_FILTER_CLIENT_PREDICATE_SRC}; return matches;`)();
    assert.deepEqual(all.filter((v) => clientMatches(['kelowna', 'penticton'], ['hiking', 'camping'], v.region, map.get(v.id) || [])).map((v) => v.id).sort((x, y) => x - y), [kelA, kelB, penA].sort((x, y) => x - y));

    // 7. Clear all -> back to the unfiltered landing (server: the empty filter; client: clearAll() re-applies with nothing pressed).
    assert.equal(app.renderCategoryAllRegionsPage('outdoor', all, { regions: [], activities: [] }), plain);
    const script = app.renderOutdoorFilterScriptHtml();
    assert.ok(script.includes("function clearAll(){ chips.forEach(function(c){ c.setAttribute('aria-pressed', 'false'); }); searchTerm = ''; if (searchInput) searchInput.value = ''; apply('push'); }"), 'Clear all resets chips AND the search box');
    assert.ok(script.includes("querySelectorAll('.outdoor-filter-chip, .outdoor-activity-toggle')"), 'the activity chips are driven by the same toggle script as the region pills');
    for (const needle of ['outdoorRegionStatus', 'outdoorActivityStatus', 'updateStepStatus', 'outdoor-activity-count-noun', "row('Regions'", "row('Activities'", 'pushState', 'popstate', 'readUrlIntoChips']) assert.ok(script.includes(needle), `script contains ${needle}`);

    // 8. The landing no longer links to the activity pages (the guides row was
    // removed 2026-09-24); the pages themselves are unchanged and still render.
    assert.doesNotMatch(pm, /outdoors-guide-link|outdoors-guides/);
    const campingPage = app.renderOutdoorActivityPage(app.OUTDOOR_ACTIVITY_BY_SLUG.camping, app.getOutdoorActivityVenues(app.OUTDOOR_ACTIVITY_BY_SLUG.camping));
    assert.match(campingPage, /<h1>Camping in the Okanagan<\/h1>/); assert.match(campingPage, /Explorer Penticton Bluffs/);
    assert.deepEqual(app.listLiveOutdoorActivities().map((a) => a.slug).sort(), ['camping', 'hiking']);

    // 10. Favorite / Add to trip, View details, region line and description survive on every landing card; no phone/website on list cards; compact clamp shipped.
    assert.match(pm, new RegExp(`<li class="venue-card" data-venue-id="${kelA}" data-venue-region="kelowna" data-venue-category="outdoor" data-venue-name="Explorer Kelowna Trail" data-surface="category_card">\\s*<h2><a class="venue-card-link" href="/kelowna/outdoors/explorer-kelowna-trail"><span class="venue-card-name">Explorer Kelowna Trail</span><span class="venue-card-cue" aria-hidden="true">View details &rarr;</span></a></h2>\\s*<p class="venue-meta">Kelowna</p>\\s*<div class="card-slot card-slot-fee"></div>\\s*<div class="card-slot card-slot-desc">\\s*<div class="golf-desc" id="golf-desc-${kelA}"><p>Explorer Kelowna Trail is a fixture[^<]*</p></div>\\s*<button type="button" class="desc-toggle" aria-expanded="false" aria-controls="golf-desc-${kelA}" hidden>Read more &rarr;</button>[\\s\\S]*?<button type="button" class="card-action fav-btn" data-fav-name="Explorer Kelowna Trail"[\\s\\S]*?<button type="button" class="card-action trip-btn" data-trip-name="Explorer Kelowna Trail"`));
    assert.doesNotMatch(pm.slice(pm.indexOf('id="outdoorResults"')), /card-action-website|card-action-phone|tel:/);
    assert.ok(plain.includes('body.outdoor-page #outdoorResults .golf-desc.is-clamped p { -webkit-line-clamp: 3; max-height: calc(3 * 1.45em); }'), 'landing cards clamp to about three lines');
    assert.ok(!app.renderOutdoorActivityPage(app.OUTDOOR_ACTIVITY_BY_SLUG.hiking, app.getOutdoorActivityVenues(app.OUTDOOR_ACTIVITY_BY_SLUG.hiking)).includes('id="outdoorResults"'), 'activity pages keep the four-line clamp (no #outdoorResults there)');
    assert.ok(plain.includes(app.GOLF_APP_SCRIPT_TAG || '/scripts/app.js'), 'trip tray / favourites script still loaded');

    // 11. Landing universe = activity universe (2026-09-22): a beach-type venue that belongs to a live
    // activity is listed on the landing, so the activity card count, the filtered result and the
    // /outdoors/<activity> page all agree; a beach without a live membership is not.
    assert.deepEqual(byId(app.getOutdoorLandingVenues()), byId(all), 'no beach member yet -> the landing is exactly the outdoor-type list');
    assert.doesNotMatch(plain, /Beach page theme/);
    const beach = app.findVenueBySlug('kelowna', 'beach', 'test-beach-park');
    add('activity_hiking', beach.id);
    const universe = app.getOutdoorLandingVenues();
    assert.deepEqual(byId(universe), byId([...all, beach]), 'the beach member joins the landing list');
    assert.equal(app.getOutdoorActivityCounts().hiking, 5);
    const landing = app.renderCategoryAllRegionsPage('outdoor', universe);
    const lm = outdoorMarkupOnly(landing);
    assert.match(lm, /data-activity="hiking"[^>]*>[\s\S]*?<span class="outdoor-activity-count">5<\/span>/, 'the Hiking card shows the activity count (same number as /outdoors/hiking)');
    assert.equal(app.getOutdoorActivityVenues(app.OUTDOOR_ACTIVITY_BY_SLUG.hiking).length, 5);
    assert.equal(summary(landing), `${all.length + 1} outdoor destinations`);
    assert.match(lm, new RegExp(`<li class="venue-card" data-venue-id="${beach.id}" data-venue-region="kelowna" data-venue-category="beach" data-venue-name="Test Beach Park"`));
    assert.match(lm, /href="\/kelowna\/beaches\/test-beach-park"/, 'the beach card links to its own beach page');
    assert.match(landing, /Beach page theme/, 'beach card rules are loaded only now that a beach card is present');
    const hikingOnly = app.renderCategoryAllRegionsPage('outdoor', universe, { regions: [], activities: ['hiking'] });
    assert.deepEqual(visible(hikingOnly), [kelA, penA, verA, osoA, beach.id].sort((x, y) => x - y), 'selecting Hiking shows the 5 the card promised');
    assert.equal(summary(hikingOnly), `5 of ${all.length + 1} outdoor destinations`);
    // The card engagement script (clamp / Read more, impressions, favourite + trip mirroring) covers every allowlisted card type on outdoor surfaces; Golf/Beach pages keep their own selector.
    assert.ok(landing.includes(`querySelectorAll('.venue-card:is([data-venue-category="outdoor"],[data-venue-category="beach"])')`));
    assert.ok(landing.includes(`var HOLDER = ':is([data-venue-category="outdoor"],[data-venue-category="beach"])';`));
    assert.ok(landing.includes("venue_category: card.dataset.venueCategory || 'outdoor'"));
    assert.ok(golfBefore.includes(`querySelectorAll('.venue-card[data-venue-category="golf"]')`) && golfBefore.includes(`var HOLDER = '[data-venue-category="golf"]';`));
    assert.ok(beachBefore.includes(`var HOLDER = '[data-venue-category="beach"]';`));
    // Region outdoor directories are untouched by the landing universe.
    assert.doesNotMatch(outdoorMarkupOnly(app.renderCategoryPage('kelowna', 'outdoor', app.getVenuesByRegionCategory('kelowna', 'outdoor'), [])), /Test Beach Park/);

    // 9. Golf, Beaches and the homepage do not change while the explorer state exists.
    assert.equal(app.renderCategoryAllRegionsPage('golf', app.getVenuesByCategory('golf')), golfBefore);
    assert.equal(app.renderCategoryAllRegionsPage('beach', app.getVenuesByCategory('beach')), beachBefore);
    assert.equal(fs.readFileSync(path.join(__dirname, '..', 'okanagan.html'), 'utf8'), homeBefore, 'the homepage file is never touched by rendering the explorer');
    assert.doesNotMatch(app.renderHomeFooterHTML(true), /outdoor-activity-toggle|outdoorRegionStatus|Choose Activity/, 'the shared footer carries none of the explorer markup');
  } finally {
    for (const [kind, id] of added) app.guardedCollectionMembershipUpdate(kind, id, 'remove', null, meta);
    for (const id of ids) db.prepare('DELETE FROM venues WHERE id = ?').run(id);
  }
  assert.deepEqual(app.listLiveOutdoorActivities(), []);
});

// ==== I.3 (2026-09-20): finalized Outdoor activity order and labels ========

test('I.3: finalized activity display order and labels; slugs unchanged; Camping/Water stay defined but not live', () => {
  assert.deepEqual(app.OUTDOOR_ACTIVITY_DISPLAY_ORDER.slice(0, 6), ['hiking', 'viewpoints', 'nature', 'cycling', 'winter', 'adventure']);
  const sorted = app.sortOutdoorActivitiesForDisplay(app.OUTDOOR_ACTIVITIES);
  assert.deepEqual(sorted.slice(0, 6).map((a) => a.label), ['Hiking & Trails', 'Viewpoints', 'Nature & Wildlife', 'Cycling & Biking', 'Winter', 'Adventure']);
  assert.deepEqual(sorted.slice(0, 6).map((a) => a.slug), ['hiking', 'viewpoints', 'nature', 'cycling', 'winter', 'adventure']);
  assert.deepEqual(sorted.slice(6).map((a) => a.slug), ['fishing', 'camping', 'water'], 'Fishing (2026-09-21), Camping and Water remain defined, after the six');
  for (const slug of ['hiking', 'viewpoints', 'nature', 'cycling', 'winter', 'adventure', 'fishing', 'camping', 'water']) assert.ok(app.OUTDOOR_ACTIVITY_BY_SLUG[slug], `slug ${slug} unchanged`);
  assert.equal(app.OUTDOOR_ACTIVITIES.length, 9, 'Fishing is the only category added since I.3');
});

test('I.3: the landing filter chips and the activity-page chips present the six live activities in the finalized order (counts on the landing only); Camping/Water not offered; filtering untouched (fixture-only, cleaned up)', () => {
  const meta = { reason: 'test', batch_id: 'outdoors-i3-test', reviewed_by: null };
  const ids = []; const added = [];
  const mk = (name, region, slug) => { const info = insert.run({ name, region, type: 'outdoor', cuisine: null, phone: null, price: null, reviews: null, rating: null, description: `${name} fixture.`, address: null, latitude: null, longitude: null, hours: null, slug }); const id = Number(info.lastInsertRowid); ids.push(id); return id; };
  const add = (kind, id) => { const r = app.guardedCollectionMembershipUpdate(kind, id, 'add', null, meta); assert.equal(r.ok, true, JSON.stringify(r)); added.push([kind, id]); };
  try {
    // Three fixtures in every one of the six activities (in a deliberately scrambled definition order), none in camping/water.
    const a = mk('Order Fixture A', 'kelowna', 'order-fixture-a'), b = mk('Order Fixture B', 'vernon', 'order-fixture-b'), c = mk('Order Fixture C', 'penticton', 'order-fixture-c');
    for (const kind of ['activity_adventure', 'activity_winter', 'activity_cycling', 'activity_nature', 'activity_viewpoints', 'activity_hiking']) for (const id of [a, b, c]) add(kind, id);
    const expectedLabels = ['Hiking & Trails', 'Viewpoints', 'Nature & Wildlife', 'Cycling & Biking', 'Winter', 'Adventure'];
    const expectedSlugs = ['hiking', 'viewpoints', 'nature', 'cycling', 'winter', 'adventure'];
    // Landing chips (multi-select buttons with counts), in order.
    const chips = app.renderOutdoorActivityFilterChips();
    assert.deepEqual([...chips.matchAll(/data-activity="([a-z]+)"/g)].map((m) => m[1]), expectedSlugs);
    assert.deepEqual([...chips.matchAll(/aria-pressed="false">([^<]+)<span class="outdoor-activity-count">(\d+)<\/span>/g)].map((m) => m[1].replace(/&amp;/g, '&')), expectedLabels);
    assert.ok(!chips.includes('data-activity="camping"') && !chips.includes('data-activity="water"'));
    // Activity-page selector (links + active pill), same order, no counts.
    const nav = app.renderOutdoorActivitySelector('nature');
    const navSlugs = [...nav.matchAll(/href="\/outdoors\/([a-z]+)"/g)].map((m) => m[1]);
    assert.deepEqual(navSlugs, ['hiking', 'viewpoints', 'cycling', 'winter', 'adventure'], 'links in order with the active one (nature) rendered as the static pill in its slot');
    assert.match(nav, /Viewpoints<\/a>\s*<span class="category-region-selector-active">Nature &amp; Wildlife<\/span>\s*<a href="\/outdoors\/cycling">/);
    assert.doesNotMatch(nav, /outdoor-activity-count/, 'no counts on activity pages');
    // Full pages: landing keeps the multi-select experience; activity page keeps its layout.
    const all = app.getVenuesByCategory('outdoor');
    const landing = app.renderCategoryAllRegionsPage('outdoor', all);
    const lm = outdoorMarkupOnly(landing);
    assert.deepEqual([...app.renderOutdoorActivityFilterChips().matchAll(/data-activity="([a-z]+)"/g)].map((m) => m[1]), expectedSlugs, 'chip renderer keeps the display order');
    // Since 2026-09-24 the landing PLACES that chip row (the renderer is the single source of chip truth).
    const actRow = lm.match(/<div class="category-region-selector outdoor-filter-group outdoors-act-row"[\s\S]*?<\/div>/)[0];
    assert.deepEqual([...actRow.matchAll(/data-activity="([a-z]+)"/g)].map((m) => m[1]), expectedSlugs, 'the landing chip row is the renderer output, in display order');
    assert.doesNotMatch(lm, /outdoors-guides-links|outdoors-guide-link/, 'no guide links on the landing');
    assert.ok(lm.indexOf('id="outdoorsSearch"') < lm.indexOf('outdoors-act-row') && lm.indexOf('outdoors-act-row') < lm.indexOf('id="outdoorRegionsBtn"') && lm.indexOf('id="outdoorRegionsBtn"') < lm.indexOf('id="outdoorResults"'));
    assert.match(lm, /<button type="button" class="outdoor-filter-chip" data-region="kelowna" aria-pressed="false">/, 'region controls are still toggle buttons');
    assert.match(landing, /replaceState|URLSearchParams/, 'URL query persistence still shipped');
    const winter = app.renderOutdoorActivityPage(app.OUTDOOR_ACTIVITY_BY_SLUG.winter, app.getOutdoorActivityVenues(app.OUTDOOR_ACTIVITY_BY_SLUG.winter));
    assert.deepEqual([...outdoorMarkupOnly(winter).match(/outdoor-activity-selector[\s\S]*?<\/nav>/)[0].matchAll(/(?:href="\/outdoors\/([a-z]+)"|category-region-selector-active">([^<]+)<)/g)].map((m) => m[1] || 'ACTIVE:' + m[2]), ['hiking', 'viewpoints', 'nature', 'cycling', 'ACTIVE:Winter', 'adventure']);
    assert.match(winter, /<h1>Winter in the Okanagan<\/h1>/); assert.match(winter, /<li class="venue-card" /);
    // Filtering semantics untouched.
    const map = app.getOutdoorActivitySlugsByVenue(all.filter((v) => ids.includes(v.id)));
    assert.equal(app.filterOutdoorVenues(all.filter((v) => ids.includes(v.id)), ['kelowna', 'vernon'], ['winter', 'adventure'], map).length, 2);
    assert.equal(app.filterOutdoorVenues(all.filter((v) => ids.includes(v.id)), ['osoyoos'], ['winter'], map).length, 0);
  } finally {
    for (const [kind, id] of added) app.guardedCollectionMembershipUpdate(kind, id, 'remove', null, meta);
    for (const id of ids) db.prepare('DELETE FROM venues WHERE id = ?').run(id);
  }
});


// ==== Outdoors simplification (2026-09-24) ==================================

test('Outdoors simplification: compact surface, no date control anywhere, activity guides kept, statuses kept, results reachable without scrolling past a filter form', () => {
  const meta = { reason: 'test', batch_id: 'outdoors-simplified-test', reviewed_by: null };
  const ids = []; const added = [];
  const mk = (name, region, slug) => { const info = insert.run({ name, region, type: 'outdoor', cuisine: null, phone: null, price: null, reviews: null, rating: null, description: `${name} sits beside a quiet lake and is a fixture destination used only by the automated test suite.`, address: null, latitude: null, longitude: null, hours: null, slug }); const id = Number(info.lastInsertRowid); ids.push(id); return id; };
  const add = (kind, id) => { const r = app.guardedCollectionMembershipUpdate(kind, id, 'add', null, meta); assert.equal(r.ok, true, JSON.stringify(r)); added.push([kind, id]); };
  try {
    const a = mk('Simplified Kelowna Ridge', 'kelowna', 'simplified-kelowna-ridge');
    const b = mk('Simplified Vernon Bluff', 'vernon', 'simplified-vernon-bluff');
    const c = mk('Simplified Penticton Flats', 'penticton', 'simplified-penticton-flats');
    for (const id of [a, b, c]) { add('activity_hiking', id); add('activity_cycling', id); }
    const all = app.getVenuesByCategory('outdoor');
    const html = app.renderCategoryAllRegionsPage('outdoor', all);
    const markup = outdoorMarkupOnly(html);

    // 1. The compact surface exists, in order, and the results follow it directly.
    assert.match(markup, /<input type="search" id="outdoorsSearch" class="outdoors-search-input"/, 'compact search field');
    assert.match(markup, /<div class="category-region-selector outdoor-filter-group outdoors-act-row" role="group" aria-label="Choose activities" data-filter="activity">/, 'compact activity chip row');
    assert.match(markup, /<button type="button" class="outdoors-pop-btn" id="outdoorRegionsBtn" aria-expanded="false" aria-controls="outdoorRegionsPanel">/, 'Regions control');
    assert.match(markup, /<div class="outdoors-pop-panel" id="outdoorRegionsPanel" hidden>/, 'the Regions popover starts closed');
    assert.match(markup, /<p class="outdoors-count" id="outdoorResultsSummary" aria-live="polite">/, 'compact result bar');
    const order = ['<p class="outdoor-intro outdoors-intro">', 'id="outdoorsSearch"', 'outdoors-act-row', 'class="outdoors-controls"', 'id="outdoorRegionsBtn"', 'id="outdoorResultsSummary"', 'id="outdoorSelected"', 'id="outdoorNoResults"', 'id="outdoorResults"'];
    let pos = -1; for (const m of order) { const i = markup.indexOf(m); assert.ok(i > pos, `order: ${m}`); pos = i; }

    // 2. The old oversized surface is gone.
    assert.equal((markup.match(/<img class="outdoor-activity-card-img"/g) || []).length, 0, 'no large activity image tiles');
    assert.doesNotMatch(markup, /Choose Region\(s\)|Choose Activity\(s\)|outdoor-activity-showcase|outdoor-activity-card-grid/, 'no step headings, no tile grid');
    assert.doesNotMatch(markup, /id="outdoorShowResults"|id="outdoorClearFilters"/, 'no Show results / Clear all CTA row');
    assert.equal((markup.slice(0, markup.indexOf('<li class="venue-card"')).match(/<h2[^>]*class="category-subsection-heading"/g) || []).length, 0, 'no visible step headings above the first result');
    assert.match(markup, /<h2 class="visually-hidden" id="outdoorResultsTop">Results<\/h2>/, 'the Results heading is kept for screen readers only');

    // 3. NO date UI or state of any kind (Outdoors is not time-sensitive).
    for (const d of ['data-when', 'when=', 'whatsOnDate', 'outdoorDate', 'Choose Dates', 'This Weekend', 'whatson-date', 'dateWindow'])
      assert.ok(html.indexOf(d) === -1, `no date artefact on Outdoors (${d})`);
    assert.deepEqual(Object.keys(app.parseOutdoorFilterQuery({ regions: 'kelowna', activities: 'hiking', when: 'today', from: '2026-01-01' })), ['regions', 'activities'], 'the query parser gained no date keys');

    // 4. The Activity guides row is gone (removed 2026-09-24 by owner decision):
    // no guide markup, and no link from the landing to any activity page. The
    // nine activity pages themselves are untouched and still render.
    assert.doesNotMatch(markup, /outdoors-guides|outdoors-guide-link|Activity guides/, 'no Activity guides row');
    assert.doesNotMatch(withoutSiteHeader(markup), /href="\/outdoors\/[a-z]+"/, 'the landing links to no /outdoors/<activity> page');
    for (const slug of ['hiking', 'cycling']) {
      const act = app.OUTDOOR_ACTIVITY_BY_SLUG[slug];
      assert.ok(app.renderOutdoorActivityPage(act, app.getOutdoorActivityVenues(act)).includes(`<h1>${slug === 'hiking' ? 'Hiking &amp; Trails' : 'Cycling &amp; Biking'} in the Okanagan</h1>`), `/outdoors/${slug} still renders`);
    }

    // 5. Accessibility: both live regions kept, semantic buttons, labelled search.
    assert.match(markup, /<span class="visually-hidden" id="outdoorRegionStatus" hidden><\/span>/);
    assert.match(markup, /<span class="visually-hidden" id="outdoorActivityStatus" hidden><\/span>/);
    const pre = outdoorMarkupOnly(app.renderCategoryAllRegionsPage('outdoor', all, { regions: ['kelowna'], activities: ['hiking', 'cycling'] }));
    assert.match(pre, /id="outdoorRegionStatus">1 selected</); assert.match(pre, /id="outdoorActivityStatus">2 selected</);
    assert.match(markup, /<label class="visually-hidden" for="outdoorsSearch">Search outdoor destinations<\/label>/);
    assert.doesNotMatch(markup, /<div[^>]*data-activity=|<div[^>]*data-region=/, 'filter controls are semantic buttons, not clickable divs');

    // 6. The image assets are NOT deleted -- the resolver still wires all nine.
    for (const k of ['hiking', 'cycling', 'water', 'adventure', 'fishing', 'winter', 'nature', 'viewpoints', 'camping'])
      assert.equal(app.outdoorActivityImagePath(k), `/images/outdoors/${k}.webp`, `${k} art still available`);

    // 7. The landing-only stylesheet ships only here.
    assert.match(html, /body\.outdoor-page \.outdoors-act-row \{/, 'the landing carries its own stylesheet');
    assert.ok(!app.renderOutdoorThemeStyles().includes('outdoors-act-row'), 'and it is not in the shared outdoor theme block');
    assert.ok(!app.renderOutdoorActivityPage(app.OUTDOOR_ACTIVITY_BY_SLUG.hiking, app.getOutdoorActivityVenues(app.OUTDOOR_ACTIVITY_BY_SLUG.hiking)).includes('outdoors-act-row'), 'activity pages are untouched');
    assert.ok(!app.renderCategoryPage('kelowna', 'outdoor', app.getVenuesByRegionCategory('kelowna', 'outdoor'), []).includes('outdoors-act-row'), 'region outdoor pages are untouched');
  } finally {
    for (const [kind, id] of added) app.guardedCollectionMembershipUpdate(kind, id, 'remove', null, meta);
    for (const id of ids) db.prepare('DELETE FROM venues WHERE id = ?').run(id);
  }
});

test('Outdoors simplification: All chip semantics, search over name/region/activity labels, and search ANDed with the existing region+activity predicate', () => {
  const meta = { reason: 'test', batch_id: 'outdoors-search-test', reviewed_by: null };
  const ids = []; const added = [];
  const mk = (name, region, slug, desc) => { const info = insert.run({ name, region, type: 'outdoor', cuisine: null, phone: null, price: null, reviews: null, rating: null, description: desc, address: null, latitude: null, longitude: null, hours: null, slug }); const id = Number(info.lastInsertRowid); ids.push(id); return id; };
  const add = (kind, id) => { const r = app.guardedCollectionMembershipUpdate(kind, id, 'add', null, meta); assert.equal(r.ok, true, JSON.stringify(r)); added.push([kind, id]); };
  try {
    const lake = mk('Search Lakeshore Loop', 'kelowna', 'search-lakeshore-loop', 'A fixture beside the water.');
    const ridge = mk('Search Ridge Climb', 'kelowna', 'search-ridge-climb', 'A fixture on a dry hillside.');
    const vern = mk('Search Vernon Lakeview', 'vernon', 'search-vernon-lakeview', 'A fixture above the valley.');
    for (const id of [lake, ridge, vern]) add('activity_hiking', id);
    add('activity_cycling', lake); add('activity_cycling', ridge); add('activity_cycling', vern);
    const all = app.getVenuesByCategory('outdoor');
    const script = app.renderOutdoorFilterScriptHtml();

    // The All chip: pressed with nothing chosen, released with an activity chosen, and it clears activities.
    const plain = outdoorMarkupOnly(app.renderCategoryAllRegionsPage('outdoor', all));
    assert.match(plain, /<button type="button" class="outdoor-filter-chip outdoors-act-chip outdoors-act-all" data-activity-all="1" aria-pressed="true">All<\/button>/);
    const one = outdoorMarkupOnly(app.renderCategoryAllRegionsPage('outdoor', all, { regions: [], activities: ['hiking'] }));
    assert.match(one, /data-activity-all="1" aria-pressed="false"/);
    assert.match(one, /data-activity="hiking" aria-pressed="true"/);
    assert.ok(script.includes("if (allChip) allChip.setAttribute('aria-pressed', activities.length ? 'false' : 'true');"), 'All tracks the activity selection');
    assert.ok(script.includes("chips.forEach(function(c){ if (c.getAttribute('data-activity')) c.setAttribute('aria-pressed', 'false'); });"), 'All clears the activity chips');
    assert.ok(script.includes("return !c.hasAttribute('data-activity-all');"), 'All is a reset control, not a filter chip');

    // The search index is built from name + region label + activity labels + meta + description.
    for (const needle of ["card.getAttribute('data-venue-name')", 'LABELS.regions[d.region]', 'LABELS.activities[a]', "card.querySelector('.venue-meta')", "card.querySelector('.golf-desc')", 'function cardMatchesSearch(card)'])
      assert.ok(script.includes(needle), `search index uses ${needle}`);
    // Search is ANDed with the untouched region/activity predicate.
    assert.ok(script.includes('var ok = matches(regions, activities, d.region, d.acts) && cardMatchesSearch(card);'), 'search ANDs with the shared predicate');
    assert.ok(script.includes(app.OUTDOOR_FILTER_CLIENT_PREDICATE_SRC), 'the shared predicate itself is unchanged and shipped verbatim');

    // Everything search needs is really in the rendered card markup.
    const lakeCard = plain.match(new RegExp(`<li class="venue-card" data-venue-id="${lake}"[\\s\\S]*?</li>`))[0];
    assert.match(lakeCard, /data-venue-name="Search Lakeshore Loop"/, 'name is searchable');
    assert.match(lakeCard, /<p class="venue-meta">Kelowna<\/p>/, 'region label is searchable');
    assert.match(lakeCard, /beside the water/, 'description is searchable');
    const labels = JSON.parse(script.match(/var LABELS = (\{[\s\S]*?\});/)[1]);
    assert.equal(labels.regions.kelowna, 'Kelowna');
    assert.equal(labels.activities.hiking, 'Hiking & Trails', 'activity labels ship for the search index');
    // (read from the full page: outdoorMarkupOnly strips <script>, and the map is one)
    const fullPage = app.renderCategoryAllRegionsPage('outdoor', all);
    assert.deepEqual(JSON.parse(fullPage.match(/id="outdoorActivityMap">(\{[\s\S]*?\})<\/script>/)[1])[String(lake)].sort(), ['cycling', 'hiking'], 'the card -> activity map the index reads is present');

    // Search counts as "filtered" in the count line (both twins agree).
    const clientSummary = new Function(`${app.OUTDOOR_SUMMARY_CLIENT_SRC}; return summaryText;`)();
    assert.equal(app.outdoorSummaryText(1, 9, [], [], 'lake'), '1 of 9 outdoor destinations');
    assert.equal(clientSummary(1, 9, [], [], 'lake'), app.outdoorSummaryText(1, 9, [], [], 'lake'));
    assert.equal(app.outdoorSummaryText(9, 9, [], []), '9 outdoor destinations', 'the existing wording is unchanged without search');
    assert.equal(clientSummary(9, 9, [], []), app.outdoorSummaryText(9, 9, [], []));

    // Clear all resets activities, regions AND the search box; no date state exists to keep.
    assert.ok(script.includes("function clearAll(){ chips.forEach(function(c){ c.setAttribute('aria-pressed', 'false'); }); searchTerm = ''; if (searchInput) searchInput.value = ''; apply('push'); }"));
    assert.ok(!script.includes("data-when") && !script.includes("'when='"), 'no date state in the Outdoors script');
    // Region multi-select still combines with activities through the unchanged server predicate.
    const map = app.getOutdoorActivitySlugsByVenue(all);
    assert.deepEqual(app.filterOutdoorVenues(all, ['kelowna'], ['hiking'], map).map((v) => v.id).filter((id) => ids.includes(id)).sort((x, y) => x - y), [lake, ridge].sort((x, y) => x - y));
    assert.deepEqual(app.filterOutdoorVenues(all, ['kelowna', 'vernon'], ['cycling'], map).map((v) => v.id).filter((id) => ids.includes(id)).sort((x, y) => x - y), [lake, ridge, vern].sort((x, y) => x - y));
  } finally {
    for (const [kind, id] of added) app.guardedCollectionMembershipUpdate(kind, id, 'remove', null, meta);
    for (const id of ids) db.prepare('DELETE FROM venues WHERE id = ?').run(id);
  }
});


// ==== Food & Drink hub (2026-09-24): the directory at /food-drink ==========

test('Food & Drink hub: compact surface at /food-drink -- search, venue-type chips with All, the two popovers, the result bar, and no oversized tiles or step headings', () => {
  const venues = app.getFoodDrinkHubVenues();
  assert.ok(venues.length > 0, 'the hub has an inventory');
  const html = app.renderFoodDrinkHubPage(venues, app.parseFoodDrinkFilterQuery({}));
  const markup = outdoorMarkupOnly(html);

  // Page identity, canonical and schema.
  assert.equal((html.match(/<h1[\s>]/g) || []).length, 1);
  assert.match(html, /<h1 id="fdHeading">Food &amp; Drink in the Okanagan<\/h1>/);
  assert.match(html, /<title>Food &amp; Drink in the Okanagan \| Okanagan Roam<\/title>/);
  assert.match(html, /rel="canonical" href="https:\/\/okanaganroam\.com\/food-drink"/);
  assert.match(html, /"@type":"ItemList"/);
  assert.match(markup, /<body class="golf-page outdoor-page fd-page">/);
  assert.match(markup, /Home<\/a>[\s\S]{0,80}Food &amp; Drink/, 'breadcrumb');

  // The compact surface, in order, with the results directly after it.
  assert.match(markup, /<input type="search" id="fdSearch" class="fd-search-input"/, 'compact search');
  assert.match(markup, /<div class="fd-type-row" role="group" aria-label="Choose venue types" data-filter="fd-type">/, 'venue-type chip row');
  assert.match(markup, /<button type="button" class="fd-pop-btn" id="fdFeaturesBtn" aria-expanded="false" aria-controls="fdFeaturesPanel">/);
  assert.match(markup, /<button type="button" class="fd-pop-btn" id="fdRegionsBtn" aria-expanded="false" aria-controls="fdRegionsPanel">/);
  assert.match(markup, /<div class="fd-pop-panel" id="fdFeaturesPanel" hidden>/, 'features popover starts closed');
  assert.match(markup, /<div class="fd-pop-panel" id="fdRegionsPanel" hidden>/, 'regions popover starts closed');
  assert.match(markup, /<p class="fd-count" id="fdResultsSummary" aria-live="polite">/, 'compact result bar');
  const order = ['class="outdoor-intro fd-intro"', 'id="fdSearch"', 'class="fd-type-row"', 'class="fd-controls"', 'id="fdFeaturesBtn"', 'id="fdRegionsBtn"', 'id="fdResultsSummary"', 'id="fdSelected"', 'id="fdNoResults"', 'id="fdResults"'];
  let pos = -1; for (const m of order) { const i = markup.indexOf(m); assert.ok(i > pos, `order: ${m}`); pos = i; }

  // None of the old oversized directory treatment.
  // The one exception (2026-10-12): the category banner, hidden unless a single type is chosen.
  assert.equal((markup.replace(/<div class="category-banner" id="fdBanner"[^>]*><img [^>]*><\/div>/, '').match(/<img/g) || []).length, 0, 'no images above or among the controls besides the category banner');
  assert.doesNotMatch(markup.slice(0, markup.indexOf('<li class="venue-card"')), /<h2[^>]*class="category-subsection-heading"/, 'no visible step headings above the results');
  assert.match(markup, /<h2 class="visually-hidden" id="fdResultsTop">Results<\/h2>/, 'the Results heading is screen-reader only');
  // Sort (2026-10-14): the one dropdown is the native Sort select in the result bar.
  assert.equal((markup.replace(/<dialog[\s\S]*?<\/dialog>/g, '').match(/<select/g) || []).length, 1, 'one dropdown control (the footer Contact dialog has its own topic select)');
  assert.match(markup, /<div class="fd-resultbar">[\s\S]*?<select id="fdSort" class="fd-sort-select"><option value="recommended" selected>Recommended<\/option><option value="rating">Top rated<\/option><option value="az">A\u2013Z<\/option><\/select>/, 'the Sort control sits in the result bar');

  // Venue types: All + the five, with counts, and NO wineries.
  assert.deepEqual([...markup.matchAll(/data-fd-type="([a-z]+)"/g)].map((m) => m[1]), app.FD_HUB_TYPES.map((t) => t.type));
  assert.match(markup, /<button type="button" class="outdoor-filter-chip fd-type-chip fd-type-all" data-fd-type-all="1" aria-pressed="true">All<\/button>/);
  assert.doesNotMatch(markup, /data-fd-type="winery"/, 'Wineries are not a Food & Drink type here');
  assert.doesNotMatch(markup, /data-venue-category="winery"/, 'no winery cards on the Food & Drink hub');
  assert.ok(venues.every((v) => v.type !== 'winery'), 'the hub universe excludes wineries entirely');

  // Features: every chip is a real BOOL_FIELDS column, never an invented one.
  assert.equal(app.FD_HUB_FEATURES.length, 14, 'the twelve researched badges plus Open Early / Open Late');
  for (const f of app.FD_HUB_FEATURES) assert.ok(app.BOOL_FIELDS.includes(f.key), `${f.key} is a real venue column`);
  assert.deepEqual([...markup.matchAll(/data-fd-feature="([a-z_]+)"/g)].map((m) => m[1]), app.FD_HUB_FEATURES.map((f) => f.key));

  // Regions: the canonical list, from the SAME renderer the other directories use.
  for (const r of Object.keys(app.REGION_LABELS)) assert.match(markup, new RegExp(`data-region="${r}"`), `canonical region chip for ${r}`);
  assert.equal((markup.match(/class="outdoor-region-group-block/g) || []).length, app.FOOTER_REGION_GROUPS.length, 'FOOTER_REGION_GROUPS grouping reused verbatim');

  // Cards: name is the link with the cue, ONLY Favorite + Add to Trip.
  const list = markup.slice(markup.indexOf('id="fdResults"'));
  assert.match(list, /<span class="venue-card-name">/); assert.match(list, /<span class="venue-card-cue" aria-hidden="true">View details &rarr;<\/span>/);
  assert.match(list, /class="card-action fav-btn"/); assert.match(list, /class="card-action trip-btn"/);
  assert.doesNotMatch(list, /card-action-website|card-action-phone|tel:/, 'no website/phone buttons on list cards');
  assert.match(html, /id="tripTray"|trip-tray/, 'Trip tray present'); assert.match(html, /<script src="\/scripts\/app\.js\?v=[0-9a-f]{12}"><\/script>/);
  assert.match(html, /<footer class="home-footer"/);
});

test('Food & Drink hub: types OR, features AND, regions OR, AND between groups; All resets types; search; Clear all; URL query; counts', () => {
  const venues = app.getFoodDrinkHubVenues();
  const cats = new Map(venues.map((v) => [v.id, (v.fd_categories && v.fd_categories.length) ? v.fd_categories : [v.type]]));
  const feats = new Map(venues.map((v) => [v.id, app.FD_HUB_FEATURES.filter((f) => Number(v[f.key]) === 1).map((f) => f.key)]));
  const sum = (html) => outdoorMarkupOnly(html).match(/id="fdResultsSummary" aria-live="polite">([^<]*)</)[1];
  // Cards in the live list (the first FD_PAGE_SIZE matches); the rest sit in
  // the <template> and are revealed by "Show more".
  const liveList = (html) => { const m = outdoorMarkupOnly(html); const a = m.indexOf('id="fdResults"'); const b = m.indexOf('<template id="fdRest">'); return m.slice(a, b === -1 ? undefined : b); };
  const shown = (html) => (liveList(html).match(/<li class="venue-card"/g) || []).length;
  const deferred = (html) => { const m = outdoorMarkupOnly(html); const b = m.indexOf('<template id="fdRest">'); return b === -1 ? 0 : (m.slice(b).match(/<li class="venue-card"/g) || []).length; };

  // No filters -> everything, plain count, only the All chip pressed.
  const plain = app.renderFoodDrinkHubPage(venues, { types: [], features: [], regions: [] });
  assert.equal(sum(plain), `${venues.length} places`);
  // Incremental rendering: the live list holds at most one page; every other
  // card is still on the page, inside the inert template, so nothing is lost.
  assert.equal(shown(plain), Math.min(app.FD_PAGE_SIZE, venues.length), 'first batch only in the render tree');
  assert.equal(shown(plain) + deferred(plain), venues.length, 'every venue is still on the page');
  if (venues.length > app.FD_PAGE_SIZE) assert.match(outdoorMarkupOnly(plain), /<button type="button" class="fd-show-more" id="fdShowMore">Show more<\/button>/, 'Show more offered when there is more');
  assert.equal((outdoorMarkupOnly(plain).match(/aria-pressed="true"/g) || []).length, 1, 'only All is pressed');
  assert.match(outdoorMarkupOnly(plain), /id="fdSelected" hidden><\/div>/);

  // Types OR.
  const one = { types: ['brewery'], features: [], regions: [] };
  const two = { types: ['brewery', 'cafe'], features: [], regions: [] };
  const nOne = app.filterFoodDrinkVenues(venues, one, cats, feats).length;
  const nTwo = app.filterFoodDrinkVenues(venues, two, cats, feats).length;
  assert.ok(nOne > 0 && nTwo > nOne, 'a second type ADDS results (OR)');
  assert.equal(shown(app.renderFoodDrinkHubPage(venues, two)), Math.min(app.FD_PAGE_SIZE, nTwo), 'a filtered render still shows one page');
  assert.equal(shown(app.renderFoodDrinkHubPage(venues, two)) + deferred(app.renderFoodDrinkHubPage(venues, two)), venues.length, 'and still carries every venue for search/filtering');
  assert.equal(sum(app.renderFoodDrinkHubPage(venues, two)), `${nTwo} of ${venues.length} places`);
  assert.match(outdoorMarkupOnly(app.renderFoodDrinkHubPage(venues, one)), /data-fd-type-all="1" aria-pressed="false"/, 'All releases once a type is chosen');

  // Features AND.
  const f1 = { types: [], features: ['patio'], regions: [] };
  const f2 = { types: [], features: ['patio', 'dog_friendly'], regions: [] };
  const nF1 = app.filterFoodDrinkVenues(venues, f1, cats, feats).length;
  const nF2 = app.filterFoodDrinkVenues(venues, f2, cats, feats).length;
  assert.ok(nF1 > 0 && nF2 <= nF1, 'a second feature NARROWS the results (AND)');
  for (const v of app.filterFoodDrinkVenues(venues, f2, cats, feats)) {
    assert.equal(Number(v.patio), 1); assert.equal(Number(v.dog_friendly), 1);
  }

  // Regions OR, and AND between the groups.
  const regions = Object.keys(app.REGION_LABELS).filter((r) => venues.some((v) => v.region === r)).slice(0, 2);
  const r1 = { types: [], features: [], regions: [regions[0]] };
  const r2 = { types: [], features: [], regions };
  assert.ok(app.filterFoodDrinkVenues(venues, r2, cats, feats).length >= app.filterFoodDrinkVenues(venues, r1, cats, feats).length, 'a second region adds results (OR)');
  const combo = { types: ['cafe'], features: ['patio'], regions: [regions[0]] };
  for (const v of app.filterFoodDrinkVenues(venues, combo, cats, feats)) {
    assert.ok((cats.get(v.id) || []).includes('cafe')); assert.equal(Number(v.patio), 1); assert.equal(v.region, regions[0]);
  }
  // The shipped client predicate agrees with the server one, case for case.
  const clientMatches = new Function(`${app.FD_HUB_FILTER_CLIENT_PREDICATE_SRC}; return fdMatches;`)();
  for (const f of [one, two, f1, f2, r1, r2, combo]) {
    const server = app.filterFoodDrinkVenues(venues, f, cats, feats).map((v) => v.id).sort((a, b) => a - b);
    const client = venues.filter((v) => clientMatches(f.types, f.features, f.regions, cats.get(v.id) || [], feats.get(v.id) || [], v.region)).map((v) => v.id).sort((a, b) => a - b);
    assert.deepEqual(client, server, 'client predicate twin matches the server');
  }

  // Selected tags, one row per group, plus Clear all.
  const tagged = outdoorMarkupOnly(app.renderFoodDrinkHubPage(venues, combo));
  assert.match(tagged, /<span class="outdoor-selected-label">Types<\/span>[\s\S]*?data-fd-remove-type="cafe"/);
  assert.match(tagged, /<span class="outdoor-selected-label">Looking for<\/span>[\s\S]*?data-fd-remove-feature="patio"/);
  assert.match(tagged, new RegExp(`<span class="outdoor-selected-label">Regions</span>[\\s\\S]*?data-fd-remove-region="${regions[0]}"`));
  assert.match(tagged, /id="fdSelectedClear">Clear all</);
  // Clearing everything is exactly the unfiltered page.
  assert.equal(app.renderFoodDrinkHubPage(venues, { types: [], features: [], regions: [] }), plain);

  // Query parsing: unknown values dropped, duplicates collapsed, no other keys.
  assert.deepEqual(app.parseFoodDrinkFilterQuery({ types: 'cafe,winery,cafe,nope', features: 'patio,unicorn', regions: 'kelowna,atlantis', when: 'today' }),
    { types: ['cafe'], features: ['patio'], regions: ['kelowna'] });
  assert.deepEqual(Object.keys(app.parseFoodDrinkFilterQuery({})), ['types', 'features', 'regions'], 'no date or sort state');

  // Contextual counts never promise results a tap will not deliver.
  const counts = app.foodDrinkChipCounts(venues, one, cats, feats);
  assert.equal(counts.regions[regions[0]], app.filterFoodDrinkVenues(venues, { types: ['brewery'], features: [], regions: [regions[0]] }, cats, feats).length);

  // The client script ships search over name/region/type/feature/description,
  // the three groups, Clear all and the URL keys -- and no date state.
  const script = app.renderFoodDrinkHubScriptHtml();
  for (const needle of ["card.getAttribute('data-venue-name')", 'LABELS.regions[d.r]', 'LABELS.types[t]', 'LABELS.features[k]', "card.querySelector('.venue-meta')", "card.querySelector('.golf-desc')",
    app.FD_HUB_FILTER_CLIENT_PREDICATE_SRC, "'types='", "'features='", "'regions='", 'pushState', 'popstate', 'fdSelectedClear', 'data-fd-remove-type', 'data-fd-remove-feature', 'data-fd-remove-region'])
    assert.ok(script.includes(needle), `script contains ${needle}`);
  assert.ok(!script.includes("'when='") && !script.includes('data-when'), 'no date state on the Food & Drink hub');
});

test('Food & Drink hub: the /food-drink route serves it, and /browse, the Wine hub, the F&D category/region/venue routes and the other directories are untouched (isolated child process)', async () => {
  const tempDir = fs.mkdtempSync(path.join(os.tmpdir(), 'okanagan-fd-'));
  const projectRoot = path.join(__dirname, '..');
  for (const f of ['server.js', 'db.js', 'okanagan.html']) fs.copyFileSync(path.join(projectRoot, f), path.join(tempDir, f));
  fs.copyFileSync(path.join(projectRoot, 'okanagan.db'), path.join(tempDir, 'okanagan.db'));
  const port = 3599;
  const child = require('node:child_process').spawn(process.execPath, ['-e', `process.env.PORT='${port}'; require('./server.js').startServer();`], { cwd: tempDir, stdio: 'ignore' });
  const get = async (p) => { const r = await fetch(`http://localhost:${port}${p}`); return { status: r.status, text: await r.text() }; };
  try {
    let ready = false;
    for (let i = 0; i < 100 && !ready; i++) {
      try { if ((await fetch(`http://localhost:${port}/robots.txt`)).status === 200) ready = true; } catch (_) { await new Promise((r) => setTimeout(r, 100)); }
    }
    assert.ok(ready, 'child server started');
    const hub = await get('/food-drink');
    assert.equal(hub.status, 200);
    assert.match(hub.text, /<h1 id="fdHeading">Food &amp; Drink in the Okanagan<\/h1>/);
    // Pre-filtered from the URL, server-side.
    const pre = await get('/food-drink?types=cafe&features=patio&regions=kelowna');
    assert.equal(pre.status, 200);
    assert.match(pre.text, /data-fd-type="cafe" aria-pressed="true"/);
    assert.match(pre.text, /data-fd-feature="patio" aria-pressed="true"/);
    assert.match(pre.text, /data-region="kelowna" aria-pressed="true"/);
    assert.match(outdoorMarkupOnly(pre.text), /id="fdResultsSummary" aria-live="polite">\d+ of \d+ places</);
    // /browse is its own hub since 2026-10-05 (it reuses this hub's classes but
    // none of its ids); the okanagan.html wizard page is /browse/classic.
    const browse = await get('/browse');
    assert.equal(browse.status, 200);
    assert.doesNotMatch(browse.text, /id="fdSearch"|id="fdResults"|id="fdVenueData"/, 'the F&D hub ids do not leak onto /browse');
    // Other directories are untouched by the new page. (The F&D category,
    // region and venue pages are asserted in-process below, where the full
    // project tree is available -- this child only carries the four files.)
    for (const p of ['/whats-on']) { // /outdoors joined the shared engine (2026-10-14)
      const r = await get(p);
      assert.equal(r.status, 200);
      assert.doesNotMatch(r.text, /fd-type-row|id="fdSearch"|fd-pop-btn|fd-page/, `${p} carries no Food & Drink hub markup or CSS`);
    }
    // /wineries runs on the same engine since 2026-10-14, without the venue-type chips.
    const wine = await get('/wineries');
    assert.equal(wine.status, 200);
    assert.match(wine.text, /id="fdSearch"/);
    assert.doesNotMatch(wine.text, /class="fd-type-row"/, '/wineries has no Food & Drink type chips');
    // The sitemap lists the hub exactly once.
    const sm = await get('/sitemap.xml');
    assert.equal((sm.text.match(/<loc>https:\/\/okanaganroam\.com\/food-drink<\/loc>/g) || []).length, 1, 'sitemapped once');
  } finally {
    child.kill('SIGTERM');
    fs.rmSync(tempDir, { recursive: true, force: true });
  }
  // The existing Food & Drink category / region / venue surfaces still render
  // and carry none of the hub's markup or CSS.
  // Pick a Food & Drink region/type pair that actually has venues in whatever
  // state the shared fixture is in at this point in the run.
  const fdVenues = app.getFoodDrinkHubVenues();
  const sample = fdVenues.find((v) => app.CATEGORY_SLUGS[v.type]);
  assert.ok(sample, 'the fixture has at least one Food & Drink venue');
  const sameCell = app.getVenuesByRegionCategory(sample.region, sample.type);
  assert.ok(sameCell.length > 0, `${sample.region}/${sample.type} has venues`);
  const catPage = app.renderCategoryPage(sample.region, sample.type, sameCell, []);
  assert.equal((catPage.match(/<h1[\s>]/g) || []).length, 1, 'category page still renders one H1');
  assert.doesNotMatch(catPage, /fd-type-row|id="fdSearch"|fd-pop-btn|fd-page/, 'category page carries no hub markup or CSS');
  const venuePage = app.renderVenuePage(sample, [], [], []);
  assert.doesNotMatch(venuePage, /fd-type-row|id="fdSearch"|fd-pop-btn|fd-page/, 'venue detail page carries no hub markup or CSS');
  assert.match(venuePage, /venue-cta-row|card-action|Get Directions|Visit Website/, 'venue detail page keeps its own CTA row');
});

test('FROZEN HOMEPAGE (Food & Drink hub): "/" and the Outdoors/What\'s On surfaces are byte-identical with the hub in place', () => {
  const homeBefore = fs.readFileSync(path.join(__dirname, '..', 'okanagan.html'), 'utf8');
  // Rendering the hub must not mutate any shared state the other pages read.
  const venues = app.getFoodDrinkHubVenues();
  const outdoorsBefore = app.renderCategoryAllRegionsPage('outdoor', app.getVenuesByCategory('outdoor'));
  const whatsOnBefore = app.renderWhatsOnPage(app.parseWhatsOnPageQuery({}));
  app.renderFoodDrinkHubPage(venues, app.parseFoodDrinkFilterQuery({ types: 'cafe' }));
  assert.equal(fs.readFileSync(path.join(__dirname, '..', 'okanagan.html'), 'utf8'), homeBefore, 'okanagan.html untouched');
  assert.equal(app.renderCategoryAllRegionsPage('outdoor', app.getVenuesByCategory('outdoor')), outdoorsBefore, '/outdoors byte-identical');
  assert.equal(app.renderWhatsOnPage(app.parseWhatsOnPageQuery({})), whatsOnBefore, '/whats-on byte-identical');
  // The shared Outdoors predicate is one implementation and is not this one.
  assert.notEqual(app.FD_HUB_FILTER_CLIENT_PREDICATE_SRC, app.OUTDOOR_FILTER_CLIENT_PREDICATE_SRC);
  assert.ok(outdoorsBefore.includes(app.OUTDOOR_FILTER_CLIENT_PREDICATE_SRC) && whatsOnBefore.includes(app.OUTDOOR_FILTER_CLIENT_PREDICATE_SRC));
  assert.ok(!outdoorsBefore.includes('fd-type-row') && !whatsOnBefore.includes('fd-type-row'));
});


test('Food & Drink incremental rendering: one batch in the render tree, every venue still present and filterable, Show more reveals the rest', () => {
  const venues = app.getFoodDrinkHubVenues();
  assert.ok(venues.length > 0);
  const batched = venues.length > app.FD_PAGE_SIZE;
  const html = app.renderFoodDrinkHubPage(venues, app.parseFoodDrinkFilterQuery({}));
  const markup = outdoorMarkupOnly(html);
  const split = markup.indexOf('<template id="fdRest">');
  assert.ok(split > 0, 'the deferred cards go into an inert <template>, not hidden with CSS');
  const live = markup.slice(markup.indexOf('id="fdResults"'), split);
  const rest = markup.slice(split);

  // At most one batch is in the render tree; everything else is in the template.
  assert.equal((live.match(/<li class="venue-card"/g) || []).length, Math.min(app.FD_PAGE_SIZE, venues.length));
  assert.equal((rest.match(/<li class="venue-card"/g) || []).length, Math.max(0, venues.length - app.FD_PAGE_SIZE));
  // NOT hidden with CSS -- that would keep the DOM cost this exists to remove.
  assert.doesNotMatch(live, /<li class="venue-card"[^>]* hidden/, 'live cards are not hidden-by-attribute');
  assert.ok(!/#fdResults > \.venue-card \{[^}]*display: none/.test(html), 'deferred cards are not merely display:none');

  // Identical card markup either way -- one renderer, no client-side copy.
  const liveFirst = live.match(/<li class="venue-card"[\s\S]*?<\/li>/)[0];
  const restFirst = batched ? rest.match(/<li class="venue-card"[\s\S]*?<\/li>/)[0] : null;
  for (const marker of ['venue-card-link', 'venue-card-name', 'venue-card-cue', 'fav-btn', 'trip-btn']) {
    assert.ok(liveFirst.includes(marker), `${marker} present in live cards`);
    if (restFirst) assert.ok(restFirst.includes(marker), `${marker} present in deferred cards too`);
  }
  // Stable canonical ordering so the client can re-render any subset in order.
  const idx = [...markup.matchAll(/data-fd-i="(\d+)"/g)].map((m) => Number(m[1]));
  assert.equal(idx.length, venues.length, 'every card carries its canonical index');
  assert.equal(new Set(idx).size, venues.length, 'indices are unique');

  // The count is always over the FULL set, never the rendered batch.
  assert.match(markup, new RegExp(`id="fdResultsSummary" aria-live="polite">${venues.length} places<`));
  // Show more is offered only when there is more, and withheld otherwise.
  if (batched) assert.match(markup, /<button type="button" class="fd-show-more" id="fdShowMore">Show more<\/button>/);
  else assert.match(markup, /id="fdShowMore" hidden>/, 'nothing beyond one batch -> no Show more');
  const narrow = { types: [], features: app.FD_HUB_FEATURES.map((f) => f.key), regions: [] };
  const narrowHtml = outdoorMarkupOnly(app.renderFoodDrinkHubPage(venues, narrow));
  const nNarrow = app.filterFoodDrinkVenues(venues, narrow,
    new Map(venues.map((v) => [v.id, (v.fd_categories && v.fd_categories.length) ? v.fd_categories : [v.type]])),
    new Map(venues.map((v) => [v.id, app.FD_HUB_FEATURES.filter((f) => Number(v[f.key]) === 1).map((f) => f.key)]))).length;
  if (nNarrow <= app.FD_PAGE_SIZE) assert.match(narrowHtml, /id="fdShowMore" hidden>/, 'Show more is withheld when everything matching is already shown');

  // SEO: the structured data still describes every venue, not just the batch.
  // (Count inside the ItemList only -- the BreadcrumbList uses ListItem too.)
  const itemList = html.split('<script type="application/ld+json">').map((b) => b.split('</script>')[0].trim())
    .filter((b) => b.startsWith('{') && b.includes('"@type":"ItemList"')).map((b) => JSON.parse(b))[0];
  assert.ok(itemList, 'the ItemList block is present');
  assert.equal(itemList.itemListElement.length, venues.length, 'every venue is still in the ItemList schema');
  assert.ok(itemList.itemListElement.every((x) => x.url && x.name && !x.item), 'each entry keeps its URL and name (summary format)');
  assert.match(html, /rel="canonical" href="https:\/\/okanaganroam\.com\/food-drink"/);
  assert.match(html, /<title>Food &amp; Drink in the Okanagan \| Okanagan Roam<\/title>/);
});

test('Food & Drink incremental rendering: the client filters the FULL pool and wires revealed cards through the shared hook', () => {
  const script = app.renderFoodDrinkHubScriptHtml();
  // The pool is live cards PLUS the template's, so search/filter see all of them.
  assert.ok(script.includes("var tpl = document.getElementById('fdRest');"), 'the template is read');
  assert.ok(script.includes("tpl.content.querySelectorAll('.venue-card')"), 'its cards join the pool without being instantiated');
  assert.ok(script.includes("data-fd-i"), 'the pool is sorted into canonical order');
  // Only the current page is put in the render tree.
  assert.ok(script.includes('var visible = matches.slice(0, page * PAGE_SIZE);'), 'one page of matches is rendered');
  assert.ok(script.includes('results.replaceChildren.apply(results, visible);'));
  assert.ok(script.includes("showMore.hidden = visible.length >= shown;"), 'Show more disappears when everything matching is shown');
  assert.ok(script.includes("showMore.textContent = 'Show more (' + visible.length + ' of ' + shown + ')';"), 'it reports progress');
  // The count is the FULL match total, not the rendered count.
  assert.ok(script.includes('var shown = matches.length;'));
  // Any filter or search change resets to the first page.
  assert.equal((script.match(/page = 1;/g) || []).length >= 6, true, 'every filter/search entry point resets the page');
  assert.ok(script.includes("showMore.addEventListener('click', function(){ page += 1; apply('none'); });"));
  // Revealed cards are wired by the SHARED engagement code, not a copy.
  assert.ok(script.includes('window.__ogWireVenueCards(fresh)'), 'newly revealed cards go through the shared hook');
  const engagement = app.golfCardEngagementScriptHtml('fd', true);
  assert.ok(engagement.includes('window.__ogWireVenueCards = function(list)'), 'the hook exists');
  assert.ok(engagement.indexOf('window.__ogWireVenueCards') < engagement.indexOf('__syncTripButtons'),
    'the hook is defined BEFORE the fav/trip body, which returns out of the IIFE when app.js is present');
  // And the hub wires all five Food & Drink types, not just restaurants.
  for (const t of ['restaurant', 'cafe', 'pub', 'cocktail', 'brewery']) {
    assert.ok(engagement.includes(`[data-venue-category="${t}"]`), `${t} cards get engagement wiring`);
  }
});


