// Phase 3.5: the planner's "tonight"/"right now" clock is the Okanagan wall
// clock (America/Vancouver), never the machine's timezone.
test('Phase 3.5: okanaganClock converts fixed instants to America/Vancouver weekday and minutes', () => {
  // The clock carries the Okanagan calendar date too (2026-10-18), for seasonal hours and closures.
  assert.deepEqual(app.okanaganClock(new Date('2026-09-25T04:06:00Z')), { weekday: 'thu', minutes: 21 * 60 + 6, date: '2026-09-24' });
  assert.deepEqual(app.okanaganClock(new Date('2026-09-25T03:30:00Z')), { weekday: 'thu', minutes: 20 * 60 + 30, date: '2026-09-24' });
  assert.deepEqual(app.okanaganClock(new Date('2026-09-25T01:00:00Z')), { weekday: 'thu', minutes: 18 * 60, date: '2026-09-24' });
  assert.deepEqual(app.okanaganClock(new Date('2026-09-25T07:30:00Z')), { weekday: 'fri', minutes: 30, date: '2026-09-25' });
  // Independent of the process timezone.
  const tz = process.env.TZ;
  try { process.env.TZ = 'Asia/Bangkok'; assert.deepEqual(app.okanaganClock(new Date('2026-09-25T04:06:00Z')), { weekday: 'thu', minutes: 1266, date: '2026-09-24' }); }
  finally { if (tz === undefined) delete process.env.TZ; else process.env.TZ = tz; }
});

// ---- Canonical opening hours (hours.js, Open Now Phase 1) --------------------
// venueHoursStatusAt() = hours.js status on the okanaganClock() wall clock --
// the site's one America/Vancouver path, so offsets come from the runtime's
// IANA data and are never hard-coded here. Instants below are UTC. The
// transitions used are ones that data contains: the last fall-back (Sun
// 2025-11-02, 02:00 PDT -> 01:00 PST) and the spring-forward (Sun 2026-03-08,
// 02:00 PST -> 03:00 PDT). (tzdata 2026c keeps British Columbia on UTC-7 after
// that, so no later fall-back is asserted.)
test('hours.js status on the Okanagan clock: Pacific Time, daylight-saving changes, any process timezone', () => {
  const H = JSON.stringify({ sat: [['18:00', '02:00']], sun: null, mon: [['09:00', '17:00']] });
  const s = (iso) => app.venueHoursStatusAt(H, new Date(iso)).state;
  // Summer (PDT, UTC-7): Monday 09:00 local is 16:00Z.
  assert.equal(s('2026-09-28T15:59:00Z'), 'closed');
  assert.equal(s('2026-09-28T16:00:00Z'), 'open');
  assert.equal(s('2026-09-28T23:59:00Z'), 'open');
  assert.equal(s('2026-09-29T00:00:00Z'), 'closed', 'Monday 17:00 PDT');
  // Winter (PST, UTC-8): Monday 2026-01-05 09:00 local is 17:00Z.
  assert.equal(s('2026-01-05T16:59:00Z'), 'closed');
  assert.equal(s('2026-01-05T17:00:00Z'), 'open');
  // Spring forward, Sat 2026-03-07 18:00-02:00: 01:59 PST is open; the next
  // minute is 03:00 PDT (02:00 never happens), already closed.
  assert.equal(s('2026-03-08T09:59:00Z'), 'open');
  assert.equal(s('2026-03-08T10:00:00Z'), 'closed');
  // The Monday after: 09:00 PDT is 16:00Z.
  assert.equal(s('2026-03-09T15:59:00Z'), 'closed');
  assert.equal(s('2026-03-09T16:00:00Z'), 'open');
  // Fall back, Sat 2025-11-01 18:00-02:00: 01:30 happens twice (PDT, then
  // PST) and is open both times; 02:00 PST closes.
  assert.equal(s('2025-11-02T08:30:00Z'), 'open');
  assert.equal(s('2025-11-02T09:30:00Z'), 'open');
  assert.equal(s('2025-11-02T10:00:00Z'), 'closed');
  // Local midnight, not UTC midnight: Saturday 23:30 PDT is Sunday 06:30Z.
  assert.equal(s('2026-09-27T06:30:00Z'), 'open');
  assert.deepEqual(app.venueHoursStatusAt(H, new Date('2026-09-27T06:30:00Z')).closesAt, { weekday: 'sun', minutes: 120 });
  // The process timezone never matters.
  const tz = process.env.TZ;
  try {
    for (const zone of ['UTC', 'Asia/Bangkok', 'America/New_York']) {
      process.env.TZ = zone;
      assert.equal(s('2026-09-28T16:00:00Z'), 'open', zone);
      assert.equal(s('2025-11-02T09:30:00Z'), 'open', zone);
    }
  } finally { if (tz === undefined) delete process.env.TZ; else process.env.TZ = tz; }
  // Unknown stays unknown on the real clock too.
  assert.equal(app.venueHoursStatusAt(null, new Date('2026-09-28T16:00:00Z')).state, 'unknown');
  assert.equal(app.venueHoursStatusAt(JSON.stringify({ tue: [['09:00', '17:00']] }), new Date('2026-09-28T16:00:00Z')).state, 'unknown', 'Monday not listed');
});

// Stage 2 (2026-09-29): hours.js is the one hours reading for the venue page
// list, the OpeningHoursSpecification and Build My Trip too. The open/closed
// STATUS is still computed only where it was (venueHoursStatusAt and the Food
// & Drink Open Now), and /browse (app.js, frozen) still keeps its own logic.
test('hours.js scope: guarded load; one reading for the venue page, structured data and Build My Trip; status only in venueHoursStatusAt() and the Food & Drink Open Now; never /browse', () => {
  const src = fs.readFileSync(path.join(__dirname, '..', 'server.js'), 'utf8');
  assert.match(src, /const hoursModule = \(\(\) => \{ try \{ return require\('\.\/hours\.js'\); \} catch \(e\) \{ return null; \} \}\)\(\);/, 'guarded require, like golf-data.js');
  assert.equal((src.match(/hoursModule\.statusAt/g) || []).length, 2, 'status is computed only in venueHoursStatusAt and foodDrinkOpenNowInfo');
  assert.equal((src.match(/renderFoodDrinkHubScriptHtml\(\{ openNow: true \}\)/g) || []).length, 1, 'the browser status runs on the /food-drink hub only');
  // Since 2026-10-14 the venue page's open-now line reads it (venueOpenStatus).
  assert.equal((src.match(/venueHoursStatusAt/g) || []).length, 3, 'defined, exported, and read by the venue page status line');
  assert.equal((src.match(/hoursModule\.openingPeriods\(/g) || []).length, 1, 'structured data periods come from hours.js');
  assert.equal((src.match(/hoursModule\.dayHoursText\(/g) || []).length, 1, 'the venue page list comes from hours.js');
  const planner = fs.readFileSync(path.join(__dirname, '..', 'trip-planner.js'), 'utf8');
  assert.match(planner, /const hoursModule = require\('\.\/hours\.js'\);/, 'Build My Trip reads hours through hours.js');
  assert.doesNotMatch(planner, /statusAt/, 'Build My Trip does not claim open/closed status');
  assert.doesNotMatch(fs.readFileSync(path.join(__dirname, '..', 'public', 'scripts', 'app.js'), 'utf8'), /statusAt|hours\.js/, '/browse keeps its own logic');
});

test('Stage 2: the Okanagan clock across 2026-11-01 -- America/Vancouver stays on UTC-7 (no fall-back hour), and Open Now reads it the same in any server timezone', () => {
  const clock = (iso) => app.okanaganClock(new Date(iso));
  // PDT before, permanent UTC-7 after (tz 2026b+): 01:59 -> 02:00 -> 03:00 with no repeated hour.
  assert.deepEqual(clock('2026-11-01T08:59:00Z'), { weekday: 'sun', minutes: 1 * 60 + 59, date: '2026-11-01' });
  assert.deepEqual(clock('2026-11-01T09:00:00Z'), { weekday: 'sun', minutes: 2 * 60, date: '2026-11-01' });
  assert.deepEqual(clock('2026-11-01T10:00:00Z'), { weekday: 'sun', minutes: 3 * 60, date: '2026-11-01' });
  assert.deepEqual(clock('2026-11-15T20:00:00Z'), { weekday: 'sun', minutes: 13 * 60, date: '2026-11-15' });
  assert.deepEqual(clock('2027-01-15T20:00:00Z'), { weekday: 'fri', minutes: 13 * 60, date: '2027-01-15' });
  assert.equal(app.todayLocal(new Date('2026-11-02T07:30:00Z')), '2026-11-02', 'the Okanagan date stays UTC-7 after midnight');
  assert.equal(app.toVancouverIso('2026-11-08', '02:30'), '2026-11-08T02:30:00-07:00', 'event wall times use permanent UTC-7');
  // A 12:00-26:00 venue on Saturday night is open at 01:30 Sunday before and after the change.
  const h = JSON.stringify({ sat: [['12:00', '26:00']], sun: [['12:00', '26:00']] });
  const tz = process.env.TZ;
  try {
    for (const zone of ['UTC', 'Asia/Bangkok', 'America/Vancouver']) {
      process.env.TZ = zone;
      assert.equal(app.venueHoursStatusAt(h, new Date('2026-10-25T08:30:00Z')).state, 'open', `${zone} Oct 25 01:30`);
      assert.equal(app.venueHoursStatusAt(h, new Date('2026-11-08T08:30:00Z')).state, 'open', `${zone} Nov 8 01:30 (UTC-7)`);
      assert.equal(app.venueHoursStatusAt(h, new Date('2026-11-08T09:30:00Z')).state, 'closed', `${zone} Nov 8 02:30 (UTC-7)`);
    }
  } finally { if (tz === undefined) delete process.env.TZ; else process.env.TZ = tz; }
});

// ---- Hours provenance (Open Now Phase 2) ------------------------------------
// hours_source / hours_checked_at: two nullable TEXT columns added by db.js,
// written only by guardedHoursVerifyUpdate() (no route), never backfilled.
test('hours provenance: two nullable TEXT columns with no default; every existing row is NULL', () => {
  const cols = Object.fromEntries(db.prepare('PRAGMA table_info(venues)').all().map((c) => [c.name, c]));
  for (const name of ['hours_source', 'hours_checked_at']) {
    assert.ok(cols[name], `${name} exists`);
    assert.equal(cols[name].type, 'TEXT', name);
    assert.equal(cols[name].notnull, 0, `${name} is nullable`);
    assert.equal(cols[name].dflt_value, null, `${name} has no default`);
  }
  assert.equal(db.prepare('SELECT COUNT(*) AS n FROM venues WHERE hours_source IS NOT NULL OR hours_checked_at IS NOT NULL').get().n, 0, 'nothing backfilled');
  // The public venue shape is unchanged: provenance is not in rowToVenue().
  const any = db.prepare('SELECT id FROM venues WHERE redirect_to IS NULL LIMIT 1').get();
  const v = app.getVenue(any.id);
  assert.equal('hours_source' in v, false);
  assert.equal('hours_checked_at' in v, false);
});

test('hours provenance migration: adds the columns to an existing database without touching its rows, and re-runs as a no-op', async () => {
  const tempDir = fs.mkdtempSync(path.join(os.tmpdir(), 'okanagan-hours-provenance-'));
  try {
    fs.copyFileSync(path.join(__dirname, '..', 'db.js'), path.join(tempDir, 'db.js'));
    const dbFile = path.join(tempDir, 'okanagan.db');
    fs.copyFileSync(path.join(__dirname, '..', 'okanagan.db'), dbFile);
    const { DatabaseSync } = require('node:sqlite');
    // Recreate the pre-Phase-2 shape: same rows, no provenance columns.
    const legacy = new DatabaseSync(dbFile);
    legacy.exec('ALTER TABLE venues DROP COLUMN hours_source');
    legacy.exec('ALTER TABLE venues DROP COLUMN hours_checked_at');
    legacy.prepare("UPDATE venues SET hours = ? WHERE id = (SELECT MIN(id) FROM venues)").run('{"mon":[["16:00","25:00"]],"tue":null}');
    const before = legacy.prepare('SELECT id, hours FROM venues ORDER BY id').all();
    legacy.close();
    const runDbJs = () => new Promise((resolve, reject) => {
      const child = spawn(process.execPath, ['--no-warnings', '-e', "require('./db.js')"], { cwd: tempDir, stdio: ['ignore', 'pipe', 'pipe'] });
      let err = '';
      child.stderr.on('data', (c) => { err += c; });
      child.on('exit', (code) => (code === 0 ? resolve() : reject(new Error(`db.js exited ${code}: ${err}`))));
    });
    await runDbJs();
    await runDbJs();
    const after = new DatabaseSync(dbFile);
    const cols = after.prepare('PRAGMA table_info(venues)').all().filter((c) => c.name === 'hours_source' || c.name === 'hours_checked_at');
    assert.deepEqual(cols.map((c) => [c.name, c.type, c.notnull, c.dflt_value]), [['hours_source', 'TEXT', 0, null], ['hours_checked_at', 'TEXT', 0, null]], 'added once, nullable, no default');
    assert.deepEqual(after.prepare('SELECT id, hours FROM venues ORDER BY id').all(), before, 'no row added, removed or re-written; hours byte-identical (incl. "25:00")');
    assert.equal(after.prepare('SELECT COUNT(*) AS n FROM venues WHERE hours_source IS NOT NULL OR hours_checked_at IS NOT NULL').get().n, 0);
    after.close();
  } finally {
    fs.rmSync(tempDir, { recursive: true, force: true });
  }
});

test('guardedHoursVerifyUpdate: a valid verification records hours, source and date, audited, without changing the public venue shape', () => {
  const now = new Date('2026-09-26T19:00:00Z');
  const original = '{"mon":[["11:00","21:00"]],"tue":[["11:00","21:00"]]}';
  const id = Number(db.prepare("INSERT INTO venues (name, region, type, hours) VALUES ('Hours Provenance Fixture', 'kelowna', 'restaurant', ?)").run(original).lastInsertRowid);
  try {
    const week = { mon: null, tue: [], wed: [['11:00', '14:00'], ['17:00', '22:00']], thu: [['7:00', '15:00']], fri: [['16:00', '25:00']], sat: [['18:00', '02:00']], sun: [['00:00', '24:00']] };
    const meta = { reason: 'checked against the official website', batch_id: 'hours-test-1' };
    const r = app.guardedHoursVerifyUpdate(id, original, { hours: week, hours_source: 'official_website', hours_checked_at: '2026-09-26' }, meta, now);
    assert.equal(r.ok, true, JSON.stringify(r));
    assert.deepEqual(r.changedFields, ['hours', 'hours_source', 'hours_checked_at']);
    const row = db.prepare('SELECT hours, hours_source, hours_checked_at FROM venues WHERE id = ?').get(id);
    assert.equal(row.hours, JSON.stringify(week), 'stored in the existing format, mon..sun, period strings as given');
    assert.equal(row.hours_source, 'official_website');
    assert.equal(row.hours_checked_at, '2026-09-26');
    const logs = db.prepare("SELECT field_name, old_value, new_value, source, source_ref, confidence, batch_id FROM venue_enrichment_log WHERE venue_id = ? ORDER BY id").all(id);
    assert.deepEqual(logs.map((l) => l.field_name), ['hours', 'hours_source', 'hours_checked_at']);
    assert.equal(logs[0].old_value, original);
    assert.equal(logs[1].old_value, null);
    for (const l of logs) {
      assert.equal(l.source, 'official_website');
      assert.equal(l.source_ref, meta.reason);
      assert.equal(l.confidence, 'high');
      assert.equal(l.batch_id, 'hours-test-1');
    }
    // Re-verifying the same hours later only moves the date (one audit row).
    const again = app.guardedHoursVerifyUpdate(id, row.hours, { hours: JSON.stringify(week), hours_source: 'official_website', hours_checked_at: '2026-09-26' }, meta, now);
    assert.deepEqual(again.changedFields, []);
    const later = app.guardedHoursVerifyUpdate(id, row.hours, { hours: week, hours_source: 'official_website', hours_checked_at: '2026-09-26' }, { reason: 'recheck', batch_id: 'hours-test-2' }, new Date('2026-12-01T19:00:00Z'));
    assert.deepEqual(later.changedFields, []);
    const moved = app.guardedHoursVerifyUpdate(id, row.hours, { hours: week, hours_source: 'venue_phone', hours_checked_at: '2026-11-30' }, { reason: 'phoned', batch_id: 'hours-test-3' }, new Date('2026-12-01T19:00:00Z'));
    assert.deepEqual(moved.changedFields, ['hours_source', 'hours_checked_at']);
    // The stored hours still read correctly through hours.js / the venue page data.
    assert.equal(app.venueHoursStatusAt(db.prepare('SELECT hours FROM venues WHERE id = ?').get(id).hours, new Date('2026-09-27T08:30:00Z')).state, 'open', 'Sat 18:00-02:00 at Sun 01:30');
    const v = app.getVenue(id);
    assert.equal('hours_source' in v, false);
    assert.equal('hours_checked_at' in v, false);
  } finally {
    db.prepare('DELETE FROM venue_enrichment_log WHERE venue_id = ?').run(id);
    db.prepare('DELETE FROM venues WHERE id = ?').run(id);
  }
});

test('guardedHoursVerifyUpdate: invalid hours, source, date or meta are rejected and nothing is written', () => {
  const now = new Date('2026-09-26T19:00:00Z');
  const original = '{"mon":[["11:00","21:00"]]}';
  const id = Number(db.prepare("INSERT INTO venues (name, region, type, hours) VALUES ('Hours Reject Fixture', 'kelowna', 'cafe', ?)").run(original).lastInsertRowid);
  const full = (over) => ({ mon: [['09:00', '17:00']], tue: [['09:00', '17:00']], wed: [['09:00', '17:00']], thu: [['09:00', '17:00']], fri: [['09:00', '17:00']], sat: null, sun: null, ...over });
  const good = { hours: full({}), hours_source: 'official_website', hours_checked_at: '2026-09-25' };
  const meta = { reason: 'r', batch_id: 'b' };
  try {
    const cases = [
      [{ ...good, hours: 'not json' }, 'invalid_hours'],
      [{ ...good, hours: '[1,2]' }, 'invalid_hours'],
      [{ ...good, hours: null }, 'invalid_hours'],
      [{ ...good, hours: '' }, 'invalid_hours'],
      [{ ...good, hours: { mon: [['09:00', '17:00']] } }, 'invalid_hours'],
      [{ ...good, hours: full({ holiday: null }) }, 'invalid_hours'],
      [{ ...good, hours: full({ mon: '9-5' }) }, 'invalid_hours'],
      [{ ...good, hours: full({ mon: [['9am', '5pm']] }) }, 'invalid_hours'],
      [{ ...good, hours: full({ mon: [['09:00']] }) }, 'invalid_hours'],
      [{ ...good, hours: full({ mon: [['25:00', '26:00']] }) }, 'invalid_hours'],
      [{ ...good, hours: full({ mon: [['10:00', '35:00']] }) }, 'invalid_hours'],
      [{ ...good, hours: full({ mon: [['09:00', '12:00'], ['bad', '17:00']] }) }, 'invalid_hours'],
      [{ ...good, hours_source: undefined }, 'invalid_source'],
      [{ ...good, hours_source: 'initial_import' }, 'invalid_source'],
      [{ ...good, hours_source: 'Official Website' }, 'invalid_source'],
      [{ ...good, hours_checked_at: undefined }, 'invalid_checked_at'],
      [{ ...good, hours_checked_at: '2026-09-27' }, 'invalid_checked_at'],
      [{ ...good, hours_checked_at: '2026-02-30' }, 'invalid_checked_at'],
      [{ ...good, hours_checked_at: '26/09/2026' }, 'invalid_checked_at'],
      [{ ...good, hours_checked_at: '2026-09-25T10:00' }, 'invalid_checked_at'],
    ];
    for (const [verified, reason] of cases) {
      const r = app.guardedHoursVerifyUpdate(id, original, verified, meta, now);
      assert.equal(r.ok, false, JSON.stringify(verified));
      assert.equal(r.reason, reason, JSON.stringify(verified));
    }
    for (const badMeta of [undefined, {}, { reason: 'r' }, { batch_id: 'b' }, { reason: '  ', batch_id: 'b' }]) {
      assert.equal(app.guardedHoursVerifyUpdate(id, original, good, badMeta, now).reason, 'invalid_meta');
    }
    // Stale expected hours: nothing written, live value reported.
    const stale = app.guardedHoursVerifyUpdate(id, '{"mon":null}', good, meta, now);
    assert.deepEqual(stale, { ok: false, reason: 'mismatch', live: { hours: original } });
    assert.equal(app.guardedHoursVerifyUpdate(999999999, null, good, meta, now).reason, 'venue_not_found');
    const row = db.prepare('SELECT hours, hours_source, hours_checked_at FROM venues WHERE id = ?').get(id);
    assert.deepEqual({ ...row }, { hours: original, hours_source: null, hours_checked_at: null }, 'every rejection left the row untouched');
    assert.equal(db.prepare('SELECT COUNT(*) AS n FROM venue_enrichment_log WHERE venue_id = ?').get(id).n, 0, 'and wrote no audit rows');
    // A redirected (retired) venue is refused.
    const target = db.prepare('SELECT id FROM venues WHERE redirect_to IS NULL AND id != ? LIMIT 1').get(id).id;
    db.prepare('UPDATE venues SET redirect_to = ? WHERE id = ?').run(target, id);
    assert.equal(app.guardedHoursVerifyUpdate(id, original, good, meta, now).reason, 'venue_redirected');
    // A venue with no hours yet can be verified with expected NULL.
    db.prepare('UPDATE venues SET redirect_to = NULL, hours = NULL WHERE id = ?').run(id);
    assert.equal(app.guardedHoursVerifyUpdate(id, original, good, meta, now).reason, 'mismatch');
    assert.equal(app.guardedHoursVerifyUpdate(id, null, good, meta, now).ok, true);
  } finally {
    db.prepare('DELETE FROM venue_enrichment_log WHERE venue_id = ?').run(id);
    db.prepare('DELETE FROM venues WHERE id = ?').run(id);
  }
});

test('hours provenance: absent/NULL provenance is harmless, and hours changed through the plain API path drop stale provenance', () => {
  const now = new Date('2026-09-26T19:00:00Z');
  const week = '{"mon":[["09:00","17:00"]],"tue":[["09:00","17:00"]],"wed":[["09:00","17:00"]],"thu":[["09:00","17:00"]],"fri":[["09:00","17:00"]],"sat":null,"sun":null}';
  const id = Number(db.prepare("INSERT INTO venues (name, region, type, hours) VALUES ('Hours Plain Path Fixture', 'kelowna', 'pub', ?)").run(week).lastInsertRowid);
  const prov = () => ({ ...db.prepare('SELECT hours, hours_source, hours_checked_at FROM venues WHERE id = ?').get(id) });
  try {
    // Never verified: NULL provenance, status and venue data work as before.
    assert.deepEqual(prov(), { hours: week, hours_source: null, hours_checked_at: null });
    assert.equal(app.venueHoursStatusAt(week, new Date('2026-09-28T17:00:00Z')).state, 'open');
    app.updateVenue(id, { hours: '{"mon":null}' });
    assert.deepEqual(prov(), { hours: '{"mon":null}', hours_source: null, hours_checked_at: null }, 'NULL stays NULL');
    app.updateVenue(id, { hours: week });
    // Verified, then edited elsewhere: unrelated edits and identical hours keep it...
    assert.equal(app.guardedHoursVerifyUpdate(id, week, { hours: week, hours_source: 'google_business_profile', hours_checked_at: '2026-09-26' }, { reason: 'r', batch_id: 'b' }, now).ok, true);
    app.updateVenue(id, { phone: '250-555-0199' });
    app.updateVenue(id, { hours: week });
    assert.deepEqual(prov(), { hours: week, hours_source: 'google_business_profile', hours_checked_at: '2026-09-26' });
    // ...but different hours written without verification clear it.
    app.updateVenue(id, { hours: '{"mon":[["10:00","16:00"]]}' });
    assert.deepEqual(prov(), { hours: '{"mon":[["10:00","16:00"]]}', hours_source: null, hours_checked_at: null });
  } finally {
    db.prepare('DELETE FROM venue_enrichment_log WHERE venue_id = ?').run(id);
    db.prepare('DELETE FROM venues WHERE id = ?').run(id);
  }
});

// ---- Open Now on the Food & Drink hub (2026-09-26) ---------------------------
test('Open Now eligibility: verified provenance within the Food & Drink freshness window, no advisory -- everything else is ineligible', () => {
  const now = new Date('2026-09-26T19:00:00Z'); // Okanagan date 2026-09-26
  const hours = '{"mon":[["09:00","17:00"]]}';
  const ok = { hours_source: 'official_website', hours_checked_at: '2026-09-20' };
  const e = (venue, prov, extra = {}) => app.openNowEligibility(venue, prov, { now, ...extra });
  assert.equal(app.OPEN_NOW_MAX_CHECK_AGE_DAYS.food_drink, 180);
  assert.deepEqual(e({ hours: null }, ok), { eligible: false, reason: 'no_hours' });
  assert.deepEqual(e({ hours }, undefined), { eligible: false, reason: 'unverified' });
  assert.deepEqual(e({ hours }, { hours_source: null, hours_checked_at: null }), { eligible: false, reason: 'unverified' });
  assert.deepEqual(e({ hours }, { hours_source: 'initial_import', hours_checked_at: '2026-09-20' }), { eligible: false, reason: 'unverified' });
  assert.deepEqual(e({ hours }, { hours_source: 'official_website', hours_checked_at: '2026-02-30' }), { eligible: false, reason: 'unverified' });
  assert.deepEqual(e({ hours }, { ...ok, hours_checked_at: '2026-03-30' }), { eligible: true, reason: 'ok' }, 'exactly 180 days old');
  assert.deepEqual(e({ hours }, { ...ok, hours_checked_at: '2026-03-29' }), { eligible: false, reason: 'stale' }, '181 days old');
  assert.deepEqual(e({ hours }, { ...ok, hours_checked_at: '2026-09-27' }), { eligible: false, reason: 'stale' }, 'a future check date is not trusted');
  assert.deepEqual(e({ hours }, ok, { hasAdvisory: true }), { eligible: false, reason: 'advisory' });
  assert.deepEqual(e({ hours }, ok), { eligible: true, reason: 'ok' });
});

test('Open Now on /food-drink: per-card status from stored hours on the Okanagan clock (no provenance requirement), and an Open now filter that shows every proven-open venue', () => {
  const pool = app.getFoodDrinkHubVenues();
  const picks = pool.slice(0, 7).map((v) => v.id);
  const saved = picks.map((id) => db.prepare('SELECT id, hours, hours_source, hours_checked_at FROM venues WHERE id = ?').get(id));
  const W = (r) => JSON.stringify(Object.fromEntries(['mon', 'tue', 'wed', 'thu', 'fri', 'sat', 'sun'].map((d) => [d, r])));
  const [A, B, C, D, E, F, G] = picks;
  const setRow = (id, hours, src, chk) => db.prepare('UPDATE venues SET hours = ?, hours_source = ?, hours_checked_at = ? WHERE id = ?').run(hours, src, chk, id);
  try {
    setRow(A, W([['11:00', '21:00']]), 'official_website', '2026-09-20');           // normal
    setRow(B, W([['18:00', '02:00']]), 'official_website', '2026-09-20');           // overnight
    setRow(C, W([['16:00', '25:00']]), 'official_website', '2026-09-20');           // past-midnight notation
    setRow(D, W([['03:30', '23:00']]), 'official_website', '2026-09-20');           // early opening
    setRow(E, '{"mon":[["09:00","17:00"]],"tue":[["09:00","17:00"]]}', 'venue_phone', '2026-09-20'); // Friday not listed
    setRow(F, W([['11:00', '21:00']]), 'official_website', '2026-01-01');           // stale check: no longer matters
    setRow(G, W([['00:00', '24:00']]), null, null);                                 // never verified: no longer matters
    const venues = app.getFoodDrinkHubVenues();
    const none = { types: [], features: [], regions: [] };
    const render = (iso, f = none) => app.renderFoodDrinkHubPage(venues, f, null, new Date(iso));
    const statusOf = (html, id) => { const m = html.match(new RegExp(`data-venue-id="${id}"[\\s\\S]*?<p class="fd-open-status" data-fd-open="(\\w+)">([^<]*)</p>`)); return m ? [m[1], m[2]] : null; };
    // Friday 13:00 PDT
    const fri = render('2026-09-25T20:00:00Z');
    assert.deepEqual(statusOf(fri, A), ['open', 'Open now · Closes 9 PM']);
    assert.deepEqual(statusOf(fri, B), ['closed', 'Closed · Opens 6 PM']);
    assert.deepEqual(statusOf(fri, C), ['closed', 'Closed · Opens 4 PM']);
    assert.deepEqual(statusOf(fri, D), ['open', 'Open now · Closes 11 PM']);
    assert.deepEqual(statusOf(fri, E), ['unknown', 'Hours not listed for today'], 'an unlisted day is unknown, never "Closed"');
    const card = (html, id) => (html.match(new RegExp(`<li class="venue-card" data-fd-i="\\d+" data-venue-id="${id}"[\\s\\S]*?</li>`)) || [''])[0];
    assert.deepEqual(statusOf(fri, F), ['open', 'Open now · Closes 9 PM'], 'stale check: stored hours decide');
    assert.deepEqual(statusOf(fri, G), ['open', 'Open 24 hours'], '24-hour listing without provenance: open on stored hours');
    assert.ok(card(fri, F) && card(fri, G));
    // Stored hours ship to the browser for every venue that has them.
    const data = JSON.parse(fri.match(/<script type="application\/json" id="fdVenueData">([\s\S]*?)<\/script>/)[1]);
    assert.ok(data[String(A)].h && data[String(B)].h && data[String(E)].h);
    assert.ok(data[String(F)].h && data[String(G)].h);
    for (const id of [A, B, C, D, E, F, G]) assert.ok(statusOf(fri, id), `venue ${id} has stored hours: it carries a status line`);
    assert.ok(!fri.includes('Hours not verified') && !/data-fd-open="unverified"/.test(fri));
    // After midnight: Saturday 01:30 PDT -- Friday night's overnight venue is open.
    const sat = render('2026-09-26T08:30:00Z');
    assert.deepEqual(statusOf(sat, B), ['open', 'Open now · Closes 2 AM']);
    assert.deepEqual(statusOf(sat, A), ['closed', 'Closed · Opens 11 AM']);
    assert.deepEqual(statusOf(render('2026-09-26T07:30:00Z'), C), ['open', 'Open now · Closes 1 AM'], '"25:00" at Saturday 00:30');
    assert.deepEqual(statusOf(render('2026-09-26T11:00:00Z'), D), ['open', 'Open now · Closes 11 PM'], 'the 03:30 opening at 04:00');
    // The filter: only proven-open, verified venues; counts and summary follow.
    const onFri = render('2026-09-25T20:00:00Z', { ...none, openNow: true });
    const live = (html) => [...html.split('<template id="fdRest">')[0].matchAll(/<li class="venue-card" data-fd-i="\d+" data-venue-id="(\d+)"/g)].map((m) => Number(m[1])).sort((x, y) => x - y);
    assert.deepEqual(live(onFri), [A, D, F, G].sort((x, y) => x - y));
    assert.match(onFri, new RegExp(`id="fdResultsSummary"[^>]*>4 of ${venues.length} places<`));
    assert.match(onFri, /id="fdOpenNow" data-fd-open-now aria-pressed="true">[\s\S]*?id="fdOpenNowCount">4</);
    assert.match(onFri, /data-fd-remove-open="now"/, 'removable Open now tag');
    assert.match(fri, /id="fdOpenNow" data-fd-open-now aria-pressed="false">[\s\S]*?id="fdOpenNowCount">4</, 'the toggle shows how many are open');
    // AND with the existing groups, over the same set.
    const regionA = venues.find((v) => v.id === A).region;
    const inRegion = venues.filter((v) => v.region === regionA && [A, D, F, G].includes(v.id)).length;
    const both = render('2026-09-25T20:00:00Z', { types: [], features: [], regions: [regionA], openNow: true });
    assert.match(both, new RegExp(`id="fdResultsSummary"[^>]*>${inRegion} of ${venues.length} places<`));
    // Open now off: the existing filters behave exactly as before.
    const plainIds = live(render('2026-09-25T20:00:00Z'));
    assert.equal(plainIds.length, Math.min(app.FD_PAGE_SIZE, venues.length));
    assert.match(fri, new RegExp(`id="fdResultsSummary"[^>]*>${venues.length} places<`));
    // The note and the hub-only script pieces.
    assert.ok(fri.includes('<p class="fd-open-note">Open Now is based on each place’s listed hours. Hours can change for holidays, seasons or special closures — check with the venue before you go.</p>'));
    assert.ok(!fri.includes('recently verified hours'));
    // No hours, or an advisory: still no status, never counted open.
    const advInfo = app.foodDrinkOpenNowInfo(venues, new Map([[A, 'Temporary closure.']]), new Date('2026-09-25T20:00:00Z'), { requireVerified: false });
    assert.equal(advInfo.byId.get(A).eligible, false);
    assert.equal(advInfo.openIds.has(A), false);
    assert.ok(fri.includes('function hoursStatusLabel(') && fri.includes('function okanaganClock(') && fri.includes("q.push('open=now')"));
  } finally {
    for (const r of saved) db.prepare('UPDATE venues SET hours = ?, hours_source = ?, hours_checked_at = ? WHERE id = ?').run(r.hours, r.hours_source, r.hours_checked_at, r.id);
  }
});

test('Open Now on /browse follows stored hours + the Okanagan clock with no provenance; /food-drink still requires it; no hours and advisories stay excluded', () => {
  const pool = app.getBrowseHubVenues();
  const picks = pool.slice(0, 6).map((v) => v.id);
  const saved = picks.map((id) => db.prepare('SELECT id, hours, hours_source, hours_checked_at FROM venues WHERE id = ?').get(id));
  const W = (r) => JSON.stringify(Object.fromEntries(['mon', 'tue', 'wed', 'thu', 'fri', 'sat', 'sun'].map((d) => [d, r])));
  const [A, B, C, D, E, F] = picks;
  const setRow = (id, hours, src, chk) => db.prepare('UPDATE venues SET hours = ?, hours_source = ?, hours_checked_at = ? WHERE id = ?').run(hours, src, chk, id);
  try {
    setRow(A, W([['06:00', '21:00']]), null, null);                          // never verified
    setRow(B, W([['06:00', '21:00']]), 'official_website', '2026-01-01');    // stale check
    setRow(C, W([['06:00', '25:00']]), 'initial_import', '2026-09-20');      // past-midnight notation, bad source
    setRow(D, null, null, null);                                             // no stored hours
    setRow(E, W([['06:00', '21:00']]), null, null);                          // open, but under an advisory
    setRow(F, W([['11:00', '21:00']]), null, null);                          // closed at the test time
    const venues = app.getBrowseHubVenues();
    // Monday 2026-10-05 06:51 PDT
    const now = new Date('2026-10-05T13:51:00Z');
    const advisory = new Map([[E, 'Temporary closure.']]);
    const browse = app.foodDrinkOpenNowInfo(venues, advisory, now, { requireVerified: false });
    assert.deepEqual([...browse.openIds].filter((id) => picks.includes(id)).sort((x, y) => x - y), [A, B, C].sort((x, y) => x - y));
    assert.equal(browse.byId.get(D).eligible, false, 'no stored hours: excluded');
    assert.equal(browse.byId.get(E).eligible, false, 'advisory: no Open Now');
    assert.equal(browse.byId.get(F).state, 'closed');
    // Default (the /food-drink call): the same venues stay ineligible without provenance.
    const fd = app.foodDrinkOpenNowInfo(venues, new Map(), now);
    for (const id of [A, B, C]) assert.equal(fd.openIds.has(id), false, `food-drink: ${id} unverified/stale stays out`);
    // The rendered /browse page: status line, payload hours and count.
    const html = app.renderBrowseHubPage(venues, app.parseBrowseHubQuery({}, app.browseCuisines(venues)), now);
    const card = (id) => (html.match(new RegExp(`<li class="venue-card"[^>]*data-venue-id="${id}"[\\s\\S]*?</li>`)) || [''])[0];
    for (const id of [A, B, C]) assert.match(card(id), /<p class="fd-open-status" data-fd-open="open">/, `card ${id} shows Open now`);
    assert.ok(!card(D).includes('fd-open-status'), 'no hours: no status line');
    const data = JSON.parse(html.match(/<script type="application\/json" id="[^"]*">([\s\S]*?)<\/script>/)[1]);
    assert.ok(data[String(A)].h && !data[String(D)].h);
    const onHtml = app.renderBrowseHubPage(venues, { ...app.parseBrowseHubQuery({}, app.browseCuisines(venues)), openNow: true }, now);
    const openCount = Number(onHtml.match(/id="bhOpenNowCount">(\d+)</)[1]);
    assert.ok(openCount >= 3, 'count includes the unverified open venues');
  } finally {
    for (const r of saved) db.prepare('UPDATE venues SET hours = ?, hours_source = ?, hours_checked_at = ? WHERE id = ?').run(r.hours, r.hours_source, r.hours_checked_at, r.id);
  }
});

test('Open Now on the food & drink pages: the type pages carry it too (2026-10-18), and the browser clock equals okanaganClock()', () => {
  const v = app.getFoodDrinkHubVenues().find((x) => ['restaurant', 'cafe', 'pub'].includes(x.type));
  const scoped = app.renderFoodDrinkHubPage(app.getVenuesByRegionCategory(v.region, v.type), { types: [], features: [], regions: [] }, { region: v.region, type: v.type, categoryCounts: app.getRegionCategoryCounts(v.region) });
  for (const needle of ['fdOpenNow', 'hoursStatusLabel', 'open=now']) assert.ok(scoped.includes(needle), needle);
  // The page script builds okanaganClock() from the same function and options.
  const vm = require('node:vm');
  const ctx = { Intl };
  vm.runInNewContext(`var okanaganClockFormatter = new Intl.DateTimeFormat('en-US', ${JSON.stringify(app.OKANAGAN_CLOCK_FORMAT)}); ${app.okanaganClock.toString()}`, ctx);
  for (const iso of ['2026-09-25T04:06:00Z', '2026-09-26T08:30:00Z', '2026-01-05T17:00:00Z', '2025-11-02T09:30:00Z', '2026-03-08T10:00:00Z']) {
    assert.deepEqual(JSON.parse(JSON.stringify(ctx.okanaganClock(new Date(iso)))), app.okanaganClock(new Date(iso)), iso);
  }
});

// ---- Hidden Gems destination link (2026-09-25) ------------------------------
// /secret-spots lists only the outdoor + beach Hidden Gems. The planner's
// "See everything that matches on Okanagan Roam" link (and the Hero Search
// destination) may point there only when that page really holds every Hidden
// Gem in scope; otherwise there is no link. The Hidden Gem results themselves
// are unchanged.
function withHiddenGemScopeFixtures(fn) {
  const meta = { reason: 'test', batch_id: 'test-hidden-gem-scope' };
  const add = (name, region, type, slug) => {
    db.prepare('INSERT INTO venues (name, region, type, slug, description, rating) VALUES (?, ?, ?, ?, ?, ?)').run(name, region, type, slug, 'Hidden gem scope fixture.', 4.5);
    return db.prepare('SELECT * FROM venues WHERE slug = ? AND region = ?').get(slug, region);
  };
  const made = [
    add('HG Osoyoos Trail', 'osoyoos', 'outdoor', 'hg-osoyoos-trail'),
    add('HG Osoyoos Beach', 'osoyoos', 'beach', 'hg-osoyoos-beach'),
    add('HG Kelowna Park', 'kelowna', 'outdoor', 'hg-kelowna-park'),
    add('HG Kelowna Brewery', 'kelowna', 'brewery', 'hg-kelowna-brewery'),
    add('HG Kelowna Golf', 'kelowna', 'golf', 'hg-kelowna-golf'),
  ];
  for (const v of made) assert.equal(app.guardedCollectionMembershipUpdate('hidden_gem', v.id, 'add', null, meta).ok, true, v.name);
  return Promise.resolve().then(() => fn(Object.fromEntries(made.map((v) => [v.name, v])))).finally(() => {
    for (const v of made) app.guardedCollectionMembershipUpdate('hidden_gem', v.id, 'remove', null, meta);
    for (const v of made) db.prepare('DELETE FROM venues WHERE id = ?').run(v.id);
  });
}

