// ---- Header navigation (2026-09-25 redesign) ---------------------------------
// One shared header (okanagan.html <header id="top">) used by /, /browse,
// /trip and every themed page. Exact items, order, URLs and i18n keys.
const HEADER_SPEC = [
  // Menus refresh (2026-10-14): Map is the /map page; Guides and Secret Spots
  // (no i18n keys, so not parsed here) sit between Map and Dog-Friendly Finds.
  { label: 'Discover', key: 'nav.discover', items: [
    ['/destinations', 'nav.destinations', 'Destinations'],
    ['/local-favorites', 'gems.localFavourites.title', 'Local Favourites'],
    ['/dog-friendly', 'gems.dogFriendly.title', 'Dog-Friendly Finds'],
    ['/browse', 'nav.browseSearch', 'Browse &amp; Search'],
  ] },
  // Roam Now (2026-10-14): its own item with a live dot, right after Discover; no app.js key, so its name stays.
  { href: '/map', key: null, label: 'Roam Now' },
  { href: '/hidden-gems', key: 'gems.heading', label: 'Hidden Gems' },
  { label: 'Things to Do', key: 'nav.thingsToDo', items: [
    ['/outdoors', 'mood.outdoors.title', 'Outdoors'],
    ['/beaches', 'mood.beaches.title', 'Beaches'],
    ['/golf', 'mood.golf.title', 'Golf'],
    ['/sports', 'tripv3.type.sport', 'Sports &amp; Recreation'],
    ['/tours', 'tripv3.type.tour', 'Tours &amp; Experiences'],
    ['/indoor', 'mood.indoor.title', 'Indoor &amp; Rainy Day'],
    ['/ski-snow', 'mood.skiSnow.title', 'Ski &amp; Snow'],
  ] },
  { label: 'Food &amp; Drink', key: 'mood.foodDrink.title', items: [
    ['/food-drink', 'mood.foodDrink.title', 'Food &amp; Drink'],
    ['/restaurants', 'wizard.restaurants', 'Restaurants'],
    ['/cafes', 'wizard.cafes', 'Cafes'],
    ['/pubs', 'wizard.pubsAndBars', 'Pubs &amp; Bars'],
    ['/wineries', 'wizard.wineries', 'Wineries'],
    ['/breweries', 'wizard.breweries', 'Breweries'],
    ['/distilleries', 'nav.distilleries', 'Distilleries'],
    ['/cocktail-lounges', 'wizard.cocktailLounges', 'Cocktail Lounges'],
  ] },
  { href: '/whats-on', key: 'mood.whatsOn.title', label: 'What\'s On' },
  // Phones only (2026-10-15): on computers Business login stays at the end of Discover.
  { href: '/owner/login', key: null, label: 'Business login' },
  { href: '/trip', key: 'trip.buildMyTrip', label: 'Build My Trip', mobileOnly: true },
];
function parseNav(html) {
  const header = (html.match(/<header id="top">[\s\S]*?<\/header>/) || [''])[0];
  const ul = (header.match(/<ul class="nav-links" id="navLinks">([\s\S]*?)\n\s*<\/ul>/) || ['', ''])[1];
  // The mobile menu's EN / FR row is a control, not a navigation item.
  const items = ul.split(/\n\s*<li/).slice(1).map((li) => '<li' + li).filter((li) => !/class="nav-links-lang"/.test(li));
  return { header, items: items.map((li) => {
    if (/class="nav-dropdown"/.test(li)) {
      const m = li.match(/<span data-i18n="([^"]+)">([^<]+)<\/span>/);
      return { key: m[1], label: m[2], items: [...li.matchAll(/<a href="([^"]+)"(?: id="[^"]+")? data-i18n="([^"]+)">([^<]+)<\/a>/g)].map((x) => [x[1], x[2], x[3]]) };
    }
    // Stage 4.4: the Favorites link has no data-i18n key (app.js's frozen dictionary has none).
    // Roam Now (2026-10-14) carries a class and its live dot.
    const a = li.match(/<a(?: class="[^"]+")? href="([^"]+)"(?: data-i18n="([^"]+)")?>(?:<span[^>]*><\/span>)?([^<]+)<\/a>/);
    return { href: a[1], key: a[2] || null, label: a[3], mobileOnly: /class="nav-links-trip"/.test(li) };
  }) };
}

test('Header: the exact approved items, order, URLs and i18n keys on /, /browse, /trip and themed pages', () => withDiscoveryServer(async (base) => {
  const pages = {
    '/': await (await fetch(`${base}/`)).text(),
    '/browse': await (await fetch(`${base}/browse`)).text(),
    '/browse/classic': await (await fetch(`${base}/browse/classic`)).text(),
    '/trip': await (await fetch(`${base}/trip`)).text(),
    '/destinations': await (await fetch(`${base}/destinations`)).text(),
    themed: app.renderGolfHeaderHtml(),
  };
  // Stage 4.4: server-built headers (/trip, themed pages) add Favorites before
  // the mobile-only Build My Trip row; /, /browse and /browse/classic keep the template's
  // own (the hub-style /browse is a themed page but is deliberately served without it).
  const withFavorites = [...HEADER_SPEC.slice(0, -1), { href: '/favorites', key: null, label: 'Favorites' }, HEADER_SPEC[HEADER_SPEC.length - 1]];
  for (const [name, html] of Object.entries(pages)) {
    const nav = parseNav(html);
    const spec = (name === '/' || name === '/browse' || name === '/browse/classic') ? HEADER_SPEC : withFavorites;
    assert.deepEqual(nav.items.map((i) => (i.items ? { label: i.label, key: i.key, items: i.items } : { href: i.href, key: i.key, label: i.label, mobileOnly: i.mobileOnly })),
      spec.map((i) => (i.items ? { label: i.label, key: i.key, items: i.items } : { href: i.href, key: i.key, label: i.label, mobileOnly: !!i.mobileOnly })), name);
    // The desktop Build My Trip button is still the header CTA.
    assert.match(nav.header, /id="navTripBtn"/, `${name}: Build My Trip button`);
    // Map keeps its id and href (okanagan.html is frozen); Stage 3.4: the
    // server answers /browse?openMap=1 with the map page (/map).
    assert.match(nav.header, /<li><a class="nav-roam-now" href="\/map"><span class="live-dot" aria-hidden="true"><\/span>Roam Now<\/a><\/li>/, name); // straight to /map (2026-10-14)
    // No duplicates; Hidden Gems top-level only; no top-level Golf/Map. Secret
    // Spots joined Discover in the menus refresh (2026-10-14).
    // /owner/login is in Discover on computers and its own item on phones; CSS shows only one.
    const hrefs = [...nav.header.matchAll(/<li[\s\S]*?<\/li>/g)].flatMap((m) => [...m[0].matchAll(/href="([^"]+)"/g)].map((x) => x[1])).filter((h) => h !== '/owner/login');
    assert.equal(new Set(hrefs).size, hrefs.length, `${name}: no duplicate navigation targets`);
    assert.doesNotMatch(nav.header, /#hiddenGems|#exploreRegions|#moodCards|#mapPanel|\/kelowna\//, `${name}: no stale targets`);
  }
}));

