test('Footer: "List your venue" points to /list-your-venue on every footer page; the rest of the footer is unchanged', () => withDiscoveryServer(async (base) => {
  for (const page of ['/', '/browse', '/trip', '/destinations', '/kelowna/restaurants', '/kelowna/restaurants/test-trattoria', '/list-your-venue', '/list-an-event']) {
    const res = await fetch(base + page);
    assert.equal(res.status, 200, page);
    const html = await res.text();
    const footer = html.match(/<footer class="home-footer">[\s\S]*?<\/footer>/);
    assert.ok(footer, `${page} renders the shared footer`);
    assert.ok(footer[0].includes(LYV_FOOTER_ABOUT), `${page}: About column is exactly About Okanagan Roam / List your venue / List an Event / Business login / Contact`);
    const footerLinks = footer[0].replace(/<dialog[\s\S]*?<\/dialog>|<script[\s\S]*?<\/script>/g, '');
    assert.equal((footerLinks.match(/href="\/list-your-venue"/g) || []).length, 1, page);
    assert.equal((footerLinks.match(/href="\/list-an-event"/g) || []).length, 1, `${page}: exactly one List an Event link`);
    assert.equal((footer[0].match(/>List an Event</g) || []).length, 1, page);
    assert.doesNotMatch(footer[0], /browse#list-venue/, `${page}: footer no longer links to the old /browse form`);
    // Explore and Regions are <details> that fold on phones (2026-10-14).
    const cols = footer[0].match(/<(?:div|details) class="home-footer-col(?: home-footer-col-regions)?(?: home-footer-fold)?"(?: open)?>\s*(?:<summary>)?<h2 data-i18n="([^"]+)"/g).map((c) => c.match(/data-i18n="([^"]+)"/)[1]);
    assert.deepEqual(cols, ['homeFooter.explore', 'footer.about', 'footer.regions', 'homeFooter.socialMedia'], `${page}: same four columns in the same order`);
    // Venue pages keep the legacy minimal <header class="top">; every other page has the approved header.
    const header = html.match(/<header (?:id="top"|class="top")>[\s\S]*?<\/header>/);
    assert.ok(header, page);
    assert.doesNotMatch(header[0].replace(/<a class="lang-toggle"[^>]*>[^<]*<\/a>/, ''), /list-your-venue|list-venue|nav\.listVenue/, `${page}: header has no List Your Venue link`);
  }
}));

