  assert.match(script, /track\('trip_plan_start', \{ input_method: fromExample \? 'example' : 'typed' \}\)/);
  assert.match(script, /regions\.length === 1 \? regions\[0\] : \(regions\.length \? 'multiple' : 'none'\)/);
