// ==== Analytics Cleanup C1 (2026-09-28): / and /browse join roam_internal ===
//
// The homepage and /browse keep okanagan.html on disk untouched; the server
// swaps only the static loader tag and the plain gtag('config') for the shared
// GA4 IIFE (renderGa4ConfigIifeJs('{}')). The resulting head script is run in
// the same kind of VM as the Phase B snippet tests.
const C1_LOADER = '<script async src="https://www.googletagmanager.com/gtag/js?id=G-J312FGJPSC"></script>\n';
const C1_CONFIG = "  gtag('js', new Date());\n  gtag('config', 'G-J312FGJPSC');\n";
const c1SiteHtml = () => fs.readFileSync(path.join(__dirname, '..', 'okanagan.html'), 'utf8');
const runHomepageHead = (href, { cookie = '', referrer = '' } = {}) => {
  const html = app.applyHomepageAnalyticsHead(c1SiteHtml());
  const start = html.indexOf('<!-- Google Analytics (GA4) -->');
  const js = html.slice(html.indexOf('<script>', start) + 8, html.indexOf('</script>', start));
  const u = new URL(href);
  let jar = cookie; const writes = []; const loaded = [];
  const document = { referrer, addEventListener() {}, getElementById: () => null, head: { appendChild(el) { loaded.push({ src: el.src, async: el.async }); } }, createElement() { return {}; } };
  Object.defineProperty(document, 'cookie', {
    get: () => jar,
    set: (v) => { writes.push(v); const [kv, ...attrs] = v.split(';'); const k = kv.split('=')[0]; const keep = jar.split(/;\s*/).filter((c) => c && !c.startsWith(k + '=')); jar = (attrs.some((x) => /max-age=0/.test(x)) ? keep : [...keep, kv.trim()]).join('; '); },
  });
  const ctx = { location: { href: u.href, search: u.search, origin: u.origin, pathname: u.pathname, hash: u.hash, hostname: u.hostname, protocol: u.protocol }, document };
  ctx.window = ctx;
  vm.createContext(ctx); vm.runInContext(js, ctx);
  const calls = ctx.dataLayer.map((a) => Array.from(a));
  return JSON.parse(JSON.stringify({ cfg: calls.find((c) => c[0] === 'config')[2], configs: calls.filter((c) => c[0] === 'config').length, loaded, jar, writes, trackEvent: typeof ctx.trackEvent }));
};

test('Analytics Cleanup C1: applyHomepageAnalyticsHead makes exactly two swaps and leaves okanagan.html, the trackEvent wrapper and the body byte-identical', () => {
  const before = c1SiteHtml();
  const out = app.applyHomepageAnalyticsHead(before);
  assert.equal(c1SiteHtml(), before, 'okanagan.html on disk is never modified');
  assert.equal(before.split(C1_LOADER).length, 2);
  assert.equal(before.split(C1_CONFIG).length, 2);
  assert.equal(out, before.replace(C1_LOADER, '').replace(C1_CONFIG, `${app.renderGa4ConfigIifeJs('{}')}\n`), 'only the two swaps');
  assert.equal(out.slice(out.indexOf('</head>')), before.slice(before.indexOf('</head>')), 'visible markup (everything after </head>) unchanged');
  const wrapper = before.slice(before.indexOf('  // Small wrapper so every custom event'), before.indexOf('</script>\n</head>'));
  assert.ok(wrapper.length > 200 && wrapper.includes('window.trackEvent = function(name, params)'));
  assert.ok(out.includes(wrapper), 'okanagan.html\'s own window.trackEvent wrapper is byte-identical');
  assert.doesNotMatch(out, /page_type/, 'no page_type on the homepage');
  // The shared IIFE is literally the one every server template uses.
  assert.ok(app.renderAnalyticsHeadHtml('hub').includes(app.renderGa4ConfigIifeJs("{ page_type: 'hub' }")));
  // Fail-safe: anything unexpected -> served unchanged.
  for (const broken of [before.replace(C1_LOADER, ''), before.replace(C1_CONFIG, ''), before + C1_LOADER, before + C1_CONFIG, '']) {
    assert.equal(app.applyHomepageAnalyticsHead(broken), broken);
  }
});

test('Analytics Cleanup C1: homepage visitors are never marked internal; ?roam_internal=on/off sets and clears the same cookie; toggle stripped; gtag.js only on the live hostname', () => {
  for (const href of ['https://okanaganroam.com/', 'https://okanaganroam.com/browse?regions=kelowna&features=dog']) {
    const r = runHomepageHead(href);
    assert.deepEqual(r.cfg, {}, href);
    assert.equal(r.writes.length, 0);
    assert.equal(r.configs, 1);
    assert.deepEqual(r.loaded, [{ src: 'https://www.googletagmanager.com/gtag/js?id=G-J312FGJPSC', async: true }]);
    assert.equal(r.trackEvent, 'function', 'okanagan.html\'s trackEvent wrapper still defined');
  }
  const on = runHomepageHead('https://okanaganroam.com/?roam_internal=on#top');
  assert.equal(on.cfg.traffic_type, 'internal');
  assert.equal(on.cfg.page_location, 'https://okanaganroam.com/#top');
  assert.deepEqual(on.writes, ['roam_internal=1; max-age=31536000; path=/; samesite=lax; secure']);
  const later = runHomepageHead('https://okanaganroam.com/browse', { cookie: on.jar, referrer: 'https://okanaganroam.com/trip?roam_internal=on' });
  assert.deepEqual(later.cfg, { traffic_type: 'internal', page_referrer: 'https://okanaganroam.com/trip' });
  const off = runHomepageHead('https://okanaganroam.com/browse?roam_internal=off', { cookie: on.jar });
  assert.deepEqual(off.cfg, { page_location: 'https://okanaganroam.com/browse' });
  assert.deepEqual(off.writes, ['roam_internal=; max-age=0; path=/; samesite=lax; secure']);
  assert.equal(off.jar, '');
  for (const href of ['http://localhost:3001/', 'http://127.0.0.1:3000/browse', 'https://www.okanaganroam.com/', 'https://okanagan-roam-production.up.railway.app/']) {
    const r = runHomepageHead(href);
    assert.equal(r.loaded.length, 0, `${href}: gtag.js not fetched`);
    assert.equal(r.configs, 1, `${href}: calls still queue harmlessly`);
  }
});

// ==== Analytics Cleanup C2 (2026-09-28): filter_change on listing surfaces ===
//
// Each filter script is executed in a VM against a minimal fake DOM. Only the
// visitor's own clicks may emit filter_change: page load with a pre-filled URL,
// Back/Forward (popstate) and search typing must emit nothing.
function c2El(attrs = {}, opts = {}) {
  const el = {
    tag: opts.tag || 'button', classes: new Set(opts.classes || []), parentId: opts.parentId || null,
    _attrs: {}, _listeners: {}, hidden: false, textContent: opts.textContent || '', innerHTML: '', value: '', style: {},
    get id() { return this._attrs.id || ''; },
    get classList() { const c = this.classes; return { add: (x) => c.add(x), remove: (x) => c.delete(x), toggle: (x, on) => { if (on === undefined ? !c.has(x) : on) c.add(x); else c.delete(x); }, contains: (x) => c.has(x) }; },
    getAttribute(k) { return Object.prototype.hasOwnProperty.call(this._attrs, k) ? String(this._attrs[k]) : null; },
    setAttribute(k, v) { this._attrs[k] = String(v); },
    hasAttribute(k) { return Object.prototype.hasOwnProperty.call(this._attrs, k); },
    removeAttribute(k) { delete this._attrs[k]; },
    addEventListener(t, fn) { (this._listeners[t] = this._listeners[t] || []).push(fn); },
    querySelector() { return null; }, querySelectorAll() { return []; }, closest() { return this; },
    focus() {}, scrollIntoView() {}, appendChild() {}, insertBefore() {}, removeChild() {},
    content: { querySelectorAll: () => [] },
  };
  for (const [k, v] of Object.entries(attrs)) el._attrs[k] = String(v);
  return el;
}
function c2Match(el, part) {
  part = part.trim(); let m;
  if ((m = /^#([\w-]+)\s*>\s*\.([\w-]+)$/.exec(part))) return el.parentId === m[1] && el.classes.has(m[2]);
  if ((m = /^([a-z]+)?((?:\.[\w-]+)*)((?:\[[^\]]+\])*)$/.exec(part))) {
    const [, tag, cls, attrs] = m;
    if (tag && el.tag !== tag) return false;
    for (const c of (cls || '').split('.').filter(Boolean)) if (!el.classes.has(c)) return false;
    for (const a of (attrs || '').match(/\[[^\]]+\]/g) || []) {
      const am = /^\[([\w-]+)(?:="([^"]*)")?\]$/.exec(a);
      if (!am || (am[2] === undefined ? !el.hasAttribute(am[1]) : el.getAttribute(am[1]) !== am[2])) return false;
    }
    return !!(tag || cls || attrs);
  }
  return false;
}
function c2Run(scriptHtml, { url, elements = [], byId = {} }) {
  const js = scriptHtml.slice(scriptHtml.indexOf('<script>') + 8, scriptHtml.lastIndexOf('</script>'));
  const u = new URL(url);
  const loc = { href: u.href, pathname: u.pathname, search: u.search, hash: u.hash, hostname: u.hostname, protocol: u.protocol, origin: u.origin, reload() {}, assign() {} };
  const setUrl = (next) => { const n = new URL(next, loc.href); loc.href = n.href; loc.pathname = n.pathname; loc.search = n.search; loc.hash = n.hash; };
  const history = { pushes: [], replaces: [], pushState(s, t, next) { this.pushes.push(next); setUrl(next); }, replaceState(s, t, next) { this.replaces.push(next); setUrl(next); } };
  const events = []; const winListeners = {};
  const all = elements.filter(Boolean);
  for (const [id, el] of Object.entries(byId)) { el._attrs.id = id; all.push(el); }
  const document = {
    getElementById: (id) => byId[id] || null,
    querySelectorAll: (sel) => all.filter((el) => sel.split(',').some((p) => c2Match(el, p))),
    querySelector: (sel) => all.find((el) => sel.split(',').some((p) => c2Match(el, p))) || null,
    addEventListener() {}, createElement: () => c2El(), head: { appendChild() {} }, body: c2El(),
  };
  const ctx = {
    document, location: loc, history, URLSearchParams,
    setTimeout: (fn) => { fn(); return 0; }, clearTimeout() {}, setInterval: () => 0, clearInterval() {},
    matchMedia: () => ({ matches: false, addEventListener() {} }),
    addEventListener: (t, fn) => { (winListeners[t] = winListeners[t] || []).push(fn); },
    trackEvent: (name, params) => events.push({ name, params: JSON.parse(JSON.stringify(params)) }),
  };
  ctx.window = ctx;
  vm.createContext(ctx); vm.runInContext(js, ctx);
  const evt = (target) => ({ preventDefault() {}, stopPropagation() {}, target, isTrusted: true });
  return {
    history, loc,
    click(el) { for (const fn of el._listeners.click || []) fn(evt(el)); },
    clickInside(container, target) { for (const fn of container._listeners.click || []) fn(evt(target)); },
    input(el, value) { el.value = value; for (const fn of el._listeners.input || []) fn(evt(el)); },
    popstate(next) { setUrl(next); for (const fn of winListeners.popstate || []) fn({}); },
    fc() { return events.filter((e) => e.name === 'filter_change').map((e) => { const p = e.params; return [p.filter_surface, p.filter_group, p.filter_value, p.filter_action, p.active_filter_count].join('|'); }); },
    other() { return events.filter((e) => e.name !== 'filter_change'); },
  };
}
// The chip-based hubs (Food & Drink hub + category pages, Dog Friendly,
// Local Favourites / Hidden Gems / Secret Spots) share one control contract.
function c2ChipSurface(scriptHtml, url, { pre, feature, open, shape }) {
  const type = c2El({ [`data-${pre}-type`]: 'cafe', 'aria-pressed': 'false' });
  const feat = feature ? c2El({ [`data-${pre}-feature`]: 'patio', 'aria-pressed': 'false' }) : null;
  const region = c2El({ 'data-region': 'kelowna', 'aria-pressed': 'false' }, { classes: ['outdoor-filter-chip'] });
  const all = c2El({ [`data-${pre}-type-all`]: '', 'aria-pressed': 'true' });
  const cards = [1, 2].map((i) => c2El({ 'data-venue-id': i, [`data-${pre}-i`]: i - 1, 'data-venue-name': 'V' + i }, { classes: ['venue-card'], parentId: `${pre}Results`, tag: 'li' }));
  const byId = { [`${pre}Selected`]: c2El(), [`${pre}NoResultsClear`]: c2El(), [`${pre}VenueData`]: c2El({}, { textContent: JSON.stringify({ 1: shape(1), 2: shape(2) }) }), [`${pre}Search`]: c2El() };
  if (open) byId.fdOpenNow = c2El({ 'aria-pressed': 'false' });
  return { r: c2Run(scriptHtml, { url, elements: [type, feat, region, all, ...cards], byId }), type, feat, region, all, byId };
}

test('Analytics Cleanup C2: every approved surface ships filter_change with its own fixed surface slug; search is never a filter_change', () => {
  const surfaces = {
    food_drink: app.renderFoodDrinkHubScriptHtml({ openNow: true }),
    food_drink_category: app.renderFoodDrinkHubScriptHtml({ surface: 'food_drink_category' }),
    dog_friendly: app.renderDogHubScriptHtml(),
    outdoors: app.renderOutdoorFilterScriptHtml(),
    whats_on: app.renderWhatsOnFilterScriptHtml({ hasInventory: true }),
    local_favourites: app.renderLocalFavouritesScriptHtml('local favourite', 'local_favourites'),
    hidden_gems: app.renderLocalFavouritesScriptHtml('hidden gem', 'hidden_gems'),
    secret_spots: app.renderLocalFavouritesScriptHtml('tucked-away', 'secret_spots'),
  };
  for (const [slug, html] of Object.entries(surfaces)) {
    assert.ok(html.includes(`var FILTER_SURFACE = "${slug}";`), `${slug}: surface slug`);
    assert.ok(html.includes("window.trackEvent('filter_change', { filter_surface: FILTER_SURFACE, filter_group: group, filter_value: String(value), filter_action: action, active_filter_count: activeFilterCount() })"), `${slug}: event shape`);
    assert.doesNotMatch(html, /trackFilterChange\([^)]*search/i, `${slug}: search is not instrumented`);
    new Function(html.slice(html.indexOf('<script>') + 8, html.lastIndexOf('</script>'))); // parses
  }
  // The pages themselves carry the right slug.
  assert.ok(app.renderLocalFavouritesPage([], null).includes('var FILTER_SURFACE = "local_favourites";'));
  assert.ok(app.renderHiddenGemsPage([], null).includes('var FILTER_SURFACE = "hidden_gems";'));
  assert.ok(app.renderSecretSpotsPage([], null).includes('var FILTER_SURFACE = "secret_spots";'));
  assert.ok(app.renderCategoryAllRegionsPage('outdoor', app.getVenuesByCategory('outdoor')).includes('var FILTER_SURFACE = "outdoors";'));
  // Pages without filters stay uninstrumented.
  assert.doesNotMatch(app.renderAnalyticsHeadHtml('hub'), /filter_change/);
});

test('Analytics Cleanup C2: chip hubs -- URL prefill, page load, popstate and search emit nothing; add/remove/clear_all emit filter_change; URLs keep their query params', () => {
  const fdShape = (i) => ({ c: ['cafe'], f: ['patio'], r: i === 1 ? 'kelowna' : 'vernon', h: null });
  const lfShape = (i) => ({ t: 'cafe', r: i === 1 ? 'kelowna' : 'vernon' });
  const cases = [
    ['food_drink', app.renderFoodDrinkHubScriptHtml({ openNow: true }), { pre: 'fd', feature: true, open: true, shape: fdShape }],
    ['food_drink_category', app.renderFoodDrinkHubScriptHtml({ surface: 'food_drink_category' }), { pre: 'fd', feature: true, shape: fdShape }],
    ['dog_friendly', app.renderDogHubScriptHtml(), { pre: 'dog', feature: true, shape: fdShape }],
    ['local_favourites', app.renderLocalFavouritesScriptHtml('local favourite', 'local_favourites'), { pre: 'lf', shape: lfShape }],
    ['hidden_gems', app.renderLocalFavouritesScriptHtml('hidden gem', 'hidden_gems'), { pre: 'lf', shape: lfShape }],
    ['secret_spots', app.renderLocalFavouritesScriptHtml('tucked-away', 'secret_spots'), { pre: 'lf', shape: lfShape }],
  ];
  for (const [slug, html, opts] of cases) {
    const s = c2ChipSurface(html, 'https://okanaganroam.com/x?types=cafe&regions=kelowna&features=patio&open=now', opts);
    assert.equal(s.type.getAttribute('aria-pressed'), 'true', `${slug}: URL prefill applied`);
    assert.deepEqual(s.r.fc(), [], `${slug}: no filter_change on load with a pre-filled URL`);
    assert.equal(s.r.history.pushes.length, 0, `${slug}: load only replaces`);
    s.r.popstate('https://okanaganroam.com/x?regions=kelowna');
    assert.deepEqual(s.r.fc(), [], `${slug}: no filter_change on Back/Forward`);
    s.r.input(s.byId[`${opts.pre}Search`], 'pizza');
    assert.deepEqual(s.r.fc(), [], `${slug}: search typing is not a filter_change`);
    s.r.click(s.type); s.r.click(s.type);
    if (s.feat) s.r.click(s.feat);
    s.r.clickInside(s.byId[`${opts.pre}Selected`], c2El({ [`data-${opts.pre}-remove-region`]: 'kelowna' }));
    if (opts.open) { s.r.click(s.byId.fdOpenNow); s.r.clickInside(s.byId.fdSelected, c2El({ 'data-fd-remove-open': '1' })); }
    s.r.click(s.type); s.r.click(s.all);
    s.r.click(s.region);
    s.r.clickInside(s.byId[`${opts.pre}Selected`], c2El({ id: `${opts.pre}SelectedClear` }));
    s.r.click(s.byId[`${opts.pre}NoResultsClear`]); // nothing left to clear -> no event
    const f = opts.feature ? 1 : 0;
    const expected = [
      // popstate left kelowna pressed, so the first add counts type + region.
      `${slug}|type|cafe|add|2`, `${slug}|type|cafe|remove|1`,
      ...(opts.feature ? [`${slug}|feature|patio|add|2`] : []),
      `${slug}|region|kelowna|remove|${opts.feature ? 1 : 0}`,
      ...(opts.open ? [`${slug}|open_now|now|add|2`, `${slug}|open_now|now|remove|1`] : []),
      `${slug}|type|cafe|add|${1 + f}`, `${slug}|type|all|clear_all|${f}`,
      `${slug}|region|kelowna|add|${1 + f}`, `${slug}|all|all|clear_all|0`,
    ];
    assert.deepEqual(s.r.fc(), expected, slug);
    assert.deepEqual(s.r.other(), [], `${slug}: no other events from the filter script`);
    for (const p of s.r.history.pushes) assert.match(p, /^\/x(\?(types|features|regions|open)=[^&]+(&(types|features|regions|open)=[^&]+)*)?$/, `${slug}: pushed URL ${p}`);
  }
});

test('Analytics Cleanup C2: Outdoors and What\'s On -- region/activity/category chips emit filter_change; prefill, popstate, search and date presets do not', () => {
  // Outdoors
  const oc = [
    c2El({ 'data-region': 'kelowna', 'aria-pressed': 'false' }, { classes: ['outdoor-filter-chip'] }),
    c2El({ 'data-region': 'vernon', 'aria-pressed': 'false' }, { classes: ['outdoor-filter-chip'] }),
    c2El({ 'data-activity': 'hiking', 'aria-pressed': 'false' }, { classes: ['outdoor-activity-toggle'] }),
  ];
  const oAll = c2El({ 'data-activity-all': '', 'aria-pressed': 'true' }, { classes: ['outdoor-filter-chip'] });
  const oCards = [1, 2].map((i) => c2El({ 'data-venue-id': i, 'data-venue-region': i === 1 ? 'kelowna' : 'vernon', 'data-venue-name': 'V' + i }, { classes: ['venue-card'], parentId: 'outdoorResults', tag: 'li' }));
  const oById = { outdoorSelected: c2El(), outdoorNoResultsClear: c2El(), outdoorActivityMap: c2El({}, { textContent: JSON.stringify({ 1: ['hiking'], 2: [] }) }), outdoorsSearch: c2El() };
  const o = c2Run(app.renderOutdoorFilterScriptHtml(), { url: 'https://okanaganroam.com/outdoors?regions=kelowna&activities=hiking', elements: [...oc, oAll, ...oCards], byId: oById });
  assert.equal(oc[0].getAttribute('aria-pressed'), 'true');
  o.popstate('https://okanaganroam.com/outdoors?regions=vernon');
  o.input(oById.outdoorsSearch, 'lake');
  assert.deepEqual(o.fc(), [], 'outdoors: nothing on load, popstate or search');
  o.click(oc[0]); o.click(oc[0]);
  o.clickInside(oById.outdoorSelected, c2El({ 'data-remove-region': 'vernon' }));
  o.click(oc[2]); o.click(oAll); o.click(oc[1]);
  o.clickInside(oById.outdoorSelected, c2El({ id: 'outdoorSelectedClear' }));
  o.clickInside(oById.outdoorSelected, c2El({ id: 'outdoorSelectedClear' }));
  assert.deepEqual(o.fc(), ['outdoors|region|kelowna|add|2', 'outdoors|region|kelowna|remove|1', 'outdoors|region|vernon|remove|0', 'outdoors|activity|hiking|add|1', 'outdoors|activity|all|clear_all|0', 'outdoors|region|vernon|add|1', 'outdoors|all|all|clear_all|0']);
  assert.deepEqual(o.history.pushes, ['/outdoors?regions=kelowna,vernon', '/outdoors?regions=vernon', '/outdoors', '/outdoors?activities=hiking', '/outdoors', '/outdoors?regions=vernon', '/outdoors'], 'existing URL/query behaviour unchanged');
  // What's On (date presets are real links -> page loads, not filter_change)
  const wRegion = c2El({ 'data-region': 'kelowna', 'aria-pressed': 'false' }, { classes: ['outdoor-filter-chip'] });
  const wCat = c2El({ 'data-category': 'live-music', 'aria-pressed': 'false' }, { classes: ['outdoor-filter-chip'] });
  const wAll = c2El({ 'data-category-all': '', 'aria-pressed': 'true' }, { classes: ['outdoor-filter-chip'] });
  const wDate = c2El({ 'data-when': 'weekend', 'aria-pressed': 'false' }, { classes: ['outdoor-filter-chip', 'whatson-date-chip'], tag: 'a' });
  const wCards = [1, 2].map((i) => c2El({ 'data-venue-id': i, 'data-event-region': i === 1 ? 'kelowna' : 'vernon', 'data-event-categories': 'live-music', 'data-venue-name': 'E' + i }, { classes: ['venue-card'], parentId: 'whatsOnResults', tag: 'li' }));
  const wById = { whatsOnSelected: c2El(), whatsOnNoResultsClear: c2El(), whatsOnClearFilters: c2El(), whatsOnSearch: c2El() };
  const w = c2Run(app.renderWhatsOnFilterScriptHtml({ hasInventory: true, dateState: { when: 'weekend', from: '', to: '' } }), { url: 'https://okanaganroam.com/whats-on?when=weekend&regions=kelowna&categories=live-music', elements: [wRegion, wCat, wAll, wDate, ...wCards], byId: wById });
  w.popstate('https://okanaganroam.com/whats-on?when=weekend&regions=kelowna');
  w.input(wById.whatsOnSearch, 'jazz');
  w.click(wDate);
  assert.deepEqual(w.fc(), [], "what's on: nothing on load, popstate, search or a date preset");
  w.click(wCat); w.click(wCat);
  w.clickInside(wById.whatsOnSelected, c2El({ 'data-remove-region': 'kelowna' }));
  w.click(wCat); w.click(wAll); w.click(wRegion);
  w.click(wById.whatsOnClearFilters);
  w.click(wById.whatsOnNoResultsClear);
  assert.deepEqual(w.fc(), ['whats_on|category|live-music|add|2', 'whats_on|category|live-music|remove|1', 'whats_on|region|kelowna|remove|0', 'whats_on|category|live-music|add|1', 'whats_on|category|all|clear_all|0', 'whats_on|region|kelowna|add|1', 'whats_on|all|all|clear_all|0']);
  for (const p of w.history.pushes) assert.match(p, /^\/whats-on\?when=weekend(&(regions|categories)=[^&]+)*$/, `date window kept on every push: ${p}`);
});

// ==== Build My Trip V3 (Step 2, 2026-09-29): flag, preview opt-in, API additions ====
//
// TRIP_PLANNER_V3 'off' (default) leaves /trip exactly as before; 'preview'
// serves V3 only to a browser that opted in with /trip?trip_v3=on; 'on'
// serves it to everyone. POST /api/trip/plan gains an optional `overrides`
// object and returns an additive `understood` block; every existing request
// body is answered as before.
const withEnv = (vars, fn) => {
  const saved = {};
  for (const k of Object.keys(vars)) { saved[k] = process.env[k]; if (vars[k] === undefined) delete process.env[k]; else process.env[k] = vars[k]; }
  try { return fn(); } finally { for (const k of Object.keys(saved)) { if (saved[k] === undefined) delete process.env[k]; else process.env[k] = saved[k]; } }
};

test('Build My Trip V3: flag modes and the preview cookie decide who sees V3; off by default', () => {
  withEnv({ TRIP_PLANNER_V3: undefined }, () => {
    assert.equal(app.tripPlannerV3Mode(), 'off');
    assert.equal(app.tripPlannerV3ActiveFor({ headers: { cookie: 'roam_trip_v3=1' } }), false, 'a cookie alone never turns V3 on');
  });
  for (const v of ['on', '1', 'true', 'YES']) withEnv({ TRIP_PLANNER_V3: v }, () => assert.equal(app.tripPlannerV3Mode(), 'on', v));
  withEnv({ TRIP_PLANNER_V3: 'preview' }, () => {
    assert.equal(app.tripPlannerV3Mode(), 'preview');
    assert.equal(app.tripPlannerV3ActiveFor({ headers: {} }), false);
    assert.equal(app.tripPlannerV3ActiveFor({ headers: { cookie: 'a=b; roam_trip_v3=1' } }), true);
    assert.equal(app.tripPlannerV3ActiveFor({ headers: { cookie: 'roam_trip_v3=0' } }), false);
  });
  withEnv({ TRIP_PLANNER_V3: 'on' }, () => assert.equal(app.tripPlannerV3ActiveFor({ headers: {} }), true));
  withEnv({ TRIP_PLANNER_V3: 'nonsense' }, () => assert.equal(app.tripPlannerV3Mode(), 'off'));
});

test('Build My Trip V3: /api/trip/plan overrides are optional, strictly validated, and only steer days, pace and base', () => {
  assert.deepEqual(app.parseTripPlanBody({ text: 'plan 2 days in Kelowna' }).value.overrides, null, 'no overrides: unchanged request');
  assert.deepEqual(app.parseTripPlanBody({ text: 'x', overrides: { days: 3, pace: 'relaxed', baseRegion: 'penticton' } }).value.overrides, { days: 3, pace: 'relaxed', baseRegion: 'penticton' });
  assert.ok(app.parseTripPlanBody({ text: 'x', overrides: { baseRegion: 'valley' } }).value);
  for (const bad of [{ days: 0 }, { days: 8 }, { days: 2.5 }, { pace: 'fast' }, { baseRegion: 'seattle' }, { venue: 1 }, [], null]) {
    assert.ok(app.parseTripPlanBody({ text: 'x', overrides: bad }).error, JSON.stringify(bad));
  }
  const now = new Date('2026-09-29T19:00:00Z');
  const base = app.runTripPlan({ text: 'Plan 2 days in Kelowna with wineries' }, now);
  assert.ok(base.understood && Array.isArray(base.understood.interests), 'understood block is returned');
  assert.deepEqual(app.runTripPlan({ text: 'Plan 2 days in Kelowna with wineries', overrides: { days: 3 } }, now).days.length, 3);
  const moved = app.runTripPlan({ text: 'Plan 2 days in Kelowna with wineries', overrides: { baseRegion: 'penticton' } }, now);
  assert.ok(moved.days.every((d) => !d.region || d.region === 'penticton'));
  assert.deepEqual(moved.understood.base.map((b) => b.slug), ['penticton']);
  assert.equal(app.runTripPlan({ text: 'Plan 2 days in Kelowna with wineries', overrides: { pace: 'packed' } }, now).understood.pace, 'packed');
  // Without overrides the plan is exactly the previous one (plus the additive block).
  const again = app.runTripPlan({ text: 'Plan 2 days in Kelowna with wineries' }, now);
  delete again.understood; const b2 = { ...base }; delete b2.understood;
  assert.deepEqual(again, b2);
});

test('Build My Trip V3: the page is the site shell + the V3 view; canonical /trip; noindex only in preview; analytics page_type trip_v3', () => {
  const html = app.renderTripPlannerV3Page({ preview: false });
  assert.match(html, /<link rel="canonical" href="https:\/\/okanaganroam\.com\/trip">/);
  assert.doesNotMatch(html, /noindex/);
  assert.match(app.renderTripPlannerV3Page({ preview: true }), /<meta name="robots" content="noindex">/);
  // Stage 5A (F12): V3 views are labelled trip_v3, apart from V2's 'trip'.
  ga4Check(html, 'trip_v3', 'trip v3');
  assert.ok(!html.includes("page_type: 'trip'"), 'not the V2 label');
  assert.ok(html.includes('<header id="top">') && html.includes('id="tripTray"'), 'the homepage header and Trip tray');
  assert.ok(html.includes(`<script src="${app.APP_JS_SRC}"></script>`), 'app.js (versioned), for Add to Trip / Favorites');
  assert.ok(html.includes('id="t3Form"') && html.includes('id="t3Input"') && html.includes('fetch(\'/api/trip/plan\''));
  for (const ev of ["'trip_plan_start'", "'trip_plan_complete'", "'trip_plan_error'", "'trip_plan_regenerate'", "'add_whole_trip'", "'open_my_trip'"]) assert.ok(html.includes(ev), ev);
  assert.doesNotMatch(html, /\/api\/trip\/(generate|parse)/, 'the V3 view never uses the legacy endpoints');
  assert.doesNotMatch(html, /openai|gpt-/i, 'no model is called');
  const js = html.slice(html.lastIndexOf('<script>') + 8, html.lastIndexOf('</script>'));
  new Function(js); // parses
});

// Stage 5A (F12, 2026-10-01): the V3 events -- where each fires, and that no
// event carries the request text, a venue name or a venue id.
test('Stage 5A F12: V3 reports edits, shares, Map this day and shared-link opens with fixed values only', () => {
  const html = app.renderTripPlannerV3Page({ preview: true });
  const js = html.slice(html.lastIndexOf('<script>') + 8, html.lastIndexOf('</script>'));
  const calls = js.match(/track\('[a-z_]+', \{[^}]*\}\)/g) || [];
  const byName = (n) => calls.filter((c) => c.startsWith(`track('${n}'`));
  // Edits: one call each in the Keep (keep / unkeep), Remove and Undo handlers.
  assert.equal(byName('trip_plan_edit').length, 3);
  assert.ok(byName('trip_plan_edit').every((c) => /\{ edit_action: (on \? 'keep' : 'unkeep'|'remove'|'undo'), plan_kind: planFacts\(state\.last\)\.plan_kind \}/.test(c)), byName('trip_plan_edit').join('\n'));
  // Share: one call, after the copy succeeded ('clipboard') or the link was shown ('manual').
  assert.deepEqual(byName('trip_plan_share'), ["track('trip_plan_share', { share_method: method, plan_kind: f.plan_kind, day_count: f.day_count })"]);
  assert.ok(js.includes("shared('clipboard')") && js.includes("shared('manual')"));
  // Map this day: the established outbound_click, with fixed values.
  assert.deepEqual(byName('outbound_click'), ["track('outbound_click', { link_type: 'trip_day_map', surface: 'trip_planner' })"]);
  assert.ok(js.includes("data-t3-map-day>' + esc(tx('tripv3.mapDay')) + '</a>"));
  // Opening a shared link: trip_plan_start (input_method link), then the
  // plan request reported as request_type shared_link; an unreadable link
  // is trip_plan_error invalid_share. Stage 5H: a reload / Back-Forward of
  // the page's own plan is reported as 'restore' instead (see the 5H test).
  assert.ok(js.includes("track('trip_plan_start', { input_method: arrival })"));
  assert.ok(js.includes("requestType: arrival === 'restore' ? 'restore' : 'shared_link'"));
  assert.equal(byName('trip_plan_error').filter((c) => c.includes("error_type: 'invalid_share'")).length, 2);
  // Every V3 event is fired from a handler or a request completion, never from render().
  const renderFn = js.slice(js.indexOf('function render(focus)'), js.indexOf('// ---- My Trip (tray)'));
  assert.ok(renderFn.length > 1000 && !/track\(/.test(renderFn), 'render() fires no events');
  // No visitor text, names or ids in any V3 event parameter.
  for (const c of calls) assert.doesNotMatch(c, /state\.text|\.name\b|venue\.id|\bid\b|location|href/, c);
  // Existing V3 events are unchanged.
  for (const c of ["track('trip_plan_complete', facts)", "track('trip_plan_regenerate', { plan_kind: planFacts(state.last).plan_kind })", "track('trip_plan_start', { input_method: fromExample ? 'example' : 'typed' })"]) assert.ok(js.includes(c), c);
});

test('Stage 5A F09/F12: the V2 /trip page is untouched -- no share replay, no V3 events, page_type trip', () => {
  const v2 = app.renderTripPlannerPage(true);
  ga4Check(v2, 'trip', 'trip v2');
  for (const s of ['trip_plan_edit', 'trip_plan_share', 'shared_link', 'invalid_share', 'trip_day_map', 'data-t3-', 't3QueryToState']) assert.ok(!v2.includes(s), s);
});

// Stage 5G (2026-10-02): the V3 whole-trip map. Collapsed until opened;
// Leaflet 1.9.4 (cdnjs, integrity-pinned) and the OpenStreetMap tiles are
// fetched only by the page script on first open -- never by the page itself;
// visible OpenStreetMap attribution; one map element kept outside render();
// day plans only; no analytics; the share link and the V2 page untouched.
test('Stage 5G: V3 whole-trip map -- collapsed, loaded on demand, attributed, kept across render(), no new events', () => {
  for (const preview of [true, false]) {
    const html = app.renderTripPlannerV3Page({ preview });
    assert.match(html, /<link rel="canonical" href="https:\/\/okanaganroam\.com\/trip">/);
    assert.equal(/noindex/.test(html), preview, 'noindex only in preview');
    assert.doesNotMatch(html, /<(script|link)[^>]*leaflet/i, 'the page itself never loads Leaflet');
    assert.doesNotMatch(html, /tile\.openstreetmap\.org[^'"]*\.png"/, 'no tile in the page markup');
  }
  const html = app.renderTripPlannerV3Page({ preview: true });
  const js = html.slice(html.lastIndexOf('<script>') + 8, html.lastIndexOf('</script>'));
  new Function(js); // parses
  // On demand, pinned, from the approved sources only.
  assert.ok(js.includes("var LEAFLET_BASE = 'https://cdnjs.cloudflare.com/ajax/libs/leaflet/1.9.4/';"));
  assert.ok(js.includes("var LEAFLET_JS_SRI = 'sha512-puJW3E/qXDqYp9IfhAI54BJEaWIfloJ7JWs7OeD5i6ruC9JZL1gERT1wjtwXFlh7CjE7ZJ+/vcRZRkIYIb6p4g==';"));
  assert.ok(js.includes("var LEAFLET_CSS_SRI = 'sha512-h9FcoyWjHcOcmEVkxOfTLnmZFWIH0iZhZT1H2TbOq55xssQGEJHEaIm+PgoUaZbRvQTNTluNOEfb1ZRy6D3BOw==';"));
  assert.ok(js.includes("js.integrity = LEAFLET_JS_SRI; js.crossOrigin = 'anonymous';") && js.includes("css.integrity = LEAFLET_CSS_SRI; css.crossOrigin = 'anonymous';"));
  assert.ok(js.includes("var MAP_TILES = 'https://tile.openstreetmap.org/{z}/{x}/{y}.png';"), 'tiles without subdomains');
  assert.doesNotMatch(js, /\{s\}\.tile\.openstreetmap/);
  assert.ok(js.includes('href="https://www.openstreetmap.org/copyright"') && js.includes('OpenStreetMap</a> contributors') && js.includes('attribution: MAP_ATTRIBUTION'), 'OpenStreetMap attribution');
  const openFn = js.slice(js.indexOf('function openMap()'), js.indexOf('function loadLeaflet('));
  assert.ok(openFn.includes('loadLeaflet(') && js.indexOf('loadLeaflet(') > js.indexOf('function setMapOpen('), 'Leaflet is requested only from opening the map');
  // Collapsed by default, on every screen size.
  assert.ok(js.includes(`aria-expanded="false" aria-controls="t3MapPanel">' + esc(tx('tripv3.map.show')) + '</button>`) && js.includes('<div class="t3-map-panel" id="t3MapPanel" hidden>'));
  assert.ok(js.includes("var tripMap = { box: null, open: false,"));
  // render(): the map slot only in day plans; the map is detached before the
  // result is rewritten and placed back after.
  const renderFn = js.slice(js.indexOf('function render(focus)'), js.indexOf('// ---- My Trip (tray)'));
  assert.ok(renderFn.includes("if (planKinds && days().length) {\n      html += '<div class=\"t3-tools\">' + schedHtml + '<div class=\"t3-map-slot\" data-t3-map-slot></div></div>';"));
  assert.equal(renderFn.split('data-t3-map-slot').length, 2, 'one slot');
  const i = (s) => renderFn.indexOf(s);
  assert.ok(i('detachMap();') > 0 && i('detachMap();') < i('resultEl.innerHTML = html;') && i('resultEl.innerHTML = html;') < i('placeMap();'));
  // Map controls never collide with the result's own click handling.
  const mapSrc = js.slice(js.indexOf('// ---- whole-trip map'), js.indexOf('// ---- rendering ----'));
  assert.ok(mapSrc.length > 3000);
  assert.ok(!/data-t3-(add-all|add-day|view-trip|map-day|share|keep|remove|undo|swap|regen)/.test(mapSrc.replace("'[data-t3-keep=\"' + key + '\"]'", '')), 'map controls use their own attributes');
  // Names reach the popup as text only.
  assert.ok(mapSrc.includes('name.textContent = p.name;') && !/innerHTML[^;]*p\.name/.test(mapSrc));
  // No analytics from the map.
  assert.ok(!/track\(|trackEvent|dataLayer|gtag/.test(mapSrc), 'no map analytics');
  assert.equal((js.match(/track\('/g) || []).length, 16, 'the V3 page has exactly the track() calls it had before Stage 5G');
  // Share link: the map adds nothing to it (the fixed-state link is checked byte for byte in trip-v3.test.js).
  assert.ok(!/tripMap|t3MapPoints/.test(js.slice(js.indexOf('function syncUrl()'), js.indexOf('// ---- plan helpers'))), 'the URL never carries map state');
  // V2 untouched.
  const v2 = app.renderTripPlannerPage(true);
  for (const s of ['t3MapPoints', 't3-map', 'LEAFLET_JS_SRI', 'https://tile.openstreetmap.org/']) assert.ok(!v2.includes(s), s);
});

// Stage 5H (2026-10-02): analytics only. trip_plan_complete carries the
// plan's pace (relaxed / standard / packed, never text), and a page that
// reloads its own plan (refresh, or Back / Forward loading it again) reports
// 'restore' instead of 'link' / 'shared_link'. Event names, other parameters
// and planner behaviour are unchanged; a damaged link is still
// trip_plan_error shared_link / invalid_share.
test('Stage 5H: V3 analytics -- pace on trip_plan_complete; reload / back-forward reported as restore, genuine links unchanged', () => {
  const html = app.renderTripPlannerV3Page({ preview: false });
  const js = html.slice(html.lastIndexOf('<script>') + 8, html.lastIndexOf('</script>'));
  new Function(js); // parses
  // pace: read from the plan, restricted to the three planner values, added to trip_plan_complete only.
  const PACE = "var pace = res.j && res.j.understood && res.j.understood.pace;\n        if (pace === 'relaxed' || pace === 'standard' || pace === 'packed') facts.pace = pace;\n        track('trip_plan_complete', facts);";
  assert.ok(js.includes(PACE));
  assert.equal(js.split('facts.pace').length, 2, 'pace is set in one place');
  const calls = js.match(/track\('[a-z_]+', \{[^}]*\}\)/g) || [];
  assert.ok(calls.every((c) => !/pace/.test(c)), 'no other event carries pace');
  const paceOf = (j) => { const facts = {}; vm.runInNewContext(PACE.replace("track('trip_plan_complete', facts);", ''), { res: { j }, facts }); return facts.pace; };
  for (const p of ['relaxed', 'standard', 'packed']) assert.equal(paceOf({ understood: { pace: p } }), p);
  for (const j of [{ understood: { pace: 'chaotic' } }, { understood: { pace: '<b>' } }, { understood: {} }, {}, null]) assert.equal(paceOf(j), undefined);
  // restore: only the browser's own load type; reload / back_forward -> restore, anything else -> link.
  const ARRIVAL = "var arrival = 'link';\n    try { var nav = performance.getEntriesByType('navigation')[0]; if (nav && (nav.type === 'reload' || nav.type === 'back_forward')) arrival = 'restore'; } catch (e) {}";
  assert.ok(js.includes(ARRIVAL));
  const arrivalFor = (performance) => vm.runInNewContext(ARRIVAL + '\narrival;', { performance });
  const nav = (type) => ({ getEntriesByType: (k) => (k === 'navigation' ? [{ type }] : []) });
  assert.equal(arrivalFor(nav('reload')), 'restore');
  assert.equal(arrivalFor(nav('back_forward')), 'restore');
  assert.equal(arrivalFor(nav('navigate')), 'link');
  assert.equal(arrivalFor(nav('prerender')), 'link');
  assert.equal(arrivalFor({ getEntriesByType: () => [] }), 'link', 'no entry: as before');
  assert.equal(arrivalFor({ getEntriesByType: () => { throw new Error('x'); } }), 'link', 'unsupported: as before');
  assert.equal(arrivalFor(undefined), 'link', 'no performance API: as before');
  // The restore block: start and plan request both follow arrival; the damaged-link error is unchanged.
  const block = js.slice(js.indexOf('var restored = t3QueryToState('), js.indexOf('})();', js.indexOf('var restored = t3QueryToState(')));
  assert.ok(block.indexOf(ARRIVAL) < block.indexOf("track('trip_plan_start', { input_method: arrival })"));
  assert.ok(block.includes("request(replay, { requestType: arrival === 'restore' ? 'restore' : 'shared_link', removedKeys: restored.removed });"));
  assert.equal(block.split("track('trip_plan_error', { request_type: 'shared_link', error_type: 'invalid_share' })").length, 3, 'both invalid_share errors still shared_link');
  // Nothing else: same event names and the same number of track() calls; requestType only labels analytics.
  assert.equal((js.match(/track\('/g) || []).length, 16);
  assert.deepEqual([...new Set((js.match(/track\('[a-z_]+'/g) || []).map((c) => c.slice(7, -1)))].sort(), ['add_whole_trip', 'open_my_trip', 'outbound_click', 'trip_plan_complete', 'trip_plan_edit', 'trip_plan_error', 'trip_plan_regenerate', 'trip_plan_share', 'trip_plan_start'].sort());
  // The planner also uses requestType to preserve the current itinerary when
  // an edit would lose a matched activity; remaining uses should be analytics.
  assert.ok(js.includes("t3EditLosesMatch(state.last,res.j)"), 'edit safety guard remains');
  for (const use of js.split('\n').filter((l) => /\brequestType\b/.test(l) && !/requestType: '|requestType: arrival|var requestType = /.test(l) && !/t3EditLosesMatch/.test(l))) assert.match(use, /track\(|facts\.request_type = requestType/, use.trim());
  // V2 untouched.
  const v2 = app.renderTripPlannerPage(true);
  for (const s of ['facts.pace', "'restore'", 'arrival']) assert.ok(!v2.includes(s), s);
});

test('Build My Trip V3: routes -- off ignores ?trip_v3; preview needs the opt-in cookie; on serves everyone (isolated child processes)', async () => {
  const projectRoot = path.join(__dirname, '..');
  const files = ['server.js', 'db.js', 'okanagan.html', 'hours.js', 'trip-planner.js', 'trip-requirements.js', 'trip-planner-fr.js', 'discovery-intent.js', 'discovery-search.js', 'trip-planner-v3-page.js', 'trip-event-location.js', 'trip-french-copy.js'];
  const run = async (port, env, fn) => {
    const tempDir = fs.mkdtempSync(path.join(os.tmpdir(), 'okanagan-tripv3-'));
    for (const f of files) fs.copyFileSync(path.join(projectRoot, f), path.join(tempDir, f));
    fs.copyFileSync(path.join(projectRoot, 'okanagan.db'), path.join(tempDir, 'okanagan.db'));
    const child = spawn(process.execPath, ['-e', `process.env.PORT='${port}'; require('./server.js').startServer();`], { cwd: tempDir, stdio: 'ignore', env: { ...process.env, TRIP_PLANNER_V2: 'on', ...env } });
    try {
      let ready = false;
      for (let i = 0; i < 100 && !ready; i++) { try { if ((await fetch(`http://localhost:${port}/robots.txt`)).status === 200) ready = true; } catch (_) { await new Promise((r) => setTimeout(r, 100)); } }
      assert.ok(ready, `child server ${port} started`);
      await fn((p, cookie) => fetch(`http://localhost:${port}${p}`, { redirect: 'manual', headers: cookie ? { cookie } : {} }));
    } finally { child.kill('SIGKILL'); fs.rmSync(tempDir, { recursive: true, force: true }); }
  };
  await run(3621, { TRIP_PLANNER_V3: '' }, async (get) => {
    const plain = await (await get('/trip')).text();
    const r = await get('/trip?trip_v3=on');
    assert.equal(r.status, 200);
    assert.equal(r.headers.get('set-cookie'), null);
    assert.equal(await r.text(), plain, 'with the flag off, ?trip_v3 is ignored');
    assert.equal(await (await get('/trip', 'roam_trip_v3=1')).text(), plain, 'and so is the cookie');
    assert.doesNotMatch(plain, /id="tripV3"/);
  });
  await run(3622, { TRIP_PLANNER_V3: 'preview' }, async (get) => {
    assert.doesNotMatch(await (await get('/trip')).text(), /id="tripV3"/, 'no opt-in: the current page');
    const on = await get('/trip?trip_v3=on');
    assert.equal(on.status, 302);
    assert.equal(on.headers.get('location'), '/trip');
    assert.match(on.headers.get('set-cookie'), /^roam_trip_v3=1; Path=\/; Max-Age=2592000; SameSite=Lax/);
    const v3 = await (await get('/trip', 'roam_trip_v3=1')).text();
    assert.match(v3, /id="tripV3"/);
    assert.match(v3, /noindex/);
    const off = await get('/trip?trip_v3=off');
    assert.match(off.headers.get('set-cookie'), /^roam_trip_v3=; Path=\/; Max-Age=0/);
    const api = await fetch('http://localhost:3622/api/trip/plan', { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ text: 'plan 2 days in Kelowna', overrides: { pace: 'relaxed' } }) });
    assert.equal(api.status, 200);
  });
  await run(3623, { TRIP_PLANNER_V3: 'on', TRIP_PLANNER_V2: '' }, async (get) => {
    const v3 = await (await get('/trip')).text();
    assert.match(v3, /id="tripV3"/);
    assert.doesNotMatch(v3, /noindex/);
    const api = await fetch('http://localhost:3623/api/trip/plan', { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ text: 'plan 2 days in Kelowna' }) });
    assert.equal(api.status, 200, 'the planner API is available to V3 even with V2 off');
  });
});

// V3 French support (PR #31 review, 2026-10-04): trip-planner-fr.js is loaded
// like the interpreter, never behind a try/catch. Present, French and English
// requests both plan through the real server; missing, the plan request fails
// with the module's own error instead of quietly planning in English only.
test('Build My Trip French: /api/trip/plan uses trip-planner-fr.js, and fails clearly without it (isolated child processes)', async () => {
  const projectRoot = path.join(__dirname, '..');
  const base = ['server.js', 'db.js', 'okanagan.html', 'hours.js', 'trip-planner.js', 'trip-requirements.js', 'discovery-intent.js', 'discovery-search.js', 'trip-planner-v3-page.js'];
  const run = async (port, files, fn) => {
    const tempDir = fs.mkdtempSync(path.join(os.tmpdir(), 'okanagan-tripfr-'));
    for (const f of files) fs.copyFileSync(path.join(projectRoot, f), path.join(tempDir, f));
    fs.copyFileSync(path.join(projectRoot, 'okanagan.db'), path.join(tempDir, 'okanagan.db'));
    const child = spawn(process.execPath, ['-e', `process.env.PORT='${port}'; require('./server.js').startServer();`], { cwd: tempDir, stdio: 'ignore', env: { ...process.env, TRIP_PLANNER_V2: 'on', TRIP_PLANNER_V3: 'on' } });
    try {
      let ready = false;
      for (let i = 0; i < 100 && !ready; i++) { try { if ((await fetch(`http://localhost:${port}/robots.txt`)).status === 200) ready = true; } catch (_) { await new Promise((r) => setTimeout(r, 100)); } }
      assert.ok(ready, `child server ${port} started`);
      await fn((text) => fetch(`http://localhost:${port}/api/trip/plan`, { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ text }) }));
    } finally { child.kill('SIGKILL'); fs.rmSync(tempDir, { recursive: true, force: true }); }
  };
  await run(3624, [...base, 'trip-planner-fr.js'], async (plan) => {
    const frRes = await plan('3 jours à Kelowna avec des vignobles');
    assert.equal(frRes.status, 200);
    const fr = await frRes.json();
    const en = await (await plan('3 days in Kelowna with vineyards')).json();
    assert.equal(fr.kind, 'multi_day');
    assert.equal(fr.days.length, 3);
    assert.deepEqual(fr.intent.types, ['winery']);
    assert.equal(fr.query, '3 jours à Kelowna avec des vignobles', 'the request shown is the visitor’s own');
    assert.deepEqual(fr.days.map((d) => d.stops.map((s) => s.venue && s.venue.id)), en.days.map((d) => d.stops.map((s) => s.venue && s.venue.id)), 'the same stops as the English request');
  });
  await run(3625, base, async (plan) => {
    for (const text of ['3 jours à Kelowna avec des vignobles', 'Plan 3 days in Kelowna']) {
      const r = await plan(text);
      assert.equal(r.status, 500, text);
      assert.match((await r.json()).error, /trip-planner-fr/, 'the error names the missing module');
    }
  });
});

// ---- Build My Trip static map day headers (2026-10-07) --------------------------
// 20 pre-rendered OSM Carto maps (Geoapify Static Maps, osm-carto), two per region, built by
// scripts/build-region-maps.js. The day header makes no tile, Leaflet or API request.
const MAPS_DIR = path.join(__dirname, '..', 'public', 'images', 'regions', 'maps');
const MAPS_CONFIG = require('../scripts/region-maps.config.json');
const MAPS_MANIFEST = () => JSON.parse(fs.readFileSync(path.join(MAPS_DIR, 'manifest.json'), 'utf8'));
// Pixel size of a WebP (lossy VP8, lossless VP8L or extended VP8X).
const webpDims = (file) => {
  const b = fs.readFileSync(file);
  assert.equal(b.toString('ascii', 0, 4), 'RIFF'); assert.equal(b.toString('ascii', 8, 12), 'WEBP');
  const t = b.toString('ascii', 12, 16);
  if (t === 'VP8 ') return [b.readUInt16LE(26) & 0x3fff, b.readUInt16LE(28) & 0x3fff];
  if (t === 'VP8X') return [1 + b.readUIntLE(24, 3), 1 + b.readUIntLE(27, 3)];
  const v = b.readUInt32LE(21); return [(v & 0x3fff) + 1, ((v >> 14) & 0x3fff) + 1];
};

test('map day headers: exactly the 20 locked configs, the approved Penticton and West Kelowna values, markers inside BC', () => {
  const slugs = Object.keys(MAPS_CONFIG.regions);
  assert.equal(slugs.length, 20);
  assert.deepEqual([...slugs].sort(), Object.keys(app.REGION_LABELS).sort(), 'one config per planner region, no extras');
  assert.deepEqual(MAPS_CONFIG.regions.penticton, { marker: [49.5008, -119.5939], desktop: { view: [49.5042, -119.5939], zoom: 12 } }, 'Penticton is the approved reference');
  const wk = MAPS_CONFIG.regions['west-kelowna'];
  assert.deepEqual(wk.marker, [49.8625, -119.5833]);
  assert.deepEqual(wk.desktop, { view: [49.8630, -119.5450], zoom: 12 });
  assert.deepEqual(wk.narrow, { view: [49.8607, -119.5583], zoom: 11, height: 200, switchBelow: 1100 }, 'West Kelowna alone has its own narrow framing, through 1099px');
  for (const [slug, r] of Object.entries(MAPS_CONFIG.regions)) {
    const [lat, lng] = r.marker;
    assert.ok(lat > 48.9 && lat < 50.8 && lng > -120.1 && lng < -118.7, `${slug}: marker inside the Okanagan/BC bounds`);
    assert.ok(Math.abs(r.desktop.view[0] - lat) < 0.03 && Math.abs(r.desktop.view[1] - lng) < 0.06, `${slug}: the view only nudges the composition, it never moves the marker`);
    assert.ok(Number.isInteger(r.desktop.zoom) && r.desktop.zoom >= 11 && r.desktop.zoom <= 13, `${slug}: zoom`);
    if (slug !== 'west-kelowna') assert.equal(r.narrow, undefined, `${slug}: the narrow map uses the locked framing`);
  }
  // The documented decisions for the points that changed during QA.
  assert.deepEqual(MAPS_CONFIG.regions['lake-country'].marker, [50.0300, -119.4022]);
  assert.deepEqual(MAPS_CONFIG.regions.coldstream.marker, [50.2236, -119.2300]);
  assert.deepEqual(MAPS_CONFIG.regions.apex.marker, [49.3910, -119.9040]);
});

test('map day headers: 40 WebP assets (2 per region at 2x), valid manifest, ring inside every window, no secrets', () => {
  const m = MAPS_MANIFEST();
  assert.equal(m.provider, 'Geoapify Static Maps'); assert.equal(m.style, 'osm-carto');
  assert.equal(m.sourceFormat, 'png'); assert.equal(m.outputFormat, 'webp'); assert.equal(m.webpQuality, 82); assert.equal(m.scaleFactor, 2);
  assert.notEqual(m.attributionParam, 'none', 'attribution=none is for white-label paid plans only');
  assert.deepEqual(m.attribution, [
    { text: '© OpenStreetMap contributors', href: 'https://www.openstreetmap.org/copyright' },
    { text: 'Powered by Geoapify', href: 'https://www.geoapify.com/' },
  ]);
  const slugs = Object.keys(MAPS_CONFIG.regions);
  assert.deepEqual(Object.keys(m.regions).sort(), [...slugs].sort());
  let files = 0, bytes = 0;
  for (const slug of slugs) {
    const r = m.regions[slug];
    assert.deepEqual(r.marker, MAPS_CONFIG.regions[slug].marker, `${slug}: manifest marker equals the locked marker`);
    for (const kind of ['desktop', 'narrow']) {
      const x = r[kind];
      const full = path.join(MAPS_DIR, x.file);
      assert.ok(fs.existsSync(full), x.file);
      const [w, h] = webpDims(full);
      const wantH = kind === 'desktop' ? 480 : (slug === 'west-kelowna' ? 480 : 320);
      assert.deepEqual([w, h], [kind === 'desktop' ? 1292 : 1280, wantH], `${x.file}: 2x of the CSS size, nothing upscaled`);
      assert.deepEqual([x.sourceSize.w, x.sourceSize.h], [w, h]);
      assert.deepEqual([x.cssSize.w * 2, x.cssSize.h * 2], [w, h]);
      assert.ok(x.webpBytes === fs.statSync(full).size && x.webpBytes < 90000, `${x.file}: a small download`);
      files++; bytes += x.webpBytes;
      // The true marker must sit inside the displayed window with the ring fully visible (desktop 646x200; narrow 317x120, or 200 for West Kelowna).
      const win = kind === 'desktop' ? { w: 646, h: 200 } : { w: 317, h: x.displayWindow.h };
      assert.ok(Math.abs(x.markerOffsetPx.dx) <= win.w / 2 - 10 && Math.abs(x.markerOffsetPx.dy) <= win.h / 2 - 10, `${slug} ${kind}: ring fully inside the window`);
    }
  }
  assert.equal(files, 40); assert.ok(bytes < 2 * 1024 * 1024, 'all 40 maps together stay under 2 MB');
  assert.equal(fs.readdirSync(MAPS_DIR).filter((f) => f.endsWith('.webp')).length, 40, 'no stray map files');
  assert.equal(m.regions['west-kelowna'].narrow.switchBelowPx, 1100);
  for (const slug of slugs.filter((x) => x !== 'west-kelowna')) assert.equal(m.regions[slug].narrow.switchBelowPx, 721);
  // No credential or authenticated URL anywhere we ship.
  const shipped = [fs.readFileSync(path.join(MAPS_DIR, 'manifest.json'), 'utf8'), fs.readFileSync(path.join(__dirname, '..', 'scripts', 'region-maps.config.json'), 'utf8'), fs.readFileSync(path.join(__dirname, '..', 'scripts', 'build-region-maps.js'), 'utf8')];
  for (const t of shipped) assert.ok(!/apiKey=[0-9a-f]{16,}/i.test(t) && !/GEOAPIFY_API_KEY\s*=\s*['"]?[0-9a-f]{16,}/i.test(t) && !/\b[0-9a-f]{32}\b/i.test(t), 'no API key');
  assert.ok(!/apiKey|maps\.geoapify\.com/i.test(shipped[0]), 'the manifest holds no request URL');
});

test('map day headers: the page uses static <picture> maps with both credits as links, makes no live map request, and keeps its other behaviour', () => withDiscoveryFlag('on', () => withPlannerFlag('on', () => withDiscoveryServer(async (base) => {
  const page = app.renderTripPlannerV3Page({ preview: true });
  const mh = JSON.parse(page.match(/var MAP_HEADERS = (\{.*?\});\n/s)[1]);
  assert.equal(Object.keys(mh).length, 20, 'every region has a map header config');
  assert.deepEqual(mh['west-kelowna'].assets.narrow.below, 1100);
  assert.equal(mh.penticton.assets.narrow.below, 721);
  assert.match(mh.penticton.assets.desktop.src, /^\/images\/regions\/maps\/penticton-d\.webp\?v=[0-9a-f]+$/);
  assert.deepEqual(mh.penticton.group, { key: 'wizard.south', label: 'South Okanagan' });
  assert.deepEqual(mh['big-white'].group, { key: 'wizard.skiResorts', label: 'Ski resorts' });
  // Responsive loading: one <picture>, only the matching file downloads; the ring is an HTML overlay.
  for (const bit of ['function staticMapHtml', '<picture>', "'<source media=\"(max-width: '", 'class="t3-dh-ring"', 'aria-hidden="true"', 'alt=""', 'width="', "loading=\"' + (first ? 'eager' : 'lazy')", 'function watchStaticMaps', 't3-dh-nomap', '(max-width: 1099px)']) assert.ok(page.includes(bit), bit);
  // Both required credits are real links beside the map.
  assert.ok(page.includes('href="https://www.openstreetmap.org/copyright"') && page.includes('href="https://www.geoapify.com/"'));
  assert.ok(page.includes("Powered by Geoapify") && page.includes('\u00a9 OpenStreetMap contributors'));
  // No Geoapify API traffic for day headers (the old live header maps stay gone).
  for (const gone of ['initDayMaps', 'destroyDayMaps', 'data-t3-dhmap', 't3-dh-canvas', 'dayMapData']) assert.ok(!page.includes(gone), `${gone} is gone`);
  // 2026-10-18: each day's stops are placed on its header map (numbered pins on the picture, from its zoom and centre);
  // a day spread wider than the picture gets a small OpenStreetMap map fitted to its stops, only once it scrolls near.
  assert.ok(page.includes('t3-dh-pin') && page.includes('function fitDayMaps') && page.includes('IntersectionObserver') && page.includes('data-t3-fit-day'));
  assert.ok(Number.isFinite(mh.penticton.assets.desktop.z) && mh.penticton.assets.desktop.view.length === 2, 'zoom and centre reach the page');
  assert.ok(!/maps\.geoapify\.com|apiKey/i.test(page), 'the browser never talks to the Geoapify API');
  // The whole-trip interactive map and "Map this day" are unchanged.
  assert.ok(page.includes('function loadLeaflet') && page.includes('L.tileLayer(MAP_TILES') && page.includes('tripMap'));
  assert.ok(page.includes('data-t3-map-day') && page.includes("esc(tx('tripv3.mapDay'))") && page.includes('data-t3-regen-day') && page.includes('data-t3-add-day'));
  assert.ok(page.includes("var head = MAP_HEADERS[d.region] && MAP_HEADERS[d.region].assets ? mapHeadHtml("), 'every day with a map gets the map header (2026-10-18); a region without a map keeps the photo header');
  // The served images are real WebP, and nothing else carries any of it.
  const res = await fetch(`${base}${mh.penticton.assets.desktop.src}`);
  assert.equal(res.status, 200); assert.equal(res.headers.get('content-type'), 'image/webp');
  const home = await (await fetch(`${base}/`)).text();
  assert.ok(!home.includes('t3-dh-') && !home.includes('MAP_HEADERS') && !home.includes('regions/maps/'), 'homepage untouched');
  const classic = await fetch(`${base}/browse/classic`);
  assert.ok(!(await classic.text()).includes('regions/maps/'), '/browse/classic untouched');
}))));

test('map day headers: the baked colour treatment is the one recorded in the manifest, and maps carry no CSS tint', () => {
  const T = require('../scripts/map-treatment.js');
  assert.equal(MAPS_MANIFEST().treatment, T.TREATMENT_ID);
  const near = (a, b, tol) => a.every((v, i) => Math.abs(v - b[i]) <= tol);
  assert.ok(near(T.mapPixel(0xa8, 0xd0, 0xdc), [0xA7, 0xC4, 0xC9], 6), 'water becomes the approved muted teal');
  const road = T.mapPixel(0xf8, 0xb0, 0x9c); assert.ok(road[1] > 0xA0 && road[0] - road[2] < 60, 'the trunk road is sand, no longer pink');
  assert.ok(T.mapPixel(0, 0, 0)[2] > T.mapPixel(0, 0, 0)[0], 'label text is navy, not black');
  assert.deepEqual(T.mapPixel(0xa8, 0xd0, 0xdc), T.mapPixel(0xa8, 0xd0, 0xdc), 'deterministic');
  const buf = Buffer.from([0xf8, 0xb0, 0x9c, 0xa8, 0xd0, 0xdc]);
  assert.deepEqual([...T.treatRgb(buf)].slice(0, 3), T.mapPixel(0xf8, 0xb0, 0x9c), 'treatRgb is the per-pixel map');
  const page = app.renderTripPlannerV3Page({ preview: true });
  const rule = (sel) => { const m = page.match(new RegExp(sel.replace(/[.*+?^${}()|[\]\\]/g, '\\$&') + ' \\{([^}]*)\\}')); assert.ok(m, sel); return m[1]; };
  assert.match(rule('.t3-dh-frame img'), /filter: none/);
  assert.ok(!/saturate\(|sepia\(/.test(rule('.t3-dh-frame img')), 'no CSS map tint');
  assert.match(rule('.t3-day .t3-day-head--map'), /background: var\(--ref-navy, #1B2B3A\)/);
  assert.match(rule('.t3-day-head--map .t3-eyebrow'), /#E0A94E/);
  assert.match(rule('.t3-dh-sub'), /#E0A94E/);
  assert.ok(!/#E0A94E/.test(rule('.t3-day-head--map .t3-day-title')), 'the destination name is not gold');
  assert.match(rule('.t3-day-head--map .t3-day-actions .t3-btn'), /background: #fff; color: var\(--ref-navy-deep/);
});

test('map day headers: a region whose config or image is missing falls back to the existing photo header', () => {
  const tmp = fs.mkdtempSync(path.join(os.tmpdir(), 'maps-fallback-'));
  try {
    const m = MAPS_MANIFEST();
    fs.writeFileSync(path.join(tmp, 'manifest.json'), JSON.stringify(m));
    for (const f of fs.readdirSync(MAPS_DIR).filter((x) => x.endsWith('.webp'))) fs.copyFileSync(path.join(MAPS_DIR, f), path.join(tmp, f));
    assert.equal(Object.keys(app.tripV3MapHeaders(tmp)).length, 20, 'a complete set is all listed');
    fs.unlinkSync(path.join(tmp, 'kelowna-n.webp'));
    const out = app.tripV3MapHeaders(tmp);
    assert.equal(out.kelowna, undefined, 'a missing narrow image drops that region (no broken image, no blank shell)');
    assert.equal(Object.keys(out).length, 19);
    const bad = MAPS_MANIFEST(); bad.regions.penticton.desktop.file = '../server.js'; bad.regions.atlantis = bad.regions.oliver;
    fs.writeFileSync(path.join(tmp, 'manifest.json'), JSON.stringify(bad));
    const out2 = app.tripV3MapHeaders(tmp);
    assert.equal(out2.penticton, undefined, 'an unsafe file name is refused'); assert.equal(out2.atlantis, undefined, 'an unknown region is ignored');
    fs.writeFileSync(path.join(tmp, 'manifest.json'), '{not json');
    assert.deepEqual(app.tripV3MapHeaders(tmp), {}, 'an unreadable manifest means no map headers at all');
    assert.deepEqual(app.tripV3MapHeaders(path.join(tmp, 'nope')), {});
  } finally { fs.rmSync(tmp, { recursive: true, force: true }); }
});

