const browseCardIds = (html) => {
  const list = html.slice(html.indexOf('id="bhResults"'), html.indexOf('<template id="bhRest">'));
  return [...list.matchAll(/<li class="venue-card"[^>]*data-venue-id="(\d+)"/g)].map((m) => Number(m[1]));
};

