// ---- /browse/classic Open Now status from the canonical hours engine (2026-10) -----------
// app.js's computeOpenStatus() / formatWeeklyHoursTooltip() (frozen) mis-read 25:00+ closes,
// call a missing day "Closed" and print 25:00 as "1 PM". renderClassicOpenStatusScript()
// replaces both on /browse/classic with versions built from hours.js.
{
  const vm = require('node:vm');
  const appSrc = fs.readFileSync(path.join(__dirname, '..', 'public', 'scripts', 'app.js'), 'utf8');
  const legacyBlock = appSrc.slice(appSrc.indexOf("var DAY_ORDER = ['sun'"), appSrc.indexOf('var CARD_REGION_LABEL'))
    + appSrc.slice(appSrc.indexOf('function formatTime12h'), appSrc.indexOf('function escapeAttr'));
  const hoursMod = require('../hours.js');
  const WD = ['mon', 'tue', 'wed', 'thu', 'fri', 'sat', 'sun'];
  const classicCtx = (override) => {
    const ctx = { Intl, Date, parseInt, JSON, console };
    ctx.window = ctx;
    vm.createContext(ctx);
    vm.runInContext(legacyBlock, ctx);
    if (override) vm.runInContext(app.renderClassicOpenStatusScript().replace(/^\s*<script>/, '').replace(/<\/script>\s*$/, ''), ctx);
    return ctx;
  };
  // Mon 2026-10-05 00:00 PDT = 07:00Z
  const when = (wd, hhmm) => { const [h, m] = hhmm.split(':').map(Number); return new Date(Date.UTC(2026, 9, 5 + wd, 7, 0) + (h * 60 + m) * 60000); };
  const week = (f) => JSON.stringify(Object.fromEntries(WD.map((d, i) => [d, f(d, i)])));

  test('Classic Open Now: 25:00+ closes read as the next morning (the legacy function got these wrong)', () => {
    const legacy = classicCtx(false), fixed = classicCtx(true);
    const late = week(() => [['21:00', '25:00']]);
    assert.equal(legacy.computeOpenStatus(late, when(1, '00:30')), 'closed', 'the legacy bug is real (guards the test)');
    assert.equal(fixed.computeOpenStatus(late, when(0, '23:30')), 'open', 'Monday 23:30, 90 minutes to the 01:00 close');
    assert.equal(fixed.computeOpenStatus(late, when(1, '00:30')), 'closing-soon', 'Tuesday 00:30 is still Monday night: 30 minutes to the close');
    assert.equal(fixed.computeOpenStatus(late, when(1, '01:00')), 'closed');
    const later = week(() => [['12:00', '26:00']]);
    assert.equal(fixed.computeOpenStatus(later, when(0, '00:30')), 'open', 'Sunday night run into Monday');
    assert.equal(fixed.computeOpenStatus(later, when(1, '01:10')), 'closing-soon');
    assert.equal(fixed.computeOpenStatus(later, when(1, '02:00')), 'closed');
  });

  test('Classic Open Now: unknown or missing hours show no badge, never "Closed"; closed days still say Closed', () => {
    const legacy = classicCtx(false), fixed = classicCtx(true);
    const noMon = JSON.stringify({ tue: [['11:00', '21:00']], wed: null, thu: null, fri: null, sat: null, sun: null });
    assert.equal(legacy.computeOpenStatus(noMon, when(0, '12:00')), 'closed', 'legacy called a missing day Closed (guards the test)');
    assert.equal(fixed.computeOpenStatus(noMon, when(0, '12:00')), null, 'missing Monday: no claim');
    assert.equal(fixed.computeOpenStatus(noMon, when(2, '12:00')), 'closed', 'a day listed null is Closed');
    for (const bad of [null, '', '{not json', '[1,2]', '{}']) assert.equal(fixed.computeOpenStatus(bad, when(0, '12:00')), null, String(bad));
    assert.equal(fixed.computeOpenStatus(week(() => [['00:00', '00:00']]), when(3, '15:00')), 'open', '24-hour day');
  });

  test('Classic Open Now: for every hours shape and 15-minute step, the result agrees with hours.js (open/closing-soon <=> open, closed <=> closed, null <=> unknown)', () => {
    const fixed = classicCtx(true);
    const shapes = [
      week(() => [['11:00', '21:00']]), week(() => [['9:00', '17:00']]), week((d) => (d === 'mon' ? null : [['11:00', '21:00']])),
      week(() => [['11:00', '14:00'], ['17:00', '22:00']]), week(() => [['18:00', '02:00']]), week(() => [['23:00', '01:00']]),
      week(() => [['12:00', '26:00']]), week(() => [['21:00', '25:00']]), week(() => [['00:00', '00:00']]), week(() => [['00:00', '24:00']]),
      week(() => [['00:00', '23:59']]), week(() => [['10:00', '00:00']]), week((d) => (d === 'sun' ? undefined : [['11:00', '21:00']])),
    ];
    for (const raw of shapes) {
      const parsed = hoursMod.parseHours(raw);
      for (let wd = 0; wd < 7; wd++) for (let m = 0; m < 1440; m += 15) {
        const want = hoursMod.statusAt(parsed, { weekday: WD[wd], minutes: m }).state;
        const got = fixed.computeOpenStatus(raw, when(wd, String(Math.floor(m / 60)).padStart(2, '0') + ':' + String(m % 60).padStart(2, '0')));
        const mapped = got === 'open' || got === 'closing-soon' ? 'open' : (got === 'closed' ? 'closed' : 'unknown');
        assert.equal(mapped, want, `${raw.slice(0, 60)} ${WD[wd]} ${m}`);
      }
    }
  });

  test('Classic Open Now: the hours tooltip prints 25:00+ as the next morning, and a missing day as not listed', () => {
    const legacy = classicCtx(false), fixed = classicCtx(true);
    const raw = JSON.stringify({ mon: [['21:00', '25:00']], tue: [['12:00', '26:00']], wed: [['18:00', '02:00']], thu: null, fri: [['11:00', '14:00'], ['17:00', '22:00']], sat: [['00:00', '23:59']] });
    assert.match(legacy.formatWeeklyHoursTooltip(raw), /Mon: 9 PM\u20131 PM/, 'the legacy tooltip bug is real (guards the test)');
    assert.equal(fixed.formatWeeklyHoursTooltip(raw), [
      'Mon: 9 PM\u20131 AM', 'Tue: 12 PM\u20132 AM', 'Wed: 6 PM\u20132 AM', 'Thu: Closed', 'Fri: 11 AM\u20132 PM, 5 PM\u201310 PM', 'Sat: 12 AM\u201311:59 PM', 'Sun: Hours not listed',
    ].join('\n'));
    assert.equal(fixed.formatWeeklyHoursTooltip(null), ''); assert.equal(fixed.formatWeeklyHoursTooltip('{bad'), '');
  });

  test('Classic Open Now: the override is injected on /browse/classic only, after app.js; the filter keeps Closing Soon there', () => withDiscoveryServer(async (base) => {
    const classic = await (await fetch(`${base}/browse/classic`)).text();
    const appAt = classic.indexOf('<script src="/scripts/app.js');
    const overrideAt = classic.indexOf('window.computeOpenStatus = function');
    const filterAt = classic.indexOf('var SHOW_OPEN_NOW_BUTTON = true;');
    assert.ok(appAt > 0 && overrideAt > appAt && filterAt > overrideAt, 'app.js, then the override, then the Open Now filter');
    assert.equal((classic.match(/window\.computeOpenStatus = function/g) || []).length, 1);
    assert.match(classic, /card\.querySelector\('\.open-status-open, \.open-status-closing-soon'\)/);
    for (const page of ['/', '/browse', '/food-drink', '/trip']) {
      const html = await (await fetch(base + page)).text();
      assert.doesNotMatch(html, /window\.computeOpenStatus = function/, `${page}: untouched`);
    }
    const crypto = require('node:crypto');
    const md5 = (rel) => crypto.createHash('md5').update(fs.readFileSync(path.join(__dirname, '..', rel))).digest('hex');
    assert.equal(md5('public/scripts/app.js'), 'e079ad5a3e0a9a71b3fe37994377ef85', 'app.js is unchanged by the classic Open Now page');
  }));
}


// ---- Reviewed event batches (2026-10-09) ---------------------------------------
test('Event batches: the reviewed batch goes in through createEvent, adds a missing date to an existing event, and is idempotent', () => {
  // Only this batch, so later batch files in data/event-batches don't change the counts.
  const batchDir = fs.mkdtempSync(path.join(require('node:os').tmpdir(), 'okr-batch-'));
  fs.copyFileSync(path.join(__dirname, '..', 'data', 'event-batches', '2026-10-09-tourism-kelowna-harvest-bites-sips.json'), path.join(batchDir, 'harvest.json'));
  const batch = JSON.parse(fs.readFileSync(path.join(batchDir, 'harvest.json'), 'utf8'));
  const names = [...batch.events.map((e) => e.name), 'Oktoberfest at The Hatching Post'];
  const cleanup = () => {
    const ids = db.prepare(`SELECT id FROM events WHERE name IN (${names.map(() => '?').join(',')})`).all(...names).map((r) => r.id);
    for (const id of ids) {
      db.prepare('DELETE FROM event_enrichment_log WHERE event_id = ?').run(id);
      db.prepare('DELETE FROM event_categories WHERE event_id = ?').run(id);
      db.prepare('DELETE FROM event_occurrences WHERE event_id = ?').run(id);
      db.prepare('DELETE FROM events WHERE id = ?').run(id);
    }
  };
  cleanup();
  try {
    // An existing event (as Visit Westside lists it) that only has Oct 16.
    const existing = app.createEvent({
      name: 'Oktoberfest at The Hatching Post', region: 'west-kelowna', venue_name_text: 'The Hatching Post', categories: ['food-drink-events', 'holiday-seasonal'],
      source_type: 'tourism_org', source_name: 'Visit Westside', source_url: 'https://example.com/batch-test/oktoberfest', occurrences: [{ start_date: '2026-10-16', start_time: '15:00', end_time: '21:00' }],
    }, { reason: 'batch test fixture', batch_id: 'batch-test' });
    assert.equal(existing.ok, true, JSON.stringify(existing));
    const first = app.importEventBatches(batchDir);
    assert.deepEqual(first.failed, []);
    assert.equal(first.created.length, batch.events.length + 1, 'every new event plus the added Oct 17 date');
    const okt = db.prepare("SELECT id FROM events WHERE name = 'Oktoberfest at The Hatching Post'").get();
    assert.deepEqual(db.prepare('SELECT start_date FROM event_occurrences WHERE event_id = ? ORDER BY start_date').all(okt.id).map((r) => r.start_date), ['2026-10-16', '2026-10-17']);
    const whisky = app.queryWhatsOnEvents({ from: '2026-10-17', to: '2026-10-17' }).find((e) => e.name === 'Whisky Global');
    assert.ok(whisky, 'Whisky Global shows on What’s On for Oct 17');
    assert.equal(whisky.attribution, 'Tourism Kelowna');
    assert.ok(app.queryWhatsOnEvents({ from: '2026-10-18', to: '2026-10-18' }).some((e) => e.name === 'Lake Country Cider Fest'));
    assert.ok(app.queryWhatsOnEvents({ from: '2026-10-24', to: '2026-10-24' }).some((e) => e.name === 'Brewphoria 2026'));
    // Idempotent: a second run (every deploy) creates and changes nothing.
    const second = app.importEventBatches(batchDir);
    assert.deepEqual([second.created.length, second.failed.length], [0, 0]);
    assert.equal(db.prepare(`SELECT COUNT(*) AS n FROM events WHERE name IN (${names.map(() => '?').join(',')})`).get(...names).n, names.length);
    // A missing directory or file is harmless.
    assert.deepEqual(app.importEventBatches(path.join(batchDir, 'nope')), { created: [], skipped: [], failed: [] });
  } finally {
    cleanup();
  }
  assert.equal(db.prepare(`SELECT COUNT(*) AS n FROM events WHERE name IN (${names.map(() => '?').join(',')})`).get(...names).n, 0);
});

test('Event batches: `updates` correct an existing event\'s description and categories through the logged update path, only once, and report a missing event', () => {
  const dir = fs.mkdtempSync(path.join(require('node:os').tmpdir(), 'okr-batch-upd-'));
  const name = 'Batch Update Fixture Ballet';
  const cleanup = () => {
    for (const { id } of db.prepare('SELECT id FROM events WHERE name = ?').all(name)) {
      for (const t of ['event_enrichment_log', 'event_categories', 'event_occurrences']) db.prepare(`DELETE FROM ${t} WHERE event_id = ?`).run(id);
      db.prepare('DELETE FROM events WHERE id = ?').run(id);
    }
  };
  cleanup();
  try {
    const made = app.createEvent({
      name, region: 'vernon', venue_name_text: 'Test Hall', description: 'Placeholder.', categories: ['events-festivals', 'holiday-seasonal'],
      source_type: 'tourism_org', source_name: 'Test Tourism', source_url: 'https://example.com/batch-update/ballet', occurrences: [{ start_date: '2032-02-04' }],
    }, { reason: 'batch update fixture', batch_id: 'batch-update-test' });
    assert.equal(made.ok, true, JSON.stringify(made));
    fs.writeFileSync(path.join(dir, 'fix.json'), JSON.stringify({
      batch_id: 'batch-update-test', reason: 'test corrections', reviewed_by: 'test',
      updates: [
        { region: 'vernon', name, fields: { description: 'A full-length ballet.' }, categories: ['arts-culture', 'events-festivals'] },
        { region: 'vernon', name: 'No Such Event Anywhere', categories: ['arts-culture'] },
      ],
    }));
    const first = app.importEventBatches(dir);
    assert.deepEqual(first.created, [`${name} (updated)`]);
    assert.deepEqual(first.failed, [{ name: 'No Such Event Anywhere', reason: 'event_not_found' }]);
    const row = db.prepare('SELECT id, description FROM events WHERE name = ?').get(name);
    assert.equal(row.description, 'A full-length ballet.');
    assert.deepEqual(db.prepare('SELECT category_key FROM event_categories WHERE event_id = ? ORDER BY position').all(row.id).map((r) => r.category_key), ['arts-culture', 'events-festivals']);
    const logged = db.prepare('SELECT field_name FROM event_enrichment_log WHERE event_id = ?').all(row.id).map((r) => r.field_name);
    assert.ok(logged.includes('description') && logged.includes('categories'), 'both changes are in the change log');
    const second = app.importEventBatches(dir);
    assert.deepEqual(second.created, [], 'a re-run changes nothing');
    assert.ok(second.skipped.includes(name));
  } finally {
    cleanup();
  }
});

// ---- Page weight (2026-10-10): listing ItemLists don't repeat descriptions ----
test('Page weight: Food & Drink and guide ItemLists keep url + name per venue but no repeated description', () => {
  const venues = app.listVenues({ limit: 1000 }).venues;
  const parseItemList = (html) => html.split('<script type="application/ld+json">').map((b) => b.split('</script>')[0].trim())
    .filter((b) => b.startsWith('{') && b.includes('"@type":"ItemList"')).map((b) => JSON.parse(b))[0];
  for (const html of [app.renderFoodDrinkHubPage(venues.filter((v) => ['restaurant', 'cafe', 'brewery', 'pub', 'cocktail'].includes(v.type))), app.renderGuidePage('kelowna', 'patio', venues.filter((v) => v.region === 'kelowna'))]) {
    const list = parseItemList(html);
    assert.ok(list && list.itemListElement.length > 0, 'ItemList present');
    assert.ok(list.itemListElement.every((x) => (x.name || (x.item && x.item.name)) && !('description' in (x.item || {})) && !('description' in x)), 'name kept, description dropped');
  }
});

