test('Sports & Recreation: other-type venues tagged sports_also get a "More places to play" section on /sports, with "Play:" notes, linking to their own pages', async () => {
  const park = app.createVenue({ name: 'Sports Also City Park', region: 'kelowna', type: 'outdoor', description: 'A lakeside city park with a skate park, tennis courts and long descriptions that run on and on (fixture).', slug: 'sports-also-city-park' });
  const course = app.createVenue({ name: 'Sports Also Disc Golf Club', region: 'vernon', type: 'golf', description: 'A golf course with a disc golf loop (fixture).', slug: 'sports-also-disc-golf-club' });
  try {
    await withWinterServer(async (base) => {
      for (const v of [park, course]) {
        const r = app.guardedCollectionMembershipUpdate('sports_also', v.id, 'add', v === park ? 'Skate park and four tennis courts' : null, { reason: 'fixture', batch_id: 'test' });
        assert.ok(r.ok, JSON.stringify(r));
      }
      assert.deepEqual(app.getSportsAlsoVenues().map((v) => v.name), ['Sports Also City Park', 'Sports Also Disc Golf Club']);
      assert.equal(app.countSportsHubVenues(), 2);
      const hub = await WINTER_GET(base, '/sports');
      assert.equal(hub.status, 200);
      // One list since 2026-10-14: tagged places sit with the rest, counted.
      assert.match(hub.text, /id="fdResultsSummary" aria-live="polite">2 places to play</);
      assert.doesNotMatch(hub.text, /class="sport-coming-soon"/, 'tagged places count as places to play');
      assert.match(hub.text, /href="\/kelowna\/outdoors\/sports-also-city-park"/, 'a park links to its outdoors page');
      assert.match(hub.text, /href="\/vernon\/golf\/sports-also-disc-golf-club"/, 'a golf course links to its golf page');
      assert.doesNotMatch(hub.text, /noindex/);
      // The membership note is that card's "Play:" line; a card without one names its activities.
      assert.match(hub.text, /<p class="card-note"><span class="card-note-label">Play:<\/span> Skate park and four tennis courts<\/p>/);
      assert.match(hub.text, /<p class="card-note"><span class="card-note-label">Play:<\/span> Disc Golf<\/p>/);
      assert.doesNotMatch(hub.text, /Rainy day:|Experience:<\/span>/);
      // The card script wires every type on /sports, and descriptions clamp to 3 lines.
      assert.match(hub.text, /querySelectorAll\('\.venue-card:is\([^)]*\[data-venue-category="golf"\][^)]*\[data-venue-category="outdoor"\]/);
      assert.match(hub.text, /body\.fd-page \.card-grid > li\.venue-card\[data-ph\] \.golf-desc p \{ display: -webkit-box; -webkit-line-clamp: 3;/);
      // Their own pages and types are untouched; /tours does not list them.
      assert.equal((await WINTER_GET(base, '/kelowna/outdoors/sports-also-city-park')).status, 200);
      assert.equal(app.getVenue(park.id).type, 'outdoor');
      assert.doesNotMatch((await WINTER_GET(base, '/tours')).text, /Play:<\/span>|sports-also-city-park/);
      // Region pages (2026-10-12): a region whose only places to play are
      // tagged venues still gets /:region/sports, with the same section and
      // notes, and the sitemap lists it; the hub's region selector offers it.
      const kel = await WINTER_GET(base, '/kelowna/sports');
      assert.equal(kel.status, 200);
      assert.match(kel.text, /<h2 class="category-subsection-heading" id="sportsAlsoHeading">More places to play<\/h2>/);
      assert.match(kel.text, /href="\/kelowna\/outdoors\/sports-also-city-park"/);
      assert.match(kel.text, /<span class="card-note-label">Play:<\/span> Skate park and four tennis courts/);
      assert.doesNotMatch(kel.text, /noindex|No sports &amp; recreation are listed/);
      assert.doesNotMatch(kel.text, /sports-also-disc-golf-club/, 'only this region\'s tagged venues');
      const sitemap = await WINTER_GET(base, '/sitemap.xml');
      assert.match(sitemap.text, /<loc>https:\/\/okanaganroam\.com\/kelowna\/sports<\/loc>/);
      assert.match(sitemap.text, /<loc>https:\/\/okanaganroam\.com\/vernon\/sports<\/loc>/);
      // A region with nothing to play is still a 404.
      assert.equal((await WINTER_GET(base, '/osoyoos/sports')).status, 404);
      // With one sport venue of its own, the count reads in the singular.
      const own = app.createVenue({ name: 'Sports Also Test Skate Park', region: 'kelowna', type: 'sport', description: 'A fixture skate park.', slug: 'sports-also-test-skate-park' });
      try {
        const kel2 = await WINTER_GET(base, '/kelowna/sports');
        assert.match(kel2.text, /<p class="subtitle">1 verified sports &amp; recreation spot in Kelowna\.<\/p>/);
        assert.match(kel2.text, /href="\/kelowna\/sports\/sports-also-test-skate-park"[\s\S]*id="sportsAlsoHeading"/, 'its own venues first, then More places to play');
        const hub2 = await WINTER_GET(base, '/sports');
        // One list since 2026-10-14: its own venue and the two tagged places.
        assert.match(hub2.text, /id="fdResultsSummary" aria-live="polite">3 places to play</);
        assert.match(hub2.text, /<a href="\/vernon\/sports">Vernon <span>1<\/span><\/a>/, 'the town links offer a region that only has tagged venues');
      } finally {
        db.prepare('DELETE FROM venues WHERE id = ?').run(own.id);
      }
    });
    // The admin endpoint accepts the kind.
    await withWinterServer(async (base) => {
      const res = await fetch(`${base}/admin/collection-membership`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json', Authorization: `Bearer ${process.env.ENRICHMENT_ADMIN_TOKEN}` },
        body: JSON.stringify({ kind: 'sports_also', venue_id: course.id, action: 'remove', reason: 'fixture', batch_id: 'test' }),
      });
      assert.equal(res.status, 200, await res.text());
      assert.deepEqual(app.getSportsAlsoVenues().map((v) => v.name), ['Sports Also City Park']);
    });
  } finally {
    db.prepare("DELETE FROM collection_items WHERE content_type = 'venue' AND content_id IN (?, ?)").run(park.id, course.id);
    db.prepare('DELETE FROM venues WHERE id IN (?, ?)').run(park.id, course.id);
  }
});

