test('Venue descriptions ship in English and French: the EN / FR toggle (<html lang>) picks one by CSS; venues without French are unchanged', async () => {
  const fr = app.createVenue({ name: 'Bilingual Test Bistro', region: 'kelowna', type: 'restaurant', description: 'A cosy test bistro (fixture).', slug: 'bilingual-test-bistro' });
  db.prepare('UPDATE venues SET description_fr = ? WHERE id = ?').run("Un bistro d'essai chaleureux (fixture).", fr.id);
  const en = app.createVenue({ name: 'English Only Test Beach', region: 'kelowna', type: 'beach', description: 'A test beach & cove (fixture).', slug: 'english-only-test-beach' });
  try {
    await withWinterServer(async (base) => {
      const page = await WINTER_GET(base, '/kelowna/restaurants/bilingual-test-bistro');
      assert.equal(page.status, 200);
      // SEO audit 2 (2026-10-17): a place with a French page carries only its English description; the French is on /fr.
      assert.match(page.text, /<p class="venue-description">A cosy test bistro \(fixture\)\.<\/p>/);
      assert.doesNotMatch(page.text, /Un bistro d&#39;essai chaleureux/);
      assert.match(page.text, /\.desc-fr \{ display: none; \}\nhtml\[lang="fr"\] \.desc-fr \{ display: inline; \}\nhtml\[lang="fr"\] \.desc-en \{ display: none; \}/);
      // A list page with a French twin (2026-10-14) carries the English blurb only; its /fr twin carries the French.
      const list = await WINTER_GET(base, '/kelowna/restaurants');
      assert.match(list.text, /A cosy test bistro \(fixture\)\./);
      assert.doesNotMatch(list.text, /Un bistro d&#39;essai chaleureux/);
      const frList = await WINTER_GET(base, '/fr/kelowna/restaurants');
      assert.match(frList.text, /Un bistro d&#39;essai chaleureux/);
      // No translation: plain escaped English, exactly as before.
      const beach = await WINTER_GET(base, '/kelowna/beaches/english-only-test-beach');
      assert.match(beach.text, /<p class="venue-description">A test beach &amp; cove \(fixture\)\.<\/p>/);
      assert.doesNotMatch(beach.text, /class="desc-fr"/);
    });
  } finally {
    db.prepare('DELETE FROM venues WHERE id IN (?, ?)').run(fr.id, en.id);
  }
});

test('Browse hub: venues tagged into an "also" collection count and filter under that category chip (sports_also -> Sports & Recreation), and their note is searchable', async () => {
  const park = app.createVenue({ name: 'Browse Also Test Park', region: 'vernon', type: 'outdoor', description: 'A fixture park by the lake.', slug: 'browse-also-test-park' });
  try {
    const r = app.guardedCollectionMembershipUpdate('sports_also', park.id, 'add', 'Skate park and a paved pumptrackfixture loop', { reason: 'fixture', batch_id: 'test' });
    assert.ok(r.ok, JSON.stringify(r));
    await withWinterServer(async (base) => {
      const html = await WINTER_GET(base, '/browse?types=sport');
      assert.equal(html.status, 200);
      assert.ok(browseCardIds(html.text).includes(park.id), 'listed under Sports & Recreation');
      assert.match(html.text, new RegExp(`"${park.id}":\\{"c":\\["outdoor","sport"\\][^}]*"n":"Skate park and a paved pumptrackfixture loop"`), 'page data carries the extra category and the note');
      const outdoor = await WINTER_GET(base, '/browse?types=outdoor');
      assert.ok(browseCardIds(outdoor.text).includes(park.id), 'still listed under its own type');
      const search = await WINTER_GET(base, '/browse?q=pumptrackfixture');
      assert.deepEqual(browseCardIds(search.text), [park.id], 'the note is searchable');
      assert.match(html.text, /'d\.cu \|\| '', meta \? meta\.textContent : '', desc \? desc\.textContent : '', d\.n \|\| ''\]|d\.n \|\| ''/, 'the page script searches the note too');
    });
  } finally {
    db.prepare("DELETE FROM collection_items WHERE content_type = 'venue' AND content_id = ?").run(park.id);
    db.prepare('DELETE FROM venues WHERE id = ?').run(park.id);
  }
});

test('Navigation (2026-10-12): the header\'s Things to Do menu and the footer\'s Explore column link to Sports & Recreation, Tours & Experiences, Indoor & Rainy Day and Ski & Snow, in English and French', async () => {
  await withWinterServer(async (base) => {
    for (const p of ['/', '/sports', '/browse']) {
      const html = (await WINTER_GET(base, p)).text;
      const header = html.slice(html.indexOf('<header'), html.indexOf('</header>'));
      const footer = html.slice(html.lastIndexOf('<footer'), html.lastIndexOf('</footer>'));
      for (const [href, key, label] of [['/sports', 'tripv3.type.sport', 'Sports &amp; Recreation'], ['/tours', 'tripv3.type.tour', 'Tours &amp; Experiences'], ['/indoor', 'mood.indoor.title', 'Indoor &amp; Rainy Day'], ['/ski-snow', 'mood.skiSnow.title', 'Ski &amp; Snow']]) {
        assert.ok(header.includes(`<a href="${href}" data-i18n="${key}">${label}</a>`), `${p}: header links ${href}`);
        assert.ok(footer.includes(`<li><a href="${href}" data-i18n="${key}">${label}</a></li>`), `${p}: footer links ${href}`);
      }
    }
  });
});

test('Card rows (2026-10-12): two-up cards give every part its own subgrid row, so the open-now line on Food & Drink and browse cards never pushes the badges into the buttons\' row', () => {
  const css = app.renderGolfThemeStyles();
  assert.match(css, /body\.golf-page \.card-grid > \.venue-card \{ display: grid; grid-template-rows: subgrid; grid-row: span 10;/);
  const order = ['h2', '.venue-meta', null, '.card-slot-fee', '.card-slot-desc', '.card-slot-notice', '.card-slot-notes', '.chips', '.card-actions', '.card-links'];
  order.forEach((sel, i) => {
    if (!sel) return;
    const re = new RegExp(`body\\.golf-page \\.card-grid > \\.venue-card > ${sel.replace(/\./g, '\\.')} \\{ grid-row: ${i + 1}; \\}`);
    assert.match(css, re, `${sel} sits in row ${i + 1}`);
  });
  // The open-now line's row lives with the open-now styles, so pages without Open Now carry none of it.
  assert.doesNotMatch(css, /fd-open-status/);
  assert.match(app.renderFoodDrinkOpenNowStyles(), /body\.golf-page \.card-grid > \.venue-card > \.fd-open-status \{ grid-row: 3; \}/);
});

