      const ssV = [{ id: 990014, name: 'SS Cove', slug: 'ss-cove', region: 'kelowna', type: 'beach', description: 'Fixture.' }, { id: 990015, name: 'SS Falls', slug: 'ss-falls', region: 'kelowna', type: 'outdoor', description: 'Fixture.' }];
