test('Guide ItemList schema (2026-10-13): each guide lists the places it shows, in page order, with absolute URLs; a guide with no live places has none', () => {
  const lists = (html) => [...html.matchAll(/<script type="application\/ld\+json">\n(.*?)\n<\/script>/gs)].map((m) => JSON.parse(m[1])).filter((b) => b['@type'] === 'ItemList');
  const pages = [
    ...Object.keys(app.FILE_GUIDES).map((p) => [p, app.renderFileGuidePage(p)]),
    ['/guides/rainy-day-okanagan', app.renderEditorialGuidePage(app.RAINY_GUIDE, '/guides/rainy-day-okanagan')],
    [app.SKI_GUIDE_PATH, app.renderSkiGuidePage()],
    [app.PATIO_GUIDE_PATH, app.renderPatioGuidePage()],
  ];
  let checked = 0;
  for (const [p, html] of pages) {
    const article = html.slice(html.indexOf('<article'), html.indexOf('</article>'));
    const shown = [...new Set([...article.matchAll(/<li><strong><a href="([^"]+)">/g)].map((m) => `https://okanaganroam.com${m[1]}`))];
    const found = lists(html);
    if (!shown.length) { assert.equal(found.length, 0, `${p} has no ItemList when no places show`); continue; }
    assert.equal(found.length, 1, `${p} has one ItemList`);
    const list = found[0];
    assert.equal(list.url, `https://okanaganroam.com${p}`);
    assert.equal(list.numberOfItems, shown.length, `${p} lists every place it shows`);
    assert.deepEqual(list.itemListElement.map((e) => e.url), shown, `${p} lists them in page order`);
    assert.deepEqual(list.itemListElement.map((e) => e.position), shown.map((_, i) => i + 1));
    assert.ok(list.itemListElement.every((e) => e.name), `${p} names every place`);
    checked++;
  }
  assert.ok(checked > 0, 'at least one guide shows places in the test database');
  const gone = { ...app.RAINY_GUIDE, sections: [{ id: 'gone', jump: 'Gone', heading: 'Gone', items: [{ ref: 'nowhere/not-a-place', name: 'Ghost', text: 'gone' }] }] };
  assert.equal(lists(app.renderEditorialGuidePage(gone, '/guides/test')).length, 0);
  assert.equal(app.guideItemListSchema('X', 'u', [{ name: 'A', url: 'a' }, { name: 'A again', url: 'a' }]).numberOfItems, 1, 'a place named twice is listed once');
});

test('Fall guides (2026-10-13): data/guides files load, render on the shared guide page, are in the sitemap; event refs link upcoming events and drop past ones', async () => {
  const paths = Object.keys(app.FILE_GUIDES);
  assert.ok(paths.length >= 12, 'the fall guides load from data/guides');
  for (const p of paths) {
    const g = app.FILE_GUIDES[p];
    assert.ok(app.GUIDE_BANNERS[JSON.parse(require('node:fs').readFileSync(require('node:path').join(__dirname, '..', 'data', 'guides', p.slice(8) + '.json'), 'utf8')).banner], `${p} names a known banner`);
    const html = app.renderFileGuidePage(p);
    assert.match(html, new RegExp(`<link rel="canonical" href="https://okanaganroam\\.com${p}">`));
    assert.match(html, /"@type":"Article"/);
    const article = html.slice(html.indexOf('<article'), html.indexOf('</article>'));
    assert.doesNotMatch(article, /\{(page:|event:|[a-z-]+\/)[^}]*\||\]\(|\*\*/, `${p} has no raw markup`);
    assert.ok(g.title.length <= 70 && g.description.length <= 160, `${p} title/description lengths`);
  }
  for (const [key, hubPath] of [['fall', '/guides/fall-okanagan'], ['winter', '/guides/winter-okanagan']]) {
    const hub = app.renderFileGuidePage(hubPath);
    const group = app.GUIDE_GROUPS.find((x) => x.key === key).paths.filter((x) => x !== hubPath && app.FILE_GUIDES[x]);
    for (const p of group) assert.ok(hub.includes(`href="${p}"`), `the ${key} hub links ${p}`);
  }
  const upcoming = s5create({ name: 'Fall Guide Fixture Upcoming', occurrences: [{ start_date: '2032-10-20', start_time: '18:00', end_time: '20:00' }] });
  const past = s5create({ name: 'Fall Guide Fixture Past', occurrences: [{ start_date: '2020-10-20', start_time: '18:00', end_time: '20:00' }] });
  try {
    assert.equal(app.guideRefVenue(`event:kelowna/${upcoming.slug}`)._href, `/kelowna/events/${upcoming.slug}`);
    assert.equal(app.guideRefVenue(`event:kelowna/${past.slug}`), null, 'a past event drops out');
    assert.equal(app.guideRefVenue('event:kelowna/not-an-event'), null);
    assert.equal(app.guideTipHtml(`See {event:kelowna/${upcoming.slug}|the show} or {event:kelowna/${past.slug}|the old one}.`), `See <a href="/kelowna/events/${upcoming.slug}">the show</a> or the old one.`);
  } finally { /* fixtures stay, like the other Step 5 event fixtures */ }
  await withWinterServer(async (base) => {
    assert.equal((await WINTER_GET(base, '/guides/halloween-okanagan')).status, 200);
    const sitemap = (await WINTER_GET(base, '/sitemap.xml')).text;
    for (const p of paths) assert.equal(sitemap.includes(`<loc>https://okanaganroam.com${p}</loc>`), !app.guideIsThin(app.FILE_GUIDES[p]), `sitemap lists ${p} unless thin`);
  });
});

test('Guides hub (2026-10-13): /guides lists live guides by season, header/footer/homepage link to it, venue pages show "Featured in", thin guides are noindex and out of the sitemap', async () => {
  const oct = new Date('2026-10-13T12:00:00-07:00');
  const idx = app.renderGuidesIndexPage(oct);
  assert.match(idx, /<title>Okanagan Guides: Things to Do by Season \| Okanagan Roam<\/title>/);
  assert.match(idx, /<link rel="canonical" href="https:\/\/okanaganroam\.com\/guides">/);
  assert.deepEqual(app.guideGroupOrder(oct), ['fall', 'cozy', 'winter', 'towns', 'year'], 'fall leads in October');
  assert.deepEqual(app.guideGroupOrder(new Date('2027-01-15T12:00:00-08:00')), ['winter', 'cozy', 'towns', 'year', 'fall'], 'winter leads in January');
  assert.deepEqual(app.guideGroupOrder(new Date('2027-06-15T12:00:00-07:00')), ['towns', 'year', 'fall', 'cozy', 'winter'], 'year-round leads in summer');
  assert.match(idx, /<h2>Winter in the Okanagan<\/h2>/, 'the ski guide is always listed');
  assert.match(idx, /href="\/guides\/ski-season-big-white-silverstar"/);
  assert.equal(app.seasonalGuideLink(new Date('2026-07-15T12:00:00-07:00')), null, 'no seasonal link in summer');
  assert.equal(app.seasonalGuideLink(new Date('2027-01-15T12:00:00-08:00')).href, app.FILE_GUIDES['/guides/winter-okanagan'] && !app.guideIsThin(app.FILE_GUIDES['/guides/winter-okanagan']) ? '/guides/winter-okanagan' : '/guides/ski-season-big-white-silverstar');
  // Thin: a guide whose places are all gone is noindex with a note.
  const ghost = { ...app.RAINY_GUIDE, sections: [{ id: 's', jump: 'S', heading: 'S', items: [{ ref: 'nowhere/gone', name: 'Gone', text: 'gone' }] }] };
  assert.ok(app.guideIsThin(ghost));
  const thinHtml = app.renderEditorialGuidePage(ghost, '/guides/test');
  assert.match(thinHtml, /<meta name="robots" content="noindex">/);
  assert.match(thinHtml, /This guide is between seasons\./);
  assert.match(app.renderEditorialGuidePage(app.FILE_GUIDES['/guides/fall-okanagan'], '/guides/fall-okanagan'), /href="\/guides">More Okanagan guides/);
  // Featured in: a venue a live guide mentions links back to it.
  const live = app.allGuides().find((x) => x.editorial && !app.guideIsThin(x.editorial) && x.refs.some((r) => !r.startsWith('event:') && app.guideRefVenue(r)));
  if (live) {
    const ref = live.refs.find((r) => !r.startsWith('event:') && app.guideRefVenue(r));
    app.resetGuideCache();
    assert.ok(app.guidesFeaturing(ref).some((x) => x.path === live.path), `${ref} is featured in ${live.path}`);
  }
  await withWinterServer(async (base) => {
    const page = await WINTER_GET(base, '/guides');
    assert.equal(page.status, 200);
    assert.match(page.text, /<a href="\/guides">Guides<\/a>/, 'header Discover menu links Guides');
    assert.match(page.text, /<li><a href="\/guides">Guides<\/a><\/li>/, 'footer links Guides');
    const sitemap = (await WINTER_GET(base, '/sitemap.xml')).text;
    assert.ok(sitemap.includes('<loc>https://okanaganroam.com/guides</loc>'));
    for (const p of Object.keys(app.FILE_GUIDES)) assert.equal(sitemap.includes(`<loc>https://okanaganroam.com${p}</loc>`), !app.guideIsThin(app.FILE_GUIDES[p]), `sitemap lists ${p} only when not thin`);
  });
});


