test('What\'s On pages (2026-10-13): /whats-on/<category> and /<region>/events render scoped, self-canonical pages with an ItemList; thin ones are noindex and out of the sitemap', async () => {
  assert.deepEqual(app.whatsOnScopeFromPath('/whats-on/holiday-seasonal'), { category: 'holiday-seasonal' });
  assert.deepEqual(app.whatsOnScopeFromPath('/lumby/events/'), { region: 'lumby' });
  assert.equal(app.whatsOnScopeFromPath('/whats-on/not-a-category'), null);
  assert.equal(app.whatsOnScopeFromPath('/nowhere/events'), null);
  const day = (n) => app.addLocalDays(app.todayLocal(), n);
  const made = [];
  const mk = (name, over) => { const e = s5create({ name, occurrences: [{ start_date: day(10 + made.length), start_time: '19:00' }], ...over }); made.push(e); return e; };
  try {
    // Names share no significant words, so the duplicate gate doesn't hold any back.
    for (const n of ['Zebra Disco', 'Quartz Comedy', 'Velvet Karaoke']) mk(n, { region: 'lumby', venue_id: undefined, venue_name_text: 'Lumby Hall', categories: ['nightlife'] });
    mk('Ember Ballroom', { region: 'lumby', venue_id: undefined, venue_name_text: 'Lumby Hall', categories: ['nightlife'], occurrences: [{ start_date: day(200) }] });
    const live = app.liveWhatsOnScopes().map((x) => x.path);
    assert.ok(live.includes('/lumby/events'), 'three Lumby events in the next 90 days make the town page live');
    assert.ok(live.includes('/whats-on/nightlife'));
    const town = await s5get('/lumby/events');
    assert.equal(town.status, 200);
    assert.match(town.text, /<title>Lumby Events: What’s On in Lumby \| Okanagan Roam<\/title>/);
    assert.match(town.text, /<link rel="canonical" href="https:\/\/okanaganroam\.com\/lumby\/events">/);
    assert.doesNotMatch(town.text, /name="robots" content="noindex/);
    assert.match(town.text, /<h1>What’s On in Lumby<\/h1>/);
    assert.match(town.text, /Showing the next 90 days:/);
    const ld = s5jsonLd(town.text);
    assert.deepEqual(ld.find((b) => b['@type'] === 'BreadcrumbList').itemListElement.map((x) => x.name), ['Home', "What's On", 'Lumby']);
    const list = ld.find((b) => b['@type'] === 'ItemList');
    const urls = list.itemListElement.map((x) => x.url);
    for (const e of made.slice(0, 3)) assert.ok(urls.includes(`https://okanaganroam.com/lumby/events/${e.slug}`), `${e.name} is listed`);
    assert.ok(!urls.some((u) => u.endsWith(made[3].slug)), 'an event past the 90-day window is not listed');
    assert.match(town.text, /<nav class="whatson-browse"[\s\S]*<span aria-current="page">Lumby<\/span>/, 'the browse links mark the current page');
    const cat = await s5get('/whats-on/nightlife');
    assert.match(cat.text, /<title>Nightlife in the Okanagan \| Okanagan Roam<\/title>/);
    assert.match(cat.text, /<link rel="canonical" href="https:\/\/okanaganroam\.com\/whats-on\/nightlife">/);
    assert.match(cat.text, /class="whatson-cat-chip[^"]*"[^>]*data-category="nightlife"[^>]*aria-pressed="true"|data-category="nightlife"[^>]*aria-pressed="true"/, 'the page\'s own chip starts selected');
    assert.match(cat.text, /var SCOPE = \{"region":\[\],"category":\["nightlife"\]\}/);
    const sitemap = (await s5get('/sitemap.xml')).text;
    assert.ok(sitemap.includes('<loc>https://okanaganroam.com/lumby/events</loc>'));
    assert.ok(sitemap.includes('<loc>https://okanaganroam.com/whats-on/nightlife</loc>'));
    // Thin: a town with no events of its own is noindex and not in the sitemap.
    const thinTown = Object.keys(app.REGION_LABELS).find((r) => !app.liveWhatsOnScopes().some((x) => x.path === `/${r}/events`));
    const thin = await s5get(`/${thinTown}/events`);
    assert.equal(thin.status, 200);
    assert.match(thin.text, /name="robots" content="noindex/);
    assert.ok(!sitemap.includes(`<loc>https://okanaganroam.com/${thinTown}/events</loc>`));
    assert.equal((await s5get('/whats-on/not-a-category')).status, 404);
    // The general page keeps its own canonical and lists the live pages.
    const all = await s5get('/whats-on');
    assert.match(all.text, /<link rel="canonical" href="https:\/\/okanaganroam\.com\/whats-on">/);
    assert.match(all.text, /<a href="\/lumby\/events">Lumby<\/a>/);
  } finally {
    for (const e of made) {
      for (const t of ['event_enrichment_log', 'event_categories', 'event_occurrences']) db.prepare(`DELETE FROM ${t} WHERE event_id = ?`).run(e.id);
      db.prepare('DELETE FROM events WHERE id = ?').run(e.id);
    }
  }
});

test('What\'s On pages (2026-10-13): a type or town page links to the guides that feature its events; guides link back', () => {
  assert.deepEqual(app.whatsOnRelatedGuides([]), []);
  // Fixture events stand in for a page's list: refs taken from a real guide, so that guide must come back first.
  const withEvents = app.allGuides().find((g) => g.refs.filter((r) => r.startsWith('event:')).length >= 2 && app.liveGuides().some((x) => x.path === g.path));
  if (withEvents) {
    const evs = withEvents.refs.filter((r) => r.startsWith('event:')).map((r) => { const [region, slug] = r.slice(6).split('/'); return { region, slug }; });
    const got = app.whatsOnRelatedGuides(evs);
    assert.equal(got[0].path, withEvents.path);
    assert.ok(got.length <= 4);
  }
  assert.equal(app.whatsOnRelatedGuides([{ region: 'kelowna', slug: 'not-in-any-guide' }]).length, 0);
  const holiday = JSON.parse(fs.readFileSync(path.join(__dirname, '..', 'data', 'guides', 'okanagan-holiday-events.json'), 'utf8'));
  assert.match(holiday.footerHtml, /href="\/whats-on\/holiday-seasonal"/, 'the holiday guide links to its What\'s On page');
  assert.match(JSON.parse(fs.readFileSync(path.join(__dirname, '..', 'data', 'guides', 'okanagan-hockey-season.json'), 'utf8')).footerHtml, /href="\/whats-on\/sports-recreation"/);
});

test('Weekend pages (2026-10-13): /whats-on/this-weekend and /<region>/events/this-weekend show the coming Fri-Sun, are indexable when their town page is, and fill a quiet weekend with what comes next', async () => {
  assert.deepEqual(app.whatsOnScopeFromPath('/whats-on/this-weekend'), { weekend: true });
  assert.deepEqual(app.whatsOnScopeFromPath('/lumby/events/this-weekend'), { region: 'lumby', weekend: true });
  assert.equal(app.whatsOnScopeFromPath('/nowhere/events/this-weekend'), null);
  const wk = app.whatsOnWeekendWindow();
  assert.equal(app.localWeekday(wk.to), 0, 'the window ends on a Sunday');
  const made = [];
  const mk = (name, date) => { const e = s5create({ name, region: 'lumby', venue_id: undefined, venue_name_text: 'Lumby Hall', categories: ['live-music'], occurrences: [{ start_date: date, start_time: '19:00' }] }); made.push(e); return e; };
  try {
    // A quiet weekend in a live town: three events later in the month, none this weekend.
    for (const [n, name] of [[8, 'Harbour Lantern Gala'], [9, 'Cobalt Fiddle Night'], [10, 'Juniper Poetry Slam']]) mk(name, app.addLocalDays(wk.to, n));
    let page = await s5get('/lumby/events/this-weekend');
    assert.equal(page.status, 200);
    assert.match(page.text, /<title>Things to Do in Lumby This Weekend \| Okanagan Roam<\/title>/);
    assert.match(page.text, /<link rel="canonical" href="https:\/\/okanaganroam\.com\/lumby\/events\/this-weekend">/);
    assert.doesNotMatch(page.text, /name="robots" content="noindex/, 'indexable because /lumby/events is live');
    assert.ok(page.text.includes(app.formatLocalDateShort(wk.from)), 'the intro names the weekend dates');
    assert.match(page.text, /Coming up after the weekend<\/h2>[\s\S]*Harbour Lantern Gala/, 'a quiet weekend shows what comes next');
    const crumbs = s5jsonLd(page.text).find((b) => b['@type'] === 'BreadcrumbList').itemListElement.map((x) => x.name);
    assert.deepEqual(crumbs, ['Home', "What's On", 'Lumby', 'This Weekend']);
    assert.match(page.text, /var DATE = \{"when":"","from":"","to":""\}/, 'the weekend is the page default, so no date parameters');
    // A busy weekend: three events on the Sunday (always inside the window, whatever day the test runs).
    for (const name of ['Saffron Blues Revue', 'Tundra Brass Quintet', 'Marigold Open Stage']) mk(name, wk.to);
    page = await s5get('/lumby/events/this-weekend');
    assert.doesNotMatch(page.text, /Coming up after the weekend<\/h2>/);
    const list = s5jsonLd(page.text).find((b) => b['@type'] === 'ItemList');
    for (const e of made.slice(3)) assert.ok(list.itemListElement.some((x) => x.url.endsWith(`/lumby/events/${e.slug}`)), `${e.name} is in the weekend list`);
    assert.ok(!list.itemListElement.some((x) => x.url.endsWith(made[0].slug)), 'next month is not in the weekend list');
    const sitemap = (await s5get('/sitemap.xml')).text;
    assert.ok(sitemap.includes('<loc>https://okanaganroam.com/whats-on/this-weekend</loc>'));
    assert.ok(sitemap.includes('<loc>https://okanaganroam.com/lumby/events/this-weekend</loc>'));
    assert.match((await s5get('/lumby/events')).text, /<a href="\/lumby\/events\/this-weekend">Lumby<\/a>/, 'town pages link the weekend pages');
    const thinTown = Object.keys(app.REGION_LABELS).find((r) => !app.liveWhatsOnScopes().some((x) => x.path === `/${r}/events`));
    assert.match((await s5get(`/${thinTown}/events/this-weekend`)).text, /name="robots" content="noindex/, 'a thin town\'s weekend page is noindex');
    assert.ok(!sitemap.includes(`<loc>https://okanaganroam.com/${thinTown}/events/this-weekend</loc>`));
  } finally {
    for (const e of made) {
      for (const t of ['event_enrichment_log', 'event_categories', 'event_occurrences']) db.prepare(`DELETE FROM ${t} WHERE event_id = ?`).run(e.id);
      db.prepare('DELETE FROM events WHERE id = ?').run(e.id);
    }
  }
});

