test('Event schema (2026-10-13): organizer only when the source is the organizer; offers need a stated price and carry the official link', () => {
  const base = { name: 'X', region: 'kelowna', website: null, source_type: 'official_organizer', source_name: 'Kettle Valley Steam Railway', source_url: 'https://www.kettlevalleyrail.org/x', description: 'A steam train ride. Tickets are $45.' };
  const offer = (url, price = '45') => ({ '@type': 'Offer', price, priceCurrency: 'CAD', availability: 'https://schema.org/InStock', url });
  assert.deepEqual(app.eventOrganizerSchema(base), { '@type': 'Organization', name: 'Kettle Valley Steam Railway', url: 'https://www.kettlevalleyrail.org/x' });
  assert.deepEqual(app.eventOffersSchema(base), offer('https://www.kettlevalleyrail.org/x'));
  assert.equal(app.eventOrganizerSchema({ ...base, source_type: 'official_venue' }), undefined, 'a ticket seller is not the organizer');
  assert.deepEqual(app.eventOffersSchema({ ...base, source_type: 'official_venue' }), offer('https://www.kettlevalleyrail.org/x'), 'an official ticketing page is the offer link');
  assert.deepEqual(app.eventOffersSchema({ ...base, source_type: 'tourism_org' }), offer(undefined), 'a tourism listing is not a ticket link, but the price still counts');
  assert.deepEqual(app.eventOffersSchema({ ...base, source_type: 'tourism_org', website: 'https://example.com/tickets' }), offer('https://example.com/tickets'), 'the event\'s own website always counts');
  assert.equal(app.eventOffersSchema({ ...base, description: 'A steam train ride.' }), undefined, 'no stated price: no offer (2026-10-18)');
  const ev = s5create({ name: 'Schema Organizer Fixture', source_type: 'official_organizer', source_name: 'Fixture Society', description: 'A fixture concert. Tickets are $20 to $30.' });
  try {
    const ld = app.eventJsonLd(app.getEventById(ev.id), app.listEventOccurrences(ev.id), ['live-music'], null, 'https://x', app.todayLocal());
    assert.equal(ld.organizer.name, 'Fixture Society');
    assert.equal(ld.offers['@type'], 'AggregateOffer');
    assert.equal(ld.offers.lowPrice, '20');
    assert.equal(ld.offers.highPrice, '30');
    assert.equal(ld.offers.priceCurrency, 'CAD');
  } finally {
    for (const t of ['event_enrichment_log', 'event_categories', 'event_occurrences']) db.prepare(`DELETE FROM ${t} WHERE event_id = ?`).run(ev.id);
    db.prepare('DELETE FROM events WHERE id = ?').run(ev.id);
  }
});

test('Event batches: `updates` retime moves a stored start (and end) time, logged, once; a missing date or a clash is reported', () => {
  const dir = fs.mkdtempSync(path.join(require('node:os').tmpdir(), 'okr-batch-retime-'));
  const name = 'Retime Fixture Festival';
  const cleanup = () => {
    for (const { id } of db.prepare('SELECT id FROM events WHERE name = ?').all(name)) {
      for (const t of ['event_enrichment_log', 'event_categories', 'event_occurrences']) db.prepare(`DELETE FROM ${t} WHERE event_id = ?`).run(id);
      db.prepare('DELETE FROM events WHERE id = ?').run(id);
    }
  };
  cleanup();
  try {
    const made = app.createEvent({ name, region: 'big-white', venue_name_text: 'Village Centre', categories: ['events-festivals'], source_type: 'official_venue', source_name: 'Test Resort', source_url: 'https://example.com/retime', occurrences: [{ start_date: '2032-12-24', start_time: '17:30', end_time: '20:05' }, { start_date: '2032-12-25', start_time: '11:30' }] }, { reason: 'fixture', batch_id: 'retime-test' });
    assert.equal(made.ok, true, JSON.stringify(made));
    const write = (retime) => fs.writeFileSync(path.join(dir, 'b.json'), JSON.stringify({ batch_id: 'retime-test', reason: 'test', reviewed_by: 'test', updates: [{ region: 'big-white', name, retime }] }));
    write([{ start_date: '2032-12-24', from: '17:30', to: '16:30', end_to: '19:05' }, { start_date: '2032-12-25', from: '11:30', to: '10:30' }]);
    const first = app.importEventBatches(dir);
    assert.deepEqual([first.created, first.failed], [[`${name} (updated)`], []]);
    const occ = db.prepare('SELECT start_date, start_time, end_time FROM event_occurrences WHERE event_id = ? ORDER BY start_date').all(made.event.id);
    assert.deepEqual(occ.map((o) => [o.start_date, o.start_time, o.end_time]), [['2032-12-24', '16:30', '19:05'], ['2032-12-25', '10:30', null]]);
    assert.ok(db.prepare("SELECT 1 FROM event_enrichment_log WHERE event_id = ? AND field_name = 'start_time' AND old_value = '17:30' AND new_value = '16:30'").get(made.event.id), 'logged');
    assert.deepEqual(app.importEventBatches(dir).created, [], 'a re-run changes nothing');
    write([{ start_date: '2032-12-26', from: '10:00', to: '09:00' }]);
    assert.equal(app.importEventBatches(dir).failed[0].reason, 'occurrence_not_found');
    assert.equal(app.retimeEventOccurrence(made.event.id, '2032-12-24', '16:30', '20:30', { reason: 'r', batch_id: 'b' }).reason, 'occurrence_end_time_before_start');
  } finally {
    cleanup();
  }
});

test('Event batches: an entry\'s reviewed_duplicates clears the fuzzy duplicate gate for those ids only', () => {
  const dir = fs.mkdtempSync(path.join(require('node:os').tmpdir(), 'okr-batch-dup-'));
  const names = ['Fixture Craftworks Holiday Market', 'Fixture Christkindl Holiday Market'];
  const cleanup = () => {
    for (const { id } of db.prepare(`SELECT id FROM events WHERE name IN (?, ?)`).all(...names)) {
      for (const t of ['event_enrichment_log', 'event_categories', 'event_occurrences']) db.prepare(`DELETE FROM ${t} WHERE event_id = ?`).run(id);
      db.prepare('DELETE FROM events WHERE id = ?').run(id);
    }
  };
  cleanup();
  try {
    const base = { region: 'kelowna', categories: ['markets-fairs'], source_type: 'official_organizer', source_name: 'Fixture Org', occurrences: [{ start_date: '2032-12-04' }] };
    const existing = app.createEvent({ ...base, name: names[0], venue_name_text: 'Arena', source_url: 'https://example.com/dup/a' }, { reason: 'fixture', batch_id: 'dup-test' });
    assert.equal(existing.ok, true, JSON.stringify(existing));
    const entry = { ...base, name: names[1], venue_name_text: 'Packinghouse', source_url: 'https://example.com/dup/b' };
    const write = (e) => fs.writeFileSync(path.join(dir, 'b.json'), JSON.stringify({ batch_id: 'dup-test', reason: 'test', reviewed_by: 'test', events: [e] }));
    write(entry);
    const blocked = app.importEventBatches(dir);
    assert.equal(blocked.failed.length, 1);
    assert.equal(blocked.failed[0].reason, 'possible_duplicate', 'same-day near match is held back');
    write({ ...entry, reviewed_duplicates: [existing.event.id + 9999] });
    assert.equal(app.importEventBatches(dir).failed[0].reason, 'possible_duplicate', 'acknowledging a different id does not clear it');
    write({ ...entry, reviewed_duplicates: [existing.event.id] });
    const ok = app.importEventBatches(dir);
    assert.deepEqual([ok.created, ok.failed], [[names[1]], []]);
  } finally {
    cleanup();
  }
});

