  const html = app.renderVenuePage(venue, [], [], [], { now: tueNoon });
  assert.match(html, /<p class="venue-open-status" data-open="open" id="venueOpenStatus">Open now · Closes 2 PM <a href="#venueHours">See hours<\/a><\/p>/);
