test('Listing forms (2026-10-14): venue extras are stored and emailed; an event needs no link, keeps its price and poster link, and approves with the submission as its source', () => laeWithTransport(() => withDiscoveryServer(async (base) => {
  // Venue: hours, happy hour, social link and role reach the reviewer.
  app.setVenueSubmissionTransport(async (payload) => { lyvSent.push(payload); });
  const vres = await lyvPost(base, lyvValid({ name: 'Extras Test Bistro', hours_text: 'Mon-Fri 11am-9pm\nSat-Sun 10am-10pm', happy_hour_text: 'Mon-Fri 3-6pm', social_url: 'instagram.com/extrastest', submitter_role: 'owner' }));
  assert.equal(vres.status, 201);
  const v = db.prepare('SELECT hours_text, happy_hour_text, social_url, submitter_role FROM venue_submissions WHERE id = ?').get((await vres.json()).id);
  assert.deepEqual({ ...v }, { hours_text: 'Mon-Fri 11am-9pm\nSat-Sun 10am-10pm', happy_hour_text: 'Mon-Fri 3-6pm', social_url: 'https://instagram.com/extrastest', submitter_role: 'owner' });
  const vmail = lyvSent[lyvSent.length - 1];
  assert.equal(vmail['Happy hour (as given)'], 'Mon-Fri 3-6pm');
  assert.equal(vmail['Submitter role'], 'Owner');
  assert.equal((await lyvPost(base, lyvValid({ name: 'Bad Role Cafe', submitter_role: 'ceo' }))).status, 400);
  assert.equal((await lyvPost(base, lyvValid({ name: 'Bad Social Cafe', social_url: 'not a link' }))).status, 400);
  app.setVenueSubmissionTransport(async (payload) => { laeSent.push(payload); });

  // Event with no link, a price and a poster link.
  const eres = await laePost(base, laeValid({ name: 'No Link Community Market', event_url: undefined, price_text: 'Free', image_link: 'posters.example.com/market.jpg' }));
  assert.equal(eres.status, 201);
  const created = await eres.json();
  const sub = app.getEventSubmission(created.id);
  assert.equal(sub.event_url, '');
  assert.equal(sub.price_text, 'Free');
  assert.equal(sub.image_link, 'https://posters.example.com/market.jpg');
  const email = laeSent[laeSent.length - 1];
  assert.equal(email['Event website / tickets'], '(none given)');
  assert.equal(email['Price (as given)'], 'Free');
  const ok = await laeAdmin(base, `/admin/event-submissions/${created.id}/approve`, { reviewer: 'test-admin' });
  assert.equal(ok.status, 200);
  const event = db.prepare('SELECT source_url, website, image_url FROM events WHERE id = ?').get((await ok.json()).event.id);
  assert.equal(event.source_url, `https://okanaganroam.com/list-an-event#submission-${created.id}`);
  assert.equal(event.website, null);
  assert.equal(event.image_url, null, 'a poster link is never published automatically');
})));

test('Venue lookup (2026-10-14): name search for the listing forms, at most 8, page links only, safe with LIKE characters', () => withDiscoveryServer(async (base) => {
  assert.deepEqual(app.venueLookup('a'), [], 'two characters minimum');
  assert.deepEqual(app.venueLookup('%%'), [], 'LIKE wildcards are matched literally');
  const any = db.prepare("SELECT name, region, type, slug FROM venues WHERE redirect_to IS NULL AND slug IS NOT NULL LIMIT 1").get();
  const hits = app.venueLookup(any.name.slice(0, 6));
  assert.ok(hits.length >= 1 && hits.length <= 8);
  for (const h of hits) assert.deepEqual(Object.keys(h).sort(), ['name', 'region', 'type', 'url']);
  const res = await fetch(`${base}/api/venue-lookup?q=${encodeURIComponent(any.name.slice(0, 6))}&region=${any.region}`);
  assert.equal(res.status, 200);
  assert.ok((await res.json()).venues.every((h) => h.region === app.REGION_LABELS[any.region]));
  const page = await (await fetch(`${base}/list-your-venue`)).text();
  assert.match(page, /Already listed\? Find your venue/);
  assert.match(page, /Free for every Okanagan business/);
  assert.match(page, /<a href="\/privacy">Privacy Policy<\/a>/);
}));

test('Contact (2026-10-14): topics, the app launch sign-up with only an email, and the /contact page', () => withDiscoveryServer(async (base) => {
  contactReset();
  const ok = await contactPost(base, contactValid({ topic: 'correction' }));
  assert.equal(ok.status, 201);
  assert.equal(contactSent[0].Topic, 'Correct a listing');
  assert.match(contactSent[0]._subject, /^\[Contact: Correct a listing\] Message from Sam Visitor$/);
  assert.equal((await contactPost(base, contactValid({ topic: 'bogus' }))).status, 400, 'unknown topics are refused');
  const plain = await contactPost(base, contactValid());
  assert.equal(plain.status, 201, 'a message without a topic still works');
  // App launch: an email is enough.
  const app1 = await contactPost(base, { email: 'early@example.com', topic: 'app_launch', company_website: '', started_at: Date.now() - 10000 });
  assert.equal(app1.status, 201);
  const p = contactSent[contactSent.length - 1];
  assert.equal(p._subject, '[App launch list] early@example.com');
  assert.equal(p.Message, 'Please email me when the Okanagan Roam app launches.');
  assert.equal((await contactPost(base, { email: 'not-an-email', topic: 'app_launch', company_website: '', started_at: Date.now() - 10000 })).status, 400);
  // The page and the dialogs.
  const page = await fetch(`${base}/contact`);
  assert.equal(page.status, 200);
  const html = await page.text();
  assert.match(html, /<h1>Contact Okanagan Roam<\/h1>/);
  assert.match(html, /mailto:info@okanaganroam\.com/);
  assert.match(html, /data-contact-topic="correction"/);
  assert.match(html, /<select id="contactTopic" name="topic">/);
  assert.doesNotMatch(html.match(/<select id="contactTopic"[\s\S]*?<\/select>/)[0], /app_launch/, 'the launch list is not a contact topic');
  const teaser = html.match(/<dialog class="app-teaser-dialog" id="appTeaserDialog"[\s\S]*?<\/dialog>/)[0];
  assert.match(teaser, /The Okanagan Roam app is on its way/);
  assert.match(teaser, /id="appSignupForm"/);
  assert.doesNotMatch(teaser, /App Store|Google Play|now in your pocket/, 'no store buttons that do nothing, no claim the app exists');
  assert.match(await (await fetch(`${base}/sitemap.xml`)).text(), /<loc>https:\/\/okanaganroam\.com\/contact<\/loc>/);
}));


test('My Trip (2026-10-14): /api/trip-stops describes each stop, /my-trip is a private page with share, map and day grouping, and the tray links to it', () => withDiscoveryServer(async (base) => {
  const v = db.prepare("SELECT id, name, region, type, slug FROM venues WHERE redirect_to IS NULL AND slug IS NOT NULL LIMIT 1").get();
  const out = app.tripStopsFor([`venue:${v.id}`, 'venue:999999999', 'nonsense', 'venue:0']);
  assert.equal(out.length, 2, 'malformed refs are skipped');
  assert.equal(out[0].name, v.name);
  assert.equal(out[0].url, `/${v.region}/${app.CATEGORY_SLUGS[v.type]}/${v.slug}`);
  assert.match(out[0].photo, /^\/images\//);
  assert.match(out[0].query, /Okanagan Valley, BC$/);
  assert.deepEqual(out[1], { ref: 'venue:999999999', missing: true });
  const api = await (await fetch(`${base}/api/trip-stops?refs=venue:${v.id}`)).json();
  assert.equal(api.stops[0].ref, `venue:${v.id}`);
  const res = await fetch(`${base}/my-trip`);
  assert.equal(res.status, 200);
  const html = await res.text();
  assert.match(html, /<meta name="robots" content="noindex">/, 'a personal page stays out of search');
  assert.doesNotMatch(html, /<div id="tripTray">/, 'no tray here, so app.js does not hold a second copy of the trip');
  for (const id of ['mtCopy', 'mtSave', 'mtMap', 'mtDays', 'mtEmpty']) assert.match(html, new RegExp(`id="${id}"`));
  assert.ok(html.includes("'okanaganTripDays'"), 'reads the day of each stop');
  const kelowna = await (await fetch(`${base}/kelowna`)).text();
  assert.ok(kelowna.includes("full.href = '/my-trip'"), 'the tray offers the full trip');
  assert.ok(kelowna.includes("/api/trip-stops?refs="), 'the tray links each stop to its page');
  const planner = app.renderTripPlannerPage(true);
  assert.ok(planner.includes("localStorage.setItem('okanaganTripDays'"), 'Add whole trip remembers the days');
  assert.doesNotMatch(await (await fetch(`${base}/sitemap.xml`)).text(), /my-trip/);
}));

test('Sections on the shared engine (2026-10-14): Outdoors, Beaches, Tours, Ski & Snow and their town pages; Golf ranks by rating with card photos', () => withDiscoveryServer(async (base) => {
  for (const p of ['/outdoors', '/beaches', '/tours', '/ski-snow']) {
    const res = await fetch(base + p);
    if (res.status !== 200) { await res.text(); continue; }
    const html = await res.text();
    assert.match(html, /<script type="application\/json" id="fdVenueData">/, `${p} uses the shared engine`);
    assert.match(html, /<option value="recommended"[^>]*>Mixed<\/option>/, `${p} opens in the Mixed order`);
    const grid = (html.match(/<ul class="card-grid" id="fdResults"[^>]*>([\s\S]*?)<\/ul>/) || [])[1] || '';
    assert.ok((grid.match(/<li class="venue-card"/g) || []).length <= 48, `${p}: at most 48 before Show more`);
    assert.ok([...grid.matchAll(/<li class="venue-card"[^>]*>/g)].every((m) => /data-ph="/.test(m[0])), `${p}: a photo on every card`);
  }
  // Ski resorts open the list, north to south.
  const ski = app.renderSkiSnowHubPage([
    { id: 99301, name: 'Tube Park Fixture', region: 'big-white', type: 'outdoor', slug: 'tube-park-fixture', description: 'Fixture.' },
    { id: 99302, name: 'Big White Ski Resort', region: 'big-white', type: 'outdoor', slug: 'big-white-ski-resort-fx', description: 'Fixture.' },
    { id: 99303, name: 'SilverStar Mountain Resort', region: 'silverstar', type: 'outdoor', slug: 'silverstar-fx', description: 'Fixture.' },
  ], []);
  const order = [...ski.matchAll(/class="venue-card-name">([^<]*)/g)].map((m) => m[1]);
  assert.deepEqual(order.slice(0, 2), ['SilverStar Mountain Resort', 'Big White Ski Resort']);
  assert.deepEqual(app.skiKinds({ name: 'Big White Tube Park (Happy Valley)' }), ['tubing']);
  // A town page: no Regions control, the town in the breadcrumb and heading.
  const town = await fetch(`${base}/kelowna/beaches`);
  if (town.status === 200) {
    const th = await town.text();
    assert.doesNotMatch(th, /id="fdRegionsBtn"/);
    assert.match(th, /<h1>Beaches in Kelowna<\/h1>/);
    assert.match(th, /<link rel="canonical" href="https:\/\/okanaganroam\.com\/kelowna\/beaches">/);
  }
  // Tour activity pages keep their own address and title.
  const wine = await fetch(`${base}/tours/wine`);
  if (wine.status === 200) {
    const wh = await wine.text();
    assert.match(wh, /<link rel="canonical" href="https:\/\/okanaganroam\.com\/tours\/wine">/);
    assert.match(wh, /data-fd-type="wine" aria-pressed="true"/);
  }
  // Golf: a photo on each course card, no "Value index unavailable" filler.
  const golf = await fetch(`${base}/golf`);
  if (golf.status === 200) {
    const gh = await golf.text();
    assert.doesNotMatch(gh, /Value index unavailable/);
    assert.match(gh, /data-card-ph style="--card-ph:url\('/);
  }
}));


test('Browse (2026-10-14): only the first page of cards ships with /browse; the rest and the search words come from /browse/cards.json', () => withDiscoveryServer(async (base) => {
  const html = await (await fetch(`${base}/browse`)).text();
  const m = html.match(/<template id="bhRest" data-src="(\/browse\/cards\.json\?v=[0-9a-f]{12})"><\/template>/);
  assert.ok(m, 'the template points at the rest of the cards');
  assert.doesNotMatch(html.match(/<script type="application\/json" id="bhVenueData">([\s\S]*?)<\/script>/)[1], /"k":/, 'search words are not in the page');
  const grid = (html.match(/<ul class="card-grid" id="bhResults"[^>]*>([\s\S]*?)<\/ul>/) || [])[1] || '';
  assert.ok([...grid.matchAll(/<li class="venue-card"[^>]*>/g)].every((x) => /data-ph="/.test(x[0])), 'a photo on every card');
  const rest = await fetch(base + m[1]);
  assert.equal(rest.status, 200);
  const data = await rest.json();
  const venues = app.getBrowseHubVenues();
  assert.equal((data.html.match(/<li class="venue-card"/g) || []).length, venues.length, 'every place is in the rest');
  assert.ok(!/<button type="button" class="card-action/.test(data.html), 'buttons are built when a card is shown');
  assert.ok(Object.keys(data.k).length > 0, 'search words for the places');
  assert.match(html, /<option value=""[^>]*>Recommended<\/option>/);
}));

