// ---- SEO fixes: French season crash, trailing slash, head clamping ----------
test('SEO fixes: season notice with a comma, trailing-slash 301, clamped head tags', async () => {
  assert.equal(app.frSeasonText('Closed for the season. Reopens May 1, 2027.'), 'Fermé pour la saison. Réouverture le 1er mai 2027.');
  const longDesc = 'word '.repeat(60).trim();
  const head = `<!DOCTYPE html><title>${'A very long page title that keeps going and going past the limit'} | Okanagan Roam</title><meta name="description" content="${longDesc}"><meta property="og:description" content="${longDesc}">`;
  const tidy = app.tidySeoHead(head);
  assert.ok(!/\| Okanagan Roam<\/title>/.test(tidy), 'long title drops the site suffix');
  for (const m of tidy.matchAll(/content="([^"]*)"/g)) assert.ok(m[1].length <= 160, 'description clamped to 160');
  assert.match(app.tidySeoHead('<!DOCTYPE html><title>Short | Okanagan Roam</title>'), /Short \| Okanagan Roam/);
  await new Promise((resolve, reject) => {
    const tmp = require('node:http').createServer((req, res) => app.server.emit('request', req, res));
    tmp.listen(0, '127.0.0.1', async () => {
      try {
        let res = await fetch(`http://127.0.0.1:${tmp.address().port}/kelowna/?x=1`, { redirect: 'manual' });
        assert.equal(res.status, 301);
        assert.equal(res.headers.get('location'), '/kelowna?x=1');
        res = await fetch(`http://127.0.0.1:${tmp.address().port}/api/venues/`, { redirect: 'manual' });
        assert.notEqual(res.status, 301, 'API paths are left alone');
        resolve();
      } catch (err) { reject(err); } finally { tmp.close(); }
    });
  });
});

// ---- SEO round 3 (2026-10-17): image sizes, short titles, French event pages ----
test('SEO round 3: photos declare their size, long names shorten in titles, French event pages need a translation', () => {
  assert.match(app.imgDimsAttr('/images/whats-on/arts-culture.jpg?v=1'), /^ width="\d+" height="\d+"$/);
  assert.equal(app.imgDimsAttr('https://example.com/a.jpg'), '');
  assert.equal(app.imgDimsAttr('/images/../server.js'), '');
  assert.equal(app.shortTitleName('Vernon Recreation Complex – Priest Valley Arena & Centennial Outdoor Rink'), 'Vernon Recreation Complex');
  assert.equal(app.shortTitleName('Short name'), 'Short name');
  const cut = app.shortTitleName('Spring Awakening Easter Yin Yoga Sound Healing Renewal in the Salt Cave Today', 50);
  assert.ok(cut.length <= 50 && cut.endsWith('…'), cut);
  const ev = { name: 'Skillful', region: 'kelowna' };
  assert.equal(app.frEventTitle('Skillful — Event in Kelowna, BC | Okanagan Roam', ev), 'Skillful — Événement à Kelowna (C.-B.) | Okanagan Roam');
  assert.equal(app.frEventTitle('Skillful — October 16, 2026 — Event in Kelowna, BC', ev), 'Skillful — 16 octobre 2026 — Événement à Kelowna (C.-B.)');
  assert.equal(app.frEventTitle('Skillful — Kelowna', ev), 'Skillful (Kelowna, C.-B.)');
  // Long names keep what tells two events apart (the date, the film) and drop the town instead.
  assert.equal(app.frEventTitle("Handel's Messiah Live — November 29, 2026 — Event in Kelowna, BC", ev), "Handel's Messiah Live — 29 novembre 2026 (Kelowna, C.-B.)");
  assert.notEqual(app.frEventTitle('PAG Film Series: H is for Hawk at Landmark Cinema — Penticton', { region: 'penticton' }),
    app.frEventTitle('PAG Film Series: The Christophs at Landmark Cinema — Penticton', { region: 'penticton' }));
  assert.notEqual(app.frEventTitle('Freya & Friends: Okanagan Symphony Holiday Concert — Penticton', { region: 'penticton' }),
    app.frEventTitle('Freya & Friends: Okanagan Symphony Holiday Concert — Vernon', { region: 'vernon' }));
  // A fixture event has no French description, so it stays English-only.
  assert.equal(app.hasFrenchTwin('/kelowna/events/test-future-festival'), false);
  const venue = app.findVenueBySlug('kelowna', 'restaurant', 'test-trattoria');
  const title = (html) => html.match(/<title>([^<]*)<\/title>/)[1];
  const longVenue = { ...venue, name: 'Vernon Recreation Complex – Priest Valley Arena & Centennial Outdoor Rink', description_fr: 'Un aréna.' };
  const en = title(app.renderVenuePage(longVenue, [], [], [])), fr = title(app.renderVenuePage(longVenue, [], [], [], { lang: 'fr' }));
  assert.ok(en.length <= 65 && fr.length <= 65 && en !== fr, `${en} / ${fr}`);
  assert.match(en, /^Vernon Recreation Complex — /);
});

test('SEO audit fixes (2026-10-17): sitemap pages, .ics noindex, no hreflang on noindex pages, shared descriptions, Field of Screams in French', async () => {
  const get = (urlPath) => new Promise((resolve, reject) => {
    const tmp = require('node:http').createServer((req, res) => app.server.emit('request', req, res));
    tmp.listen(0, '127.0.0.1', async () => {
      try { const res = await fetch(`http://127.0.0.1:${tmp.address().port}${urlPath}`); resolve({ status: res.status, headers: res.headers, text: await res.text() }); }
      catch (err) { reject(err); } finally { tmp.close(); }
    });
  });
  const ids = [];
  try {
    // Build My Trip, the directory and the two listing forms are in the sitemap, each with its French twin.
    const sitemap = (await get('/sitemap.xml')).text;
    for (const p of ['/trip', '/browse', '/list-your-venue', '/list-an-event']) {
      assert.match(sitemap, new RegExp(`<loc>https://okanaganroam\\.com${p}</loc>`), p);
      assert.match(sitemap, new RegExp(`<loc>https://okanaganroam\\.com/fr${p}</loc>`), `/fr${p}`);
      assert.match(sitemap, new RegExp(`hreflang="fr-CA" href="https://okanaganroam\\.com/fr${p}"`), `${p} alternates`);
    }

    // A calendar download is kept out of search.
    const shared = 'S5 audit shared moose hunt description.';
    const feb = s5create({ name: 'S5 Audit Moose February', description: shared, occurrences: [{ start_date: '2032-02-14' }] });
    const mar = s5create({ name: 'S5 Audit Moose March', description: shared, occurrences: [{ start_date: '2032-03-14' }] });
    const solo = s5create({ name: 'S5 Audit Solo Show', description: 'S5 audit one-of-a-kind description.' });
    ids.push(feb.id, mar.id, solo.id);
    const ics = await get(`/kelowna/events/${feb.slug}/calendar.ics`);
    assert.equal(ics.status, 200);
    assert.equal(ics.headers.get('x-robots-tag'), 'noindex');

    // Two events sharing a description get different snippets: next date and town first.
    const meta = (html) => (html.match(/<meta name="description" content="([^"]*)"/) || [])[1];
    const febMeta = meta((await get(`/kelowna/events/${feb.slug}`)).text), marMeta = meta((await get(`/kelowna/events/${mar.slug}`)).text);
    assert.match(febMeta, /^[A-Z][a-z]{2} Feb 14 · Kelowna: S5 audit shared moose hunt/);
    assert.match(marMeta, /^[A-Z][a-z]{2} Mar 14 · Kelowna: S5 audit shared moose hunt/);
    assert.equal(app.eventSharedDescriptionLead(app.getEventById(solo.id)), null, 'a unique description is left alone');
    assert.equal(meta((await get(`/kelowna/events/${solo.slug}`)).text), 'S5 audit one-of-a-kind description.');

    // A noindex page carries no hreflang; an indexable one does.
    const head = (robots) => `<!DOCTYPE html><html lang="en"><head>\n<link rel="canonical" href="https://okanaganroam.com/naramata/events">\n${robots}</head><body></body></html>`;
    assert.doesNotMatch(app.addTwinHead(head('<meta name="robots" content="noindex">\n'), '/naramata/events'), /hreflang/);
    assert.match(app.addTwinHead(head(''), '/naramata/events'), /hreflang="fr-CA" href="https:\/\/okanaganroam\.com\/fr\/naramata\/events"/);

    // Field of Screams: its stored description has French, so it gets a French twin whose written title, description
    // and sections are French too.
    const fosDesc = "Thirteen seasons in, the Okanagan's biggest haunted corn maze has gone all-in on the number. Field of Screams takes over the fields at Historic O'Keefe Ranch north of Vernon with four separate walk-through mazes — The Village, Distortion, Chocolate Factory and the Vintage Hotel — each with its own build, its own set and its own live scare actors waiting in the corn. Parking opens at 6 pm and the mazes start taking people at 6:30, which means the whole thing happens in the dark. You can buy into one maze, two, all four, or a VIP pass that moves you up the queue. Opening week, September 25 to October 4, is the cheapest time to go, and Wednesdays are discounted all season. This is built to frighten adults: the organizers do not recommend it for children under 12, and say it is best suited to teens and adults.";
    const fos = s5create({ name: 'Field of Screams XIII: The Unlucky', region: 'vernon', venue_id: null, venue_name_text: "Historic O'Keefe Ranch", description: fosDesc, occurrences: [{ start_date: '2026-09-25', end_date: '2026-11-01' }] });
    ids.push(fos.id);
    assert.equal(fos.slug, 'field-of-screams-xiii-the-unlucky');
    const path = '/vernon/events/field-of-screams-xiii-the-unlucky';
    assert.equal(app.hasFrenchTwin(path), true);
    const en = app.renderEventPage(app.getEventById(fos.id), null, { now: new Date('2026-10-17T19:00:00Z') });
    assert.match(en, /<title>Field of Screams Vernon 2026: Dates &amp; Tickets \| Okanagan Roam<\/title>/);
    const fr = app.frenchTwinHtml(en, path);
    assert.match(fr, /<title>Field of Screams Vernon 2026 : dates et billets \| Okanagan Roam<\/title>/);
    assert.match(meta(fr), /^Field of Screams à Vernon, du 25 septembre au 1er novembre 2026 : labyrinthes hantés/);
    assert.match(fr, /Billets et soirs disponibles/);
    assert.match(fr, /Arrivée et stationnement/);
    assert.match(fr, /Field of Screams revient au Historic O’Keefe Ranch/);
    for (const english of ['Tickets and available nights', 'Arrival and parking', 'Check available nights', 'Explore Field of Screams in Vernon']) {
      assert.ok(!fr.includes(english), `no English left: ${english}`);
    }
  } finally {
    for (const id of ids) {
      for (const t of ['event_enrichment_log', 'event_submissions', 'owner_event_changes', 'event_categories', 'event_occurrences']) db.prepare(`DELETE FROM ${t} WHERE event_id = ?`).run(id);
      db.prepare('DELETE FROM events WHERE id = ?').run(id);
    }
  }
});

test('SEO audit 2 (2026-10-17): FR breadcrumbs, event end dates, summary ItemLists, activity links, /contact link, EN-only place text, further-ahead events, FR guides, /trip script', async () => {
  const ldBlocks = (html) => [...html.matchAll(/<script type="application\/ld\+json">\s*([\s\S]*?)\s*<\/script>/g)].map((m) => JSON.parse(m[1]));
  const ids = [];
  try {
    // 1. A French place page's breadcrumb trail stays on /fr.
    const venue = app.findVenueBySlug('kelowna', 'restaurant', 'test-trattoria');
    const frPage = app.renderVenuePage({ ...venue, description_fr: 'Une trattoria (fixture).' }, [], [], [], { lang: 'fr' });
    const crumbs = ldBlocks(frPage).find((b) => b['@type'] === 'BreadcrumbList').itemListElement.map((li) => li.item);
    assert.deepEqual(crumbs, ['https://okanaganroam.com/fr', 'https://okanaganroam.com/fr/kelowna', 'https://okanaganroam.com/fr/kelowna/restaurants', 'https://okanaganroam.com/fr/kelowna/restaurants/test-trattoria']);
    const enCrumbs = ldBlocks(app.renderVenuePage(venue, [], [], [])).find((b) => b['@type'] === 'BreadcrumbList').itemListElement.map((li) => li.item);
    assert.equal(enCrumbs[0], 'https://okanaganroam.com/');
    assert.equal(enCrumbs[2], 'https://okanaganroam.com/kelowna/restaurants');

    // 2. A timed start with no end time on the same day: no endDate (never midnight before the start); series dates carry status.
    const timed = s5create({ name: 'S5 Audit2 Timed Show', occurrences: [{ start_date: '2032-05-15', start_time: '19:30', end_time: null }, { start_date: '2032-05-16', start_time: '19:30', end_time: null }] });
    const spanning = s5create({ name: 'S5 Audit2 Two Day Fair', occurrences: [{ start_date: '2032-06-01', end_date: '2032-06-02', start_time: '10:00', end_time: null }] });
    ids.push(timed.id, spanning.id);
    const ev = ldBlocks((await s5get(`/kelowna/events/${timed.slug}`)).text).find((b) => /Event/.test(b['@type']) && b.startDate);
    assert.equal(ev.startDate, '2032-05-15T19:30:00-07:00');
    assert.ok(!('endDate' in ev), 'no endDate before the start');
    assert.equal(ev.subEvent.length, 1);
    assert.equal(ev.subEvent[0].eventStatus, 'https://schema.org/EventScheduled');
    assert.equal(ev.subEvent[0].eventAttendanceMode, 'https://schema.org/OfflineEventAttendanceMode');
    assert.ok(!('endDate' in ev.subEvent[0]));
    const fair = ldBlocks((await s5get(`/kelowna/events/${spanning.slug}`)).text).find((b) => /Event/.test(b['@type']) && b.startDate);
    assert.equal(fair.endDate, '2032-06-02', 'a multi-day event keeps its later end date');

    // 3. Summary-format ItemLists: position, url and name, no partial item.
    const list = ldBlocks((await s5get('/kelowna/restaurants')).text).find((b) => b['@type'] === 'ItemList');
    assert.ok(list.itemListElement.length && list.itemListElement.every((x) => x.position && x.url && x.name && !x.item));

    // 4. /categories links every live activity page.
    const categories = (await s5get('/categories')).text;
    assert.match(categories, /<h2 class="category-subsection-heading" id="categoriesActivities">Browse by activity<\/h2>/);
    for (const p of app.liveActivityPagePaths()) assert.ok(categories.includes(`href="${p}"`), p);

    // 5. The footer's Contact is a real link that still opens the dialog.
    assert.match(app.renderHomeFooterHTML(), /<a href="\/contact" data-contact-open aria-haspopup="dialog" aria-controls="contactDialog"/);

    // 6. Further ahead: an event past the town page's 90-day window is linked from the town and valley pages.
    const far = s5create({ name: 'S5 Audit2 Far Future Gala', occurrences: [{ start_date: '2033-02-10' }] });
    ids.push(far.id);
    for (const page of ['/kelowna/events', '/whats-on']) {
      const html = (await s5get(page)).text;
      assert.match(html, /<h2 class="category-subsection-heading" id="whatsOnFurtherHeading">Further ahead<\/h2>/, page);
      assert.ok(html.includes(`href="/kelowna/events/${far.slug}"`), `${page} links the far event`);
      assert.match(html, /Feb 10, 2033/);
    }
    assert.doesNotMatch((await s5get('/kelowna/events?when=this-week')).text, /whatsOnFurtherHeading/, 'filtered views stay as they were');

    // 7. The French guide pieces that were left in English now translate.
    const guideFr = require('../data/french/guides-4.json');
    for (const [en, fr] of Object.entries(guideFr)) assert.equal(app.frText(en), fr, en);
    assert.equal(app.frText('Browse by activity'), 'Parcourir par activité');
    assert.equal(app.frText('Further ahead'), 'Plus tard dans le calendrier');

    // 8. /trip's script no longer holds a link-shaped string a crawler reads as a broken URL.
    const trip = (await s5get('/trip')).text;
    assert.doesNotMatch(trip, /href="\/'\s*\+/);
  } finally {
    for (const id of ids) {
      for (const t of ['event_enrichment_log', 'event_submissions', 'owner_event_changes', 'event_categories', 'event_occurrences']) db.prepare(`DELETE FROM ${t} WHERE event_id = ?`).run(id);
      db.prepare('DELETE FROM events WHERE id = ?').run(id);
    }
  }
});

test('French leaks (2026-10-17): notes, blurbs, directions and linked guide lines are French on /fr; place pages translate address and advisory', () => {
  const notes = require('../data/french/notes-2026-10-17.json');
  for (const [en, fr] of Object.entries(notes)) if (!en.includes('{a0}')) assert.equal(app.frText(en), fr, en);
  const page = (body, enPath) => app.frenchTwinHtml(`<!DOCTYPE html><html lang="en"><head>\n<title>T</title>\n<link rel="canonical" href="https://okanaganroam.com${enPath}">\n</head><body><main>${body}</main></body></html>`, enPath);
  // A guide line with links is translated whole, links kept in place.
  const kokanee = page('<ul><li><strong>The salmon run:</strong> <a href="/guides/kokanee-salmon-okanagan">Where to see the kokanee salmon run</a> covers the creeks where the listings mention spawning kokanee, plus other salmon runs and fishing.</li></ul>', '/guides/fall-okanagan');
  assert.match(kokanee, /couvre les ruisseaux où les fiches mentionnent la fraie des kokanis/);
  assert.match(kokanee, /href="\/fr\/guides\/kokanee-salmon-okanagan"/);
  const empty = page('<p>Okanagan Roam is building its What’s On listings community by community. Your region and category choices are saved in the address bar, so this page is ready the moment the first events arrive — in the meantime, <a href="/outdoors">explore the outdoors</a> or <a href="/trip">start planning a trip</a>.</p>', '/whats-on');
  assert.match(empty, /Okanagan Roam construit ses listes d’événements une communauté à la fois/);
  assert.doesNotMatch(empty, /is building its What/);
  // A card note on a list page.
  assert.match(page('<p class="card-note"><span class="card-note-label">Dogs:</span> Designated area on the east side of the beach for dogs</p>', '/beaches'), /Zone désignée pour les chiens du côté est de la plage/);
  // The French place page: address (directions) and advisory text in French; the map link keeps the stored English.
  const venue = app.findVenueBySlug('kelowna', 'restaurant', 'test-trattoria');
  const address = 'Knox Mountain Drive, just north of downtown Kelowna, BC (additional parking at the western base off Poplar Point Drive)';
  const fr = app.renderVenuePage({ ...venue, address, latitude: null, longitude: null, description_fr: 'Une trattoria (fixture).' }, [], [], [], { lang: 'fr' });
  assert.match(fr, /Knox Mountain Drive, juste au nord du centre-ville de Kelowna \(C\.-B\.\)/);
  assert.ok(fr.includes(encodeURIComponent(address)), 'the map link searches the stored address');
  assert.match(app.advisoryNoticeHtml('The trail down to the waterfalls is closed for slope stability issues.', app.frTextOr), /Le sentier qui descend aux chutes est fermé en raison de problèmes de stabilité de la pente\./);
  assert.match(app.advisoryNoticeHtml('The trail down to the waterfalls is closed for slope stability issues.'), /The trail down to the waterfalls is closed/, 'English pages unchanged');
});

test('Ski-hill town pages (2026-10-17): approved winter titles and descriptions in English and French', () => {
  const want = {
    'big-white': ['Big White Restaurants, Après-Ski &amp; Winter Guide | Okanagan Roam', 'Restaurants, après-ski et guide d’hiver à Big White'],
    silverstar: ['SilverStar Dining, Winter Activities &amp; Après Guide', 'Guide d’hiver, restaurants et après-ski à SilverStar'],
    apex: ['Apex Mountain Restaurants, Pubs &amp; Winter Guide | Okanagan Roam', 'Guide de la station Apex : restaurants et après-ski'],
    baldy: ['Mount Baldy Winter Guide &amp; Local Dining | Okanagan Roam', 'Guide d’hiver et restauration au mont Baldy | Okanagan Roam'],
  };
  const fr = require('../data/french/ski-resorts-2026-10-17.json');
  for (const [region, [enTitle, frTitle]] of Object.entries(want)) {
    const en = app.renderRegionPage(region, { restaurant: 3, pub: 2, cafe: 1 }, []);
    const twin = app.frenchTwinHtml(en, `/${region}`);
    const title = (h) => h.match(/<title>([^<]*)<\/title>/)[1];
    const desc = (h) => h.match(/<meta name="description" content="([^"]*)"/)[1];
    assert.equal(title(en), enTitle, region);
    assert.equal(title(twin), frTitle, `${region} fr`);
    assert.ok(title(en).replace(/&amp;/g, '&').length <= 65 && title(twin).length <= 65, `${region}: titles fit`);
    const enDesc = desc(en).replace(/&amp;/g, '&');
    assert.equal(desc(twin), fr[enDesc], `${region} fr description`);
    assert.ok(enDesc.length <= 160 && fr[enDesc].length <= 160, `${region}: descriptions fit`);
  }
  // Other towns keep their own titles.
  assert.match(app.renderRegionPage('kelowna', { restaurant: 3 }, []), /<title>(?!Big White|SilverStar|Apex|Mount Baldy)/);
});

test('Menus (2026-10-17): reading, checking and publishing a menu; private links wait for review; menu page and SEO', async () => {
  const http = require('node:http');
  seasonInsert.run({ name: 'Menu Fixture Bistro', type: 'restaurant', hours: SEASON_WEEK, slug: 'menu-fixture-bistro' });
  seasonInsert.run({ name: 'Menu Fixture Cafe', type: 'cafe', hours: SEASON_WEEK, slug: 'menu-fixture-cafe' });
  const v = app.findVenueBySlug('kelowna', 'restaurant', 'menu-fixture-bistro');
  const c = app.findVenueBySlug('kelowna', 'cafe', 'menu-fixture-cafe');
  const token = app.createOwnerLink(v.id, { contact_email: 'chef@example.com' }).url.split('/owner/')[1];
  const tokenC = app.createOwnerLink(c.id, {}).url.split('/owner/')[1];
  const jpeg = (w, h) => Buffer.concat([Buffer.from([0xFF, 0xD8, 0xFF, 0xC0, 0x00, 0x11, 0x08, h >> 8, h & 255, w >> 8, w & 255, 0x03, 1, 0x22, 0, 2, 0x11, 1, 3, 0x11, 1]), Buffer.alloc(64), Buffer.from([0xFF, 0xD9])]);
  const dataUrl = (buf) => `data:image/jpeg;base64,${buf.toString('base64')}`;
  const handler = app.server.listeners('request')[0];
  const srv = http.createServer(handler);
  await new Promise((resolve) => srv.listen(0, resolve));
  const base = `http://localhost:${srv.address().port}`;
  let ip = 1;
  const post = (p, body, cookie) => fetch(`${base}${p}`, { method: 'POST',
    headers: { 'Content-Type': 'application/json', Origin: base, 'X-Real-IP': `10.21.0.${ip++}`, ...(cookie ? { Cookie: cookie } : {}) }, body: JSON.stringify(body) })
    .then(async (r) => ({ status: r.status, body: await r.json().catch(() => ({})), setCookie: r.headers.get('set-cookie') || '' }));
  const get = (p, cookie) => fetch(`${base}${p}`, { redirect: 'manual', headers: cookie ? { Cookie: cookie } : {} });
  const state = (p, cookie) => get(`${p}/state`, cookie).then((r) => r.json());
  const waitRead = async (p, cookie) => {
    for (let i = 0; i < 50; i++) { const s = await state(p, cookie); if (s.menu.status !== 'reading') return s; await new Promise((r) => setTimeout(r, 20)); }
    throw new Error('read never finished');
  };
  const reads = [];
  const MENU = { readable: true, problem: 'none', sections: [
    { name: 'Starters', note: '', items: [
      { name: 'Poutine', description: 'Fries, cheese curds, gravy', price: '14', dietary: ['gluten_free'], check: false },
      { name: 'Caesar Salad', description: '', price: '12.50', dietary: [], check: true },
      { name: '<b>Wings</b>', description: '', price: '16', dietary: ['spicy', 'made-up'], check: false }] },
    { name: 'Mains', note: 'Served with fries or salad', items: [
      { name: 'Smash Burger', description: '', price: '19', dietary: [], check: false },
      { name: 'Fish & Chips', description: 'Ling cod', price: 'MP', dietary: [], check: false },
      { name: 'Veggie Bowl', description: '', price: '17', dietary: ['vegan'], check: false }] },
  ] };
  app.setMenuReader(async (pages) => { reads.push(pages.map((p) => p.kind)); return { ok: true, result: JSON.parse(JSON.stringify(MENU)), usage: { input: 1, output: 1 }, model: 'stub' }; });
  const sent = [], ownerMail = [];
  app.setVenueSubmissionTransport(async (payload) => { sent.push(payload); });
  app.setOwnerEmailTransport(async (m) => { ownerMail.push(m); });
  const menuBase = `/owner/${token}/menu`;
  try {
    // The owner page leads with the big menu button; the menu screen works.
    assert.match(await get(`/owner/${token}`).then((r) => r.text()), /class="op-menu-card" href="\/owner\/[^"]+\/menu"[^>]*><span class="op-menu-big">&#128247; Add your menu/);
    const page = await get(menuBase).then((r) => r.text());
    assert.match(page, /window\.MENU_CFG = /);
    assert.match(page, /Take a photo of your menu/);
    assert.match(await get(`${menuBase}?lang=fr`).then((r) => r.text()), /Prendre votre menu en photo/);
    assert.equal((await get(`/owner/${'z'.repeat(32)}/menu`)).status, 404);

    // Pages: photos and PDFs; bad files get kind messages.
    assert.equal((await post(`${menuBase}/pages`, { image: 'data:image/png;base64,AAAA' })).status, 400);
    assert.match((await post(`${menuBase}/pages`, { image: dataUrl(jpeg(300, 200)) })).body.error, /a bit small/);
    assert.equal((await post(`${menuBase}/pages`, { pdf: `data:application/pdf;base64,${Buffer.from('not a pdf').toString('base64')}` })).status, 400);
    const p1 = await post(`${menuBase}/pages`, { image: dataUrl(jpeg(1600, 1200)) });
    assert.equal(p1.status, 201, JSON.stringify(p1.body));
    const p2 = await post(`${menuBase}/pages`, { pdf: `data:application/pdf;base64,${Buffer.from('%PDF-1.4 fake').toString('base64')}` });
    assert.equal(p2.status, 201);
    assert.equal((await get(p1.body.page.preview)).status, 200);
    assert.equal((await get(p2.body.page.preview)).headers.get('content-type'), 'application/pdf');
    let s = await state(menuBase);
    assert.equal(s.menu.pages.length, 2);
    assert.equal(s.menu.status, 'draft');
    // Nothing public yet.
    assert.equal((await get('/kelowna/restaurants/menu-fixture-bistro/menu')).status, 302);

    // Reading: both pages go to the reader; the result is cleaned up.
    assert.equal((await post(`${menuBase}/read`, {})).status, 200);
    s = await waitRead(menuBase);
    assert.deepEqual(reads[0], ['jpeg', 'pdf']);
    assert.equal(s.menu.status, 'ready');
    assert.equal(s.menu.data.sections.length, 2);
    assert.equal(s.menu.data.sections[0].items[2].name, 'bWings/b', 'no markup survives');
    assert.deepEqual(s.menu.data.sections[0].items[2].dietary, ['spicy']);
    assert.equal(s.menu.data.sections[0].items[1].check, true);

    // The owner fixes a price; autosave keeps it; publishing from a private link waits for review.
    const data = s.menu.data;
    data.sections[0].items[1] = { ...data.sections[0].items[1], price: '13', check: false };
    data.sections[0].items[2].name = 'Wings';
    assert.equal((await post(`${menuBase}/save`, { data })).status, 200);
    assert.equal((await state(menuBase)).menu.data.sections[0].items[1].price, '13');
    const pub = await post(`${menuBase}/publish`, { data, contact_email: 'chef@example.com' });
    assert.equal(pub.status, 200, JSON.stringify(pub.body));
    assert.equal(pub.body.live, false);
    assert.match(sent.at(-1)._subject, /\[PENDING REVIEW\] Menu from Menu Fixture Bistro \(6 dishes\)/);
    assert.equal((await state(menuBase)).menu.status, 'pending');
    assert.equal(app.publishedMenu(v.id), null);

    // Dayton sees it, opens the editor and publishes it; the owner is emailed.
    const cookie = (await post('/admin/review/login', { token: LYV_TOKEN })).setCookie.split(';')[0];
    const review = await get('/admin/review', cookie).then((r) => r.text());
    const menuId = s.menu.id;
    assert.match(review, new RegExp(`href="/admin/review/menu/${menuId}">Open the menu editor`));
    assert.equal((await get(`/admin/review/menu/${menuId}`)).status, 302, 'needs the admin session');
    assert.match(await get(`/admin/review/menu/${menuId}`, cookie).then((r) => r.text()), /"mode":"admin"/);
    const ap = await post(`/admin/review/menu/${menuId}/publish`, { data }, cookie);
    assert.equal(ap.status, 200, JSON.stringify(ap.body));
    assert.equal(ap.body.live, true);
    assert.ok(ownerMail.some((m) => m.to === 'chef@example.com' && /Approved: your menu/.test(m.subject)));
    const live = app.publishedMenu(v.id);
    assert.equal(live.items, 6);

    // The menu page: title, prices, schema, indexable (6 dishes), linked from the place page and the sitemap.
    const mp = await get('/kelowna/restaurants/menu-fixture-bistro/menu');
    assert.equal(mp.status, 200);
    const html = await mp.text();
    assert.match(html, /<title>Menu Fixture Bistro Menu &amp; Prices — Kelowna, BC \| Okanagan Roam<\/title>|<title>Menu Fixture Bistro Menu & Prices — Kelowna, BC \| Okanagan Roam<\/title>/);
    assert.match(html, /<h1>Menu Fixture Bistro Menu<\/h1>/);
    assert.match(html, /\$12\.50|\$13/);
    assert.match(html, /<span class="vm-price">MP<\/span>/);
    assert.match(html, /Menu updated/);
    assert.doesNotMatch(html, /name="robots" content="noindex"/);
    const ld = [...html.matchAll(/<script type="application\/ld\+json">([\s\S]*?)<\/script>/g)].map((m) => JSON.parse(m[1]));
    const biz = ld.find((x) => x.hasMenu);
    assert.equal(biz.hasMenu['@type'], 'Menu');
    const poutine = biz.hasMenu.hasMenuSection[0].hasMenuItem[0];
    assert.deepEqual(poutine.offers, { '@type': 'Offer', price: '14.00', priceCurrency: 'CAD' });
    assert.deepEqual(poutine.suitableForDiet, ['https://schema.org/GlutenFreeDiet']);
    assert.equal(biz.hasMenu.hasMenuSection[1].hasMenuItem[1].offers, undefined, 'market price has no Offer');
    const venuePage = await get('/kelowna/restaurants/menu-fixture-bistro').then((r) => r.text());
    assert.match(venuePage, /See the full menu \(6 dishes\)/);
    assert.match(venuePage, /"hasMenu":"https:\/\/okanaganroam\.com\/kelowna\/restaurants\/menu-fixture-bistro\/menu"/);
    // No French page for this place: the French menu address goes to the English one.
    assert.equal((await get('/fr/kelowna/restaurants/menu-fixture-bistro/menu')).headers.get('location'), '/kelowna/restaurants/menu-fixture-bistro/menu');
    const sitemap = await get('/sitemap.xml').then((r) => r.text());
    assert.match(sitemap, /<loc>https:\/\/okanaganroam\.com\/kelowna\/restaurants\/menu-fixture-bistro\/menu<\/loc>/);

    // "Make a change" copies the live menu; a short menu is noindex and not in the sitemap.
    const ed = await post(`${menuBase}/edit`, {});
    assert.equal(ed.body.menu.status, 'ready');
    assert.equal(ed.body.menu.data.sections.length, 2);

    // Signed-in owners publish straight away.
    const made = await post(`/owner/${tokenC}/account`, { email: 'barista@example.com', password: 'a long enough password' });
    assert.equal(made.status, 201, JSON.stringify(made.body));
    const oc = made.setCookie.split(';')[0];
    const cBase = `/owner/account/venue/${c.id}/menu`;
    assert.equal((await get(cBase)).status, 302, 'signed out goes to the login');
    assert.equal((await post(`${cBase}/pages`, { image: dataUrl(jpeg(1600, 1200)) }, oc)).status, 201);
    assert.equal((await post(`${cBase}/read`, {}, oc)).status, 200);
    const cs = await waitRead(cBase, oc);
    const short = { sections: [{ name: 'Coffee', note: '', items: [{ name: 'Latte', description: '', price: '5.25', dietary: [], check: false }] }] };
    const cp = await post(`${cBase}/publish`, { data: short }, oc);
    assert.equal(cp.body.live, true, JSON.stringify(cp.body));
    assert.equal(cs.menu.status, 'ready');
    assert.match(sent.at(-1)._subject, /\[LIVE\] Menu from Menu Fixture Cafe/);
    const cafeMenu = await get('/kelowna/cafes/menu-fixture-cafe/menu').then((r) => r.text());
    assert.match(cafeMenu, /name="robots" content="noindex"/);
    assert.doesNotMatch(await get('/sitemap.xml').then((r) => r.text()), /menu-fixture-cafe\/menu/);
    // Taking it down removes the page.
    assert.equal((await post(`${cBase}/unpublish`, {}, oc)).status, 200);
    assert.equal((await get('/kelowna/cafes/menu-fixture-cafe/menu')).status, 302);

    // "Can you do it for me?" goes to info@, with the photos, and lands in Dayton's queue.
    assert.equal((await post(`${cBase}/pages`, { image: dataUrl(jpeg(1600, 1200)) }, oc)).status, 201);
    const help = await post(`${cBase}/help`, { note: 'Our specials change weekly', contact_phone: '250-555-0101' }, oc);
    assert.equal(help.status, 200, JSON.stringify(help.body));
    const helpMail = ownerMail.at(-1);
    assert.equal(helpMail.to, 'info@okanaganroam.com');
    assert.match(helpMail.subject, /\[MENU HELP\] Menu Fixture Cafe/);
    assert.match(helpMail.text, /owner-menus\/preview\/[A-Za-z0-9_-]{24}\.jpg/);
    assert.match(helpMail.text, /Our specials change weekly/);
    assert.match(await get('/admin/review', cookie).then((r) => r.text()), /Asked us to do it/);
    // Without Brevo the request still reaches Dayton through FormSubmit.
    app.setOwnerEmailTransport(null);
    const n = sent.length;
    assert.equal((await post(`/owner/${token}/menu/help`, { note: 'https://example.com/menu.pdf' })).status, 200);
    assert.equal(sent.length, n + 1);
    assert.match(sent.at(-1)._subject, /\[MENU HELP\]/);

    // A blurry photo gets the retake message, not a broken menu.
    app.setMenuReader(async () => ({ ok: true, usage: {}, result: { readable: false, problem: 'too_blurry', sections: [] } })); // usage {} once crashed the server
    const t2 = `/owner/${token}/menu`;
    assert.equal((await post(`${t2}/restart`, {})).status, 200);
    assert.equal((await post(`${t2}/pages`, { image: dataUrl(jpeg(1600, 1200)) })).status, 201);
    await post(`${t2}/read`, {});
    const blurry = await waitRead(t2);
    assert.equal(blurry.menu.status, 'draft');
    assert.equal(blurry.menu.read_error, 'blurry');
    assert.equal(blurry.scan, 'ai');

    // No API key (the free setup): the page scans the pages on the owner's phone instead, and nothing calls the API.
    const savedKey = process.env.ANTHROPIC_API_KEY;
    delete process.env.ANTHROPIC_API_KEY;
    app.setMenuReader(null);
    try {
      const free = await state(t2);
      assert.equal(free.scan, 'device');
      assert.equal(free.reading_available, false);
      assert.match(await get(t2).then((r) => r.text()), /tesseract\.js@5\.1\.1/);
    } finally { if (savedKey !== undefined) process.env.ANTHROPIC_API_KEY = savedKey; }
  } finally {
    app.setMenuReader(null);
    app.setOwnerEmailTransport(null);
    app.setVenueSubmissionTransport(async (payload) => { lyvSent.push(payload); });
    for (const f of db.prepare('SELECT file FROM venue_menu_files').all()) { try { fs.unlinkSync(path.join(app.MENU_DIR, f.file)); } catch (e) { /* gone */ } }
    await new Promise((resolve) => srv.close(resolve));
  }
});

test('Menus: the Claude request (model, refusal fallback, structured output) and price helpers', async () => {
  const realFetch = global.fetch;
  const realKey = process.env.ANTHROPIC_API_KEY;
  let req = null;
  process.env.ANTHROPIC_API_KEY = '"sk-test-key"';
  global.fetch = async (url, init) => {
    req = { url, init, body: JSON.parse(init.body) };
    return { ok: true, status: 200, json: async () => ({ model: 'claude-opus-5-5', stop_reason: 'end_turn', usage: { input_tokens: 10, output_tokens: 5 },
      content: [{ type: 'text', text: JSON.stringify({ readable: true, problem: 'none', sections: [] }) }] }) };
  };
  try {
    const r = await app.readMenuWithClaude([{ kind: 'jpeg', buf: Buffer.from('a') }, { kind: 'pdf', buf: Buffer.from('b') }]);
    assert.equal(r.ok, true);
    assert.equal(req.url, 'https://api.anthropic.com/v1/messages');
    assert.equal(req.init.headers['x-api-key'], 'sk-test-key', 'quotes around the pasted key are dropped');
    assert.equal(req.init.headers['anthropic-beta'], 'server-side-fallback-2026-07-01');
    assert.equal(req.body.model, 'claude-opus-5-5');
    assert.equal(req.body.fallbacks, 'default');
    assert.equal(req.body.output_config.format.type, 'json_schema');
    assert.equal(req.body.thinking, undefined);
    assert.deepEqual(req.body.messages[0].content.map((b) => b.type), ['image', 'document', 'text']);
    global.fetch = async () => ({ ok: true, status: 200, json: async () => ({ stop_reason: 'refusal', content: [] }) });
    assert.equal((await app.readMenuWithClaude([{ kind: 'jpeg', buf: Buffer.from('a') }])).error, 'refused');
    delete process.env.ANTHROPIC_API_KEY;
    assert.equal((await app.readMenuWithClaude([{ kind: 'jpeg', buf: Buffer.from('a') }])).error, 'unavailable');
  } finally {
    global.fetch = realFetch;
    if (realKey === undefined) delete process.env.ANTHROPIC_API_KEY; else process.env.ANTHROPIC_API_KEY = realKey;
  }
  assert.equal(app.menuPriceLabel('18'), '$18');
  assert.equal(app.menuPriceLabel('18.50', 'fr'), '18,50 $');
  assert.equal(app.menuPriceLabel('12 / 16'), '12 / 16');
  assert.equal(app.menuPriceNumber('$18.50'), 18.5);
  assert.equal(app.menuPriceNumber('MP'), null);
  assert.deepEqual(app.normalizeMenuData({ sections: [{ name: 'Empty', items: [] }, { name: 'X', items: [{ name: '  ' }, { name: 'Tea', price: 3 }] }] }),
    { sections: [{ name: 'X', note: '', items: [{ name: 'Tea', description: '', price: '', dietary: [], check: false }] }] });
});

test('Tours & prices (2026-10-17): tour operators use the uploader for their price list, published at /prices', async () => {
  const http = require('node:http');
  seasonInsert.run({ name: 'Prices Fixture Tours', type: 'tour', hours: SEASON_WEEK, slug: 'prices-fixture-tours' });
  const v = app.findVenueBySlug('kelowna', 'tour', 'prices-fixture-tours');
  const token = app.createOwnerLink(v.id, { contact_email: 'guide@example.com' }).url.split('/owner/')[1];
  const jpeg = (w, h) => Buffer.concat([Buffer.from([0xFF, 0xD8, 0xFF, 0xC0, 0x00, 0x11, 0x08, h >> 8, h & 255, w >> 8, w & 255, 0x03, 1, 0x22, 0, 2, 0x11, 1, 3, 0x11, 1]), Buffer.alloc(64), Buffer.from([0xFF, 0xD9])]);
  const handler = app.server.listeners('request')[0];
  const srv = http.createServer(handler);
  await new Promise((resolve) => srv.listen(0, resolve));
  const base = `http://localhost:${srv.address().port}`;
  let ip = 1;
  const post = (p, body, cookie) => fetch(`${base}${p}`, { method: 'POST',
    headers: { 'Content-Type': 'application/json', Origin: base, 'X-Real-IP': `10.22.0.${ip++}`, ...(cookie ? { Cookie: cookie } : {}) }, body: JSON.stringify(body) })
    .then(async (r) => ({ status: r.status, body: await r.json().catch(() => ({})), setCookie: r.headers.get('set-cookie') || '' }));
  const get = (p, cookie) => fetch(`${base}${p}`, { redirect: 'manual', headers: cookie ? { Cookie: cookie } : {} });
  const kinds = [];
  app.setMenuReader(async (pages, kind) => { kinds.push(kind); return { ok: true, result: { readable: true, problem: 'none', sections: [{ name: 'Wine Tours', note: '', items: [
    { name: 'Naramata Bench Tour', description: '4 hours, includes lunch', price: '$129 per person', dietary: [], check: false },
    { name: 'Sunset Cruise', description: '2 hours', price: 'From 89', dietary: [], check: false },
    { name: 'Private Charter', description: 'Up to 12 guests', price: '1,299', dietary: [], check: false }] }] } }; });
  const sent = [], ownerMail = [];
  app.setVenueSubmissionTransport(async (payload) => { sent.push(payload); });
  app.setOwnerEmailTransport(async (m) => { ownerMail.push(m); });
  const mb = `/owner/${token}/menu`;
  try {
    assert.match(await get(`/owner/${token}`).then((r) => r.text()), /Add your tours &amp; prices/);
    const page = await get(mb).then((r) => r.text());
    assert.match(page, /Take a photo of your price list/);
    assert.match(page, /"diet":\{\}/, 'no diet tags for tours');
    assert.equal((await post(`${mb}/pages`, { image: `data:image/jpeg;base64,${jpeg(1600, 1200).toString('base64')}` })).status, 201);
    await post(`${mb}/read`, {});
    let s;
    for (let i = 0; i < 50; i++) { s = await get(`${mb}/state`).then((r) => r.json()); if (s.menu.status !== 'reading') break; await new Promise((r) => setTimeout(r, 20)); }
    assert.deepEqual(kinds, ['tours'], 'the reader is told it is a price list');
    const pub = await post(`${mb}/publish`, { data: s.menu.data });
    assert.equal(pub.body.live, false);
    assert.match(sent.at(-1)._subject, /\[PENDING REVIEW\] Tours & prices from Prices Fixture Tours \(3 tours\)/);
    const cookie = (await post('/admin/review/login', { token: LYV_TOKEN })).setCookie.split(';')[0];
    assert.match(await get('/admin/review', cookie).then((r) => r.text()), /Tours &amp; prices #\d+|Tours & prices #\d+/);
    assert.equal((await post(`/admin/review/menu/${s.menu.id}/publish`, { data: s.menu.data }, cookie)).body.live, true);
    assert.ok(ownerMail.some((m) => /Approved: your tours & prices/.test(m.subject)));

    const html = await get('/kelowna/tours/prices-fixture-tours/prices').then((r) => r.text());
    assert.match(html, /<h1>Prices Fixture Tours Tours &amp; Prices<\/h1>/);
    assert.match(html, /<span class="vm-price">\$129 per person<\/span>/);
    assert.match(html, /<span class="vm-price">\$1,299<\/span>/);
    assert.match(html, /Prices, times and availability can change/);
    assert.doesNotMatch(html, /name="robots" content="noindex"/, '3 tours is enough to index');
    const ld = [...html.matchAll(/<script type="application\/ld\+json">([\s\S]*?)<\/script>/g)].map((m) => JSON.parse(m[1]));
    const biz = ld.find((x) => x.hasOfferCatalog);
    assert.equal(biz.hasMenu, undefined);
    const offer = biz.hasOfferCatalog.itemListElement[0].itemListElement[0];
    assert.deepEqual(offer, { '@type': 'Offer', itemOffered: { '@type': 'TouristTrip', name: 'Naramata Bench Tour', description: '4 hours, includes lunch' }, price: '129.00', priceCurrency: 'CAD' });
    assert.equal(biz.hasOfferCatalog.itemListElement[0].itemListElement[2].price, '1299.00');
    // A tour operator has no /menu page, and the place page links to /prices.
    assert.equal((await get('/kelowna/tours/prices-fixture-tours/menu')).status, 302);
    const venuePage = await get('/kelowna/tours/prices-fixture-tours').then((r) => r.text());
    assert.match(venuePage, /See all tours &amp; prices \(3 tours\)/);
    assert.doesNotMatch(venuePage, /"hasMenu"/);
    assert.match(await get('/sitemap.xml').then((r) => r.text()), /prices-fixture-tours\/prices<\/loc>/);
  } finally {
    app.setMenuReader(null);
    app.setOwnerEmailTransport(null);
    app.setVenueSubmissionTransport(async (payload) => { lyvSent.push(payload); });
    for (const f of db.prepare('SELECT file FROM venue_menu_files').all()) { try { fs.unlinkSync(path.join(app.MENU_DIR, f.file)); } catch (e) { /* gone */ } }
    await new Promise((resolve) => srv.close(resolve));
  }
});

