// ---- Lighter pages (2026-10-18) ----
const lpHttp = require('node:http');
// Venue JSON (2026-10-18): a served list page's filter data, inline or from /cards/rest/<hash>.json.
async function lpVenueData(base, html, id, pagePath) {
  const m = new RegExp(`<script type="application/json" id="${id}"( data-rest="([0-9a-f]{12})")?>([\\s\\S]*?)</script>`).exec(html);
  if (!m) return null;
  if (!m[2]) return JSON.parse(m[3]);
  return (await fetch(`${base}/cards/rest/${m[2]}.json?u=${encodeURIComponent(pagePath)}`)).json();
}
// Shared CSS as versioned cached files, a capped ItemList, and the cards and
// events after the first page loaded after the page appears.
test('Lighter pages: shared page CSS is a versioned, year-cached file in the same place as the inline block was', async () => {
  const srv = lpHttp.createServer(app.server.listeners('request')[0]);
  await new Promise((resolve) => srv.listen(0, resolve));
  const base = `http://localhost:${srv.address().port}`;
  try {
    for (const p of ['/food-drink', '/fr/food-drink', '/kelowna']) {
      const html = await (await fetch(base + p)).text();
      const seo = app.sharedStyles().get('seo-page');
      assert.ok(seo, 'SEO_PAGE_CSS is registered');
      assert.ok(!html.includes(seo.block), `${p}: the big inline block is gone`);
      assert.ok(html.includes(`<link rel="stylesheet" href="${seo.href}">`), `${p}: linked by content hash`);
      assert.ok(html.indexOf(seo.href) < html.indexOf('</head>'), `${p}: in the head`);
      assert.match(html, /<link rel="stylesheet" href="\/styles\/tokens\.css\?v=[0-9a-f]{12}">/, `${p}: tokens.css is versioned`);
    }
    const fd = await (await fetch(base + '/food-drink')).text();
    const order = ['seo-page', 'golf-theme', 'outdoor-theme', 'food-drink'].map((n) => fd.indexOf(app.sharedStyles().get(n).href));
    assert.ok(order.every((x, i) => x > 0 && (i === 0 || x > order[i - 1])), 'the cascade order is unchanged');
    // The same transformation as a pure function: the rendered page minus the swap is the old page.
    const raw = app.renderFoodDrinkHubPage(app.getFoodDrinkHubVenues(), { types: [], features: [], regions: [] });
    if (raw.includes('<style>')) {
      let back = app.withSharedStylesheets(raw);
      for (const s of app.sharedStyles().values()) back = back.split(`<link rel="stylesheet" href="${s.href}">`).join(s.block);
      back = back.replace(/(\/styles\/(?:tokens|app)\.css)\?v=[0-9a-f]{12}/g, '$1');
      assert.equal(back, raw, 'nothing but the style blocks and CSS URLs changes');
    }
    for (const s of app.sharedStyles().values()) {
      const r = await fetch(base + s.href);
      assert.equal(r.status, 200, s.name);
      assert.match(r.headers.get('content-type'), /text\/css/);
      assert.equal(r.headers.get('cache-control'), 'public, max-age=31536000, immutable', s.name);
      assert.equal(await r.text(), s.css, `${s.name} serves exactly the inline text`);
    }
    const stale = await fetch(`${base}/styles/shared/seo-page.css?v=000000000000`);
    assert.equal(stale.status, 200, 'an old hash never 404s');
    assert.equal(stale.headers.get('cache-control'), 'public, max-age=300');
    const tokensHref = fd.match(/\/styles\/tokens\.css\?v=[0-9a-f]{12}/)[0];
    assert.equal((await fetch(base + tokensHref)).headers.get('cache-control'), 'public, max-age=31536000, immutable');
    assert.equal((await fetch(base + '/styles/tokens.css')).headers.get('cache-control'), 'public, max-age=3600', 'unversioned stays short');
    assert.equal((await fetch(base + '/styles/tokens.css?v=nothash')).headers.get('cache-control'), 'public, max-age=3600');
  } finally {
    srv.close();
  }
});

test('Lighter pages: a long ItemList schema names the first 50 places and keeps the full count', () => {
  const list = (n) => ({ '@context': 'https://schema.org', '@type': 'ItemList', name: 'x', itemListElement: Array.from({ length: n }, (_, i) => ({ '@type': 'ListItem', position: i + 1, url: `https://okanaganroam.com/p${i}`, name: `P${i}` })) });
  const capped = app.capItemListSchema(list(120));
  assert.equal(capped.itemListElement.length, app.ITEM_LIST_SCHEMA_CAP);
  assert.equal(capped.numberOfItems, 120);
  assert.deepEqual(capped.itemListElement.map((x) => x.position), Array.from({ length: 50 }, (_, i) => i + 1), 'page order kept');
  const short = list(12);
  assert.equal(app.capItemListSchema(short), short, 'a short list is unchanged');
  const crumbs = { '@type': 'BreadcrumbList', itemListElement: list(80).itemListElement };
  assert.equal(app.capItemListSchema(crumbs), crumbs, 'only ItemList blocks are capped');
});

test('Lighter pages: /food-drink loads its waiting cards from /cards/rest/, the same cards in English and French', async () => {
  // Enough places that most of them wait for "Show more".
  const made = [];
  for (let i = 0; i < 90; i++) made.push(app.createVenue({ name: `LP Kitchen ${i}`, region: ['kelowna', 'penticton', 'vernon'][i % 3], type: i % 5 ? 'restaurant' : 'pub', description: `A lighter-pages fixture kitchen number ${i}.`, slug: `lp-kitchen-${i}` }).id);
  const srv = lpHttp.createServer(app.server.listeners('request')[0]);
  await new Promise((resolve) => srv.listen(0, resolve));
  const base = `http://localhost:${srv.address().port}`;
  try {
    for (const p of ['/food-drink', '/fr/food-drink', '/restaurants?types=pub']) {
      const html = await (await fetch(base + p)).text();
      const m = html.match(/<template id="fdRest" data-rest="([0-9a-f]{12})"><\/template>/);
      assert.ok(m, `${p}: the template ships empty with its hash ${(html.match(/<template id="fdRest"[^>]*>[\s\S]{0,80}/) || [])[0]}`);
      const ids = (s) => [...s.matchAll(/<li class="venue-card"[^>]*data-venue-id="(\d+)"/g)].map((x) => x[1]);
      const first = ids(html.slice(html.indexOf('id="fdResults"'), html.indexOf('id="fdRest"')));
      const hit = await fetch(`${base}/cards/rest/${m[1]}.html?u=${encodeURIComponent(p)}`);
      assert.equal(hit.status, 200);
      assert.equal(hit.headers.get('cache-control'), 'public, max-age=31536000, immutable');
      const rest = await hit.text();
      // After a restart (or on another instance) the hash is unknown: the page is rendered again from ?u=.
      const miss = await fetch(`${base}/cards/rest/ffffffffffff.html?u=${encodeURIComponent(p)}`);
      assert.equal(miss.status, 200);
      assert.equal(miss.headers.get('cache-control'), 'no-store');
      assert.equal(await miss.text(), rest, `${p}: a re-render gives the same cards`);
      const dataIds = Object.keys(await lpVenueData(base, html, 'fdVenueData', p));
      assert.deepEqual([...first, ...ids(rest)].sort(), dataIds.sort(), `${p}: the page plus the waiting cards are every place`);
      if (p.startsWith('/fr/')) assert.ok(rest.includes('Voir les détails') && !rest.includes('View details'), 'French cards for the French page');
      assert.match(html, /fetch\('\/cards\/rest\/' \+ restHash/, 'the page script loads them');
    }
    assert.equal((await fetch(`${base}/cards/rest/ffffffffffff.html?u=${encodeURIComponent('/admin/review')}`)).status, 404, 'no admin pages');
    assert.equal((await fetch(`${base}/cards/rest/ffffffffffff.html?u=${encodeURIComponent('//example.com/')}`)).status, 404);
    assert.equal((await fetch(`${base}/cards/rest/ffffffffffff.html?u=${encodeURIComponent('/kelowna')}`)).status, 404, 'a page without waiting cards');
  } finally {
    srv.close();
    for (const id of made) db.prepare('DELETE FROM venues WHERE id = ?').run(id);
  }
});

test('Lazy card photos (2026-10-18): the first cards load at once, the rest wait for the screen, on every list path', async () => {
  // Unit: the first LAZY_CARD_EAGER photo cards outside a <template> lose data-lz; template cards keep it.
  const card = (i) => `<li class="venue-card" data-venue-id="${i}" data-ph="own" style="--fd-ph:url('/x${i}.jpg')" data-lz>`;
  const page = `<html><head><title>t</title></head><body><ul>${[1, 2, 3, 4, 5, 6].map(card).join('')}</ul><template id="fdRest">${card(7)}</template></body></html>`;
  const out = app.withLazyCardPhotos(page);
  assert.equal(app.LAZY_CARD_EAGER, 4);
  const lz = (id) => new RegExp(`data-venue-id="${id}"[^>]* data-lz>`).test(out);
  assert.deepEqual([1, 2, 3, 4, 5, 6, 7].map(lz), [false, false, false, false, true, true, true]);
  assert.ok(out.indexOf('id="lazy-card-photos"') < out.indexOf('</head>'), 'the lazy script sits in the head, before any card');
  assert.match(out, /html\.lzp li\.venue-card\[data-lz\]::before\{background-image:none!important\}/, 'only hidden once the script has run (no JS: every photo loads)');
  assert.match(out, /new IntersectionObserver\([\s\S]*rootMargin: '300px 0px'/);
  assert.match(out, /new MutationObserver\([\s\S]*childList: true, subtree: true/, 'cards added later (Show more, filters, deferred cards) are observed');
  assert.match(out, /if \(!window\.IntersectionObserver \|\| !window\.MutationObserver\) return;/, 'old browsers load every photo');
  assert.equal(app.withLazyCardPhotos('<html><head></head><body><li class="venue-card"></li></body></html>'), '<html><head></head><body><li class="venue-card"></li></body></html>', 'pages without photo cards are unchanged');

  const made = [];
  for (let i = 0; i < 70; i++) made.push(app.createVenue({ name: `LZ Kitchen ${i}`, region: ['kelowna', 'penticton'][i % 2], type: 'restaurant', description: `A lazy-photo fixture kitchen ${i}.`, slug: `lz-kitchen-${i}` }).id);
  for (const id of made) db.prepare('UPDATE venues SET image_url = ? WHERE id = ?').run(`/images/venues/lz-fixture-${id}.jpg`, id);
  const srv = lpHttp.createServer(app.server.listeners('request')[0]);
  await new Promise((resolve) => srv.listen(0, resolve));
  const base = `http://localhost:${srv.address().port}`;
  try {
    for (const p of ['/restaurants', '/kelowna/restaurants', '/food-drink', '/fr/restaurants', '/browse']) {
      const html = await (await fetch(base + p)).text();
      const tags = [...html.matchAll(/<li class="venue-card"[^>]*>/g)].map((m) => m[0]).filter((t) => /data-(?:card-)?ph[ =]/.test(t));
      assert.ok(tags.length > 8, `${p}: photo cards on the page`);
      assert.deepEqual(tags.slice(0, 4).map((t) => /\sdata-lz\b/.test(t)), [false, false, false, false], `${p}: the first four load at once`);
      assert.ok(tags.slice(4).every((t) => /\sdata-lz\b/.test(t)), `${p}: every later card waits`);
      assert.equal((html.match(/id="lazy-card-photos"/g) || []).length, 1, `${p}: one lazy script`);
      const rest = html.match(/<template id="fdRest" data-rest="([0-9a-f]{12})"><\/template>/);
      if (rest) {
        const part = await (await fetch(`${base}/cards/rest/${rest[1]}.html?u=${encodeURIComponent(p)}`)).text();
        const restTags = [...part.matchAll(/<li class="venue-card"[^>]*>/g)].map((m) => m[0]);
        assert.ok(restTags.length && restTags.every((t) => /\sdata-lz\b/.test(t)), `${p}: deferred cards wait too`);
      }
    }
    const json = await (await fetch(base + '/browse/cards.json')).json();
    const jTags = [...json.html.matchAll(/<li class="venue-card"[^>]*>/g)].map((m) => m[0]);
    assert.ok(jTags.length && jTags.every((t) => /\sdata-lz\b/.test(t)), '/browse/cards.json cards wait for the screen');
    // Phones keep the 480 copy (speed first); iPhones do not zoom on the sort menu.
    const css = app.inlineSharedStylesheets(await (await fetch(base + '/restaurants')).text());
    assert.doesNotMatch(css, /max-width: 899px\) and \(min-resolution/);
    assert.match(css, /body\.fd-page \.fd-sort-select \{ font-size: 16px; \}/);
    // /guides: the first row of guide photos is not lazy.
    const guides = await (await fetch(base + '/guides')).text();
    const imgs = [...guides.matchAll(/<span class="guide-card-img"><img [^>]*>/g)].map((m) => m[0]);
    if (imgs.length > 4) {
      assert.ok(imgs.slice(0, 4).every((t) => !/loading="lazy"/.test(t)), 'first row eager');
      assert.match(imgs[0], /fetchpriority="high"/);
      assert.ok(imgs.slice(4).every((t) => /loading="lazy"/.test(t)), 'later guides lazy');
    }
  } finally {
    srv.close();
    for (const id of made) db.prepare('DELETE FROM venues WHERE id = ?').run(id);
  }
});

test("Lighter pages: What's On ships its first page of events and every other item waits with its place in the list", async () => {
  const made = [];
  const regions = ['kelowna', 'penticton', 'vernon', 'oliver'];
  const cats = ['live-music', 'markets-fairs', 'arts-culture', 'family-kids'];
  const today = new Date();
  const pad = (x) => String(x).padStart(2, '0');
  const srv = lpHttp.createServer(app.server.listeners('request')[0]);
  await new Promise((resolve) => srv.listen(0, resolve));
  const base = `http://localhost:${srv.address().port}`;
  try {
    for (let i = 0; i < 130; i++) {
      const d = new Date(today.getTime() + (i % 20) * 86400000);
      const data = { name: `LP Fixture ${i} ${cats[i % 4]}`, region: regions[i % 4], description: 'A lighter-pages fixture event.', venue_name_text: `LP Hall ${i}`,
        source_type: 'official_venue', source_name: 'LP', source_url: `https://example.com/lp-${i}`, categories: [cats[i % 4]],
        occurrences: [{ start_date: `${d.getFullYear()}-${pad(d.getMonth() + 1)}-${pad(d.getDate())}`, start_time: '19:00', end_time: '21:00' }] };
      let r = app.createEvent(data, { reason: 'lighter pages fixture', batch_id: 'test-lp' });
      if (r && r.reason === 'possible_duplicate') r = app.createEvent(data, { reason: 'lighter pages fixture', batch_id: 'test-lp', reviewed_duplicates: r.detail.map((x) => x.event_id) });
      assert.ok(r && r.ok !== false, JSON.stringify(r));
    }
    made.push(...db.prepare("SELECT id FROM events WHERE name LIKE 'LP Fixture %'").all().map((x) => x.id));
    for (const [p, filter] of [['/whats-on', null], ['/whats-on?categories=live-music', { regions: [], categories: ['live-music'] }]]) {
      const page = app.renderWhatsOnPage(filter);
      const list = page.slice(page.indexOf('id="whatsOnResults"'), page.indexOf('</ul>', page.indexOf('id="whatsOnResults"')));
      const tpl = (page.match(/<template id="whatsOnRest">([\s\S]*?)<\/template>/) || [])[1];
      assert.ok(tpl, `${p}: later events wait in the template`);
      const items = (s) => [...s.matchAll(/<li class="(whatson-group-head|venue-card whatson-event-card)"([^>]*?)(?: data-wo-at="(\d+)")?>/g)].map((x) => ({ at: x[3] == null ? null : Number(x[3]), head: x[1] === 'whatson-group-head', hidden: /^\s*hidden/.test(x[2]), key: (x[2].match(/data-(?:venue-id|group)="([^"]+)"/) || [])[1] }));
      const first = items(list), rest = items(tpl);
      const shownFirst = first.filter((x) => !x.head);
      assert.ok(shownFirst.every((x) => !x.hidden), `${p}: only shown events in the HTML`);
      const shownAll = (page.match(/<li class="venue-card whatson-event-card" data-venue-id/g) || []).length;
      assert.equal(shownFirst.length, Math.min(app.WHATSON_PAGE_SIZE, shownAll), `${p}: one page of them`);
      assert.ok(rest.every((x) => x.at !== null && x.at >= 0 && x.at <= first.length), `${p}: every waiting item knows its place`);
      // Put the list back together the way the page does and check it is whole and in date-group order.
      const merged = [];
      let r = 0;
      for (let k = 0; k <= first.length; k++) {
        while (r < rest.length && rest[r].at === k) merged.push(rest[r++]);
        if (k < first.length) merged.push(first[k]);
      }
      assert.equal(merged.length, first.length + rest.length);
      const heads = merged.filter((x) => x.head).map((x) => x.key);
      assert.equal(new Set(heads).size, heads.length, `${p}: each heading once`);
      let group = null;
      for (const x of merged) { if (x.head) group = x.key; else assert.ok(group, 'every event sits under a heading'); }
      const cardGroups = merged.filter((x) => !x.head);
      const allCards = (page.match(/data-surface="whatson_card" data-group="/g) || []).length;
      assert.equal(cardGroups.length, allCards, `${p}: no event lost`);
      const html = await (await fetch(base + p)).text();
      assert.match(html, /<template id="whatsOnRest" data-rest="[0-9a-f]{12}"><\/template>/, `${p}: the response ships it empty`);
      assert.match(html, /\(window\.__whatsOnReady \|\| function\(fn\)\{ fn\(\); \}\)\(function\(\)\{\n  var LABELS/, 'the filter script waits for them');
    }
  } finally {
    srv.close();
    for (const id of made) {
      db.prepare('DELETE FROM event_enrichment_log WHERE event_id = ?').run(id);
      db.prepare('DELETE FROM event_categories WHERE event_id = ?').run(id);
      db.prepare('DELETE FROM event_occurrences WHERE event_id = ?').run(id);
      db.prepare('DELETE FROM events WHERE id = ?').run(id);
    }
  }
});


// ---- Crawlable links and Venue JSON (2026-10-18) ----
// The raw HTML a crawler (or a visitor without JavaScript) sees: no scripts, no templates.
const crawlLinks = (html) => new Set([...html.replace(/<script[\s\S]*?<\/script>|<template[\s\S]*?<\/template>/g, '').matchAll(/<a\b[^>]*\shref="([^"#?]+)/g)].map((m) => m[1]));

test('Lighter pages: crawlable links: every place and event waiting for "Show more" is linked from its hub without JavaScript, in English and French', async () => {
  const made = [], events = [];
  for (let i = 0; i < 120; i++) made.push(app.createVenue({ name: `CR Kitchen ${String(i).padStart(3, '0')}`, region: 'kelowna', type: 'restaurant', description: `A crawlable-links fixture kitchen number ${i}.`, slug: `cr-kitchen-${i}` }));
  const pad = (x) => String(x).padStart(2, '0'), today = new Date();
  const srv = lpHttp.createServer(app.server.listeners('request')[0]);
  await new Promise((resolve) => srv.listen(0, resolve));
  const base = `http://localhost:${srv.address().port}`;
  try {
    for (let i = 0; i < 110; i++) {
      const d = new Date(today.getTime() + (i % 20) * 86400000);
      const data = { name: `CR Fixture Show ${i}`, region: 'kelowna', description: 'A crawlable-links fixture event.', venue_name_text: `CR Hall ${i}`,
        source_type: 'official_venue', source_name: 'CR', source_url: `https://example.com/cr-${i}`, categories: ['live-music'],
        occurrences: [{ start_date: `${d.getFullYear()}-${pad(d.getMonth() + 1)}-${pad(d.getDate())}`, start_time: '19:00', end_time: '21:00' }] };
      let r = app.createEvent(data, { reason: 'crawlable links fixture', batch_id: 'test-cr' });
      if (r && r.reason === 'possible_duplicate') r = app.createEvent(data, { reason: 'crawlable links fixture', batch_id: 'test-cr', reviewed_duplicates: r.detail.map((x) => x.event_id) });
      assert.ok(r && r.ok !== false, JSON.stringify(r));
    }
    events.push(...db.prepare("SELECT id, slug, region FROM events WHERE name LIKE 'CR Fixture Show %'").all());
    // Every active place in the fixture set, from its town hub and the valley-wide ones.
    for (const [p, fr] of [['/kelowna/restaurants', false], ['/fr/kelowna/restaurants', true], ['/restaurants', false], ['/food-drink', false], ['/fr/food-drink', true]]) {
      const html = await (await fetch(base + p)).text();
      assert.match(html, /<template id="fdRest" data-rest="[0-9a-f]{12}"><\/template>/, `${p}: cards are deferred`);
      const links = crawlLinks(html);
      const missing = made.filter((v) => !links.has(`${fr ? '/fr' : ''}/kelowna/restaurants/${v.slug}`)).map((v) => v.slug);
      assert.deepEqual(missing, [], `${p}: every fixture place is linked in the raw HTML`);
      // A visible, closed <details> list right after the empty template: no hiding tricks.
      const list = html.match(/<template id="fdRest" data-rest="[0-9a-f]{12}"><\/template>\n  <style id="rest-links-css">[^<]*<\/style><details class="rest-links" id="fdRestLinks"><summary>([^<]*)<\/summary><ul>([\s\S]*?)<\/ul><\/details>/);
      assert.ok(list, `${p}: the A-Z list follows the template`);
      assert.match(list[1], fr ? /^Toutes les adresses de cette page, de A à Z \(\d+\)$/ : /^All places on this page, A–Z \(\d+\)$/);
      const names = [...list[2].matchAll(/<li><a href="[^"]+">([^<]*)<\/a>/g)].map((m) => m[1]);
      assert.deepEqual(names, names.slice().sort((a, b) => a.localeCompare(b, fr ? 'fr' : 'en', { sensitivity: 'base' })), `${p}: A to Z`);
      assert.doesNotMatch(list[0], /display:\s*none|hidden/, `${p}: nothing is hidden`);
      assert.ok(list[2].length / names.length < 100, `${p}: light (${Math.round(list[2].length / names.length)} bytes a link)`);
      if (fr) assert.ok(names.length && !/href="\/kelowna\//.test(list[2]), `${p}: French addresses`);
    }
    // Events: /whats-on keeps the soonest-first order.
    for (const p of ['/whats-on', '/fr/whats-on']) {
      const html = await (await fetch(base + p)).text();
      assert.match(html, /<template id="whatsOnRest" data-rest="[0-9a-f]{12}"><\/template>/, `${p}: events are deferred`);
      const links = crawlLinks(html);
      const missing = events.filter((e) => !links.has(`/${e.region}/events/${e.slug}`) && !links.has(`/fr/${e.region}/events/${e.slug}`)).map((e) => e.slug);
      assert.deepEqual(missing, [], `${p}: every upcoming fixture event is linked`);
      assert.match(html, p === '/whats-on' ? /<details class="rest-links" id="whatsOnRestLinks"><summary>More upcoming events \(\d+\)<\/summary>/ : /<details class="rest-links" id="whatsOnRestLinks"><summary>Autres événements à venir \(\d+\)<\/summary>/);
    }
    // A page whose cards all ship gets no list.
    assert.doesNotMatch(await (await fetch(base + '/kelowna')).text(), /class="rest-links"/);
  } finally {
    srv.close();
    for (const v of made) db.prepare('DELETE FROM venues WHERE id = ?').run(v.id);
    for (const e of events) {
      db.prepare('DELETE FROM event_enrichment_log WHERE event_id = ?').run(e.id);
      db.prepare('DELETE FROM event_categories WHERE event_id = ?').run(e.id);
      db.prepare('DELETE FROM event_occurrences WHERE event_id = ?').run(e.id);
      db.prepare('DELETE FROM events WHERE id = ?').run(e.id);
    }
  }
});

test('Lighter pages: venue JSON: /food-drink, /browse and their French twins load the filter data from a year-cached /cards/rest/<hash>.json that never 404s', async () => {
  const made = [];
  for (let i = 0; i < 90; i++) made.push(app.createVenue({ name: `VJ Kitchen ${i}`, region: ['kelowna', 'penticton'][i % 2], type: 'restaurant', description: `A venue-json fixture kitchen with a sunny lakeside patio number ${i}.`, slug: `vj-kitchen-${i}` }).id);
  db.prepare('UPDATE venues SET description_fr = ? WHERE id = ?').run('Une cuisine d’essai avec une terrasse ensoleillée au bord du lac.', made[0]);
  app.resetFrSearchWords();
  const srv = lpHttp.createServer(app.server.listeners('request')[0]);
  await new Promise((resolve) => srv.listen(0, resolve));
  const base = `http://localhost:${srv.address().port}`;
  try {
    for (const [p, id] of [['/food-drink', 'fdVenueData'], ['/fr/food-drink', 'fdVenueData'], ['/restaurants', 'fdVenueData'], ['/browse', 'bhVenueData'], ['/fr/browse', 'bhVenueData']]) {
      const html = await (await fetch(base + p)).text();
      const m = html.match(new RegExp(`<script type="application/json" id="${id}" data-rest="([0-9a-f]{12})"></script>`));
      assert.ok(m, `${p}: the data tag ships empty with its hash ${(html.match(new RegExp(`<script type="application/json" id="${id}"[^>]*>[^<]{0,40}`)) || [])[0]}`);
      assert.match(html, /fetch\('\/cards\/rest\/' \+ dataHash \+ '\.json\?u=' \+ /, `${p}: the page script loads it`);
      assert.match(html, /Promise\.all\(waits\)\.then\((?:fd|bh)Start\)/, `${p}: the filters start once it is in`);
      const hit = await fetch(`${base}/cards/rest/${m[1]}.json?u=${encodeURIComponent(p)}`);
      assert.equal(hit.status, 200);
      assert.match(hit.headers.get('content-type'), /application\/json/);
      assert.equal(hit.headers.get('cache-control'), 'public, max-age=31536000, immutable');
      const text = await hit.text();
      const data = JSON.parse(text);
      for (const v of made) assert.ok(data[String(v)], `${p}: ${v} has its filter data`);
      // After a restart the hash is unknown: the page is rendered again from ?u=, the same data.
      const miss = await fetch(`${base}/cards/rest/ffffffffffff.json?u=${encodeURIComponent(p)}`);
      assert.equal(miss.status, 200);
      assert.equal(miss.headers.get('cache-control'), 'no-store');
      assert.equal(await miss.text(), text, `${p}: a re-render gives the same data`);
      if (id === 'fdVenueData') {
        const fr = p.startsWith('/fr/');
        assert.match(data[String(made[0])].k, fr ? /terrasse/ : /lakeside/, `${p}: search words in the page's language`);
        if (fr) assert.doesNotMatch(data[String(made[0])].k, /lakeside|sunny/, 'French pages carry the French words only');
        if (fr) assert.match(data[String(made[1])].k, /lakeside/, 'a place without French keeps its English words');
        assert.ok(['c', 'f', 'r', 'o'].every((k) => k in data[String(made[1])]), `${p}: everything the filters need`);
      }
    }
    // Small data stays in the page (under 8 KB it is not worth a request).
    const small = app.withRestCardsDeferred(`<!DOCTYPE html><html lang="en"><body><script type="application/json" id="fdVenueData">{"1":{}}</script><script>'.json?u='</script></body></html>`);
    assert.match(small, /id="fdVenueData">\{"1":\{\}\}<\/script>/);
    // A page whose script cannot load it keeps it inline.
    const big = `{"1":{"k":"${'x'.repeat(9000)}"}}`;
    assert.ok(app.withRestCardsDeferred(`<!DOCTYPE html><html lang="en"><body><script type="application/json" id="fdVenueData">${big}</script></body></html>`).includes(big));
    assert.match(app.withRestCardsDeferred(`<!DOCTYPE html><html lang="en"><body><script type="application/json" id="fdVenueData">${big}</script><script>'.json?u='</script></body></html>`), /id="fdVenueData" data-rest="[0-9a-f]{12}"><\/script>/);
    // The same page minus the swap is the old page: the transformation is only the move.
    const raw = app.renderFoodDrinkHubPage(app.getFoodDrinkHubVenues(), { types: [], features: [], regions: [] });
    assert.match(raw, /<script type="application\/json" id="fdVenueData">\{/, 'renderers still write the data inline');
    // Never a 404 into the edge cache.
    for (const u of ['/admin/review', '//example.com/', '/kelowna']) {
      const r = await fetch(`${base}/cards/rest/ffffffffffff.json?u=${encodeURIComponent(u)}`);
      assert.equal(r.status, 200, u);
      assert.equal(r.headers.get('cache-control'), 'no-store', u);
      assert.equal(await r.text(), '{}', u);
    }
    const none = await fetch(`${base}/cards/rest/ffffffffffff.json`);
    assert.equal(none.status, 200);
    assert.equal(none.headers.get('cache-control'), 'no-store');
  } finally {
    srv.close();
    for (const id of made) db.prepare('DELETE FROM venues WHERE id = ?').run(id);
  }
});


