// ---- Instant owner edits, pending pre-fill, seasonal hours, closures, price range (2026-10-18) ----------
const PE_WEEK = JSON.stringify({ mon: [['09:00', '17:00']], tue: [['09:00', '17:00']], wed: [['09:00', '17:00']], thu: [['09:00', '17:00']], fri: [['09:00', '17:00']], sat: [['09:00', '17:00']], sun: [['09:00', '17:00']] });
async function withOwnerPortalServer(fn) {
  const http = require('node:http');
  const srv = http.createServer(app.server.listeners('request')[0]);
  await new Promise((resolve) => srv.listen(0, resolve));
  const base = `http://localhost:${srv.address().port}`;
  let ip = 1;
  const post = (p, body, cookie) => fetch(`${base}${p}`, { method: 'POST', redirect: 'manual',
    headers: { 'Content-Type': 'application/json', Origin: base, 'X-Real-IP': `10.77.0.${ip++ % 250}`, ...(cookie ? { Cookie: cookie } : {}) }, body: JSON.stringify(body) })
    .then(async (r) => ({ status: r.status, cookie: (r.headers.get('set-cookie') || '').split(';')[0], body: await r.json().catch(() => ({})) }));
  const get = (p, cookie) => fetch(`${base}${p}`, { redirect: 'manual', headers: cookie ? { Cookie: cookie } : {} }).then((r) => r.text());
  try { return await fn({ base, post, get }); } finally {
    srv.closeAllConnections();
    await new Promise((resolve) => srv.close(resolve));
  }
}

test('Instant owner edits (2026-10-18): signed-in hours, phone, description, badges and price go live with an audit row; name and website wait; link edits wait', () => withOwnerPortalServer(async ({ post, get }) => {
  seasonInsert.run({ name: 'Instant Edit Fixture', type: 'restaurant', hours: PE_WEEK, slug: 'instant-edit-fixture' });
  const v = app.findVenueBySlug('kelowna', 'restaurant', 'instant-edit-fixture');
  const token = app.createOwnerLink(v.id, {}).url.split('/owner/')[1];
  const made = await post(`/owner/${token}/account`, { email: 'instant@example.com', password: 'a long enough password' });
  assert.equal(made.status, 201);
  const cookie = made.cookie;
  const page = await get(`/owner/account/venue/${v.id}`, cookie);
  assert.match(page, /go live on <a href="[^"]+">your page<\/a> straight away/);
  assert.match(page, /id="opSubmit">Save changes</);
  assert.match(page, /\$\$ &mdash; \$15–30 per person/, 'price range selector with its scale');
  // Portal polish (2026-10-18): the scale shows once, in the choices; the hint no longer repeats it.
  const priceSec = page.slice(page.indexOf('id="price"'), page.indexOf('</details>', page.indexOf('id="price"')));
  assert.equal((priceSec.match(/\$15(?:–|&ndash;)30/g) || []).length, 1, 'the price scale shows once');
  assert.match(page, /id="opPriceScale">Pick what one person usually spends on a visit\.</);
  const week = (w) => ({ mon: [w], tue: [w], wed: [w], thu: [w], fri: [w], sat: [], sun: [] });
  const r = await post(`/owner/account/venue/${v.id}/changes`, { changes: {
    phone: '250-555-0181', description: 'A cosy fixture restaurant with a wood oven, a patio and a short local wine list.',
    hours: week(['11:00', '21:00']), price_range: '2', badges: { patio: true }, name: 'Instant Edit Fixture Bistro', website: 'instantfixture.example',
  }, contact_name: 'Pat', started_at: Date.now() - 10000 }, cookie);
  assert.equal(r.status, 201, JSON.stringify(r.body));
  assert.deepEqual(r.body.live.sort(), ['badges', 'description', 'hours', 'phone', 'price_range']);
  assert.deepEqual(r.body.review.sort(), ['name', 'website']);
  const row = db.prepare('SELECT * FROM venues WHERE id = ?').get(v.id);
  assert.equal(row.phone, '250-555-0181');
  assert.equal(row.price, 2);
  assert.equal(row.patio, 1);
  assert.equal(row.name, 'Instant Edit Fixture', 'the name waits for review');
  assert.equal(row.hours_source, 'venue_owner');
  assert.equal(row.hours_checked_at, app.todayLocal());
  assert.equal(JSON.parse(row.hours).sat, null);
  // The audit row: instant, approved by the login, with what it replaced.
  const audit = app.recentInstantOwnerChanges().find((x) => x.venue_id === v.id);
  assert.equal(audit.reviewed_by, 'owner:instant@example.com');
  assert.equal(audit.previous.phone, '');
  assert.equal(audit.changes.phone, '250-555-0181');
  assert.equal(audit.previous.price_range, '');
  assert.equal(JSON.parse(audit.undo_meta).hours_source, null);
  const logged = db.prepare("SELECT field_name, old_value, new_value FROM venue_enrichment_log WHERE venue_id = ? AND source = 'venue_owner' AND reviewed_by = 'owner:instant@example.com'").all(v.id);
  assert.ok(logged.some((l) => l.field_name === 'phone' && l.new_value === '250-555-0181'));
  assert.ok(logged.some((l) => l.field_name === 'price' && l.new_value === '2'));
  const waiting = app.getOwnerChange(app.pendingOwnerChange(v.id).id);
  assert.deepEqual(Object.keys(waiting.changes).sort(), ['name', 'website']);
  // The venue page shows "Hours checked" and the new price; the review page lists the live change with Undo.
  const vp = app.renderVenuePage(app.findVenueBySlug('kelowna', 'restaurant', 'instant-edit-fixture'), [], [], []);
  assert.match(vp, /Hours checked/);
  const review = app.renderAdminReviewPage();
  assert.match(review, /Changes owners made live \(last 14 days\)/);
  assert.match(review, new RegExp(`data-kind="change" data-id="${audit.id}"[\\s\\S]*?data-act="undo">Undo<`));
  // Still-pending fields pre-fill the form, marked as waiting.
  const again = await get(`/owner/account/venue/${v.id}`, cookie);
  assert.match(again, /id="opBizName" maxlength="100" value="Instant Edit Fixture Bistro"/);
  assert.match(again, /Business name <span class="op-status op-status-wait op-wait-chip">Waiting for review<\/span>/);
  assert.match(again, /<option value="2" selected>/);
  // Safety checks stay: HTML is refused, a bad price is refused.
  const bad = await post(`/owner/account/venue/${v.id}/changes`, { changes: { description: 'Our <b>great</b> place with a patio and the best views in town.', price_range: '7' }, started_at: Date.now() - 10000 }, cookie);
  assert.equal(bad.status, 400);
  assert.match(bad.body.errors.description, /< and >/);
  assert.match(bad.body.errors.price_range, /price range/);
  // Undo puts the old values back (hours with their old provenance); a second Undo is refused.
  const u = app.undoOwnerInstantChange(audit.id, 'dayton');
  assert.equal(u.ok, true, JSON.stringify(u));
  const back = db.prepare('SELECT * FROM venues WHERE id = ?').get(v.id);
  assert.equal(back.phone, null);
  assert.equal(back.price, null);
  assert.equal(back.patio, 0);
  assert.equal(back.hours, PE_WEEK);
  assert.equal(back.hours_source, null);
  assert.equal(app.undoOwnerInstantChange(audit.id, 'dayton').reason, 'already_undone');
  assert.match(app.renderAdminReviewPage(), /Undone /);
  // A bare edit link (not signed in) still waits for review, for every field.
  const viaLink = await post(`/owner/${token}/changes`, { changes: { phone: '250-555-0199' }, started_at: Date.now() - 10000 });
  assert.equal(viaLink.status, 201);
  assert.deepEqual(viaLink.body.live, []);
  assert.deepEqual(viaLink.body.review, ['phone']);
  assert.equal(db.prepare('SELECT phone FROM venues WHERE id = ?').get(v.id).phone, null);
  const linkPage = await get(`/owner/${token}`);
  assert.match(linkPage, /id="opPhone" maxlength="40" value="250-555-0199"/, 'the pending phone, not the live (empty) one');
  assert.match(linkPage, /Phone <span class="op-status op-status-wait op-wait-chip">Waiting for review<\/span>/);
  assert.match(linkPage, /nothing changes on your page until we&rsquo;ve checked it/);
  // Inline scripts on the edit pages and the review page parse (regexes in template literals keep their backslashes).
  const vm = require('node:vm');
  for (const html of [page, again, linkPage, app.renderAdminReviewPage()]) {
    for (const m of html.matchAll(/<script(\s[^>]*)?>([\s\S]*?)<\/script>/gi)) {
      if (/\bsrc=|application\/(ld\+)?json/i.test(m[1] || '') || !m[2].trim()) continue;
      assert.doesNotThrow(() => new vm.Script(m[2]), m[2].slice(0, 80));
    }
  }
  // Setting a waiting field back to the live value takes it out of the waiting request.
  const revert = await post(`/owner/${token}/changes`, { changes: { phone: '' }, started_at: Date.now() - 10000 });
  assert.equal(revert.status, 400, 'an empty phone is still refused');
  await post(`/owner/${token}/changes`, { changes: { phone: '250-555-0123' }, started_at: Date.now() - 10000 });
  assert.equal(app.getOwnerChange(app.pendingOwnerChange(v.id).id).changes.phone, '250-555-0123');
  const liveDesc = db.prepare('SELECT description FROM venues WHERE id = ?').get(v.id).description;
  await post(`/owner/${token}/changes`, { changes: { description: 'A brand new description for this fixture, long enough to pass.' }, started_at: Date.now() - 10000 });
  assert.deepEqual(Object.keys(app.getOwnerChange(app.pendingOwnerChange(v.id).id).changes).sort(), ['description', 'name', 'phone', 'website']);
  const back2 = await post(`/owner/${token}/changes`, { changes: { description: liveDesc }, started_at: Date.now() - 10000 });
  assert.equal(back2.status, 201, JSON.stringify(back2.body));
  assert.deepEqual(Object.keys(app.getOwnerChange(app.pendingOwnerChange(v.id).id).changes).sort(), ['name', 'phone', 'website'], 'set back to the live text: no longer waiting');
}));

test('Owner status chip (2026-10-18): counts waiting menus and event changes, never "Up to date" while one waits; a live menu shows as live', () => {
  seasonInsert.run({ name: 'Status Chip Fixture', type: 'restaurant', hours: PE_WEEK, slug: 'status-chip-fixture' });
  const v = app.findVenueBySlug('kelowna', 'restaurant', 'status-chip-fixture');
  assert.match(app.ownerVenueSummary(v.id), /Up to date/);
  const menu = Number(db.prepare("INSERT INTO venue_menus (venue_id, status, data) VALUES (?, 'pending', '{}')").run(v.id).lastInsertRowid);
  let chip = app.ownerVenueSummary(v.id);
  assert.match(chip, /Waiting for review: 1 menu/);
  assert.doesNotMatch(chip, /Up to date/);
  db.prepare("UPDATE venue_menus SET status = 'published', published_at = CURRENT_TIMESTAMP WHERE id = ?").run(menu);
  chip = app.ownerVenueSummary(v.id);
  assert.match(chip, /Menu live/);
  assert.doesNotMatch(chip, /Waiting for review/);
});

test('Seasonal hours and special closures (2026-10-18): hours.js applies them by date, on the server and in the browser', () => {
  const vm = require('node:vm');
  const hours = require('../hours.js');
  const raw = JSON.stringify({ ...JSON.parse(PE_WEEK), _seasons: [{ from: '11-01', to: '04-30', label: 'Winter hours', hours: { mon: [['10:00', '16:00']], tue: [['10:00', '16:00']], wed: [['10:00', '16:00']], thu: [['10:00', '16:00']], fri: [['10:00', '16:00']], sat: null, sun: null } }],
    _closures: [{ from: '2026-10-12', to: '2026-10-12', note: 'Thanksgiving' }, { from: '2026-12-25', to: '2026-12-26', note: '' }] });
  const label = (iso) => { const c = app.okanaganClock(new Date(iso)); return hours.hoursStatusLabel(hours.statusAt(hours.parseHours(raw), c), c).text; };
  assert.equal(app.okanaganClock(new Date('2026-10-12T19:00:00Z')).date, '2026-10-12');
  assert.equal(label('2026-10-12T19:00:00Z'), 'Closed today (Thanksgiving) · Opens tomorrow 9 AM');
  assert.equal(label('2026-10-13T19:00:00Z'), 'Open now · Closes 5 PM', 'the usual hours the next day');
  assert.equal(label('2026-12-25T19:00:00Z'), 'Closed today (holiday) · Opens Mon 10 AM', 'no note: holiday; the winter set after');
  assert.equal(label('2026-11-02T23:30:00Z'), 'Closed · Opens tomorrow 10 AM', 'winter hours: 4:30 PM is after the 4 PM close');
  assert.equal(label('2026-11-02T20:00:00Z'), 'Open now · Closes 4 PM');
  // Without a date (old callers), or without extras, nothing changes.
  assert.equal(hours.statusAt(hours.parseHours(raw), { weekday: 'mon', minutes: 720 }).state, 'open');
  assert.deepEqual(hours.parseHours(PE_WEEK), hours.parseHours(JSON.parse(PE_WEEK)));
  assert.equal(hours.parseHours(PE_WEEK).seasons, undefined);
  // The browser copy reads them the same way, with the page's own okanaganClock().
  const ctx = {};
  vm.runInNewContext(`var okanaganClockFormatter = new Intl.DateTimeFormat('en-US', ${JSON.stringify(app.OKANAGAN_CLOCK_FORMAT)}); ${app.okanaganClock.toString()}\n${hours.HOURS_CLIENT_SRC}
    this.at = function(iso, raw){ var c = okanaganClock(new Date(iso)); return hoursStatusLabel(statusAt(parseHours(raw), c), c).text; };`, ctx);
  for (const iso of ['2026-10-12T19:00:00Z', '2026-12-25T19:00:00Z', '2026-11-02T23:30:00Z', '2026-10-13T19:00:00Z']) assert.equal(ctx.at(iso, raw), label(iso), iso);
  // The French page script turns the closure label French.
  const fr = require('../french-text.js');
  assert.ok(fr);
  assert.equal(app.frStatusText('Closed today (holiday) · Opens tomorrow 9 AM'), 'Fermé aujourd’hui (jour férié) · ouvre demain à 9 h');
  assert.equal(app.frStatusText('Closed today (Thanksgiving) · Opens Mon 10 AM'), 'Fermé aujourd’hui (Thanksgiving) · ouvre lun. à 10 h');
});

test('Seasonal hours and closures (2026-10-18): owners set them; the venue page (EN and FR), cards, map and trip facts respect them', () => withOwnerPortalServer(async ({ post, get }) => {
  seasonInsert.run({ name: 'Season Set Fixture', type: 'restaurant', hours: PE_WEEK, slug: 'season-set-fixture' });
  const v = app.findVenueBySlug('kelowna', 'restaurant', 'season-set-fixture');
  const token = app.createOwnerLink(v.id, {}).url.split('/owner/')[1];
  const cookie = (await post(`/owner/${token}/account`, { email: 'seasons@example.com', password: 'a long enough password' })).cookie;
  const today = app.todayLocal();
  const winter = { mon: [['10:00', '16:00']], tue: [['10:00', '16:00']], wed: [['10:00', '16:00']], thu: [['10:00', '16:00']], fri: [['10:00', '16:00']], sat: [], sun: [] };
  // Checks: a past closure, a bad note and a one-day season are refused.
  let r = await post(`/owner/account/venue/${v.id}/changes`, { changes: { closures: [{ from: app.addLocalDays(today, -3), to: '', note: '' }] }, started_at: Date.now() - 10000 }, cookie);
  assert.match(r.body.errors.closures, /already over/);
  r = await post(`/owner/account/venue/${v.id}/changes`, { changes: { closures: [{ from: today, to: '', note: '<script>' }] }, started_at: Date.now() - 10000 }, cookie);
  assert.match(r.body.errors.closures, /without < > &/);
  r = await post(`/owner/account/venue/${v.id}/changes`, { changes: { hours_seasons: [{ from: '11-01', to: '11-01', label: '', hours: winter }] }, started_at: Date.now() - 10000 }, cookie);
  assert.match(r.body.errors.hours_seasons, /two different days/);
  r = await post(`/owner/account/venue/${v.id}/changes`, { changes: {
    hours_seasons: [{ from: '11-01', to: '04-30', label: 'Winter hours', hours: winter }],
    closures: [{ from: app.addLocalDays(today, 20), to: app.addLocalDays(today, 21), note: 'Renovations' }],
  }, started_at: Date.now() - 10000 }, cookie);
  assert.equal(r.status, 201, JSON.stringify(r.body));
  assert.deepEqual(r.body.live.sort(), ['closures', 'hours_seasons']);
  const x = app.venueHoursExtras(v.id);
  assert.equal(x.seasons[0].label, 'Winter hours');
  assert.equal(x.seasons[0].hours.sat, null);
  assert.equal(x.closures[0].note, 'Renovations');
  assert.equal(db.prepare('SELECT hours_checked_at FROM venues WHERE id = ?').get(v.id).hours_checked_at, today, 'counts as the owner checking the hours');
  // The edit page shows them again.
  const page = await get(`/owner/account/venue/${v.id}`, cookie);
  assert.match(page, /id="opSeasonalOn" checked/);
  assert.match(page, /id="opSeasonalLabel" maxlength="40" placeholder="Winter hours" value="Winter hours"/);
  assert.match(page, new RegExp(`class="op-cl-from" min="${today}" value="${app.addLocalDays(today, 20)}"`));
  // Fixed clock for the surfaces: Thanksgiving 2026 as a closure, put straight in the table.
  db.prepare('UPDATE venue_hours_extra SET closures = ? WHERE venue_id = ?').run(JSON.stringify([{ from: '2026-10-12', to: '2026-10-12', note: 'Thanksgiving' }]), v.id);
  app.clearHoursExtraCache();
  const now = new Date('2026-10-12T19:00:00Z');
  const fresh = app.findVenueBySlug('kelowna', 'restaurant', 'season-set-fixture');
  assert.ok(fresh.hours_live && fresh.hours_seasonal, 'the API venue carries them');
  assert.equal(fresh.special_closures, undefined, 'a closure already over (on the real clock) is left out');
  const en = app.renderVenuePage(fresh, [], [], [], { now });
  assert.match(en, /id="venueOpenStatus">Closed today \(Thanksgiving\) · Opens tomorrow 9 AM/);
  assert.match(en, /<li class="is-today" data-closed-date="1"><span>Monday<\/span><span>Closed \(Thanksgiving\)<\/span><\/li>/);
  assert.match(en, /<summary>Winter hours \(Nov 1 – Apr 30\)<\/summary>/);
  assert.match(en, /Special closures:<\/strong> Oct 12 \(Thanksgiving\)/);
  const frPage = app.renderVenuePage(fresh, [], [], [], { now, lang: 'fr' });
  assert.match(frPage, /Fermé aujourd’hui \(Thanksgiving\) · ouvre demain à 9 h/);
  assert.match(frPage, /<span>Fermé \(Thanksgiving\)<\/span>/);
  assert.match(frPage, /<summary>Heures saisonnières \(1er nov\. – 30 avr\.\)<\/summary>/);
  assert.match(frPage, /Fermetures spéciales:<\/strong>/);
  // In winter the seasonal set is the week shown, and the usual hours fold away.
  const nov = app.renderVenuePage(fresh, [], [], [], { now: new Date('2026-11-02T20:00:00Z') });
  assert.match(nov, /<li class="is-today"><span>Monday<\/span><span>10 AM – 4 PM<\/span><\/li>/);
  assert.match(nov, /<strong>Winter hours<\/strong> \(Nov 1 – Apr 30\) apply now\./);
  assert.match(nov, /id="venueOpenStatus">Open now · Closes 4 PM/);
  // Cards and the map (foodDrinkOpenNowInfo) carry them, so the live browser status applies them too.
  const info = app.foodDrinkOpenNowInfo([fresh], new Map(), now, { requireVerified: false }).byId.get(v.id);
  assert.equal(info.state, 'closed');
  assert.equal(info.text, 'Closed today (Thanksgiving) · Opens tomorrow 9 AM');
  assert.equal(info.hours._closures[0].note, 'Thanksgiving');
  // Build My Trip: the winter week in winter, and the closure as a dated closure.
  assert.equal(JSON.parse(app.weekJsonOn(fresh, '2026-12-01')).mon[0][0], '10:00');
  assert.equal(JSON.parse(app.weekJsonOn(fresh, '2026-07-01')).mon[0][0], '09:00');
  db.prepare('UPDATE venue_hours_extra SET closures = ? WHERE venue_id = ?').run(JSON.stringify([{ from: app.addLocalDays(today, 2), to: app.addLocalDays(today, 2), note: '' }]), v.id);
  app.clearHoursExtraCache();
  const fact = app.buildTripPlannerFacts(false).find((f) => f.id === v.id);
  assert.deepEqual(fact.ownerClosures, [{ from: app.addLocalDays(today, 2), to: app.addLocalDays(today, 2) }]);
}));
// ---------- Owner portal phone pass and access (2026-10-18) ----------
function ownerUiServer() {
  const http = require('node:http');
  const srv = http.createServer(app.server.listeners('request')[0]);
  return new Promise((resolve) => srv.listen(0, () => {
    const base = `http://localhost:${srv.address().port}`;
    let ip = 1;
    const post = (p, body, cookie) => fetch(`${base}${p}`, { method: 'POST',
      headers: { 'Content-Type': 'application/json', Origin: base, 'X-Real-IP': `10.66.${Math.floor(ip / 250)}.${(ip++ % 250) + 1}`, ...(cookie ? { Cookie: cookie } : {}) }, body: JSON.stringify(body) })
      .then(async (r) => ({ status: r.status, cookie: (r.headers.get('set-cookie') || '').split(';')[0], body: await r.json().catch(() => ({})) }));
    const get = (p, cookie) => fetch(`${base}${p}`, { redirect: 'manual', headers: cookie ? { Cookie: cookie } : {} });
    resolve({ srv, base, post, get, close: () => new Promise((r) => srv.close(r)) });
  }));
}
function ownerUiInlineScripts(html) {
  return [...html.matchAll(/<script(\s[^>]*)?>([\s\S]*?)<\/script>/g)].filter((m) => !/type="application\/(ld\+)?json"/.test(m[1] || '')).map((m) => m[2]);
}

test('Owner portal phone pass (2026-10-18): checkboxes never shrink, 16px/44px fields, folding sections, section bar, footer, contrast', async () => {
  const vm = require('node:vm');
  seasonInsert.run({ name: 'Phone Pass Fixture', type: 'cafe', hours: SEASON_WEEK, slug: 'phone-pass-fixture' });
  const v = app.findVenueBySlug('kelowna', 'cafe', 'phone-pass-fixture');
  const token = app.createOwnerLink(v.id, {}).url.split('/owner/')[1];
  const s = await ownerUiServer();
  try {
    const html = await (await s.get(`/owner/${token}`)).text();
    // The rights box sits in a flex label; the shared rule stops it shrinking to a sliver.
    assert.match(html, /<label class="op-closed"[^>]*><input type="checkbox" id="ofRights"/);
    assert.match(html, /body\.owner-page input\[type=checkbox\], body\.owner-page input\[type=radio\] \{ flex: 0 0 auto; width: 22px; height: 22px; min-width: 22px;/);
    assert.match(html, /body\.owner-page \.op-times input, body\.owner-page \.op-season select \{ font-size: 16px; \}/);
    assert.match(html, /\.op-times input, body\.owner-page \.op-season select \{ min-height: 44px; \}/);
    assert.match(html, /\.op-btn \{ display: inline-flex; align-items: center; justify-content: center; min-height: 40px;/);
    // Closed days hide their times instead of fading them (no 1.94 contrast), and hints are darker.
    assert.match(html, /\.op-day\.is-off \.op-times \{ display: none; \}/);
    assert.doesNotMatch(html, /\.op-day\.is-off \.op-times \{ opacity/);
    assert.doesNotMatch(html, /\.op-hint \{[^}]*rgba\(42,32,25,0\.62\)/);
    assert.match(html, /\.op-act-date \{ font-size: 0\.8rem; color: rgba\(42,32,25,0\.8\); \}/);
    // Hours and Photos open; Badges, Events folded; one section bar.
    assert.match(html, /<details class="op-fold op-sec" id="hours" open>/);
    assert.match(html, /<details class="op-fold op-sec" id="photos" open>/);
    assert.match(html, /<details class="op-fold op-sec" id="badges">/);
    assert.match(html, /<details class="op-fold op-sec" id="events">[\s\S]*id="oeHead">Add an event</);
    assert.match(html, /<nav class="op-secnav" id="opSecNav" aria-label="Parts of this page"><a href="#hours">Hours<\/a><a href="#photos">Photos<\/a><a href="#opMenuCard">Menu<\/a><a href="#events">Events<\/a><\/nav>/);
    assert.match(html, /id="opMenuCard"/);
    assert.match(html, /position: sticky; top: 0; z-index: 30;/);
    // Footer with privacy, terms and info@ on the edit page and the simple pages.
    for (const page of [html, await (await s.get('/owner/login')).text(), await (await s.get('/owner/forgot')).text()]) {
      assert.match(page, /<footer class="op-footer"><a href="\/privacy">Privacy<\/a> &middot; <a href="\/terms">Terms<\/a> &middot; <a href="mailto:info@okanaganroam.com">/);
    }
    assert.match(await (await s.get('/fr/owner/login')).text(), /<footer class="op-footer"><a href="\/fr\/privacy">Confidentialité<\/a>/);
    for (const code of ownerUiInlineScripts(html)) assert.doesNotThrow(() => new vm.Script(code), code.slice(0, 80));
  } finally { await s.close(); }
});

test('Owner portal photos (2026-10-18): the grid refreshes in place and owners move photos earlier or later; the order sticks', async () => {
  const nodeFs = require('node:fs');
  const nodePath = require('node:path');
  seasonInsert.run({ name: 'Photo Order Fixture', type: 'cafe', hours: SEASON_WEEK, slug: 'photo-order-fixture' });
  const v = app.findVenueBySlug('kelowna', 'cafe', 'photo-order-fixture');
  const token = app.createOwnerLink(v.id, {}).url.split('/owner/')[1];
  const jpeg = Buffer.concat([Buffer.from([0xFF, 0xD8, 0xFF, 0xC0, 0x00, 0x11, 0x08, 900 >> 8, 900 & 255, 1200 >> 8, 1200 & 255, 0x03, 1, 0x22, 0, 2, 0x11, 1, 3, 0x11, 1]), Buffer.alloc(64), Buffer.from([0xFF, 0xD9])]);
  const photo = { image: `data:image/jpeg;base64,${jpeg.toString('base64')}`, credit: 'Order Cafe', rights: true, notify: false, company_website: '', started_at: Date.now() - 10000 };
  const s = await ownerUiServer();
  const files = [];
  try {
    const me = await s.post(`/owner/${token}/account`, { email: 'order@example.com', password: 'a long enough password' });
    const ids = [];
    for (let i = 0; i < 4; i++) {
      const r = await s.post(`/owner/account/venue/${v.id}/photos`, photo, me.cookie);
      assert.equal(r.status, 201, JSON.stringify(r.body));
      ids.push(r.body.id);
      files.push(db.prepare('SELECT file FROM owner_photos WHERE id = ?').get(r.body.id).file);
    }
    const [main, a, b, c] = ids; // the first became the main photo
    const gridOrder = async () => [...(await (await s.get(`/owner/account/venue/${v.id}`, me.cookie)).text()).matchAll(/<button type="button" class="op-btn op-btn-danger op-remove" data-photo="(\d+)"/g)].map((m) => Number(m[1]));
    assert.deepEqual(await gridOrder(), [main, a, b, c], 'main first, then oldest first');
    const page = await (await s.get(`/owner/account/venue/${v.id}`, me.cookie)).text();
    assert.match(page, /<div id="opPhotoBox"><div class="op-photos" id="opPhotoGrid">/, 'one box the page swaps after an upload');
    assert.match(page, new RegExp(`data-photo="${a}" data-move="up" aria-label="Move photo 1 of 3 earlier" disabled>`));
    assert.match(page, new RegExp(`data-photo="${c}" data-move="down" aria-label="Move photo 3 of 3 later" disabled>`));
    assert.match(page, /refreshPhotos\(\); \}/, 'the upload refreshes the grid');
    assert.doesNotMatch(page, /if \(j && j\.ok\) \{ location\.reload\(\); return; \}/, 'photo buttons no longer reload the page');

    const down = await s.post(`/owner/account/venue/${v.id}/photos/${a}/down`, {}, me.cookie);
    assert.equal(down.status, 200, JSON.stringify(down.body));
    assert.deepEqual(down.body.order, [b, a, c]);
    assert.equal(down.body.position, 2);
    assert.deepEqual((await s.post(`/owner/account/venue/${v.id}/photos/${c}/up`, {}, me.cookie)).body.order, [b, c, a]);
    assert.equal((await s.post(`/owner/account/venue/${v.id}/photos/${b}/up`, {}, me.cookie)).body.moved, false, 'already first');
    assert.equal((await s.post(`/owner/account/venue/${v.id}/photos/${main}/up`, {}, me.cookie)).status, 409, 'the main photo stays first');
    assert.equal((await s.post(`/owner/account/venue/${v.id}/photos/${a}/up`, {})).status, 401, 'signed out');
    assert.deepEqual(db.prepare('SELECT id, sort_order FROM owner_photos WHERE venue_id = ? ORDER BY sort_order').all(v.id).filter((r) => r.sort_order != null).map((r) => r.id), [b, c, a], 'stored');
    assert.deepEqual(await gridOrder(), [main, b, c, a]);
    // The public gallery uses the same order after the main photo.
    const gallery = app.venueGalleryPhotos(app.findVenueBySlug('kelowna', 'cafe', 'photo-order-fixture'));
    const byFile = Object.fromEntries(db.prepare('SELECT id, file FROM owner_photos WHERE venue_id = ?').all(v.id).map((r) => [`/images/owner/${r.file}`, r.id]));
    assert.deepEqual(gallery.map((g) => byFile[g.src.split('?')[0]]).filter(Boolean), [main, b, c, a]);
    // A new upload goes after the ordered ones.
    const e = await s.post(`/owner/account/venue/${v.id}/photos`, photo, me.cookie);
    files.push(db.prepare('SELECT file FROM owner_photos WHERE id = ?').get(e.body.id).file);
    assert.deepEqual(await gridOrder(), [main, b, c, a, e.body.id]);
  } finally {
    for (const f of files) { try { nodeFs.unlinkSync(nodePath.join(app.OWNER_PHOTO_DIR, f)); } catch (err) { /* gone */ } }
    await s.close();
  }
});

test('Owner portal access (2026-10-18): People with access lists logins, emails them about a new login, and only older logins can remove newer ones', async () => {
  seasonInsert.run({ name: 'Access Fixture', type: 'cafe', hours: SEASON_WEEK, slug: 'access-fixture' });
  const v = app.findVenueBySlug('kelowna', 'cafe', 'access-fixture');
  const token = app.createOwnerLink(v.id, {}).url.split('/owner/')[1];
  const s = await ownerUiServer();
  const mail = [];
  const dayton = [];
  app.setOwnerEmailTransport(async (m) => { mail.push(m); });
  app.setVenueSubmissionTransport(async (p) => { dayton.push(p); });
  try {
    const owner = await s.post(`/owner/${token}/account`, { email: 'first.owner@example.com', password: 'first owner password' });
    assert.equal(owner.status, 201);
    assert.equal(mail.length, 0, 'nobody else to tell');
    const staff = await s.post(`/owner/${token}/account`, { email: 'newstaff@example.com', password: 'staff member password' });
    assert.equal(staff.status, 201);
    assert.deepEqual(mail.map((m) => m.to), ['first.owner@example.com'], 'the existing login is told about the new one');
    assert.equal(mail[0].subject, 'New login added to Access Fixture on Okanagan Roam');
    assert.match(mail[0].text, /newstaff@example\.com now has a login/);
    assert.match(mail[0].text, new RegExp(`/owner/account/venue/${v.id}#access`));
    // Signing in again on the same listing is not a new login.
    await s.post(`/owner/${token}/account`, { email: 'newstaff@example.com', password: 'staff member password' });
    assert.equal(mail.length, 1);

    const ownerPage = await (await s.get(`/owner/account/venue/${v.id}`, owner.cookie)).text();
    assert.match(ownerPage, /<details class="op-fold" id="access">[\s\S]*2 logins can update this listing/);
    assert.match(ownerPage, /<strong>first\.owner@example\.com<\/strong> \(you\)/);
    // Full emails (2026-10-18): everyone on the panel has access to the same listing, so two staff never look alike.
    assert.match(ownerPage, /<strong>newstaff@example\.com<\/strong>/, 'colleagues see full emails');
    assert.doesNotMatch(ownerPage, /•••@/);
    assert.match(ownerPage, /<span class="op-fold-hint" id="opAccessCount">2 logins can update this listing<\/span>/);
    assert.match(ownerPage, /id="opResetLink">Reset edit link<\/button>/, 'the first login can reset the link');
    const staffId = db.prepare('SELECT id FROM owner_accounts WHERE email = ?').get('newstaff@example.com').id;
    const ownerId = db.prepare('SELECT id FROM owner_accounts WHERE email = ?').get('first.owner@example.com').id;
    assert.match(ownerPage, new RegExp(`data-login-remove="${staffId}"`), 'the owner can remove the newer login');
    const staffPage = await (await s.get(`/owner/account/venue/${v.id}`, staff.cookie)).text();
    assert.match(staffPage, /first\.owner@example\.com<\/strong><\/span><span class="op-act-date">Added [^<]*&middot; added before you/);
    assert.doesNotMatch(staffPage, /id="opResetLink"/, 'a newer login has no Reset button');
    assert.doesNotMatch(staffPage, new RegExp(`data-login-remove="${ownerId}"`), 'no Remove button for an older login');
    assert.match(await (await s.get('/owner/account', owner.cookie)).text(), new RegExp(`href="/owner/account/venue/${v.id}#access" class="op-hint">2 people have access`));

    // The rule: the newer login can't remove the original owner.
    const blocked = await s.post(`/owner/account/venue/${v.id}/logins/${ownerId}/remove`, {}, staff.cookie);
    assert.equal(blocked.status, 403);
    assert.match(blocked.body.error, /added before you/);
    assert.equal(app.ownerLoginsForVenue(v.id).length, 2);
    assert.equal((await s.post(`/owner/account/venue/${v.id}/logins/${staffId}/remove`, {})).status, 401, 'signed out');
    assert.equal((await s.post(`/owner/account/venue/${v.id}/logins/999999/remove`, {}, owner.cookie)).status, 404);

    // The owner removes the newer login: they lose access at once, and they and Dayton are told.
    mail.length = 0;
    const removed = await s.post(`/owner/account/venue/${v.id}/logins/${staffId}/remove`, {}, owner.cookie);
    assert.equal(removed.status, 200, JSON.stringify(removed.body));
    assert.equal(removed.body.logins, 1, 'the new count, for the panel header');
    assert.equal(removed.body.link_reset, true);
    assert.equal(removed.body.emailed, 'sent');
    assert.deepEqual(app.ownerLoginsForVenue(v.id).map((l) => l.email), ['first.owner@example.com']);
    assert.equal((await s.get(`/owner/account/venue/${v.id}`, staff.cookie)).status, 404);
    assert.deepEqual(mail.map((m) => m.to).sort(), ['first.owner@example.com', 'newstaff@example.com']);
    const gone = mail.find((m) => m.to === 'newstaff@example.com');
    assert.match(gone.subject, /Your access to Access Fixture on Okanagan Roam was removed/);
    assert.match(gone.text, /edit link was reset at the same time, so the old link no longer works/);
    const fyi = dayton[dayton.length - 1];
    assert.match(fyi._subject, /Login removed from Access Fixture/);
    assert.equal(fyi['Removed'], 'newstaff@example.com');
    assert.equal(fyi['Removed by'], 'first.owner@example.com');
    assert.match(fyi['Edit link'], /^Reset: the old link stopped working at once\. The new one was emailed to first\.owner@example\.com\./);
    assert.doesNotMatch(fyi['To undo'], /opens the listing’s private edit link/);
    // Rotate on Remove (2026-10-18): the old link is dead at once (no grace), so the removed person can't re-add themselves.
    assert.equal((await s.get(`/owner/${token}`)).status, 404, 'old link page');
    const rejoin = await s.post(`/owner/${token}/account`, { email: 'newstaff@example.com', password: 'staff member password' });
    assert.equal(rejoin.status, 404, 'old link can\'t add a login');
    assert.equal(app.ownerLoginsForVenue(v.id).length, 1);
    const linkMail = mail.find((m) => m.to === 'first.owner@example.com');
    assert.equal(linkMail.subject, 'New edit link for Access Fixture');
    const newToken = /\/owner\/([A-Za-z0-9_-]{32})\b/.exec(linkMail.text)[1];
    assert.notEqual(newToken, token);
    assert.equal((await s.get(`/owner/${newToken}`)).status, 200, 'the new link works');
    assert.equal(db.prepare('SELECT contact_email FROM venue_owner_links WHERE venue_id = ?').get(v.id).contact_email, 'first.owner@example.com', '"Email me a new link" now goes to the remover');
    // The page script refreshes the header count and says the link was reset.
    assert.match(ownerPage, /cnt\.textContent = n <= 1 \? T\.onlyYou : T\.nLogins\.replace\('\{n\}', n\)/);
    assert.match(ownerPage, /"onlyYou":"Only you can update this listing","nLogins":"\{n\} logins can update this listing"/);
    const after = await (await s.get(`/owner/account/venue/${v.id}`, owner.cookie)).text();
    assert.match(after, /id="opAccessCount">Only you can update this listing</);
    // Add to my login with the new link still works (the owner sends it to the staff member again).
    const readd = await s.post(`/owner/${newToken}/account`, { add: true }, staff.cookie);
    assert.equal(readd.status, 201, JSON.stringify(readd.body));
    assert.equal(app.ownerLoginsForVenue(v.id).length, 2);
    const again2 = await s.post(`/owner/account/venue/${v.id}/logins/${staffId}/remove`, {}, owner.cookie);
    assert.equal(again2.status, 200);
    assert.equal((await s.get(`/owner/${newToken}`)).status, 404, 'each Remove resets the link again');

    // Removing yourself keeps working (settings unlink and the panel's Remove me use the same route).
    assert.equal((await s.post(`/owner/account/venue/${v.id}/unlink`, {}, owner.cookie)).status, 200);
    assert.equal(app.ownerLoginsForVenue(v.id).length, 0);
    const settings = await (await s.get('/owner/account/settings', owner.cookie)).text();
    assert.match(settings, /<p class="op-done" id="osNoVenues">No businesses are on this login now\./, 'the empty settings page says so');
  } finally {
    app.setOwnerEmailTransport(null);
    app.setVenueSubmissionTransport(async (payload) => { lyvSent.push(payload); });
    await s.close();
  }
});

test('Pending link changes (2026-10-18): creating a login or adding the listing publishes waiting hours and phone with an audit row and Undo; name and website stay waiting; banner wording', () => withOwnerPortalServer(async ({ post, get }) => {
  seasonInsert.run({ name: 'Pending Carry Fixture', type: 'restaurant', hours: PE_WEEK, slug: 'pending-carry-fixture' });
  const v = app.findVenueBySlug('kelowna', 'restaurant', 'pending-carry-fixture');
  const token = app.createOwnerLink(v.id, {}).url.split('/owner/')[1];
  const week = (w) => ({ mon: [w], tue: [w], wed: [w], thu: [w], fri: [w], sat: [], sun: [] });
  // Sent from the edit link: everything waits for review.
  const sent = await post(`/owner/${token}/changes`, { changes: { phone: '250-555-0171', hours: week(['10:00', '18:00']), badges: { patio: true },
    name: 'Pending Carry Fixture Bistro', website: 'pendingcarry.example' }, contact_name: 'Sam', contact_email: 'sam@pendingcarry.example', started_at: Date.now() - 10000 });
  assert.equal(sent.status, 201, JSON.stringify(sent.body));
  assert.deepEqual(sent.body.live, []);
  const linkPage = await get(`/owner/${token}`);
  assert.match(linkPage, /Anything else you send now is added to them\./, 'signed out, the old line stays');
  // Creating a login from the link publishes the instant-eligible ones.
  const made = await post(`/owner/${token}/account`, { email: 'sam@pendingcarry.example', password: 'a long enough password' });
  assert.equal(made.status, 201, JSON.stringify(made.body));
  assert.deepEqual(made.body.published.sort(), ['badges', 'hours', 'phone']);
  const row = db.prepare('SELECT * FROM venues WHERE id = ?').get(v.id);
  assert.equal(row.phone, '250-555-0171');
  assert.equal(row.patio, 1);
  assert.equal(JSON.parse(row.hours).mon[0][0], '10:00');
  assert.equal(row.hours_source, 'venue_owner');
  assert.equal(row.name, 'Pending Carry Fixture', 'the name still waits');
  const waiting = app.getOwnerChange(app.pendingOwnerChange(v.id).id);
  assert.deepEqual(Object.keys(waiting.changes).sort(), ['name', 'website'], 'reviewed fields stay pending');
  assert.equal(waiting.id, sent.body.id, 'the same request, so the email Dayton already has still matches');
  // The audit row: instant, approved by the login, with Undo on /admin/review.
  const audit = app.recentInstantOwnerChanges().find((x) => x.venue_id === v.id);
  assert.equal(audit.reviewed_by, 'owner:sam@pendingcarry.example');
  assert.equal(audit.contact_email, 'sam@pendingcarry.example');
  assert.equal(audit.changes.phone, '250-555-0171');
  assert.equal(audit.previous.phone, '');
  assert.equal(JSON.parse(audit.undo_meta).from_request, sent.body.id);
  assert.match(app.renderAdminReviewPage(), new RegExp(`data-kind="change" data-id="${audit.id}"[\\s\\S]*?data-act="undo">Undo<`));
  // Signed in, the banner no longer says "added to them".
  const page = await get(`/owner/account/venue/${v.id}`, made.cookie);
  assert.doesNotMatch(page, /Anything else you send now is added to them/);
  assert.match(page, /<p class="op-pending">You sent changes on [^.]+\. A new name, address, website or link is checked by us first, usually within a day; it shows below, marked &ldquo;Waiting for review&rdquo;, until then\.<\/p>/);
  assert.doesNotMatch(page, /Phone <span class="op-status op-status-wait op-wait-chip">/, 'the phone is live, not waiting');
  // Undo puts the old values back.
  const u = app.undoOwnerInstantChange(audit.id, 'dayton');
  assert.equal(u.ok, true, JSON.stringify(u));
  assert.equal(db.prepare('SELECT phone FROM venues WHERE id = ?').get(v.id).phone, null);
  assert.equal(db.prepare('SELECT hours FROM venues WHERE id = ?').get(v.id).hours, PE_WEEK);

  // Add to my login (already signed in elsewhere) publishes too.
  seasonInsert.run({ name: 'Pending Add Fixture', type: 'cafe', hours: PE_WEEK, slug: 'pending-add-fixture' });
  const w = app.findVenueBySlug('kelowna', 'cafe', 'pending-add-fixture');
  const tokenW = app.createOwnerLink(w.id, {}).url.split('/owner/')[1];
  await post(`/owner/${tokenW}/changes`, { changes: { description: 'A pending description that is long enough to be accepted by the form.', address: '123 Pending Rd, Kelowna' }, started_at: Date.now() - 10000 });
  const added = await post(`/owner/${tokenW}/account`, { add: true }, made.cookie);
  assert.equal(added.status, 201, JSON.stringify(added.body));
  assert.deepEqual(added.body.published, ['description']);
  assert.equal(db.prepare('SELECT description FROM venues WHERE id = ?').get(w.id).description, 'A pending description that is long enough to be accepted by the form.');
  assert.deepEqual(Object.keys(app.getOwnerChange(app.pendingOwnerChange(w.id).id).changes), ['address']);
  assert.equal(app.recentInstantOwnerChanges().find((x) => x.venue_id === w.id).reviewed_by, 'owner:sam@pendingcarry.example');

  // Link changes on a listing already on the login: opening it doesn't publish them (the waiting request can merge
  // several people's sends), the banner says Save will, and the next Save includes them though the form didn't send them.
  await post(`/owner/${tokenW}/changes`, { changes: { phone: '250-555-0172' }, contact_email: 'colleague@pendingcarry.example', started_at: Date.now() - 10000 });
  const wPage = await get(`/owner/account/venue/${w.id}`, made.cookie);
  assert.equal(db.prepare('SELECT phone FROM venues WHERE id = ?').get(w.id).phone, null, 'not published on opening');
  assert.match(wPage, /<p class="op-pending" id="opPendingCarry">You sent changes on [^.]+ from the edit link\. They show below, marked &ldquo;Waiting for review&rdquo;\. Tap <strong>Save changes<\/strong> to put the phone live now\./);
  const saved = await post(`/owner/account/venue/${w.id}/changes`, { changes: { badges: { patio: true } }, started_at: Date.now() - 10000 }, made.cookie);
  assert.equal(saved.status, 201, JSON.stringify(saved.body));
  assert.deepEqual(saved.body.live.sort(), ['badges', 'phone']);
  assert.deepEqual(saved.body.carried, ['phone']);
  assert.equal(db.prepare('SELECT phone FROM venues WHERE id = ?').get(w.id).phone, '250-555-0172');
  assert.deepEqual(Object.keys(app.getOwnerChange(app.pendingOwnerChange(w.id).id).changes), ['address']);
  // A Save with nothing else changed still sends the waiting ones.
  await post(`/owner/${tokenW}/changes`, { changes: { phone: '250-555-0173' }, started_at: Date.now() - 10000 });
  const onlyCarry = await post(`/owner/account/venue/${w.id}/changes`, { changes: {}, started_at: Date.now() - 10000 }, made.cookie);
  assert.equal(onlyCarry.status, 201, JSON.stringify(onlyCarry.body));
  assert.deepEqual(onlyCarry.body.live, ['phone']);
  // French: the same line in French, and no "added to them".
  await post(`/owner/${tokenW}/changes`, { changes: { phone: '250-555-0175' }, contact_email: 'sam@pendingcarry.example', started_at: Date.now() - 10000 });
  const frPage = await get(`/fr/owner/account/venue/${w.id}`, made.cookie);
  assert.equal(db.prepare('SELECT phone FROM venues WHERE id = ?').get(w.id).phone, '250-555-0173', 'opening a listing never publishes');
  assert.match(frPage, /Touchez <strong>Enregistrer les modifications<\/strong> pour mettre en ligne maintenant : téléphone\./);
  assert.doesNotMatch(frPage, /Tout ce que vous envoyez maintenant s’y ajoute/);
  const frSigned = await get(`/fr/owner/account/venue/${v.id}`, made.cookie);
  assert.match(frSigned, /Un nouveau nom, une nouvelle adresse, un site Web ou un lien est d’abord vérifié par nous, en général d’ici un jour/);
  // Inline scripts on these pages parse.
  const vm = require('node:vm');
  for (const html of [page, wPage, frPage, frSigned]) {
    for (const m of html.matchAll(/<script(\s[^>]*)?>([\s\S]*?)<\/script>/gi)) {
      if (/\bsrc=|application\/(ld\+)?json/i.test(m[1] || '') || !m[2].trim()) continue;
      assert.doesNotThrow(() => new vm.Script(m[2]), m[2].slice(0, 80));
    }
  }
}));

test('Reset edit link (2026-10-18): the longest-standing login resets the link (EN and FR); the old link stops at once; claims still work after', async () => {
  seasonInsert.run({ name: 'Reset Link Fixture', type: 'cafe', hours: SEASON_WEEK, slug: 'reset-link-fixture' });
  const v = app.findVenueBySlug('kelowna', 'cafe', 'reset-link-fixture');
  const token = app.createOwnerLink(v.id, {}).url.split('/owner/')[1];
  const s = await ownerUiServer();
  const mail = [];
  const dayton = [];
  app.setOwnerEmailTransport(async (m) => { mail.push(m); });
  app.setVenueSubmissionTransport(async (p) => { dayton.push(p); });
  try {
    const owner = await s.post(`/owner/${token}/account`, { email: 'reset.owner@example.com', password: 'reset owner password' });
    const staff = await s.post(`/owner/${token}/account`, { email: 'reset.staff@example.com', password: 'reset staff password' });
    assert.equal(staff.status, 201);
    const page = await (await s.get(`/owner/account/venue/${v.id}`, owner.cookie)).text();
    assert.match(page, /"resetConfirm":"Reset this listing’s private edit link\? The old link stops working straight away/);
    assert.match(page, /fetch\(location\.pathname \+ '\/reset-link'/);
    for (const code of ownerUiInlineScripts(page)) assert.doesNotThrow(() => new (require('node:vm').Script)(code), code.slice(0, 80));
    // Only the first login can reset; signed out is refused.
    assert.equal((await s.post(`/owner/account/venue/${v.id}/reset-link`, {}, staff.cookie)).status, 403);
    assert.equal((await s.post(`/owner/account/venue/${v.id}/reset-link`, {})).status, 401);
    assert.equal((await s.get(`/owner/${token}`)).status, 200, 'refusals change nothing');
    mail.length = 0;
    const r = await s.post(`/owner/account/venue/${v.id}/reset-link`, {}, owner.cookie);
    assert.equal(r.status, 200, JSON.stringify(r.body));
    assert.equal(r.body.emailed, 'sent');
    assert.equal((await s.get(`/owner/${token}`)).status, 404, 'the old link stops at once');
    assert.equal((await s.post(`/owner/${token}/changes`, { changes: { phone: '250-555-0100' }, started_at: Date.now() - 10000 })).status, 404);
    assert.deepEqual(mail.map((m) => m.to), ['reset.owner@example.com']);
    assert.match(mail[0].text, /You reset the private edit link for Reset Link Fixture/);
    const newToken = /\/owner\/([A-Za-z0-9_-]{32})\b/.exec(mail[0].text)[1];
    assert.equal((await s.get(`/owner/${newToken}`)).status, 200);
    assert.match(dayton[dayton.length - 1]._subject, /\[FYI\] Edit link reset for Reset Link Fixture/);
    // Both logins keep their access.
    assert.equal((await s.get(`/owner/account/venue/${v.id}`, staff.cookie)).status, 200);
    // French: the button, the confirm text and the emailed link are French.
    const fr = await (await s.get(`/fr/owner/account/venue/${v.id}`, owner.cookie)).text();
    assert.match(fr, /id="opResetLink">Réinitialiser le lien de modification<\/button>/);
    assert.match(fr, /"resetConfirm":"Réinitialiser le lien de modification privé de cette fiche\?/);
    assert.match(fr, /"nLogins":"\{n\} comptes peuvent modifier cette fiche"/);
    mail.length = 0;
    const rf = await s.post(`/fr/owner/account/venue/${v.id}/reset-link`, {}, owner.cookie);
    assert.equal(rf.status, 200, JSON.stringify(rf.body));
    assert.equal(mail[0].subject, 'Nouveau lien de modification pour Reset Link Fixture');
    assert.match(mail[0].text, /https:\/\/okanaganroam\.com\/fr\/owner\/[A-Za-z0-9_-]{32}/);
    const frToken = /\/owner\/([A-Za-z0-9_-]{32})\b/.exec(mail[0].text)[1];
    assert.equal((await s.get(`/owner/${newToken}`)).status, 404);
    // A claim approved after a reset makes a working link (and the reset link keeps working until it's opened).
    const claimId = Number(db.prepare(`INSERT INTO venue_claims (venue_id, name, role, email, phone, verify_method) VALUES (?, 'Casey', 'owner', 'casey@example.com', '250 555 0111', 'call')`).run(v.id).lastInsertRowid);
    const approved = await app.adminClaimAction(claimId, 'approve', {}, 'dayton');
    assert.equal(approved.status, 200, JSON.stringify(approved.body));
    const claimToken = approved.body.link.split('/owner/')[1];
    assert.equal((await s.get(`/owner/${frToken}`)).status, 200, 'the reset link still works until the claim link is opened');
    assert.equal((await s.get(`/owner/${claimToken}`)).status, 200);
    const claimed = await s.post(`/owner/${claimToken}/account`, { email: 'casey@example.com', password: 'casey owner password' });
    assert.equal(claimed.status, 201, JSON.stringify(claimed.body));
    assert.equal(app.ownerLoginsForVenue(v.id).length, 3);
    // Admin removal can reset the link too.
    const adminR = await fetch(`${s.base}/admin/owner-links/logins`, { method: 'POST', headers: { 'Content-Type': 'application/json', Authorization: `Bearer ${process.env.ENRICHMENT_ADMIN_TOKEN}` },
      body: JSON.stringify({ venue_id: v.id, remove_email: 'casey@example.com', reset_link: true }) }).then((x) => x.json());
    assert.equal(adminR.removed, true, JSON.stringify(adminR));
    assert.match(adminR.new_link, /^https:\/\/okanaganroam\.com\/owner\/[A-Za-z0-9_-]{32}$/);
    assert.equal((await s.get(`/owner/${claimToken}`)).status, 404);
    assert.equal((await s.get(`/owner/${adminR.new_link.split('/owner/')[1]}`)).status, 200);
  } finally {
    app.setOwnerEmailTransport(null);
    app.setVenueSubmissionTransport(async (payload) => { lyvSent.push(payload); });
    await s.close();
  }
});

